#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EntryReturnProjectionKind {
    NumericOrUnknown,
    BooleanLiteral,
}

pub fn entry_return_projection_kind(proto: &FunctionProto) -> EntryReturnProjectionKind {
    let bc = &proto.bytecode;
    let mut prev_op = None;
    let mut pc = 0usize;
    while pc < bc.len() {
        let Some(op) = op_from_byte(bc[pc]) else {
            return EntryReturnProjectionKind::NumericOrUnknown;
        };
        if op == Op::Return && matches!(prev_op, Some(Op::PushTrue | Op::PushFalse)) {
            return EntryReturnProjectionKind::BooleanLiteral;
        }
        prev_op = Some(op);
        let Some(len) = instruction_len_at(bc, pc) else {
            return EntryReturnProjectionKind::NumericOrUnknown;
        };
        pc += len;
    }
    EntryReturnProjectionKind::NumericOrUnknown
}

pub fn predicate_leaf_result_abi_candidate(proto: &FunctionProto) -> bool {
    proto.params == 2
        && entry_return_projection_kind(proto) == EntryReturnProjectionKind::BooleanLiteral
}

