fn direct_call_leaf_arity(leaf: DirectCallLeaf) -> u8 {
    match leaf {
        DirectCallLeaf::Arg0AddConst(_)
        | DirectCallLeaf::Arg0SubConst(_)
        | DirectCallLeaf::Arg0MulConst(_)
        | DirectCallLeaf::Arg0LoopSumF64 { .. }
        | DirectCallLeaf::Arg0LoopSumAffineF64 { .. }
        | DirectCallLeaf::Arg0LoopSumModDivFloorF64 { .. }
        | DirectCallLeaf::Arg0LoopSumBitwiseMixF64 { .. }
        | DirectCallLeaf::Arg0CryptoHashMix32 { .. }
        | DirectCallLeaf::Arg0LoopBranchMixF64 { .. }
        | DirectCallLeaf::Arg0LoopSumMulMod { .. }
        | DirectCallLeaf::Arg0LoopSumMulModF64 { .. }
        | DirectCallLeaf::Arg0LoopReturnArg0AfterSumMulMod { .. }
        | DirectCallLeaf::Arg0RecursiveDecAdd { .. }
        | DirectCallLeaf::Arg0ArrayPushPop64
        | DirectCallLeaf::CapturedAddArgStore { .. }
        | DirectCallLeaf::CapturedAddArgStoreVoid { .. }
        | DirectCallLeaf::CapturedTypeofNumberSinkStore { .. }
        | DirectCallLeaf::CapturedConstNumberSinkStore { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeConstOffset0SinkStore { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeConstMaskedOffsetSinkStore { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeArg0U32ConstOffset0SinkStore { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeConstOffset0Void { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeArg0U32ConstOffset0Void { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeConstOffset0SinkStoreRaw { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeConstMaskedOffsetSinkStoreRaw { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeArg0U32ConstOffset0SinkStoreRaw { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeConstOffset0VoidRaw { .. }
        | DirectCallLeaf::CapturedBufferWriteU32BeArg0U32ConstOffset0VoidRaw { .. }
        | DirectCallLeaf::CapturedMaskedU8DecimalLenSinkStore { .. }
        | DirectCallLeaf::CapturedMaskedU4DecimalLenSinkStore { .. }
        | DirectCallLeaf::CapturedMaskedU10DecimalLenSinkStore { .. } => 1,
        DirectCallLeaf::Arg0PackedSumArg1
        | DirectCallLeaf::Arg0Arg1SpectralNormA
        | DirectCallLeaf::PredicateObjObj => 2,
        DirectCallLeaf::CapturedAdd3ArgStoreVoid { .. } => 3,
    }
}

fn direct_call_leaf_may_deopt(leaf: DirectCallLeaf) -> bool {
    !matches!(
        leaf,
        DirectCallLeaf::Arg0AddConst(_)
            | DirectCallLeaf::Arg0SubConst(_)
            | DirectCallLeaf::Arg0MulConst(_)
            | DirectCallLeaf::Arg0ArrayPushPop64
            | DirectCallLeaf::CapturedConstNumberSinkStore { .. }
            | DirectCallLeaf::CapturedAddArgStoreVoid { .. }
            | DirectCallLeaf::CapturedAdd3ArgStoreVoid { .. }
            | DirectCallLeaf::CapturedMaskedU8DecimalLenSinkStore { .. }
            | DirectCallLeaf::CapturedMaskedU4DecimalLenSinkStore { .. }
            | DirectCallLeaf::CapturedMaskedU10DecimalLenSinkStore { .. }
    )
}

#[allow(clippy::too_many_arguments)]
fn emit_buffer_write_u32be_epoch_guarded_raw(
    builder: &mut FunctionBuilder,
    epoch_ref: Option<FuncRef>,
    fallback_ref: FuncRef,
    receiver_payload: i64,
    buffer_payload: i64,
    data_ptr: i64,
    byte_len: i64,
    epoch: i64,
    value_i64: ClValue,
    offset_i64: ClValue,
) -> ClValue {
    let fast_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(cont_blk, F64);

    let zero = builder.ins().iconst(I64, 0);
    let offset_nonnegative = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, offset_i64, zero);
    let four = builder.ins().iconst(I64, 4);
    let offset_end = builder.ins().iadd(offset_i64, four);
    let len = builder.ins().iconst(I64, byte_len);
    let offset_in_bounds = builder
        .ins()
        .icmp(IntCC::UnsignedLessThanOrEqual, offset_end, len);
    let offset_guard = builder.ins().band(offset_nonnegative, offset_in_bounds);
    let guard = if let Some(epoch_ref) = epoch_ref {
        let buffer = builder.ins().iconst(I64, buffer_payload);
        let epoch_call = builder.ins().call(epoch_ref, &[buffer]);
        let current_epoch = builder.inst_results(epoch_call)[0];
        let expected_epoch = builder.ins().iconst(I64, epoch);
        let epoch_ok = builder
            .ins()
            .icmp(IntCC::Equal, current_epoch, expected_epoch);
        builder.ins().band(epoch_ok, offset_guard)
    } else {
        let _ = (buffer_payload, epoch);
        offset_guard
    };
    builder.ins().brif(guard, fast_blk, &[], slow_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let m = MemFlags::trusted();
    let base = builder.ins().iconst(I64, data_ptr);
    let data_at_offset = builder.ins().iadd(base, offset_i64);
    let value_u32 = builder.ins().ireduce(I32, value_i64);
    let shift24 = builder.ins().ushr_imm(value_u32, 24);
    let shift16 = builder.ins().ushr_imm(value_u32, 16);
    let shift8 = builder.ins().ushr_imm(value_u32, 8);
    let b0 = builder.ins().ireduce(I8, shift24);
    let b1 = builder.ins().ireduce(I8, shift16);
    let b2 = builder.ins().ireduce(I8, shift8);
    let b3 = builder.ins().ireduce(I8, value_u32);
    builder.ins().store(m, b0, data_at_offset, 0);
    builder.ins().store(m, b1, data_at_offset, 1);
    builder.ins().store(m, b2, data_at_offset, 2);
    builder.ins().store(m, b3, data_at_offset, 3);
    let direct_result = builder.ins().fcvt_from_sint(F64, offset_end);
    builder.ins().jump(cont_blk, &[direct_result]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let receiver = builder.ins().iconst(I64, receiver_payload);
    let fallback = builder
        .ins()
        .call(fallback_ref, &[receiver, value_i64, offset_i64]);
    let fallback_result = builder.inst_results(fallback)[0];
    builder.ins().jump(cont_blk, &[fallback_result]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

