fn mwor_guard_probe_enabled() -> bool {
    cruft_env_var("CRUFT_MWOR_GUARD_PROBE")
        .map(|v| !(v == "0" || v.eq_ignore_ascii_case("false")))
        .unwrap_or(true)
}

