impl std::fmt::Debug for CompiledFn {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "CompiledFn({:?})", self.func)
    }
}

pub fn compile_function(proto: &FunctionProto) -> Result<CompiledFn, String> {

    if function_tier_has_named_property_write(proto) {
        return Err(
            "function-tier SetPropOnObject disabled: named property writes require Value/descriptor semantics"
                .to_string(),
        );
    }

    let ti64 = cruft_env_var("CRUFT_LEJIT_TI64")
        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        .unwrap_or(true);
    if ti64 {
        if let Some(promoted) = crate::promote::promote_to_typed_i64(proto) {
            if let Ok(c) = compile_function_inner(&promoted, false, true, false) {
                if cruft_env_var("CRUFT_LEJIT_TI64_DEBUG").is_ok() {
                    eprintln!("[ti64] typed-compiled '{}'", proto.display_name);
                }
                return Ok(c);
            }

        }
    }
    if plain_entry_interop_require_default_object_return_candidate(proto)
        || proto.display_name == "_interopRequireDefault"
    {
        return compile_function_inner(proto, false, false, true);
    }
    match compile_function_inner(proto, false, false, false) {
        Ok(c) => Ok(c),
        Err(e)
            if (e.contains("ArrayIsArrayStatic")
                && e.contains("requires mixed-domain object argument"))
                || e.contains("object-domain return requires value-return transport") =>
        {
            compile_function_inner(proto, false, false, true).map_err(|mixed_err| {
                if mixed_err.contains("object-domain return requires value-return transport") {
                    mixed_err
                } else {
                    e
                }
            })
        }
        Err(e) => Err(e),
    }
}

fn function_tier_has_named_property_write(proto: &FunctionProto) -> bool {
    parse_bytecode_with_stable_callee_preloads(
        &proto.bytecode,
        &proto.constants,
        &proto.locals,
        &std::collections::HashSet::new(),
        &std::collections::HashMap::new(),
        &std::collections::HashMap::new(),
        &std::collections::HashSet::new(),
        &std::collections::HashSet::new(),
        &std::collections::HashSet::new(),
    )
    .map(|parsed| {
        parsed
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::SetPropOnObject(_)))
    })
    .unwrap_or(false)
}

fn plain_entry_interop_require_default_object_return_candidate(proto: &FunctionProto) -> bool {
    let Ok(mut parsed) = parse_bytecode_with_stable_callee_preloads(
        &proto.bytecode,
        &proto.constants,
        &proto.locals,
        &std::collections::HashSet::new(),
        &std::collections::HashMap::new(),
        &std::collections::HashMap::new(),
        &std::collections::HashSet::new(),
        &std::collections::HashSet::new(),
        &std::collections::HashSet::new(),
    ) else {
        return false;
    };
    rewrite_value_jump_to_return(&mut parsed);
    rewrite_interop_require_default_keep_chain(&mut parsed);
    rewrite_getprop_truthy_branch_domain(&mut parsed);
    let mut slots = mixed_domain_slots(&parsed, &[]);
    for slot in interop_require_default_value_return_object_slots(&parsed) {
        push_unique_sorted(&mut slots.object_slots, slot);
        slots.f64_slots.retain(|f64_slot| *f64_slot != slot);
    }
    !slots.object_slots.is_empty() && object_entry_return_candidate(&parsed, &slots)
}

