pub fn compile_function_osr(proto: &FunctionProto) -> Result<CompiledFn, String> {
    if env_flag_enabled_by_default("CRUFT_LEJIT_MDOA") {
        match compile_function_inner(proto, true, false, true) {
            Ok(c) => {
                if cruft_env_var("CRUFT_LEJIT_MDOA_DEBUG").is_ok() {
                    eprintln!("[mdoa-osr] mixed-domain OSR compile path selected");
                }
                return Ok(c);
            }
            Err(e) => {
                if cruft_env_var("CRUFT_LEJIT_MDOA_DEBUG").is_ok() {
                    eprintln!("[mdoa-osr] mixed-domain OSR compile rejected: {e}");
                }
                if e.contains("HostNativeObjectProp")
                    || e.contains("HostNativeObjectMethod0")
                    || e.contains("HostNativeConstructor1ObjRet")
                    || e.contains("ArrayIsArrayStatic")
                    || e.contains("object-domain return requires value-return transport")
                {
                    return Err(e);
                }
            }
        }
    }

    let ti64 = cruft_env_var("CRUFT_LEJIT_TI64")
        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        .unwrap_or(true);
    if ti64 {
        if let Some(promoted) = crate::promote::promote_to_typed_i64(proto) {
            if let Ok(c) = compile_function_inner(&promoted, true, true, false) {
                if cruft_env_var("CRUFT_LEJIT_TI64_DEBUG").is_ok() {
                    eprintln!("[ti64-osr] typed-compiled OSR loop");
                }
                return Ok(c);
            }
        }
    }
    compile_function_inner(proto, true, false, false)
}

