        && preflight_has_setindex
        && !preflight_has_read
        && env_flag_enabled_by_default("CRUFT_LEJIT_SKIP_WRITE_ONLY_SETINDEX_OSR")
        && !write_only_setindex_typed_array_storeback_ready
        && !write_only_setindex_constant_overwrite_ready
        && !string_charcode_write_only_setindex_osr_ready(&parsed)
