        let mut local_vars: Vec<Variable> = Vec::with_capacity(proto.locals.len());
        let mut local_var_types: Vec<Type> = Vec::with_capacity(proto.locals.len());
        for i in 0..proto.locals.len() {
            let v = Variable::from_u32(i as u32);
            let contract_i64_local = scalar_return_contract
                .is_some_and(|contract| contract.i64_payload_slots.contains(&i))
                || scalar_storeback_contract
                    .is_some_and(|contract| contract.i64_payload_slots.contains(&i));
            let local_ty = if typed_i64 || contract_i64_local {
                I64
            } else if let Some(domains) = mixed_local_domains.as_ref() {
                match domains[i] {
                    LocalDomain::ObjectBits
                    | LocalDomain::ObjectOrNullBits
                    | LocalDomain::SafeI64 => I64,
                    LocalDomain::Null | LocalDomain::Undefined => {
                        unreachable!("null/undefined are stack-only, never local domains")
                    }
                    LocalDomain::NumberF64
                    | LocalDomain::RawF64
                    | LocalDomain::OwnedStringResult => F64,
                }
            } else {
                F64
            };
            builder.declare_var(v, local_ty);
            local_vars.push(v);
            local_var_types.push(local_ty);
        }

        for (i, v) in local_vars.iter().enumerate() {
            let contract_i64_local = scalar_return_contract
                .is_some_and(|contract| contract.i64_payload_slots.contains(&i))
                || scalar_storeback_contract
                    .is_some_and(|contract| contract.i64_payload_slots.contains(&i));
            let zero = if typed_i64 || contract_i64_local {
                builder.ins().iconst(I64, 0)
            } else if let Some(domains) = mixed_local_domains.as_ref() {
                match domains[i] {
                    LocalDomain::ObjectBits
                    | LocalDomain::ObjectOrNullBits
                    | LocalDomain::SafeI64 => builder.ins().iconst(I64, 0),
                    LocalDomain::Null | LocalDomain::Undefined => {
                        unreachable!("null/undefined are stack-only, never local domains")
                    }
                    LocalDomain::NumberF64
                    | LocalDomain::RawF64
                    | LocalDomain::OwnedStringResult => builder.ins().f64const(0.0),
                }
            } else {
                builder.ins().f64const(0.0)
            };
            builder.def_var(*v, zero);
        }

