                            let zero = builder.ins().f64const(0.0);
                            let addend = builder.ins().select(should_inc, one, zero);
                            let current = builder.use_var(*var);
                            let next = builder.ins().fadd(current, addend);
                            builder.def_var(*var, next);
                            Ok(())
