                                let ten = builder.ins().iconst(I64, 10);
                                let hundred = builder.ins().iconst(I64, 100);
                                let thousand = builder.ins().iconst(I64, 1000);
                                let one = builder.ins().iconst(I64, 1);
                                let two = builder.ins().iconst(I64, 2);
                                let three = builder.ins().iconst(I64, 3);
