fn finite_integral_f64_to_i64(value: f64) -> Option<i64> {
    if value.is_finite()
        && value.fract() == 0.0
        && value >= i64::MIN as f64
        && value <= i64::MAX as f64
    {
        Some(value as i64)
    } else {
        None
    }
}

fn u32_const_i64(value: f64) -> Option<i64> {
    let int_value = finite_integral_f64_to_i64(value)?;
    if (0..=u32::MAX as i64).contains(&int_value) {
        Some(int_value)
    } else {
        None
    }
}

fn nonnegative_i64_const(value: f64) -> Option<i64> {
    let int_value = finite_integral_f64_to_i64(value)?;
    if int_value >= 0 {
        Some(int_value)
    } else {
        None
    }
}

fn dump_filter_matches(name: &str, function_name: &str) -> bool {
    let Ok(value) = cruft_env_var(name) else {
        return false;
    };
    let filter = value.trim();
    filter.is_empty()
        || filter == "1"
        || filter.eq_ignore_ascii_case("true")
        || function_name.contains(filter)
}

fn env_flag_enabled_by_default(name: &str) -> bool {
    cruft_env_var(name)
        .map(|v| !(v == "0" || v.eq_ignore_ascii_case("false") || v.eq_ignore_ascii_case("off")))
        .unwrap_or(true)
}

fn osr_storeback_slots_for(
    mixed_domain_osr: bool,
    local_count: usize,
    written_slots: &std::collections::HashSet<u16>,
    force_written_storeback: bool,
) -> Vec<usize> {
    if mixed_domain_osr
        && (env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_STORE_WRITTEN")
            || force_written_storeback)
    {
        let mut slots: Vec<usize> = written_slots
            .iter()
            .copied()
            .map(usize::from)
            .filter(|&slot| slot < local_count)
            .collect();
        slots.sort_unstable();
        slots.dedup();
        slots
    } else {
        (0..local_count).collect()
    }
}

fn parsed_written_slots(parsed: &[(usize, ParsedOp)]) -> std::collections::HashSet<u16> {
    let mut slots = std::collections::HashSet::new();
    for (_, op) in parsed {
        match *op {
            ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) => {
                slots.insert(slot);
            }
            ParsedOp::Site874TokenFinalizationAggregateProduce {
                token_slot,
                exports_slot,
                functions_slot,
                constants_slot,
                checksum_slot,
            } => {
                slots.insert(token_slot);
                slots.insert(exports_slot);
                slots.insert(functions_slot);
                slots.insert(constants_slot);
                slots.insert(checksum_slot);
            }
            _ => {}
        }
    }
    slots
}

fn osr_snapshot_live_slots_for(
    parsed: &[(usize, ParsedOp)],
    local_count: usize,
    storeback_slots: &[usize],
) -> Vec<usize> {
    if osr_region_may_deopt(parsed) {
        return (0..local_count).collect();
    }

    osr_syntactic_live_slots_for(parsed, local_count, storeback_slots)
}

fn osr_snapshot_live_slots_policy_only_arguments_narrowed(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::LocalDescriptor],
    mut slots: Vec<usize>,
) -> Vec<usize> {
    if env_flag_truthy("CRUFT_LEJIT_OSR_POLICY_ONLY_ARGUMENTS_NARROWING_DISABLE")
        || !(env_flag_enabled_by_default("CRUFT_LEJIT_OSR_POLICY_ONLY_ARGUMENTS_NARROWING")
            || env_flag_truthy("CRUFT_LEJIT_OSR_POLICY_ONLY_ARGUMENTS_NARROWING_PROBE"))
        || !osr_region_may_deopt(parsed)
    {
        return slots;
    }

    let touched_slots = osr_syntactic_live_slots_for(parsed, locals.len(), &[]);
    let arguments_slots = locals
        .iter()
        .enumerate()
        .filter_map(|(slot, desc)| (desc.name == "arguments").then_some(slot))
        .collect::<Vec<_>>();
    if arguments_slots.is_empty() {
        return slots;
    }

    slots.retain(|slot| !arguments_slots.contains(slot) || touched_slots.contains(slot));
    slots
}

fn osr_syntactic_live_slots_for(
    parsed: &[(usize, ParsedOp)],
    local_count: usize,
    storeback_slots: &[usize],
) -> Vec<usize> {
    let mut slots: Vec<usize> = parsed
        .iter()
        .filter_map(|(_, op)| match op {
            ParsedOp::LoadLocal(slot)
            | ParsedOp::StoreLocal(slot)
            | ParsedOp::InitLocal(slot)
            | ParsedOp::TdzSeedLocal(slot) => Some(usize::from(*slot)),
            _ => None,
        })
        .chain(storeback_slots.iter().copied())
        .filter(|&slot| slot < local_count)
        .collect();
    slots.sort_unstable();
    slots.dedup();
    slots
}

fn osr_local_touch_reasons_for(parsed: &[(usize, ParsedOp)], slots: &[usize]) -> Vec<String> {
    let slot_set: std::collections::HashSet<usize> = slots.iter().copied().collect();
    parsed
        .iter()
        .filter_map(|(pc, op)| {
            let (kind, slot) = match op {
                ParsedOp::LoadLocal(slot) => ("load", usize::from(*slot)),
                ParsedOp::StoreLocal(slot) => ("store", usize::from(*slot)),
                ParsedOp::InitLocal(slot) => ("init", usize::from(*slot)),
                ParsedOp::TdzSeedLocal(slot) => ("tdz-seed", usize::from(*slot)),
                _ => return None,
            };
            slot_set
                .contains(&slot)
                .then(|| format!("{pc}:{kind}:{slot}:{op:?}"))
        })
        .collect()
}

fn osr_update_temp_ownership_candidates(parsed: &[(usize, ParsedOp)]) -> Vec<String> {
    parsed
        .windows(11)
        .filter_map(|window| {
            let [
                (load_pc, ParsedOp::LoadLocal(ind0)),
                (_, ParsedOp::ToNumeric),
                (_, ParsedOp::Dup),
                (pre_store_pc, ParsedOp::StoreLocal(pre_tmp)),
                (_, ParsedOp::Inc),
                (post_store_pc, ParsedOp::StoreLocal(post_tmp)),
                (post_load_pc, ParsedOp::LoadLocal(post_load)),
                (ind_store_pc, ParsedOp::StoreLocal(ind1)),
                (pre_load_pc, ParsedOp::LoadLocal(pre_load)),
                (_, ParsedOp::Pop),
                (next_pc, next_op),
            ] = window
            else {
                return None;
            };
            if ind0 != ind1 || pre_tmp != pre_load || post_tmp != post_load {
                return None;
            }
            Some(format!(
                "load_pc={load_pc}:induction_slot={ind0}:pre_tmp_slot={pre_tmp}:post_tmp_slot={post_tmp}:pre_store_pc={pre_store_pc}:post_store_pc={post_store_pc}:post_load_pc={post_load_pc}:ind_store_pc={ind_store_pc}:pre_load_pc={pre_load_pc}:next_pc={next_pc}:next_op={next_op:?}:materializable_from_induction=true"
            ))
        })
        .collect()
}

fn stable_object_upvalue_indexed_property_shape_proofs(
    parsed: &[(usize, ParsedOp)],
) -> Vec<StableObjectUpvalueIndexedPropertyShapeProof> {
    let stable_object_slots: std::collections::HashMap<u16, u16> = parsed
        .iter()
        .filter_map(|(_, op)| match op {
            ParsedOp::StableObjectUpvaluePreload {
                upvalue_slot,
                local_slot,
            } => Some((*local_slot, *upvalue_slot)),
            _ => None,
        })
        .collect();
    if stable_object_slots.is_empty() {
        return Vec::new();
    }

    let mut getprop_site_index = 0usize;
    let mut proofs = Vec::new();
    for (i, (_, op)) in parsed.iter().enumerate() {
        if let ParsedOp::GetPropOnObject(_) = op {
            getprop_site_index += 1;
        }

        if !matches!(op, ParsedOp::GetIndexOnObject) {
            continue;
        }
        let Some((_, ParsedOp::GetPropOnObject(prop_idx))) = parsed.get(i + 1) else {
            continue;
        };
        let Some(stack) = simulate_block_stack(&parsed[..i]) else {
            continue;
        };
        let Some(Origin::Local(object_local_slot)) = stack
            .len()
            .checked_sub(2)
            .and_then(|receiver_depth| stack.get(receiver_depth).copied())
        else {
            continue;
        };
        let Some(upvalue_slot) = stable_object_slots.get(&object_local_slot).copied() else {
            continue;
        };
        proofs.push(StableObjectUpvalueIndexedPropertyShapeProof {
            upvalue_slot,
            object_local_slot,
            getindex_op_index: i,
            getprop_op_index: i + 1,
            prop_idx: *prop_idx,
            getprop_site_index,
        });
    }
    proofs
}

fn proved_array_length_mod_nonnegative_slots(
    parsed: &[(usize, ParsedOp)],
    proofs: &[StableObjectUpvalueIndexedPropertyShapeProof],
) -> Vec<u16> {
    let mut slots = Vec::new();
    for proof in proofs {
        let Some(mod_idx) = proof.getindex_op_index.checked_sub(1) else {
            continue;
        };
        if !matches!(parsed.get(mod_idx).map(|(_, op)| op), Some(ParsedOp::Mod)) {
            continue;
        }
        let Some(stack) = simulate_expr_stack(&parsed[..mod_idx]) else {
            continue;
        };
        let Some(Origin::Local(slot)) = stack
            .len()
            .checked_sub(2)
            .and_then(|lhs_depth| stack.get(lhs_depth).map(|expr| expr.origin))
        else {
            continue;
        };
        if !slots.contains(&slot) {
            slots.push(slot);
        }
    }
    slots.sort_unstable();
    slots
}

