fn stable_object_upvalue_indexed_property_number_tag_elision_safe(
    parsed: &[(usize, ParsedOp)],
) -> bool {
    !parsed.iter().any(|(_, op)| {
        matches!(
            op,
            ParsedOp::SetPropOnObject(_)
                | ParsedOp::SetIndexOnObject
                | ParsedOp::StoreScriptGlobalVar { .. }
                | ParsedOp::NewArrayEmpty
                | ParsedOp::NewArrayLiteral { .. }
                | ParsedOp::InitIndex { .. }
                | ParsedOp::CallDirect { .. }
                | ParsedOp::CallIndexedDirect1
                | ParsedOp::CallIndexedDirectLeaf1 { .. }
                | ParsedOp::CallIndexedDirectLeafSwitch1 { .. }
                | ParsedOp::CallDirectLeaf { .. }
                | ParsedOp::CallDirectLeafConstI32 { .. }
                | ParsedOp::CallDirectLeaf2 { .. }
                | ParsedOp::CallDirectLeaf2ConstI32 { .. }
                | ParsedOp::HostNativeMethod1ObjRet { .. }
                | ParsedOp::HostNativeMethod2ObjRet { .. }
                | ParsedOp::HostNativeMethod0NumRet { .. }
                | ParsedOp::HostNativeMethod1NumRet { .. }
                | ParsedOp::HostNativeMethod1String { .. }
                | ParsedOp::HostNativeMethod2String { .. }
                | ParsedOp::HostNativeMethod4String { .. }
                | ParsedOp::HostGlobalObject { .. }
                | ParsedOp::HostNativeObjectProp { .. }
                | ParsedOp::HostNativeObjectMethod0 { .. }
                | ParsedOp::HostNativeObjectMethod1String { .. }
                | ParsedOp::HostNativeConstructor1ObjRet { .. }
                | ParsedOp::CallStringFromCharCode
                | ParsedOp::CallStringCtor
                | ParsedOp::CallStringFromCharCodeMethod
        )
    })
}

fn scalar_osr_payload_slots_for(
    osr_mode: bool,
    typed_i64: bool,
    mixed_domain_osr: bool,
    parsed: &[(usize, ParsedOp)],
    snapshot_live_slots: &[usize],
    written_slots: &std::collections::HashSet<u16>,
    local_count: usize,
) -> Vec<usize> {
    if !mixed_domain_osr {
        return pure_numeric_scalar_osr_payload_slots_for(
            osr_mode,
            typed_i64,
            parsed,
            written_slots,
            local_count,
        );
    }

    if !osr_mode
        || typed_i64
        || !env_flag_truthy("CRUFT_LEJIT_SCALAR_OSR")
        || scalar_osr_region_may_deopt(parsed)
        || parsed.iter().any(|(_, op)| {
            matches!(
                op,
                ParsedOp::GetPropOnObject(_)
                    | ParsedOp::GetIndexOnObject
                    | ParsedOp::GetIndexStringOnObject
                    | ParsedOp::SetPropOnObject(_)
                    | ParsedOp::SetIndexOnObject
                    | ParsedOp::StoreScriptGlobalVar { .. }
                    | ParsedOp::CallDirect { .. }
                    | ParsedOp::CallDirectLeaf2 { .. }
                    | ParsedOp::CallDirectLeaf2ConstI32 { .. }
            )
        })
    {
        return Vec::new();
    }

    let mut guard_slots: Vec<usize> = parsed
        .iter()
        .filter_map(|(_, op)| match op {
            ParsedOp::CallDirectLeaf { callee_slot, .. }
            | ParsedOp::CallDirectLeafConstI32 { callee_slot, .. } => {
                Some(usize::from(*callee_slot))
            }
            _ => None,
        })
        .collect();
    guard_slots.sort_unstable();
    guard_slots.dedup();
    if guard_slots.is_empty() {
        return Vec::new();
    }

    let payload = snapshot_live_slots
        .iter()
        .copied()
        .filter(|slot| !guard_slots.contains(slot))
        .collect::<Vec<_>>();
    match payload.len() {
        2 | 4 => payload,
        _ => Vec::new(),
    }
}

fn pure_numeric_scalar_osr_payload_slots_for(
    osr_mode: bool,
    typed_i64: bool,
    parsed: &[(usize, ParsedOp)],
    written_slots: &std::collections::HashSet<u16>,
    local_count: usize,
) -> Vec<usize> {
    if !osr_mode
        || typed_i64
        || !env_flag_enabled_by_default("CRUFT_LEJIT_PURE_NUMERIC_SCALAR_OSR")
        || scalar_osr_region_may_deopt(parsed)
        || parsed.iter().any(|(_, op)| {
            matches!(
                op,
                ParsedOp::GetPropOnObject(_)
                    | ParsedOp::GetIndexOnObject
                    | ParsedOp::GetIndexStringOnObject
                    | ParsedOp::SetPropOnObject(_)
                    | ParsedOp::SetIndexOnObject
                    | ParsedOp::StoreScriptGlobalVar { .. }
                    | ParsedOp::CallDirect { .. }
                    | ParsedOp::CallDirectLeaf { .. }
                    | ParsedOp::CallDirectLeafConstI32 { .. }
                    | ParsedOp::CallDirectLeaf2 { .. }
                    | ParsedOp::CallDirectLeaf2ConstI32 { .. }
            )
        })
    {
        return Vec::new();
    }

    let mut payload = parsed
        .iter()
        .filter_map(|(_, op)| match op {
            ParsedOp::LoadLocal(slot)
            | ParsedOp::StoreLocal(slot)
            | ParsedOp::InitLocal(slot)
            | ParsedOp::TdzSeedLocal(slot) => Some(usize::from(*slot)),
            _ => None,
        })
        .chain(written_slots.iter().copied().map(usize::from))
        .filter(|&slot| slot < local_count)
        .collect::<Vec<_>>();
    payload.sort_unstable();
    payload.dedup();

    let written_payload =
        pure_numeric_scalar_osr_storeback_slots_for(written_slots, &payload, local_count);
    if written_payload.is_empty() {
        return Vec::new();
    }

    match payload.len() {
        2 | 4 | 5 | 6 | 9 => payload,
        _ => Vec::new(),
    }
}

fn pure_numeric_scalar_osr_storeback_slots_for(
    written_slots: &std::collections::HashSet<u16>,
    payload_slots: &[usize],
    local_count: usize,
) -> Vec<usize> {
    let mut slots = written_slots
        .iter()
        .copied()
        .map(usize::from)
        .filter(|slot| *slot < local_count && payload_slots.contains(slot))
        .collect::<Vec<_>>();
    slots.sort_unstable();
    slots.dedup();
    slots
}

fn scalar_storeback_contract_storeback_slots(contract: &OsrScalarStorebackContract) -> Vec<usize> {
    let mut slots = contract.storeback_slots.clone().unwrap_or_else(|| {
        contract
            .payload_slots
            .iter()
            .copied()
            .filter(|slot| !contract.object_payload_slots.contains(slot))
            .collect::<Vec<_>>()
    });
    slots.sort_unstable();
    slots.dedup();
    slots
}

fn scalar_osr_i64_payload_enabled(
    payload_slots: &[usize],
    mixed_local_domains: Option<&[LocalDomain]>,
) -> bool {
    if payload_slots.is_empty() || !env_flag_truthy("CRUFT_LEJIT_SCALAR_OSR_I64") {
        return false;
    }
    let Some(domains) = mixed_local_domains else {
        return false;
    };
    payload_slots
        .iter()
        .all(|&slot| domains.get(slot) == Some(&LocalDomain::SafeI64))
}

