fn emit_mwor_value_ptr_load(builder: &mut FunctionBuilder, prop_idx: u16) -> ClValue {
    let m = MemFlags::trusted();
    let ptr_addr = builder.ins().iconst(
        I64,
        (crate::deopt::mwor_value_ptr_base_addr() + (prop_idx as usize) * 8) as i64,
    );
    builder.ins().load(I64, m, ptr_addr, 0)
}

fn emit_mwor_raw_getprop(
    builder: &mut FunctionBuilder,
    value_ptr: ClValue,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    builder
        .ins()
        .load(F64, m, value_ptr, layout.value_number_payload_off)
}

fn emit_mwor_raw_setprop(
    builder: &mut FunctionBuilder,
    value_ptr: ClValue,
    value_f64: ClValue,
    layout: &crate::deopt::InlineIcLayout,
) {
    let m = MemFlags::trusted();
    builder
        .ins()
        .store(m, value_f64, value_ptr, layout.value_number_payload_off);
}

fn emit_aria_generated_entry_table_load_opcode_contract(
    builder: &mut FunctionBuilder,
    _layout: &crate::deopt::InlineIcLayout,
    aria_string_content_eq_ref: Option<cranelift_codegen::ir::FuncRef>,
) {
    let m = MemFlags::trusted();
    let base = crate::deopt::aria_shape_value_cell_base_addr();
    let zero = builder.ins().iconst(I64, 0);
    let generated_tag_payload_dereference = aria_generated_tag_payload_dereference_enabled()
        && aria_generated_entry_table_prebody_publication_contract_enabled();
    let generated_predicate_body_consumption =
        generated_tag_payload_dereference && aria_generated_predicate_body_consumption_enabled();
    let mut tags = Vec::with_capacity(crate::deopt::ARIA_SHAPE_CELL_COUNT);
    let mut payloads = Vec::with_capacity(crate::deopt::ARIA_SHAPE_CELL_COUNT);
    for cell in 0..crate::deopt::ARIA_SHAPE_CELL_COUNT {
        let ptr_addr = builder
            .ins()
            .iconst(I64, (base + cell * std::mem::size_of::<usize>()) as i64);
        let value_ptr = builder.ins().load(I64, m, ptr_addr, 0);
        let _nonzero = builder.ins().icmp(IntCC::NotEqual, value_ptr, zero);
        if generated_tag_payload_dereference {
            let tag = builder.ins().load(I8, m, value_ptr, 0);
            let payload = builder.ins().load(
                I64,
                m,
                value_ptr,
                crate::deopt::inline_ic_layout().value_number_payload_off,
            );
            let _tag_wide = builder.ins().uextend(I64, tag);
            let _payload_nonzero = builder.ins().icmp(IntCC::NotEqual, payload, zero);
            tags.push(tag);
            payloads.push(payload);
        }
    }
    if generated_predicate_body_consumption
        && tags.len() == crate::deopt::ARIA_SHAPE_CELL_COUNT
        && payloads.len() == crate::deopt::ARIA_SHAPE_CELL_COUNT
    {
        let string_tag = builder.ins().iconst(I8, 4);
        let object_tag = builder.ins().iconst(I8, 7);
        let mut ok = builder.ins().icmp(IntCC::Equal, tags[0], string_tag);
        let rhs_name_tag_ok = builder.ins().icmp(IntCC::Equal, tags[1], string_tag);
        ok = builder.ins().band(ok, rhs_name_tag_ok);
        for tag in tags.iter().skip(2) {
            let object_tag_ok = builder.ins().icmp(IntCC::Equal, *tag, object_tag);
            ok = builder.ins().band(ok, object_tag_ok);
        }
        let name_payload_eq = builder.ins().icmp(IntCC::Equal, payloads[0], payloads[1]);
        let _generated_body_candidate = builder.ins().band(ok, name_payload_eq);
        if aria_generated_constraints_dense_string_array_comparison_enabled()
            && _layout.array_verified
        {
            let lhs_constraints_obj =
                crate::stub_aarch64::emit_array_object_addr(builder, payloads[2], _layout);
            let rhs_constraints_obj =
                crate::stub_aarch64::emit_array_object_addr(builder, payloads[3], _layout);
            let lhs_dense_flag =
                builder
                    .ins()
                    .load(I8, m, lhs_constraints_obj, _layout.object_array_dense_off);
            let rhs_dense_flag =
                builder
                    .ins()
                    .load(I8, m, rhs_constraints_obj, _layout.object_array_dense_off);
            let zero_i8 = builder.ins().iconst(I8, 0);
            let lhs_dense_ok = builder.ins().icmp(IntCC::NotEqual, lhs_dense_flag, zero_i8);
            let rhs_dense_ok = builder.ins().icmp(IntCC::NotEqual, rhs_dense_flag, zero_i8);
            let _constraints_dense_ok = builder.ins().band(lhs_dense_ok, rhs_dense_ok);
            let lhs_len = builder.ins().load(
                I64,
                m,
                lhs_constraints_obj,
                _layout.object_dense_elements_off + _layout.vec_len_off,
            );
            let rhs_len = builder.ins().load(
                I64,
                m,
                rhs_constraints_obj,
                _layout.object_dense_elements_off + _layout.vec_len_off,
            );
            let _constraints_len_eq = builder.ins().icmp(IntCC::Equal, lhs_len, rhs_len);
            if aria_generated_constraints_element_string_comparison_enabled() {
                let lhs_data = builder.ins().load(
                    I64,
                    m,
                    lhs_constraints_obj,
                    _layout.object_dense_elements_off + _layout.vec_ptr_off,
                );
                let rhs_data = builder.ins().load(
                    I64,
                    m,
                    rhs_constraints_obj,
                    _layout.object_dense_elements_off + _layout.vec_ptr_off,
                );
                let lhs_data_nonzero = builder.ins().icmp(IntCC::NotEqual, lhs_data, zero);
                let rhs_data_nonzero = builder.ins().icmp(IntCC::NotEqual, rhs_data, zero);
                let _constraints_dense_storage_ready =
                    builder.ins().band(lhs_data_nonzero, rhs_data_nonzero);
                if aria_generated_constraints_element_value_dereference_enabled() {
                    let elem_blk = builder.create_block();
                    let cont_blk = builder.create_block();
                    let lhs_nonempty =
                        builder
                            .ins()
                            .icmp(IntCC::UnsignedGreaterThan, lhs_len, zero);
                    let rhs_nonempty =
                        builder
                            .ins()
                            .icmp(IntCC::UnsignedGreaterThan, rhs_len, zero);
                    let both_nonempty = builder.ins().band(lhs_nonempty, rhs_nonempty);
                    builder
                        .ins()
                        .brif(both_nonempty, elem_blk, &[], cont_blk, &[]);

                    builder.switch_to_block(elem_blk);
                    builder.seal_block(elem_blk);
                    let lhs_elem_tag = builder.ins().load(I8, m, lhs_data, 0);
                    let rhs_elem_tag = builder.ins().load(I8, m, rhs_data, 0);
                    let lhs_elem_payload =
                        builder
                            .ins()
                            .load(I64, m, lhs_data, _layout.value_payload_off);
                    let rhs_elem_payload =
                        builder
                            .ins()
                            .load(I64, m, rhs_data, _layout.value_payload_off);
                    let lhs_elem_is_string =
                        builder.ins().icmp(IntCC::Equal, lhs_elem_tag, string_tag);
                    let rhs_elem_is_string =
                        builder.ins().icmp(IntCC::Equal, rhs_elem_tag, string_tag);
                    let _constraints_first_element_string_pair =
                        builder.ins().band(lhs_elem_is_string, rhs_elem_is_string);
                    if aria_generated_constraints_element_string_payload_comparison_enabled() {
                        let first_payload_eq =
                            builder
                                .ins()
                                .icmp(IntCC::Equal, lhs_elem_payload, rhs_elem_payload);
                        let _constraints_first_element_payload_string_eq = builder
                            .ins()
                            .band(_constraints_first_element_string_pair, first_payload_eq);
                        if aria_generated_constraints_element_string_content_comparison_enabled() {
                            if let Some(helper) = aria_string_content_eq_ref {
                                let call = builder
                                    .ins()
                                    .call(helper, &[lhs_elem_payload, rhs_elem_payload]);
                                let _constraints_first_element_content_eq =
                                    builder.inst_results(call)[0];
                            }
                        }
                    }
                    builder.ins().jump(cont_blk, &[]);

                    builder.switch_to_block(cont_blk);
                    builder.seal_block(cont_blk);
                }
            }
        }
    }
}

fn emit_inline_getprop_ic(
    builder: &mut FunctionBuilder,
    receiver: ClValue,
    prop_v: ClValue,
    site_id: crate::stub_aarch64::ICSiteId,
    gpref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();

    let mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver, mask);

    let hb_addr = builder
        .ins()
        .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
    let heap_base = builder.ins().load(I64, m, hb_addr, 0);
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    let shape = builder
        .ins()
        .load(I64, m, obj_addr, layout.object_shape_off);

    let cs_addr = builder.ins().iconst(
        I64,
        (crate::deopt::inline_ic_shape_base_addr() + (site_id as usize) * 8) as i64,
    );
    let cached_shape = builder.ins().load(I64, m, cs_addr, 0);
    let csl_addr = builder.ins().iconst(
        I64,
        (crate::deopt::inline_ic_slot_base_addr() + (site_id as usize) * 4) as i64,
    );
    let cached_slot32 = builder
        .ins()
        .load(cranelift_codegen::ir::types::I32, m, csl_addr, 0);
    let cached_slot = builder.ins().uextend(I64, cached_slot32);
    let zero = builder.ins().iconst(I64, 0);
    let nonzero = builder.ins().icmp(IntCC::NotEqual, cached_shape, zero);
    let shape_eq = builder.ins().icmp(IntCC::Equal, shape, cached_shape);
    let guard = builder.ins().band(nonzero, shape_eq);

    let load_blk = builder.create_block();
    let mono_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let num_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(load_blk, I64);
    builder.append_block_param(cont_blk, F64);

    let poly_count_addr = builder.ins().iconst(
        I64,
        (crate::deopt::poly_inline_ic_count_base_addr() + (site_id as usize) * 4) as i64,
    );
    let poly_count = builder
        .ins()
        .load(cranelift_codegen::ir::types::I32, m, poly_count_addr, 0);
    let zero32 = builder.ins().iconst(cranelift_codegen::ir::types::I32, 0);
    let has_poly = builder.ins().icmp(IntCC::NotEqual, poly_count, zero32);
    let first_poly_blk = builder.create_block();
    builder
        .ins()
        .brif(has_poly, first_poly_blk, &[], mono_blk, &[]);

    let mut next_poly_blk = first_poly_blk;
    for lane in 0..crate::deopt::POLY_INLINE_IC_MAX_SHAPES {
        builder.switch_to_block(next_poly_blk);
        builder.seal_block(next_poly_blk);
        let miss_blk = if lane + 1 == crate::deopt::POLY_INLINE_IC_MAX_SHAPES {
            slow_blk
        } else {
            builder.create_block()
        };
        let lane_count = builder
            .ins()
            .iconst(cranelift_codegen::ir::types::I32, lane as i64);
        let has_lane = builder
            .ins()
            .icmp(IntCC::UnsignedGreaterThan, poly_count, lane_count);
        let cell = (site_id as usize) * crate::deopt::POLY_INLINE_IC_MAX_SHAPES + lane;
        let shape_addr = builder.ins().iconst(
            I64,
            (crate::deopt::poly_inline_ic_shape_base_addr() + cell * 8) as i64,
        );
        let poly_shape = builder.ins().load(I64, m, shape_addr, 0);
        let poly_nonzero = builder.ins().icmp(IntCC::NotEqual, poly_shape, zero);
        let poly_shape_eq = builder.ins().icmp(IntCC::Equal, shape, poly_shape);
        let lane_guard = builder.ins().band(has_lane, poly_nonzero);
        let lane_guard = builder.ins().band(lane_guard, poly_shape_eq);
        let slot_addr = builder.ins().iconst(
            I64,
            (crate::deopt::poly_inline_ic_slot_base_addr() + cell * 4) as i64,
        );
        let poly_slot32 = builder
            .ins()
            .load(cranelift_codegen::ir::types::I32, m, slot_addr, 0);
        let poly_slot = builder.ins().uextend(I64, poly_slot32);
        builder
            .ins()
            .brif(lane_guard, load_blk, &[poly_slot], miss_blk, &[]);
        next_poly_blk = miss_blk;
    }

    builder.switch_to_block(mono_blk);
    builder.seal_block(mono_blk);
    builder
        .ins()
        .brif(guard, load_blk, &[cached_slot], slow_blk, &[]);

    builder.switch_to_block(load_blk);
    builder.seal_block(load_blk);
    let slot = builder.block_params(load_blk)[0];
    let vals = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_shape_values_off + layout.vec_ptr_off,
    );
    let vsize = builder.ins().iconst(I64, layout.value_size as i64);
    let elem_off = builder.ins().imul(slot, vsize);
    let elem_addr = builder.ins().iadd(vals, elem_off);
    let tag = builder
        .ins()
        .load(cranelift_codegen::ir::types::I8, m, elem_addr, 0);
    let tag64 = builder.ins().uextend(I64, tag);
    let numtag = builder.ins().iconst(I64, layout.value_tag_number as i64);
    let is_num = builder.ins().icmp(IntCC::Equal, tag64, numtag);
    builder.ins().brif(is_num, num_blk, &[], slow_blk, &[]);

    builder.switch_to_block(num_blk);
    builder.seal_block(num_blk);
    let val = builder
        .ins()
        .load(F64, m, elem_addr, layout.value_number_payload_off);
    builder.ins().jump(cont_blk, &[val]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let site_v = builder.ins().iconst(I64, site_id as i64);
    let call_inst = builder.ins().call(gpref, &[site_v, receiver, prop_v]);
    let r_i64 = builder.inst_results(call_inst)[0];
    let r_f64 = builder.ins().fcvt_from_sint(F64, r_i64);
    builder.ins().jump(cont_blk, &[r_f64]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_proved_poly_getprop_ic(
    builder: &mut FunctionBuilder,
    receiver: ClValue,
    prop_v: ClValue,
    site_id: crate::stub_aarch64::ICSiteId,
    lane_vars: Option<&Vec<(Variable, Variable)>>,
    elide_number_tag_check: bool,
    gpref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    let mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver, mask);
    let hb_addr = builder
        .ins()
        .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
    let heap_base = builder.ins().load(I64, m, hb_addr, 0);
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    let shape = builder
        .ins()
        .load(I64, m, obj_addr, layout.object_shape_off);

    let load_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(load_blk, I64);
    builder.append_block_param(cont_blk, F64);

    let zero = builder.ins().iconst(I64, 0);
    let mut next_blk = builder.create_block();
    builder.ins().jump(next_blk, &[]);
    for lane in 0..crate::deopt::POLY_INLINE_IC_MAX_SHAPES {
        builder.switch_to_block(next_blk);
        builder.seal_block(next_blk);
        let miss_blk = if lane + 1 == crate::deopt::POLY_INLINE_IC_MAX_SHAPES {
            slow_blk
        } else {
            builder.create_block()
        };
        let cell = (site_id as usize) * crate::deopt::POLY_INLINE_IC_MAX_SHAPES + lane;
        let poly_shape = lane_vars
            .and_then(|vars| vars.get(lane))
            .map(|(shape_var, _)| builder.use_var(*shape_var))
            .unwrap_or_else(|| {
                let shape_addr = builder.ins().iconst(
                    I64,
                    (crate::deopt::poly_inline_ic_shape_base_addr() + cell * 8) as i64,
                );
                builder.ins().load(I64, m, shape_addr, 0)
            });
        let poly_nonzero = builder.ins().icmp(IntCC::NotEqual, poly_shape, zero);
        let poly_shape_eq = builder.ins().icmp(IntCC::Equal, shape, poly_shape);
        let lane_guard = builder.ins().band(poly_nonzero, poly_shape_eq);
        let poly_slot = lane_vars
            .and_then(|vars| vars.get(lane))
            .map(|(_, slot_var)| builder.use_var(*slot_var))
            .unwrap_or_else(|| {
                let slot_addr = builder.ins().iconst(
                    I64,
                    (crate::deopt::poly_inline_ic_slot_base_addr() + cell * 4) as i64,
                );
                let poly_slot32 =
                    builder
                        .ins()
                        .load(cranelift_codegen::ir::types::I32, m, slot_addr, 0);
                builder.ins().uextend(I64, poly_slot32)
            });
        builder
            .ins()
            .brif(lane_guard, load_blk, &[poly_slot], miss_blk, &[]);
        next_blk = miss_blk;
    }

    builder.switch_to_block(load_blk);
    builder.seal_block(load_blk);
    let slot = builder.block_params(load_blk)[0];
    let vals = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_shape_values_off + layout.vec_ptr_off,
    );
    let vsize = builder.ins().iconst(I64, layout.value_size as i64);
    let elem_off = builder.ins().imul(slot, vsize);
    let elem_addr = builder.ins().iadd(vals, elem_off);
    if elide_number_tag_check {
        let val = builder
            .ins()
            .load(F64, m, elem_addr, layout.value_number_payload_off);
        builder.ins().jump(cont_blk, &[val]);
    } else {
        let num_blk = builder.create_block();
        let tag = builder
            .ins()
            .load(cranelift_codegen::ir::types::I8, m, elem_addr, 0);
        let tag64 = builder.ins().uextend(I64, tag);
        let numtag = builder.ins().iconst(I64, layout.value_tag_number as i64);
        let is_num = builder.ins().icmp(IntCC::Equal, tag64, numtag);
        builder.ins().brif(is_num, num_blk, &[], slow_blk, &[]);

        builder.switch_to_block(num_blk);
        builder.seal_block(num_blk);
        let val = builder
            .ins()
            .load(F64, m, elem_addr, layout.value_number_payload_off);
        builder.ins().jump(cont_blk, &[val]);
    }

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let site_v = builder.ins().iconst(I64, site_id as i64);
    let call_inst = builder.ins().call(gpref, &[site_v, receiver, prop_v]);
    let r_i64 = builder.inst_results(call_inst)[0];
    let r_f64 = builder.ins().fcvt_from_sint(F64, r_i64);
    builder.ins().jump(cont_blk, &[r_f64]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_proved_poly_indexed_getprop_ic(
    builder: &mut FunctionBuilder,
    receiver: ClValue,
    prop_v: ClValue,
    index: ClValue,
    site_id: crate::stub_aarch64::ICSiteId,
    indexed_table_vars: Option<(Variable, Variable)>,
    heap_base_var: Option<Variable>,
    gpref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    let fast_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(cont_blk, F64);

    let site = site_id as usize;
    let len = indexed_table_vars
        .map(|(len_var, _)| builder.use_var(len_var))
        .unwrap_or_else(|| {
            let len_addr = builder.ins().iconst(
                I64,
                (crate::deopt::poly_indexed_slot_len_base_addr() + site * 4) as i64,
            );
            let len32 = builder
                .ins()
                .load(cranelift_codegen::ir::types::I32, m, len_addr, 0);
            builder.ins().uextend(I64, len32)
        });
    let in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index, len);
    builder.ins().brif(in_bounds, fast_blk, &[], slow_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let slot_base = indexed_table_vars
        .map(|(_, slot_base_var)| builder.use_var(slot_base_var))
        .unwrap_or_else(|| {
            let slot_ptr_addr = builder.ins().iconst(
                I64,
                (crate::deopt::poly_indexed_slot_ptr_base_addr() + site * 8) as i64,
            );
            builder.ins().load(I64, m, slot_ptr_addr, 0)
        });
    let four = builder.ins().iconst(I64, 4);
    let slot_off = builder.ins().imul(index, four);
    let slot_addr = builder.ins().iadd(slot_base, slot_off);
    let slot32 = builder
        .ins()
        .load(cranelift_codegen::ir::types::I32, m, slot_addr, 0);
    let invalid = builder.ins().iconst(I32, u32::MAX as i64);
    let slot_ok = builder.ins().icmp(IntCC::NotEqual, slot32, invalid);
    let load_blk = builder.create_block();
    builder.ins().brif(slot_ok, load_blk, &[], slow_blk, &[]);

    builder.switch_to_block(load_blk);
    builder.seal_block(load_blk);
    let slot = builder.ins().uextend(I64, slot32);
    let mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver, mask);
    let heap_base = heap_base_var
        .map(|var| builder.use_var(var))
        .unwrap_or_else(|| {
            let hb_addr = builder
                .ins()
                .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
            builder.ins().load(I64, m, hb_addr, 0)
        });
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    let vals = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_shape_values_off + layout.vec_ptr_off,
    );
    let vsize = builder.ins().iconst(I64, layout.value_size as i64);
    let elem_off = builder.ins().imul(slot, vsize);
    let elem_addr = builder.ins().iadd(vals, elem_off);
    let val = builder
        .ins()
        .load(F64, m, elem_addr, layout.value_number_payload_off);
    builder.ins().jump(cont_blk, &[val]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let site_v = builder.ins().iconst(I64, site_id as i64);
    let call_inst = builder.ins().call(gpref, &[site_v, receiver, prop_v]);
    let r_i64 = builder.inst_results(call_inst)[0];
    let r_f64 = builder.ins().fcvt_from_sint(F64, r_i64);
    builder.ins().jump(cont_blk, &[r_f64]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_inline_getindex_ic(
    builder: &mut FunctionBuilder,
    receiver: ClValue,
    index_i64: ClValue,
    giref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    let mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver, mask);
    let hb_addr = builder
        .ins()
        .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
    let heap_base = builder.ins().load(I64, m, hb_addr, 0);
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    let zero = builder.ins().iconst(I64, 0);

    let packed_blk = builder.create_block();
    let dense_chk_blk = builder.create_block();
    let fast_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let num_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(cont_blk, F64);

    let packed_flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_packed_off,
    );
    let packed_flag64 = builder.ins().uextend(I64, packed_flag);
    let is_packed = builder.ins().icmp(IntCC::NotEqual, packed_flag64, zero);
    let plen = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_len_off,
    );
    let p_in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index_i64, plen);
    let p_guard = builder.ins().band(is_packed, p_in_bounds);
    builder
        .ins()
        .brif(p_guard, packed_blk, &[], dense_chk_blk, &[]);

    builder.switch_to_block(packed_blk);
    builder.seal_block(packed_blk);
    let pdata = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_ptr_off,
    );
    let eight = builder.ins().iconst(I64, 8);
    let p_elem_off = builder.ins().imul(index_i64, eight);
    let p_elem_addr = builder.ins().iadd(pdata, p_elem_off);
    let pval = builder.ins().load(F64, m, p_elem_addr, 0);
    builder.ins().jump(cont_blk, &[pval]);

    builder.switch_to_block(dense_chk_blk);
    builder.seal_block(dense_chk_blk);

    let dense_flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_dense_off,
    );
    let dense_flag64 = builder.ins().uextend(I64, dense_flag);
    let is_dense = builder.ins().icmp(IntCC::NotEqual, dense_flag64, zero);
    let len = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_elements_off + layout.vec_len_off,
    );
    let in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index_i64, len);
    let guard = builder.ins().band(is_dense, in_bounds);
    builder.ins().brif(guard, fast_blk, &[], slow_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let data = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_elements_off + layout.vec_ptr_off,
    );
    let vsize = builder.ins().iconst(I64, layout.value_size as i64);
    let elem_off = builder.ins().imul(index_i64, vsize);
    let elem_addr = builder.ins().iadd(data, elem_off);
    let tag = builder
        .ins()
        .load(cranelift_codegen::ir::types::I8, m, elem_addr, 0);
    let tag64 = builder.ins().uextend(I64, tag);
    let numtag = builder.ins().iconst(I64, layout.value_tag_number as i64);
    let is_num = builder.ins().icmp(IntCC::Equal, tag64, numtag);
    builder.ins().brif(is_num, num_blk, &[], slow_blk, &[]);

    builder.switch_to_block(num_blk);
    builder.seal_block(num_blk);
    let val = builder
        .ins()
        .load(F64, m, elem_addr, layout.value_number_payload_off);
    builder.ins().jump(cont_blk, &[val]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let call_inst = builder.ins().call(giref, &[receiver, index_i64]);
    let r_f64 = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[r_f64]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_inline_getindex_obj_ic(
    builder: &mut FunctionBuilder,
    receiver: ClValue,
    index_i64: ClValue,
    giref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    let mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver, mask);
    let hb_addr = builder
        .ins()
        .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
    let heap_base = builder.ins().load(I64, m, hb_addr, 0);
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    let zero = builder.ins().iconst(I64, 0);

    let fast_blk = builder.create_block();
    let obj_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(cont_blk, I64);

    let dense_flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_dense_off,
    );
    let dense_flag64 = builder.ins().uextend(I64, dense_flag);
    let is_dense = builder.ins().icmp(IntCC::NotEqual, dense_flag64, zero);
    let len = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_elements_off + layout.vec_len_off,
    );
    let in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index_i64, len);
    let guard = builder.ins().band(is_dense, in_bounds);
    builder.ins().brif(guard, fast_blk, &[], slow_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let data = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_elements_off + layout.vec_ptr_off,
    );
    let vsize = builder.ins().iconst(I64, layout.value_size as i64);
    let elem_off = builder.ins().imul(index_i64, vsize);
    let elem_addr = builder.ins().iadd(data, elem_off);
    let tag = builder
        .ins()
        .load(cranelift_codegen::ir::types::I8, m, elem_addr, 0);
    let tag64 = builder.ins().uextend(I64, tag);
    let objtag = builder.ins().iconst(I64, layout.value_tag_object as i64);
    let is_obj = builder.ins().icmp(IntCC::Equal, tag64, objtag);
    builder.ins().brif(is_obj, obj_blk, &[], slow_blk, &[]);

    builder.switch_to_block(obj_blk);
    builder.seal_block(obj_blk);
    let obj_bits = builder
        .ins()
        .load(I64, m, elem_addr, layout.value_number_payload_off);
    builder.ins().jump(cont_blk, &[obj_bits]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let call_inst = builder.ins().call(giref, &[receiver, index_i64]);
    let r_obj = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[r_obj]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_proved_poly_receiver_getindex_obj_ic(
    builder: &mut FunctionBuilder,
    receiver: ClValue,
    index_i64: ClValue,
    site_id: crate::stub_aarch64::ICSiteId,
    indexed_len_var: Option<Variable>,
    heap_base_var: Option<Variable>,
    giref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    let fast_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(cont_blk, I64);

    let site = site_id as usize;
    let len = indexed_len_var
        .map(|len_var| builder.use_var(len_var))
        .unwrap_or_else(|| {
            let len_addr = builder.ins().iconst(
                I64,
                (crate::deopt::poly_indexed_slot_len_base_addr() + site * 4) as i64,
            );
            let len32 = builder
                .ins()
                .load(cranelift_codegen::ir::types::I32, m, len_addr, 0);
            builder.ins().uextend(I64, len32)
        });
    let in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index_i64, len);
    builder.ins().brif(in_bounds, fast_blk, &[], slow_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver, mask);
    let heap_base = heap_base_var
        .map(|var| builder.use_var(var))
        .unwrap_or_else(|| {
            let hb_addr = builder
                .ins()
                .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
            builder.ins().load(I64, m, hb_addr, 0)
        });
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    let data = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_elements_off + layout.vec_ptr_off,
    );
    let vsize = builder.ins().iconst(I64, layout.value_size as i64);
    let elem_off = builder.ins().imul(index_i64, vsize);
    let elem_addr = builder.ins().iadd(data, elem_off);
    let obj_bits = builder
        .ins()
        .load(I64, m, elem_addr, layout.value_number_payload_off);
    builder.ins().jump(cont_blk, &[obj_bits]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let call_inst = builder.ins().call(giref, &[receiver, index_i64]);
    let r_obj = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[r_obj]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

