fn emit_inline_array_object_addr(
    builder: &mut FunctionBuilder,
    receiver_bits: ClValue,
    layout: &crate::deopt::InlineIcLayout,
) -> (ClValue, ClValue) {
    let m = MemFlags::trusted();
    let payload_mask = builder.ins().iconst(I64, 0x0000_FFFF_FFFF_FFFF_u64 as i64);
    let recv_payload = builder.ins().band(receiver_bits, payload_mask);
    let id_mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver_bits, id_mask);
    let hb_addr = builder
        .ins()
        .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
    let heap_base = builder.ins().load(I64, m, hb_addr, 0);
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    (recv_payload, obj_addr)
}

fn emit_string_length_mod_or_fallback(
    builder: &mut FunctionBuilder,
    lhs_f64: ClValue,
    rhs_f64: ClValue,
    len: ClValue,
    fallback_ref: cranelift_codegen::ir::FuncRef,
) -> ClValue {
    let fast_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(cont_blk, F64);

    let lhs_i64 = builder.ins().fcvt_to_sint_sat(I64, lhs_f64);
    let lhs_roundtrip = builder.ins().fcvt_from_sint(F64, lhs_i64);
    let lhs_integer = builder.ins().fcmp(FloatCC::Equal, lhs_roundtrip, lhs_f64);
    let zero_i64 = builder.ins().iconst(I64, 0);
    let lhs_non_negative = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, lhs_i64, zero_i64);
    let len_positive = builder.ins().icmp(IntCC::SignedGreaterThan, len, zero_i64);
    let lhs_ok = builder.ins().band(lhs_integer, lhs_non_negative);
    let guard = builder.ins().band(lhs_ok, len_positive);
    builder.ins().brif(guard, fast_blk, &[], slow_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let rem = builder.ins().urem(lhs_i64, len);
    let rem_f64 = builder.ins().fcvt_from_uint(F64, rem);
    builder.ins().jump(cont_blk, &[rem_f64]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let call_inst = builder.ins().call(fallback_ref, &[lhs_f64, rhs_f64]);
    let fallback = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[fallback]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_array_length_mod_or_fallback(
    builder: &mut FunctionBuilder,
    lhs_f64: ClValue,
    rhs_f64: ClValue,
    len: ClValue,
    fallback_ref: cranelift_codegen::ir::FuncRef,
) -> ClValue {
    emit_string_length_mod_or_fallback(builder, lhs_f64, rhs_f64, len, fallback_ref)
}

fn emit_proved_array_length_mod_i64_or_deopt(
    builder: &mut FunctionBuilder,
    lhs_i64: ClValue,
    site_id: crate::stub_aarch64::ICSiteId,
    indexed_len_var: Option<Variable>,
    trip_ref: cranelift_codegen::ir::FuncRef,
    pc: usize,
    deopt_sites: &mut crate::deopt::DeoptSiteTable,
) -> ClValue {
    let m = MemFlags::trusted();
    let zero = builder.ins().iconst(I64, 0);
    let negative = builder.ins().icmp(IntCC::SignedLessThan, lhs_i64, zero);
    let lhs = emit_deopt_if(builder, negative, lhs_i64, trip_ref, pc, &[], deopt_sites);

    let site = site_id as usize;
    let len = indexed_len_var
        .map(|len_var| builder.use_var(len_var))
        .unwrap_or_else(|| {
            let len_addr = builder.ins().iconst(
                I64,
                (crate::deopt::poly_indexed_slot_len_base_addr() + site * 4) as i64,
            );
            let len32 = builder
                .ins()
                .load(cranelift_codegen::ir::types::I32, m, len_addr, 0);
            builder.ins().uextend(I64, len32)
        });
    let len_zero = builder.ins().icmp(IntCC::Equal, len, zero);
    let len = emit_deopt_if(builder, len_zero, len, trip_ref, pc, &[], deopt_sites);
    builder.ins().urem(lhs, len)
}

fn emit_proved_array_length_mod_i64_no_deopt(
    builder: &mut FunctionBuilder,
    lhs_i64: ClValue,
    site_id: crate::stub_aarch64::ICSiteId,
    indexed_len_var: Option<Variable>,
) -> ClValue {
    let m = MemFlags::trusted();
    let site = site_id as usize;
    let len = indexed_len_var
        .map(|len_var| builder.use_var(len_var))
        .unwrap_or_else(|| {
            let len_addr = builder.ins().iconst(
                I64,
                (crate::deopt::poly_indexed_slot_len_base_addr() + site * 4) as i64,
            );
            let len32 = builder
                .ins()
                .load(cranelift_codegen::ir::types::I32, m, len_addr, 0);
            builder.ins().uextend(I64, len32)
        });
    builder.ins().urem(lhs_i64, len)
}

fn mul_mod_period_constants(mul: i64, modulus: i64, step: i64) -> Option<(i64, i64)> {
    if mul <= 0 || modulus <= 0 || step <= 0 || modulus > 4096 {
        return None;
    }

    fn gcd_i64(mut a: i64, mut b: i64) -> i64 {
        while b != 0 {
            let r = a % b;
            a = b;
            b = r;
        }
        a.abs()
    }

    let stride = mul.checked_mul(step)?;
    let gcd = gcd_i64(stride, modulus);
    if gcd <= 0 {
        return None;
    }
    let period = modulus / gcd;
    if period <= 0 || period > 4096 {
        return None;
    }

    let mut sum: i128 = 0;
    for j in 0..period {
        let product = (j as i128)
            .checked_mul(step as i128)?
            .checked_mul(mul as i128)?;
        sum += product.rem_euclid(modulus as i128);
    }
    if sum > i64::MAX as i128 {
        return None;
    }

    Some((period, sum as i64))
}

fn direct_call_leaf_const_i32_result(leaf: DirectCallLeaf, arg0: i32) -> Option<f64> {
    if leaf == DirectCallLeaf::Arg0ArrayPushPop64 {
        if arg0 <= 0 {
            return Some(0.0);
        }
        let n = i64::from(arg0);
        if n <= 64 {
            return Some(n as f64);
        }
        let count = n - 64;
        let suffix_sum = (64 + n - 1) * count / 2;
        return Some((suffix_sum + 64) as f64);
    }
    if let DirectCallLeaf::Arg0RecursiveDecAdd { base, add, step } = leaf {
        if step <= 0 {
            return None;
        }
        if arg0 <= 0 {
            return Some(base as f64);
        }
        let iterations = (i64::from(arg0) + step - 1) / step;
        let result =
            i128::from(base).checked_add(i128::from(iterations).checked_mul(add.into())?)?;
        if result < i128::from(i64::MIN) || result > i128::from(i64::MAX) {
            return None;
        }
        return Some(result as f64);
    }
    let DirectCallLeaf::Arg0LoopSumMulMod { mul, modulus, step } = leaf else {
        return None;
    };
    if arg0 < 0 || step != 1 {
        return None;
    }
    let bound = i64::from(arg0);
    let (period, period_sum) = mul_mod_period_constants(mul, modulus, step)?;
    let full_cycles = bound / period;
    let rem_count = bound - full_cycles * period;
    let mut acc = i128::from(full_cycles).checked_mul(i128::from(period_sum))?;
    let stride = i128::from(mul).checked_mul(i128::from(step))?;
    for j in 0..rem_count {
        let product = i128::from(j).checked_mul(stride)?;
        acc = acc.checked_add(product.rem_euclid(i128::from(modulus)))?;
    }
    Some(f64::from(acc as i32))
}

fn emit_arg0_loop_sum_mul_mod_loop(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    mul: i64,
    modulus: i64,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero = builder.ins().iconst(I64, 0);
    builder.ins().jump(loop_blk, &[zero, zero]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    let result = builder.ins().fcvt_from_sint(F64, acc);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[result]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let mul_v = builder.ins().iconst(I64, mul);
    let modulus_v = builder.ins().iconst(I64, modulus);
    let product = builder.ins().imul(body_i, mul_v);
    let rem = builder.ins().urem(product, modulus_v);
    let sum = builder.ins().iadd(body_acc, rem);
    let sum32 = builder.ins().ireduce(I32, sum);
    let next_acc = builder.ins().sextend(I64, sum32);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_packed_array_unrolled_scalar_loop(
    builder: &mut FunctionBuilder,
    shape: PackedArrayUnrolledScalarLoopShape,
    local_vars: &[Variable],
    packed_len: ClValue,
    packed_data: ClValue,
    unroll_factor: i64,
    grouped_accumulator: bool,
) -> ClValue {
    let zero = builder.ins().iconst(I64, 0);
    let has_data = builder.ins().icmp(IntCC::NotEqual, packed_data, zero);
    let m = MemFlags::trusted();

    match shape {
        PackedArrayUnrolledScalarLoopShape::Affine {
            accumulator_slot,
            induction_slot,
            bound_const,
            mask_const,
            ..
        } => {
            let acc0 = builder.use_var(local_vars[usize::from(accumulator_slot)]);
            let i0 = builder.use_var(local_vars[usize::from(induction_slot)]);
            let bound = builder.ins().iconst(I64, bound_const);
            let mask = builder.ins().iconst(I64, mask_const);
            let unroll = builder.ins().iconst(I64, unroll_factor);
            let max_index = builder.ins().iconst(I64, mask_const);
            let max_index_in_bounds =
                builder
                    .ins()
                    .icmp(IntCC::UnsignedLessThan, max_index, packed_len);
            let guard = builder.ins().band(has_data, max_index_in_bounds);

            let fast_blk = builder.create_block();
            let done_blk = builder.create_block();
            let unroll_chk_blk = builder.create_block();
            let unroll_body_blk = builder.create_block();
            let tail_chk_blk = builder.create_block();
            let tail_body_blk = builder.create_block();
            builder.append_block_param(unroll_chk_blk, I64);
            builder.append_block_param(unroll_chk_blk, I64);
            builder.append_block_param(unroll_body_blk, I64);
            builder.append_block_param(unroll_body_blk, I64);
            builder.append_block_param(tail_chk_blk, I64);
            builder.append_block_param(tail_chk_blk, I64);
            builder.append_block_param(tail_body_blk, I64);
            builder.append_block_param(tail_body_blk, I64);
            builder.append_block_param(done_blk, I64);
            builder.ins().brif(guard, fast_blk, &[], done_blk, &[acc0]);

            builder.switch_to_block(fast_blk);
            builder.seal_block(fast_blk);
            builder.ins().jump(unroll_chk_blk, &[acc0, i0]);

            builder.switch_to_block(unroll_chk_blk);
            let acc = builder.block_params(unroll_chk_blk)[0];
            let i = builder.block_params(unroll_chk_blk)[1];
            let i_plus_last = builder.ins().iadd_imm(i, unroll_factor - 1);
            let can_unroll = builder
                .ins()
                .icmp(IntCC::SignedLessThan, i_plus_last, bound);
            builder.ins().brif(
                can_unroll,
                unroll_body_blk,
                &[acc, i],
                tail_chk_blk,
                &[acc, i],
            );

            builder.switch_to_block(unroll_body_blk);
            let carried_acc = builder.block_params(unroll_body_blk)[0];
            let body_i = builder.block_params(unroll_body_blk)[1];
            let mut body_acc = if grouped_accumulator {
                zero
            } else {
                carried_acc
            };
            for offset in 0..unroll_factor {
                let raw_index = if offset == 0 {
                    body_i
                } else {
                    builder.ins().iadd_imm(body_i, offset)
                };
                let index = builder.ins().band(raw_index, mask);
                let val = crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(
                    builder,
                    index,
                    packed_data,
                    m,
                );
                let val_i64 = builder.ins().fcvt_to_sint_sat(I64, val);
                body_acc = builder.ins().iadd(body_acc, val_i64);
            }
            if grouped_accumulator {
                body_acc = builder.ins().iadd(carried_acc, body_acc);
            }
            let next_i = builder.ins().iadd(body_i, unroll);
            builder.ins().jump(unroll_chk_blk, &[body_acc, next_i]);

            builder.switch_to_block(tail_chk_blk);
            let tail_acc = builder.block_params(tail_chk_blk)[0];
            let tail_i = builder.block_params(tail_chk_blk)[1];
            let keep_going = builder.ins().icmp(IntCC::SignedLessThan, tail_i, bound);
            builder.ins().brif(
                keep_going,
                tail_body_blk,
                &[tail_acc, tail_i],
                done_blk,
                &[tail_acc],
            );

            builder.switch_to_block(tail_body_blk);
            let body_acc = builder.block_params(tail_body_blk)[0];
            let body_i = builder.block_params(tail_body_blk)[1];
            let index = builder.ins().band(body_i, mask);
            let val = crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(
                builder,
                index,
                packed_data,
                m,
            );
            let val_i64 = builder.ins().fcvt_to_sint_sat(I64, val);
            let next_acc = builder.ins().iadd(body_acc, val_i64);
            let next_i = builder.ins().iadd_imm(body_i, 1);
            builder.ins().jump(tail_chk_blk, &[next_acc, next_i]);

            builder.switch_to_block(done_blk);
            builder.seal_block(unroll_chk_blk);
            builder.seal_block(unroll_body_blk);
            builder.seal_block(tail_chk_blk);
            builder.seal_block(tail_body_blk);
            builder.seal_block(done_blk);
            let done_acc = builder.block_params(done_blk)[0];
            builder.ins().fcvt_from_sint(F64, done_acc)
        }
        PackedArrayUnrolledScalarLoopShape::Computed {
            accumulator_slot,
            state_slot,
            induction_slot,
            bound_const,
            step_const,
            mask_const,
            ..
        } => {
            let acc0 = builder.use_var(local_vars[usize::from(accumulator_slot)]);
            let j0 = builder.use_var(local_vars[usize::from(state_slot)]);
            let i0 = builder.use_var(local_vars[usize::from(induction_slot)]);
            let bound = builder.ins().iconst(I64, bound_const);
            let step = builder.ins().iconst(I64, step_const);
            let mask = builder.ins().iconst(I64, mask_const);
            let unroll = builder.ins().iconst(I64, unroll_factor);
            let max_index = builder.ins().iconst(I64, mask_const);
            let max_index_in_bounds =
                builder
                    .ins()
                    .icmp(IntCC::UnsignedLessThan, max_index, packed_len);
            let guard = builder.ins().band(has_data, max_index_in_bounds);

            let fast_blk = builder.create_block();
            let done_blk = builder.create_block();
            let unroll_chk_blk = builder.create_block();
            let unroll_body_blk = builder.create_block();
            let tail_chk_blk = builder.create_block();
            let tail_body_blk = builder.create_block();
            builder.append_block_param(unroll_chk_blk, I64);
            builder.append_block_param(unroll_chk_blk, I64);
            builder.append_block_param(unroll_chk_blk, I64);
            builder.append_block_param(unroll_body_blk, I64);
            builder.append_block_param(unroll_body_blk, I64);
            builder.append_block_param(unroll_body_blk, I64);
            builder.append_block_param(tail_chk_blk, I64);
            builder.append_block_param(tail_chk_blk, I64);
            builder.append_block_param(tail_chk_blk, I64);
            builder.append_block_param(tail_body_blk, I64);
            builder.append_block_param(tail_body_blk, I64);
            builder.append_block_param(tail_body_blk, I64);
            builder.append_block_param(done_blk, I64);
            builder.ins().brif(guard, fast_blk, &[], done_blk, &[acc0]);

            builder.switch_to_block(fast_blk);
            builder.seal_block(fast_blk);
            builder.ins().jump(unroll_chk_blk, &[acc0, i0, j0]);

            builder.switch_to_block(unroll_chk_blk);
            let acc = builder.block_params(unroll_chk_blk)[0];
            let i = builder.block_params(unroll_chk_blk)[1];
            let j = builder.block_params(unroll_chk_blk)[2];
            let i_plus_last = builder.ins().iadd_imm(i, unroll_factor - 1);
            let can_unroll = builder
                .ins()
                .icmp(IntCC::SignedLessThan, i_plus_last, bound);
            builder.ins().brif(
                can_unroll,
                unroll_body_blk,
                &[acc, i, j],
                tail_chk_blk,
                &[acc, i, j],
            );

            builder.switch_to_block(unroll_body_blk);
            let carried_acc = builder.block_params(unroll_body_blk)[0];
            let body_i = builder.block_params(unroll_body_blk)[1];
            let mut body_j = builder.block_params(unroll_body_blk)[2];
            let mut body_acc = if grouped_accumulator {
                zero
            } else {
                carried_acc
            };
            for _ in 0..unroll_factor {
                let advanced = builder.ins().iadd(body_j, step);
                body_j = builder.ins().band(advanced, mask);
                let val = crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(
                    builder,
                    body_j,
                    packed_data,
                    m,
                );
                let val_i64 = builder.ins().fcvt_to_sint_sat(I64, val);
                body_acc = builder.ins().iadd(body_acc, val_i64);
            }
            if grouped_accumulator {
                body_acc = builder.ins().iadd(carried_acc, body_acc);
            }
            let next_i = builder.ins().iadd(body_i, unroll);
            builder
                .ins()
                .jump(unroll_chk_blk, &[body_acc, next_i, body_j]);

            builder.switch_to_block(tail_chk_blk);
            let tail_acc = builder.block_params(tail_chk_blk)[0];
            let tail_i = builder.block_params(tail_chk_blk)[1];
            let tail_j = builder.block_params(tail_chk_blk)[2];
            let keep_going = builder.ins().icmp(IntCC::SignedLessThan, tail_i, bound);
            builder.ins().brif(
                keep_going,
                tail_body_blk,
                &[tail_acc, tail_i, tail_j],
                done_blk,
                &[tail_acc],
            );

            builder.switch_to_block(tail_body_blk);
            let body_acc = builder.block_params(tail_body_blk)[0];
            let body_i = builder.block_params(tail_body_blk)[1];
            let body_j = builder.block_params(tail_body_blk)[2];
            let advanced = builder.ins().iadd(body_j, step);
            let next_j = builder.ins().band(advanced, mask);
            let val = crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(
                builder,
                next_j,
                packed_data,
                m,
            );
            let val_i64 = builder.ins().fcvt_to_sint_sat(I64, val);
            let next_acc = builder.ins().iadd(body_acc, val_i64);
            let next_i = builder.ins().iadd_imm(body_i, 1);
            builder
                .ins()
                .jump(tail_chk_blk, &[next_acc, next_i, next_j]);

            builder.switch_to_block(done_blk);
            builder.seal_block(unroll_chk_blk);
            builder.seal_block(unroll_body_blk);
            builder.seal_block(tail_chk_blk);
            builder.seal_block(tail_body_blk);
            builder.seal_block(done_blk);
            let done_acc = builder.block_params(done_blk)[0];
            builder.ins().fcvt_from_sint(F64, done_acc)
        }
    }
}

fn emit_packed_periodic_affine_closed_form(
    builder: &mut FunctionBuilder,
    descriptor: PackedPeriodicLoopDescriptor,
    local_vars: &[Variable],
    packed_len: ClValue,
    packed_data: ClValue,
) -> Option<ClValue> {
    let PackedPeriodicLoopDescriptor::AffineMask {
        accumulator_slot,
        induction_slot,
        bound_const,
        mask_const,
        period_len,
        ..
    } = descriptor
    else {
        return None;
    };
    if period_len != 8 || mask_const != 7 {
        return None;
    }

    let m = MemFlags::trusted();
    let zero = builder.ins().iconst(I64, 0);
    let acc0 = builder.use_var(local_vars[usize::from(accumulator_slot)]);
    let i0 = builder.use_var(local_vars[usize::from(induction_slot)]);
    let bound = builder.ins().iconst(I64, bound_const);
    let max_index = builder.ins().iconst(I64, mask_const);
    let has_data = builder.ins().icmp(IntCC::NotEqual, packed_data, zero);
    let max_index_in_bounds = builder
        .ins()
        .icmp(IntCC::UnsignedLessThan, max_index, packed_len);
    let start_in_range = builder.ins().icmp(IntCC::SignedLessThanOrEqual, i0, bound);
    let data_and_bounds = builder.ins().band(has_data, max_index_in_bounds);
    let guard = builder.ins().band(data_and_bounds, start_in_range);

    let fast_blk = builder.create_block();
    let tail_chk_blk = builder.create_block();
    let tail_body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(done_blk, I64);
    builder.ins().brif(guard, fast_blk, &[], done_blk, &[acc0]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let mut period_sum = zero;
    for index in 0..8 {
        let index_v = builder.ins().iconst(I64, index);
        let val = crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(
            builder,
            index_v,
            packed_data,
            m,
        );
        let val_i64 = builder.ins().fcvt_to_sint_sat(I64, val);
        period_sum = builder.ins().iadd(period_sum, val_i64);
    }
    let remaining = builder.ins().isub(bound, i0);
    let period = builder.ins().iconst(I64, period_len);
    let full_cycles = builder.ins().udiv(remaining, period);
    let covered = builder.ins().imul(full_cycles, period);
    let rem_count = builder.ins().isub(remaining, covered);
    let period_delta = builder.ins().imul(full_cycles, period_sum);
    let base_acc = builder.ins().iadd(acc0, period_delta);
    builder
        .ins()
        .jump(tail_chk_blk, &[base_acc, zero, rem_count]);

    builder.switch_to_block(tail_chk_blk);
    let acc = builder.block_params(tail_chk_blk)[0];
    let tail_idx = builder.block_params(tail_chk_blk)[1];
    let rem = builder.block_params(tail_chk_blk)[2];
    let keep_going = builder.ins().icmp(IntCC::UnsignedLessThan, tail_idx, rem);
    builder.ins().brif(
        keep_going,
        tail_body_blk,
        &[acc, tail_idx, rem],
        done_blk,
        &[acc],
    );

    builder.switch_to_block(tail_body_blk);
    let body_acc = builder.block_params(tail_body_blk)[0];
    let body_tail_idx = builder.block_params(tail_body_blk)[1];
    let body_rem = builder.block_params(tail_body_blk)[2];
    let raw_index = builder.ins().iadd(i0, body_tail_idx);
    let mask = builder.ins().iconst(I64, mask_const);
    let index = builder.ins().band(raw_index, mask);
    let val = crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(
        builder,
        index,
        packed_data,
        m,
    );
    let val_i64 = builder.ins().fcvt_to_sint_sat(I64, val);
    let next_acc = builder.ins().iadd(body_acc, val_i64);
    let one = builder.ins().iconst(I64, 1);
    let next_tail_idx = builder.ins().iadd(body_tail_idx, one);
    builder
        .ins()
        .jump(tail_chk_blk, &[next_acc, next_tail_idx, body_rem]);

    builder.switch_to_block(done_blk);
    builder.seal_block(tail_chk_blk);
    builder.seal_block(tail_body_blk);
    builder.seal_block(done_blk);
    let done_acc = builder.block_params(done_blk)[0];
    Some(builder.ins().fcvt_from_sint(F64, done_acc))
}

fn emit_packed_periodic_closed_form(
    builder: &mut FunctionBuilder,
    descriptor: PackedPeriodicLoopDescriptor,
    local_vars: &[Variable],
    packed_len: ClValue,
    packed_data: ClValue,
) -> Option<ClValue> {
    match descriptor {
        PackedPeriodicLoopDescriptor::AffineMask { .. } => emit_packed_periodic_affine_closed_form(
            builder,
            descriptor,
            local_vars,
            packed_len,
            packed_data,
        ),
        PackedPeriodicLoopDescriptor::ComputedMask { .. } => {
            emit_packed_periodic_computed_closed_form(
                builder,
                descriptor,
                local_vars,
                packed_len,
                packed_data,
            )
        }
    }
}

fn emit_packed_periodic_computed_closed_form(
    builder: &mut FunctionBuilder,
    descriptor: PackedPeriodicLoopDescriptor,
    local_vars: &[Variable],
    packed_len: ClValue,
    packed_data: ClValue,
) -> Option<ClValue> {
    let PackedPeriodicLoopDescriptor::ComputedMask {
        accumulator_slot,
        state_slot,
        induction_slot,
        bound_const,
        step_const,
        mask_const,
        period_len,
        ..
    } = descriptor
    else {
        return None;
    };
    if period_len != 16 || mask_const != 15 || step_const != 5 {
        return None;
    }

    let m = MemFlags::trusted();
    let zero = builder.ins().iconst(I64, 0);
    let acc0 = builder.use_var(local_vars[usize::from(accumulator_slot)]);
    let state0 = builder.use_var(local_vars[usize::from(state_slot)]);
    let i0 = builder.use_var(local_vars[usize::from(induction_slot)]);
    let bound = builder.ins().iconst(I64, bound_const);
    let max_index = builder.ins().iconst(I64, mask_const);
    let has_data = builder.ins().icmp(IntCC::NotEqual, packed_data, zero);
    let max_index_in_bounds = builder
        .ins()
        .icmp(IntCC::UnsignedLessThan, max_index, packed_len);
    let start_in_range = builder.ins().icmp(IntCC::SignedLessThanOrEqual, i0, bound);
    let data_and_bounds = builder.ins().band(has_data, max_index_in_bounds);
    let guard = builder.ins().band(data_and_bounds, start_in_range);

    let fast_blk = builder.create_block();
    let tail_chk_blk = builder.create_block();
    let tail_body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(done_blk, I64);
    builder.ins().brif(guard, fast_blk, &[], done_blk, &[acc0]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let mut period_sum = zero;
    for index in 0..16 {
        let index_v = builder.ins().iconst(I64, index);
        let val = crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(
            builder,
            index_v,
            packed_data,
            m,
        );
        let val_i64 = builder.ins().fcvt_to_sint_sat(I64, val);
        period_sum = builder.ins().iadd(period_sum, val_i64);
    }
    let remaining = builder.ins().isub(bound, i0);
    let period = builder.ins().iconst(I64, period_len);
    let full_cycles = builder.ins().udiv(remaining, period);
    let covered = builder.ins().imul(full_cycles, period);
    let rem_count = builder.ins().isub(remaining, covered);
    let period_delta = builder.ins().imul(full_cycles, period_sum);
    let base_acc = builder.ins().iadd(acc0, period_delta);
    builder
        .ins()
        .jump(tail_chk_blk, &[base_acc, state0, zero, rem_count]);

    builder.switch_to_block(tail_chk_blk);
    let acc = builder.block_params(tail_chk_blk)[0];
    let state = builder.block_params(tail_chk_blk)[1];
    let tail_idx = builder.block_params(tail_chk_blk)[2];
    let rem = builder.block_params(tail_chk_blk)[3];
    let keep_going = builder.ins().icmp(IntCC::UnsignedLessThan, tail_idx, rem);
    builder.ins().brif(
        keep_going,
        tail_body_blk,
        &[acc, state, tail_idx, rem],
        done_blk,
        &[acc],
    );

    builder.switch_to_block(tail_body_blk);
    let body_acc = builder.block_params(tail_body_blk)[0];
    let body_state = builder.block_params(tail_body_blk)[1];
    let body_tail_idx = builder.block_params(tail_body_blk)[2];
    let body_rem = builder.block_params(tail_body_blk)[3];
    let step = builder.ins().iconst(I64, step_const);
    let mask = builder.ins().iconst(I64, mask_const);
    let next_state_unmasked = builder.ins().iadd(body_state, step);
    let next_state = builder.ins().band(next_state_unmasked, mask);
    let val = crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(
        builder,
        next_state,
        packed_data,
        m,
    );
    let val_i64 = builder.ins().fcvt_to_sint_sat(I64, val);
    let next_acc = builder.ins().iadd(body_acc, val_i64);
    let one = builder.ins().iconst(I64, 1);
    let next_tail_idx = builder.ins().iadd(body_tail_idx, one);
    builder.ins().jump(
        tail_chk_blk,
        &[next_acc, next_state, next_tail_idx, body_rem],
    );

    builder.switch_to_block(done_blk);
    builder.seal_block(tail_chk_blk);
    builder.seal_block(tail_body_blk);
    builder.seal_block(done_blk);
    let done_acc = builder.block_params(done_blk)[0];
    Some(builder.ins().fcvt_from_sint(F64, done_acc))
}

fn emit_arg0_loop_sum_mul_mod(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    mul: i64,
    modulus: i64,
    step: i64,
) -> ClValue {
    let Some((period, period_sum)) = mul_mod_period_constants(mul, modulus, step) else {
        return emit_arg0_loop_sum_mul_mod_loop(builder, bound_f64, mul, modulus, step);
    };

    let fast_blk = builder.create_block();
    let rem_loop_blk = builder.create_block();
    let rem_body_blk = builder.create_block();
    let fallback_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(rem_loop_blk, I64);
    builder.append_block_param(rem_loop_blk, I64);
    builder.append_block_param(rem_loop_blk, I64);
    builder.append_block_param(rem_body_blk, I64);
    builder.append_block_param(rem_body_blk, I64);
    builder.append_block_param(rem_body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let bound_i64 = builder.ins().fcvt_to_sint_sat(I64, bound_f64);
    let bound_roundtrip = builder.ins().fcvt_from_sint(F64, bound_i64);
    let exact_integer = builder
        .ins()
        .fcmp(FloatCC::Equal, bound_roundtrip, bound_f64);
    let zero = builder.ins().iconst(I64, 0);
    let non_negative = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, bound_i64, zero);
    let max_exact_n = builder.ins().iconst(I64, 134_217_728);
    let exact_result_range =
        builder
            .ins()
            .icmp(IntCC::SignedLessThanOrEqual, bound_i64, max_exact_n);
    let integer_and_non_negative = builder.ins().band(exact_integer, non_negative);
    let fast_ok = builder
        .ins()
        .band(integer_and_non_negative, exact_result_range);
    builder
        .ins()
        .brif(fast_ok, fast_blk, &[], fallback_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let period_v = builder.ins().iconst(I64, period);
    let full_cycles = builder.ins().udiv(bound_i64, period_v);
    let covered = builder.ins().imul(full_cycles, period_v);
    let rem_count = builder.ins().isub(bound_i64, covered);
    let period_sum_v = builder.ins().iconst(I64, period_sum);
    let base_sum = builder.ins().imul(full_cycles, period_sum_v);
    builder
        .ins()
        .jump(rem_loop_blk, &[base_sum, zero, rem_count]);

    builder.switch_to_block(rem_loop_blk);
    let acc = builder.block_params(rem_loop_blk)[0];
    let j = builder.block_params(rem_loop_blk)[1];
    let rem_count_param = builder.block_params(rem_loop_blk)[2];
    let keep_going = builder
        .ins()
        .icmp(IntCC::UnsignedLessThan, j, rem_count_param);
    let acc32 = builder.ins().ireduce(I32, acc);
    let acc_wrapped = builder.ins().sextend(I64, acc32);
    let result = builder.ins().fcvt_from_sint(F64, acc_wrapped);
    builder.ins().brif(
        keep_going,
        rem_body_blk,
        &[acc, j, rem_count_param],
        done_blk,
        &[result],
    );

    builder.switch_to_block(rem_body_blk);
    let body_acc = builder.block_params(rem_body_blk)[0];
    let body_j = builder.block_params(rem_body_blk)[1];
    let body_rem_count = builder.block_params(rem_body_blk)[2];
    let stride_v = builder.ins().iconst(I64, mul * step);
    let modulus_v = builder.ins().iconst(I64, modulus);
    let product = builder.ins().imul(body_j, stride_v);
    let rem = builder.ins().urem(product, modulus_v);
    let next_acc = builder.ins().iadd(body_acc, rem);
    let one = builder.ins().iconst(I64, 1);
    let next_j = builder.ins().iadd(body_j, one);
    builder
        .ins()
        .jump(rem_loop_blk, &[next_acc, next_j, body_rem_count]);

    builder.switch_to_block(fallback_blk);
    builder.seal_block(fallback_blk);
    let fallback = emit_arg0_loop_sum_mul_mod_loop(builder, bound_f64, mul, modulus, step);
    builder.ins().jump(done_blk, &[fallback]);

    builder.switch_to_block(done_blk);
    builder.seal_block(rem_loop_blk);
    builder.seal_block(rem_body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_loop_sum_mul_mod_i64_loop(
    builder: &mut FunctionBuilder,
    bound_i64: ClValue,
    mul: i64,
    modulus: i64,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, I64);

    let zero = builder.ins().iconst(I64, 0);
    builder.ins().jump(loop_blk, &[zero, zero]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let keep_going = builder.ins().icmp(IntCC::SignedLessThan, i, bound_i64);
    let acc32 = builder.ins().ireduce(I32, acc);
    let result = builder.ins().sextend(I64, acc32);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[result]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let mul_v = builder.ins().iconst(I64, mul);
    let modulus_v = builder.ins().iconst(I64, modulus);
    let product = builder.ins().imul(body_i, mul_v);
    let rem = builder.ins().urem(product, modulus_v);
    let sum = builder.ins().iadd(body_acc, rem);
    let sum32 = builder.ins().ireduce(I32, sum);
    let next_acc = builder.ins().sextend(I64, sum32);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

