fn emit_arg0_loop_sum_f64(builder: &mut FunctionBuilder, bound_f64: ClValue, step: i64) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero_i64 = builder.ins().iconst(I64, 0);
    let zero_f64 = builder.ins().f64const(0.0);
    builder.ins().jump(loop_blk, &[zero_f64, zero_i64]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[acc]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let body_i_f64 = builder.ins().fcvt_from_sint(F64, body_i);
    let next_acc = builder.ins().fadd(body_acc, body_i_f64);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_recursive_dec_add_f64(
    builder: &mut FunctionBuilder,
    arg0_f64: ClValue,
    base: i64,
    add: i64,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(done_blk, F64);

    let base_f64 = builder.ins().f64const(base as f64);
    builder.ins().jump(loop_blk, &[arg0_f64, base_f64]);

    builder.switch_to_block(loop_blk);
    let k = builder.block_params(loop_blk)[0];
    let acc = builder.block_params(loop_blk)[1];
    let zero = builder.ins().f64const(0.0);
    let keep_going = builder.ins().fcmp(FloatCC::GreaterThan, k, zero);
    builder
        .ins()
        .brif(keep_going, body_blk, &[k, acc], done_blk, &[acc]);

    builder.switch_to_block(body_blk);
    let body_k = builder.block_params(body_blk)[0];
    let body_acc = builder.block_params(body_blk)[1];
    let add_f64 = builder.ins().f64const(add as f64);
    let step_f64 = builder.ins().f64const(step as f64);
    let next_acc = builder.ins().fadd(body_acc, add_f64);
    let next_k = builder.ins().fsub(body_k, step_f64);
    builder.ins().jump(loop_blk, &[next_k, next_acc]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_loop_sum_affine_f64(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    mul: i64,
    add: i64,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero_i64 = builder.ins().iconst(I64, 0);
    let zero_f64 = builder.ins().f64const(0.0);
    builder.ins().jump(loop_blk, &[zero_f64, zero_i64]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[acc]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let body_i_f64 = builder.ins().fcvt_from_sint(F64, body_i);
    let mul_f64 = builder.ins().f64const(mul as f64);
    let add_f64 = builder.ins().f64const(add as f64);
    let term = builder.ins().fmul(body_i_f64, mul_f64);
    let term = builder.ins().fadd(term, add_f64);
    let next_acc = builder.ins().fadd(body_acc, term);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_loop_sum_mod_div_floor_f64(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    start: i64,
    modulus: i64,
    divisor: i64,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero = builder.ins().iconst(I64, 0);
    let start_v = builder.ins().iconst(I64, start);
    builder.ins().jump(loop_blk, &[zero, start_v]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    let result = builder.ins().fcvt_from_sint(F64, acc);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[result]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let modulus_v = builder.ins().iconst(I64, modulus);
    let divisor_v = builder.ins().iconst(I64, divisor);
    let rem = builder.ins().urem(body_i, modulus_v);
    let div = builder.ins().udiv(body_i, divisor_v);
    let term = builder.ins().iadd(rem, div);
    let next_acc = builder.ins().iadd(body_acc, term);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_scalar_return_affine_suffix_f64_or_loop(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    accumulator_f64: ClValue,
    induction_f64: ClValue,
    mul: i64,
    add: i64,
) -> ClValue {
    let fast_blk = builder.create_block();
    let fast_calc_blk = builder.create_block();
    let fallback_loop_blk = builder.create_block();
    let fallback_body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(fallback_loop_blk, F64);
    builder.append_block_param(fallback_loop_blk, F64);
    builder.append_block_param(fallback_body_blk, F64);
    builder.append_block_param(fallback_body_blk, F64);
    builder.append_block_param(done_blk, F64);

    let iter_limit_f64 = builder.ins().ceil(bound_f64);
    let iter_limit = builder.ins().fcvt_to_sint_sat(I64, iter_limit_f64);
    let iter_roundtrip = builder.ins().fcvt_from_sint(F64, iter_limit);
    let exact_integer_limit = builder
        .ins()
        .fcmp(FloatCC::Equal, iter_roundtrip, iter_limit_f64);
    let induction_i64 = builder.ins().fcvt_to_sint_sat(I64, induction_f64);
    let induction_roundtrip = builder.ins().fcvt_from_sint(F64, induction_i64);
    let exact_induction = builder
        .ins()
        .fcmp(FloatCC::Equal, induction_roundtrip, induction_f64);
    let accumulator_i64 = builder.ins().fcvt_to_sint_sat(I64, accumulator_f64);
    let accumulator_roundtrip = builder.ins().fcvt_from_sint(F64, accumulator_i64);
    let exact_accumulator =
        builder
            .ins()
            .fcmp(FloatCC::Equal, accumulator_roundtrip, accumulator_f64);
    let zero = builder.ins().iconst(I64, 0);
    let induction_non_negative =
        builder
            .ins()
            .icmp(IntCC::SignedGreaterThanOrEqual, induction_i64, zero);
    let max_exact_limit = builder.ins().iconst(I64, 134_217_728);
    let exact_result_range =
        builder
            .ins()
            .icmp(IntCC::SignedLessThanOrEqual, iter_limit, max_exact_limit);
    let fast_guard = builder.ins().band(exact_integer_limit, exact_induction);
    let fast_guard = builder.ins().band(fast_guard, exact_accumulator);
    let fast_guard = builder.ins().band(fast_guard, induction_non_negative);
    let fast_guard = builder.ins().band(fast_guard, exact_result_range);
    builder.ins().brif(
        fast_guard,
        fast_blk,
        &[],
        fallback_loop_blk,
        &[accumulator_f64, induction_f64],
    );

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let has_iterations = builder
        .ins()
        .icmp(IntCC::SignedGreaterThan, iter_limit, induction_i64);
    builder.ins().brif(
        has_iterations,
        fast_calc_blk,
        &[],
        done_blk,
        &[accumulator_f64],
    );

    builder.switch_to_block(fast_calc_blk);
    builder.seal_block(fast_calc_blk);
    let one = builder.ins().iconst(I64, 1);
    let count = builder.ins().isub(iter_limit, induction_i64);
    let last = builder.ins().isub(iter_limit, one);
    let first_plus_last = builder.ins().iadd(induction_i64, last);
    let product = builder.ins().imul(first_plus_last, count);
    let two = builder.ins().iconst(I64, 2);
    let sum_i = builder.ins().sdiv(product, two);
    let mul_v = builder.ins().iconst(I64, mul);
    let add_v = builder.ins().iconst(I64, add);
    let linear_sum = builder.ins().imul(sum_i, mul_v);
    let add_sum = builder.ins().imul(count, add_v);
    let suffix = builder.ins().iadd(linear_sum, add_sum);
    let result_i64 = builder.ins().iadd(accumulator_i64, suffix);
    let result = builder.ins().fcvt_from_sint(F64, result_i64);
    builder.ins().jump(done_blk, &[result]);

    builder.switch_to_block(fallback_loop_blk);
    let acc = builder.block_params(fallback_loop_blk)[0];
    let i = builder.block_params(fallback_loop_blk)[1];
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i, bound_f64);
    builder
        .ins()
        .brif(keep_going, fallback_body_blk, &[acc, i], done_blk, &[acc]);

    builder.switch_to_block(fallback_body_blk);
    let body_acc = builder.block_params(fallback_body_blk)[0];
    let body_i = builder.block_params(fallback_body_blk)[1];
    let mul_f64 = builder.ins().f64const(mul as f64);
    let add_f64 = builder.ins().f64const(add as f64);
    let term = builder.ins().fmul(body_i, mul_f64);
    let term = builder.ins().fadd(term, add_f64);
    let next_acc = builder.ins().fadd(body_acc, term);
    let one_f64 = builder.ins().f64const(1.0);
    let next_i = builder.ins().fadd(body_i, one_f64);
    builder.ins().jump(fallback_loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(fallback_loop_blk);
    builder.seal_block(fallback_body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_scalar_storeback_sum_suffix_f64_or_loop(
    builder: &mut FunctionBuilder,
    out_ptr: ClValue,
    bound_f64: ClValue,
    accumulator_f64: ClValue,
    induction_f64: ClValue,
) {
    let fast_blk = builder.create_block();
    let fast_calc_blk = builder.create_block();
    let fallback_loop_blk = builder.create_block();
    let fallback_body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(fallback_loop_blk, F64);
    builder.append_block_param(fallback_loop_blk, F64);
    builder.append_block_param(fallback_body_blk, F64);
    builder.append_block_param(fallback_body_blk, F64);
    builder.append_block_param(done_blk, F64);
    builder.append_block_param(done_blk, F64);
    builder.append_block_param(done_blk, F64);
    builder.append_block_param(done_blk, F64);

    let iter_limit_f64 = builder.ins().ceil(bound_f64);
    let iter_limit = builder.ins().fcvt_to_sint_sat(I64, iter_limit_f64);
    let iter_roundtrip = builder.ins().fcvt_from_sint(F64, iter_limit);
    let exact_integer_limit = builder
        .ins()
        .fcmp(FloatCC::Equal, iter_roundtrip, iter_limit_f64);
    let induction_i64 = builder.ins().fcvt_to_sint_sat(I64, induction_f64);
    let induction_roundtrip = builder.ins().fcvt_from_sint(F64, induction_i64);
    let exact_induction = builder
        .ins()
        .fcmp(FloatCC::Equal, induction_roundtrip, induction_f64);
    let accumulator_i64 = builder.ins().fcvt_to_sint_sat(I64, accumulator_f64);
    let accumulator_roundtrip = builder.ins().fcvt_from_sint(F64, accumulator_i64);
    let exact_accumulator =
        builder
            .ins()
            .fcmp(FloatCC::Equal, accumulator_roundtrip, accumulator_f64);
    let zero = builder.ins().iconst(I64, 0);
    let induction_non_negative =
        builder
            .ins()
            .icmp(IntCC::SignedGreaterThanOrEqual, induction_i64, zero);
    let max_exact_limit = builder.ins().iconst(I64, 134_217_728);
    let exact_result_range =
        builder
            .ins()
            .icmp(IntCC::SignedLessThanOrEqual, iter_limit, max_exact_limit);
    let fast_guard = builder.ins().band(exact_integer_limit, exact_induction);
    let fast_guard = builder.ins().band(fast_guard, exact_accumulator);
    let fast_guard = builder.ins().band(fast_guard, induction_non_negative);
    let fast_guard = builder.ins().band(fast_guard, exact_result_range);
    builder.ins().brif(
        fast_guard,
        fast_blk,
        &[],
        fallback_loop_blk,
        &[accumulator_f64, induction_f64],
    );

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let has_iterations = builder
        .ins()
        .icmp(IntCC::SignedGreaterThan, iter_limit, induction_i64);
    builder.ins().brif(
        has_iterations,
        fast_calc_blk,
        &[],
        done_blk,
        &[accumulator_f64, induction_f64, induction_f64, induction_f64],
    );

    builder.switch_to_block(fast_calc_blk);
    builder.seal_block(fast_calc_blk);
    let one = builder.ins().iconst(I64, 1);
    let count = builder.ins().isub(iter_limit, induction_i64);
    let last = builder.ins().isub(iter_limit, one);
    let first_plus_last = builder.ins().iadd(induction_i64, last);
    let product = builder.ins().imul(first_plus_last, count);
    let two = builder.ins().iconst(I64, 2);
    let suffix = builder.ins().sdiv(product, two);
    let result_i64 = builder.ins().iadd(accumulator_i64, suffix);
    let result = builder.ins().fcvt_from_sint(F64, result_i64);
    let final_i = builder.ins().fcvt_from_sint(F64, iter_limit);
    let last_f64 = builder.ins().fcvt_from_sint(F64, last);
    builder
        .ins()
        .jump(done_blk, &[result, final_i, last_f64, final_i]);

    builder.switch_to_block(fallback_loop_blk);
    let acc = builder.block_params(fallback_loop_blk)[0];
    let i = builder.block_params(fallback_loop_blk)[1];
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i, bound_f64);
    builder.ins().brif(
        keep_going,
        fallback_body_blk,
        &[acc, i],
        done_blk,
        &[acc, i, i, i],
    );

    builder.switch_to_block(fallback_body_blk);
    let body_acc = builder.block_params(fallback_body_blk)[0];
    let body_i = builder.block_params(fallback_body_blk)[1];
    let next_acc = builder.ins().fadd(body_acc, body_i);
    let one_f64 = builder.ins().f64const(1.0);
    let next_i = builder.ins().fadd(body_i, one_f64);
    builder.ins().jump(fallback_loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(fallback_loop_blk);
    builder.seal_block(fallback_body_blk);
    builder.seal_block(done_blk);
    for dense_index in 0..4 {
        let value = builder.block_params(done_blk)[dense_index];
        let offset = (dense_index * 8) as i32;
        builder
            .ins()
            .store(MemFlags::trusted(), value, out_ptr, offset);
    }
}

fn emit_typed_array_nested_storeback_f64_loop(
    builder: &mut FunctionBuilder,
    out_ptr: ClValue,
    data_ptr: ClValue,
    len: ClValue,
    bound_f64: ClValue,
    accumulator_f64: ClValue,
    outer_i64: ClValue,
) {
    let outer_loop_blk = builder.create_block();
    let outer_body_blk = builder.create_block();
    let inner_loop_blk = builder.create_block();
    let inner_body_blk = builder.create_block();
    let outer_next_blk = builder.create_block();
    let done_blk = builder.create_block();

    builder.append_block_param(outer_loop_blk, F64);
    builder.append_block_param(outer_loop_blk, I64);
    builder.append_block_param(outer_body_blk, F64);
    builder.append_block_param(outer_body_blk, I64);
    builder.append_block_param(inner_loop_blk, F64);
    builder.append_block_param(inner_loop_blk, I64);
    builder.append_block_param(inner_loop_blk, I64);
    builder.append_block_param(inner_body_blk, F64);
    builder.append_block_param(inner_body_blk, I64);
    builder.append_block_param(inner_body_blk, I64);
    builder.append_block_param(outer_next_blk, F64);
    builder.append_block_param(outer_next_blk, I64);
    builder.append_block_param(done_blk, F64);

    let bound_i64 = builder.ins().fcvt_to_sint_sat(I64, bound_f64);
    builder
        .ins()
        .jump(outer_loop_blk, &[accumulator_f64, outer_i64]);

    builder.switch_to_block(outer_loop_blk);
    let outer_acc = builder.block_params(outer_loop_blk)[0];
    let outer = builder.block_params(outer_loop_blk)[1];
    let keep_outer = builder.ins().icmp(IntCC::SignedLessThan, outer, bound_i64);
    builder.ins().brif(
        keep_outer,
        outer_body_blk,
        &[outer_acc, outer],
        done_blk,
        &[outer_acc],
    );

    builder.switch_to_block(outer_body_blk);
    let body_acc = builder.block_params(outer_body_blk)[0];
    let body_outer = builder.block_params(outer_body_blk)[1];
    let zero = builder.ins().iconst(I64, 0);
    builder
        .ins()
        .jump(inner_loop_blk, &[body_acc, zero, body_outer]);

    builder.switch_to_block(inner_loop_blk);
    let inner_acc = builder.block_params(inner_loop_blk)[0];
    let index = builder.block_params(inner_loop_blk)[1];
    let current_outer = builder.block_params(inner_loop_blk)[2];
    let keep_inner = builder.ins().icmp(IntCC::UnsignedLessThan, index, len);
    builder.ins().brif(
        keep_inner,
        inner_body_blk,
        &[inner_acc, index, current_outer],
        outer_next_blk,
        &[inner_acc, current_outer],
    );

    builder.switch_to_block(inner_body_blk);
    let read_acc = builder.block_params(inner_body_blk)[0];
    let read_index = builder.block_params(inner_body_blk)[1];
    let read_outer = builder.block_params(inner_body_blk)[2];
    let eight = builder.ins().iconst(I64, 8);
    let elem_off = builder.ins().imul(read_index, eight);
    let elem_addr = builder.ins().iadd(data_ptr, elem_off);
    let elem = builder.ins().load(F64, MemFlags::trusted(), elem_addr, 0);
    let next_acc = builder.ins().fadd(read_acc, elem);
    let one_i64 = builder.ins().iconst(I64, 1);
    let next_index = builder.ins().iadd(read_index, one_i64);
    builder
        .ins()
        .jump(inner_loop_blk, &[next_acc, next_index, read_outer]);

    builder.switch_to_block(outer_next_blk);
    let completed_acc = builder.block_params(outer_next_blk)[0];
    let completed_outer = builder.block_params(outer_next_blk)[1];
    let one_i64 = builder.ins().iconst(I64, 1);
    let next_outer = builder.ins().iadd(completed_outer, one_i64);
    builder
        .ins()
        .jump(outer_loop_blk, &[completed_acc, next_outer]);

    builder.switch_to_block(done_blk);
    builder.seal_block(outer_loop_blk);
    builder.seal_block(outer_body_blk);
    builder.seal_block(inner_loop_blk);
    builder.seal_block(inner_body_blk);
    builder.seal_block(outer_next_blk);
    builder.seal_block(done_blk);
    let result = builder.block_params(done_blk)[0];
    builder.ins().store(MemFlags::trusted(), result, out_ptr, 0);
}

fn emit_scalar_return_mod_div_suffix_f64_or_loop(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    accumulator_f64: ClValue,
    induction_f64: ClValue,
    modulus: i64,
    divisor: i64,
) -> ClValue {
    let fast_blk = builder.create_block();
    let empty_blk = builder.create_block();
    let loop_blk = builder.create_block();
    let loop_body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(loop_body_blk, I64);
    builder.append_block_param(loop_body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let iter_limit_f64 = builder.ins().ceil(bound_f64);
    let iter_limit = builder.ins().fcvt_to_sint_sat(I64, iter_limit_f64);
    let iter_roundtrip = builder.ins().fcvt_from_sint(F64, iter_limit);
    let exact_integer_limit = builder
        .ins()
        .fcmp(FloatCC::Equal, iter_roundtrip, iter_limit_f64);
    let induction_i64 = builder.ins().fcvt_to_sint_sat(I64, induction_f64);
    let induction_roundtrip = builder.ins().fcvt_from_sint(F64, induction_i64);
    let exact_induction = builder
        .ins()
        .fcmp(FloatCC::Equal, induction_roundtrip, induction_f64);
    let accumulator_i64 = builder.ins().fcvt_to_sint_sat(I64, accumulator_f64);
    let accumulator_roundtrip = builder.ins().fcvt_from_sint(F64, accumulator_i64);
    let exact_accumulator =
        builder
            .ins()
            .fcmp(FloatCC::Equal, accumulator_roundtrip, accumulator_f64);
    let one = builder.ins().iconst(I64, 1);
    let induction_at_least_one =
        builder
            .ins()
            .icmp(IntCC::SignedGreaterThanOrEqual, induction_i64, one);
    let has_iterations = builder
        .ins()
        .icmp(IntCC::SignedGreaterThan, iter_limit, induction_i64);
    let max_exact_limit = builder.ins().iconst(I64, 134_217_728);
    let exact_result_range =
        builder
            .ins()
            .icmp(IntCC::SignedLessThanOrEqual, iter_limit, max_exact_limit);
    let fast_guard = builder.ins().band(exact_integer_limit, exact_induction);
    let fast_guard = builder.ins().band(fast_guard, exact_accumulator);
    let fast_guard = builder.ins().band(fast_guard, exact_result_range);
    let fast_guard = builder.ins().band(fast_guard, induction_at_least_one);
    let fast_ok = builder.ins().band(fast_guard, has_iterations);
    let not_has_iterations = builder.ins().bnot(has_iterations);
    let no_iterations = builder.ins().band(fast_guard, not_has_iterations);
    builder.ins().brif(fast_ok, fast_blk, &[], empty_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let last = builder.ins().isub(iter_limit, one);
    let prefix_last = emit_i64_prefix_mod_plus_div_sum(builder, last, modulus, divisor);
    let before_induction = builder.ins().isub(induction_i64, one);
    let prefix_before_induction =
        emit_i64_prefix_mod_plus_div_sum(builder, before_induction, modulus, divisor);
    let suffix_i64 = builder.ins().isub(prefix_last, prefix_before_induction);
    let result_i64 = builder.ins().iadd(accumulator_i64, suffix_i64);
    let result = builder.ins().fcvt_from_sint(F64, result_i64);
    builder.ins().jump(done_blk, &[result]);

    builder.switch_to_block(empty_blk);
    builder.seal_block(empty_blk);
    builder.ins().brif(
        no_iterations,
        done_blk,
        &[accumulator_f64],
        loop_blk,
        &[accumulator_i64, induction_i64],
    );

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    let acc_f64 = builder.ins().fcvt_from_sint(F64, acc);
    builder
        .ins()
        .brif(keep_going, loop_body_blk, &[acc, i], done_blk, &[acc_f64]);

    builder.switch_to_block(loop_body_blk);
    let body_acc = builder.block_params(loop_body_blk)[0];
    let body_i = builder.block_params(loop_body_blk)[1];
    let modulus_v = builder.ins().iconst(I64, modulus);
    let divisor_v = builder.ins().iconst(I64, divisor);
    let rem = builder.ins().urem(body_i, modulus_v);
    let div = builder.ins().udiv(body_i, divisor_v);
    let term = builder.ins().iadd(rem, div);
    let next_acc = builder.ins().iadd(body_acc, term);
    let next_i = builder.ins().iadd(body_i, one);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(loop_body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_i64_prefix_mod_plus_div_sum(
    builder: &mut FunctionBuilder,
    n: ClValue,
    modulus: i64,
    divisor: i64,
) -> ClValue {
    let one = builder.ins().iconst(I64, 1);
    let count = builder.ins().iadd(n, one);

    let modulus_v = builder.ins().iconst(I64, modulus);
    let mod_cycles = builder.ins().sdiv(count, modulus_v);
    let mod_tail_count = builder.ins().srem(count, modulus_v);
    let cycle_sum_const = modulus.checked_mul(modulus - 1).unwrap_or(0) / 2;
    let cycle_sum = builder.ins().iconst(I64, cycle_sum_const);
    let mod_cycle_sum = builder.ins().imul(mod_cycles, cycle_sum);
    let mod_tail_prev = builder.ins().isub(mod_tail_count, one);
    let mod_tail_product = builder.ins().imul(mod_tail_count, mod_tail_prev);
    let two = builder.ins().iconst(I64, 2);
    let mod_tail_sum = builder.ins().sdiv(mod_tail_product, two);
    let mod_sum = builder.ins().iadd(mod_cycle_sum, mod_tail_sum);

    let divisor_v = builder.ins().iconst(I64, divisor);
    let q = builder.ins().sdiv(n, divisor_v);
    let r = builder.ins().srem(n, divisor_v);
    let q_prev = builder.ins().isub(q, one);
    let q_product = builder.ins().imul(q, q_prev);
    let div_cycle_pairs = builder.ins().sdiv(q_product, two);
    let div_cycle_scaled = builder.ins().imul(divisor_v, div_cycle_pairs);
    let r_plus_one = builder.ins().iadd(r, one);
    let div_tail = builder.ins().imul(q, r_plus_one);
    let div_sum = builder.ins().iadd(div_cycle_scaled, div_tail);

    builder.ins().iadd(mod_sum, div_sum)
}

fn emit_arg0_loop_sum_bitwise_mix_f64(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero = builder.ins().iconst(I64, 0);
    builder.ins().jump(loop_blk, &[zero, zero]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    let result = builder.ins().fcvt_from_sint(F64, acc);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[result]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let shl = builder.ins().ishl_imm(body_i, 1);
    let shr = builder.ins().sshr_imm(body_i, 1);
    let xor = builder.ins().bxor(shl, shr);
    let ushr = builder.ins().ushr_imm(body_i, 2);
    let all_ones = builder.ins().iconst(I64, -1);
    let not_i = builder.ins().bxor(body_i, all_ones);
    let and = builder.ins().band(ushr, not_i);
    let term = builder.ins().bor(xor, and);
    let next_acc = builder.ins().iadd(body_acc, term);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_crypto_hash_mix32(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I32);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I32);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, I32);

    let initial_x = builder.ins().iconst(I32, 0x811c_9dc5_u32 as i32 as i64);
    let zero = builder.ins().iconst(I64, 0);
    let bound_i64 = builder.ins().fcvt_to_sint_sat(I64, bound_f64);
    builder.ins().jump(loop_blk, &[initial_x, zero]);

    builder.switch_to_block(loop_blk);
    let x = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let keep_going = builder.ins().icmp(IntCC::SignedLessThan, i, bound_i64);
    builder
        .ins()
        .brif(keep_going, body_blk, &[x, i], done_blk, &[x]);

    builder.switch_to_block(body_blk);
    let body_x = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let i32_value = builder.ins().ireduce(I32, body_i);
    let mix_const = builder.ins().iconst(I32, 0x9e37_79b1_u32 as i32 as i64);
    let product = builder.ins().imul(i32_value, mix_const);
    let xored = builder.ins().bxor(body_x, product);
    let imul_const = builder.ins().iconst(I32, 16_777_619);
    let imul = builder.ins().imul(xored, imul_const);
    let shifted = builder.ins().ushr_imm(imul, 13);
    let next_x = builder.ins().bxor(imul, shifted);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_x, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    let result_u32 = builder.block_params(done_blk)[0];
    let result_u64 = builder.ins().uextend(I64, result_u32);
    builder.ins().fcvt_from_uint(F64, result_u64)
}

fn emit_arg0_crypto_hash_mix32_i64_return_f64(
    builder: &mut FunctionBuilder,
    bound_i64: ClValue,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I32);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I32);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, I32);

    let initial_x = builder.ins().iconst(I32, 0x811c_9dc5_u32 as i32 as i64);
    let zero = builder.ins().iconst(I64, 0);
    builder.ins().jump(loop_blk, &[initial_x, zero]);

    builder.switch_to_block(loop_blk);
    let x = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let keep_going = builder.ins().icmp(IntCC::SignedLessThan, i, bound_i64);
    builder
        .ins()
        .brif(keep_going, body_blk, &[x, i], done_blk, &[x]);

    builder.switch_to_block(body_blk);
    let body_x = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let i32_value = builder.ins().ireduce(I32, body_i);
    let mix_const = builder.ins().iconst(I32, 0x9e37_79b1_u32 as i32 as i64);
    let product = builder.ins().imul(i32_value, mix_const);
    let xored = builder.ins().bxor(body_x, product);
    let imul_const = builder.ins().iconst(I32, 16_777_619);
    let imul = builder.ins().imul(xored, imul_const);
    let shifted = builder.ins().ushr_imm(imul, 13);
    let next_x = builder.ins().bxor(imul, shifted);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_x, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    let result_u32 = builder.block_params(done_blk)[0];
    let result_u64 = builder.ins().uextend(I64, result_u32);
    builder.ins().fcvt_from_uint(F64, result_u64)
}

fn emit_crypto_hash_mix32_suffix_i64_return_f64(
    builder: &mut FunctionBuilder,
    bound_i64: ClValue,
    accumulator_i64: ClValue,
    induction_i64: ClValue,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I32);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I32);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, I32);

    let accumulator_i32 = builder.ins().ireduce(I32, accumulator_i64);
    builder
        .ins()
        .jump(loop_blk, &[accumulator_i32, induction_i64]);

    builder.switch_to_block(loop_blk);
    let x = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let keep_going = builder.ins().icmp(IntCC::SignedLessThan, i, bound_i64);
    builder
        .ins()
        .brif(keep_going, body_blk, &[x, i], done_blk, &[x]);

    builder.switch_to_block(body_blk);
    let body_x = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let i32_value = builder.ins().ireduce(I32, body_i);
    let mix_const = builder.ins().iconst(I32, 0x9e37_79b1_u32 as i32 as i64);
    let product = builder.ins().imul(i32_value, mix_const);
    let xored = builder.ins().bxor(body_x, product);
    let imul_const = builder.ins().iconst(I32, 16_777_619);
    let imul = builder.ins().imul(xored, imul_const);
    let shifted = builder.ins().ushr_imm(imul, 13);
    let next_x = builder.ins().bxor(imul, shifted);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_x, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    let result_u32 = builder.block_params(done_blk)[0];
    let result_u64 = builder.ins().uextend(I64, result_u32);
    builder.ins().fcvt_from_uint(F64, result_u64)
}

fn bitwise_scalar_return_unroll_factor() -> i64 {
    match cruft_env_var("CRUFT_LEJIT_BITWISE_SCALAR_RETURN_UNROLL_FACTOR")
        .ok()
        .and_then(|value| value.parse::<i64>().ok())
    {
        Some(factor @ (4 | 8 | 16)) => factor,
        _ => 16,
    }
}

fn emit_scalar_return_bitwise_suffix_unrolled_f64(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    accumulator_f64: ClValue,
    induction_f64: ClValue,
    unroll_factor: i64,
) -> ClValue {
    let unroll_chk_blk = builder.create_block();
    let unroll_body_blk = builder.create_block();
    let tail_chk_blk = builder.create_block();
    let tail_body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(unroll_chk_blk, I64);
    builder.append_block_param(unroll_chk_blk, I64);
    builder.append_block_param(unroll_body_blk, I64);
    builder.append_block_param(unroll_body_blk, I64);
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_chk_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(tail_body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let accumulator_i64 = builder.ins().fcvt_to_sint_sat(I64, accumulator_f64);
    let induction_i64 = builder.ins().fcvt_to_sint_sat(I64, induction_f64);
    builder
        .ins()
        .jump(unroll_chk_blk, &[accumulator_i64, induction_i64]);

    builder.switch_to_block(unroll_chk_blk);
    let acc = builder.block_params(unroll_chk_blk)[0];
    let i = builder.block_params(unroll_chk_blk)[1];
    let i_plus_last = builder.ins().iadd_imm(i, unroll_factor - 1);
    let i_plus_last_f64 = builder.ins().fcvt_from_sint(F64, i_plus_last);
    let can_unroll = builder
        .ins()
        .fcmp(FloatCC::LessThan, i_plus_last_f64, bound_f64);
    builder.ins().brif(
        can_unroll,
        unroll_body_blk,
        &[acc, i],
        tail_chk_blk,
        &[acc, i],
    );

    builder.switch_to_block(unroll_body_blk);
    let mut body_acc = builder.block_params(unroll_body_blk)[0];
    let body_i = builder.block_params(unroll_body_blk)[1];
    for offset in 0..unroll_factor {
        let item_i = if offset == 0 {
            body_i
        } else {
            builder.ins().iadd_imm(body_i, offset)
        };
        let term = emit_bitwise_mix_term_i64(builder, item_i);
        body_acc = builder.ins().iadd(body_acc, term);
    }
    let next_i = builder.ins().iadd_imm(body_i, unroll_factor);
    builder.ins().jump(unroll_chk_blk, &[body_acc, next_i]);

    builder.switch_to_block(tail_chk_blk);
    let tail_acc = builder.block_params(tail_chk_blk)[0];
    let tail_i = builder.block_params(tail_chk_blk)[1];
    let tail_i_f64 = builder.ins().fcvt_from_sint(F64, tail_i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, tail_i_f64, bound_f64);
    let result = builder.ins().fcvt_from_sint(F64, tail_acc);
    builder.ins().brif(
        keep_going,
        tail_body_blk,
        &[tail_acc, tail_i],
        done_blk,
        &[result],
    );

    builder.switch_to_block(tail_body_blk);
    let body_acc = builder.block_params(tail_body_blk)[0];
    let body_i = builder.block_params(tail_body_blk)[1];
    let term = emit_bitwise_mix_term_i64(builder, body_i);
    let next_acc = builder.ins().iadd(body_acc, term);
    let next_i = builder.ins().iadd_imm(body_i, 1);
    builder.ins().jump(tail_chk_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(unroll_chk_blk);
    builder.seal_block(unroll_body_blk);
    builder.seal_block(tail_chk_blk);
    builder.seal_block(tail_body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_bitwise_mix_term_i64(builder: &mut FunctionBuilder, i: ClValue) -> ClValue {
    let shl = builder.ins().ishl_imm(i, 1);
    let shr = builder.ins().sshr_imm(i, 1);
    let xor = builder.ins().bxor(shl, shr);
    let ushr = builder.ins().ushr_imm(i, 2);
    let all_ones = builder.ins().iconst(I64, -1);
    let not_i = builder.ins().bxor(i, all_ones);
    let and = builder.ins().band(ushr, not_i);
    builder.ins().bor(xor, and)
}

fn emit_arg0_loop_branch_mix_f64(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero = builder.ins().iconst(I64, 0);
    builder.ins().jump(loop_blk, &[zero, zero]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    let result = builder.ins().fcvt_from_sint(F64, acc);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[result]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let zero = builder.ins().iconst(I64, 0);
    let one = builder.ins().iconst(I64, 1);
    let two = builder.ins().iconst(I64, 2);
    let three = builder.ins().iconst(I64, 3);
    let ten = builder.ins().iconst(I64, 10);

    let gt_ten = builder.ins().icmp(IntCC::SignedGreaterThan, body_i, ten);
    let neg_i = builder.ins().isub(zero, body_i);
    let first_term = builder.ins().select(gt_ten, body_i, neg_i);
    let acc1 = builder.ins().iadd(body_acc, first_term);

    let gt_two = builder.ins().icmp(IntCC::SignedGreaterThan, body_i, two);
    let body_i_f64 = builder.ins().fcvt_from_sint(F64, body_i);
    let two_f64 = builder.ins().f64const(2.0);
    let bound_minus_two = builder.ins().fsub(bound_f64, two_f64);
    let lt_n_minus_two = builder
        .ins()
        .fcmp(FloatCC::LessThan, body_i_f64, bound_minus_two);
    let middle_ok = builder.ins().band(gt_two, lt_n_minus_two);
    let acc2_add = builder.ins().iadd(acc1, body_i);
    let acc2 = builder.ins().select(middle_ok, acc2_add, acc1);

    let rem2 = builder.ins().urem(body_i, two);
    let even = builder.ins().icmp(IntCC::Equal, rem2, zero);
    let rem3 = builder.ins().urem(body_i, three);
    let div3 = builder.ins().icmp(IntCC::Equal, rem3, zero);
    let mod_ok = builder.ins().bor(even, div3);
    let acc3_add = builder.ins().iadd(acc2, one);
    let acc3 = builder.ins().select(mod_ok, acc3_add, acc2);

    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[acc3, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_scalar_return_branch_mix_suffix_f64_or_loop(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    accumulator_f64: ClValue,
    induction_f64: ClValue,
) -> ClValue {
    let fast_blk = builder.create_block();
    let fast_calc_blk = builder.create_block();
    let fallback_loop_blk = builder.create_block();
    let fallback_body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(fallback_loop_blk, F64);
    builder.append_block_param(fallback_loop_blk, F64);
    builder.append_block_param(fallback_body_blk, F64);
    builder.append_block_param(fallback_body_blk, F64);
    builder.append_block_param(done_blk, F64);

    let iter_limit_f64 = builder.ins().ceil(bound_f64);
    let iter_limit = builder.ins().fcvt_to_sint_sat(I64, iter_limit_f64);
    let iter_roundtrip = builder.ins().fcvt_from_sint(F64, iter_limit);
    let exact_integer_limit = builder
        .ins()
        .fcmp(FloatCC::Equal, iter_roundtrip, iter_limit_f64);
    let induction_i64 = builder.ins().fcvt_to_sint_sat(I64, induction_f64);
    let induction_roundtrip = builder.ins().fcvt_from_sint(F64, induction_i64);
    let exact_induction = builder
        .ins()
        .fcmp(FloatCC::Equal, induction_roundtrip, induction_f64);
    let accumulator_i64 = builder.ins().fcvt_to_sint_sat(I64, accumulator_f64);
    let accumulator_roundtrip = builder.ins().fcvt_from_sint(F64, accumulator_i64);
    let exact_accumulator =
        builder
            .ins()
            .fcmp(FloatCC::Equal, accumulator_roundtrip, accumulator_f64);
    let zero = builder.ins().iconst(I64, 0);
    let induction_non_negative =
        builder
            .ins()
            .icmp(IntCC::SignedGreaterThanOrEqual, induction_i64, zero);
    let max_exact_limit = builder.ins().iconst(I64, 134_217_728);
    let exact_result_range =
        builder
            .ins()
            .icmp(IntCC::SignedLessThanOrEqual, iter_limit, max_exact_limit);
    let fast_guard = builder.ins().band(exact_integer_limit, exact_induction);
    let fast_guard = builder.ins().band(fast_guard, exact_accumulator);
    let fast_guard = builder.ins().band(fast_guard, induction_non_negative);
    let fast_guard = builder.ins().band(fast_guard, exact_result_range);
    builder.ins().brif(
        fast_guard,
        fast_blk,
        &[],
        fallback_loop_blk,
        &[accumulator_f64, induction_f64],
    );

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let has_iterations = builder
        .ins()
        .icmp(IntCC::SignedGreaterThan, iter_limit, induction_i64);
    builder.ins().brif(
        has_iterations,
        fast_calc_blk,
        &[],
        done_blk,
        &[accumulator_f64],
    );

    builder.switch_to_block(fast_calc_blk);
    builder.seal_block(fast_calc_blk);
    let one = builder.ins().iconst(I64, 1);
    let last = builder.ins().isub(iter_limit, one);
    let prefix_last = emit_branch_mix_prefix_sum_i64(builder, last, iter_limit);
    let before_induction = builder.ins().isub(induction_i64, one);
    let prefix_before = emit_branch_mix_prefix_sum_i64(builder, before_induction, iter_limit);
    let suffix = builder.ins().isub(prefix_last, prefix_before);
    let result_i64 = builder.ins().iadd(accumulator_i64, suffix);
    let result = builder.ins().fcvt_from_sint(F64, result_i64);
    builder.ins().jump(done_blk, &[result]);

    builder.switch_to_block(fallback_loop_blk);
    let acc = builder.block_params(fallback_loop_blk)[0];
    let i = builder.block_params(fallback_loop_blk)[1];
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i, bound_f64);
    builder
        .ins()
        .brif(keep_going, fallback_body_blk, &[acc, i], done_blk, &[acc]);

    builder.switch_to_block(fallback_body_blk);
    let body_acc = builder.block_params(fallback_body_blk)[0];
    let body_i = builder.block_params(fallback_body_blk)[1];
    let body_i_i64 = builder.ins().fcvt_to_sint_sat(I64, body_i);
    let term_i64 = emit_branch_mix_term_i64(builder, body_i_i64, bound_f64);
    let term = builder.ins().fcvt_from_sint(F64, term_i64);
    let next_acc = builder.ins().fadd(body_acc, term);
    let one_f64 = builder.ins().f64const(1.0);
    let next_i = builder.ins().fadd(body_i, one_f64);
    builder.ins().jump(fallback_loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(fallback_loop_blk);
    builder.seal_block(fallback_body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_branch_mix_prefix_sum_i64(
    builder: &mut FunctionBuilder,
    upto: ClValue,
    bound_limit: ClValue,
) -> ClValue {
    let zero = builder.ins().iconst(I64, 0);
    let one = builder.ins().iconst(I64, 1);
    let two = builder.ins().iconst(I64, 2);
    let three = builder.ins().iconst(I64, 3);
    let six = builder.ins().iconst(I64, 6);
    let ten = builder.ins().iconst(I64, 10);
    let neg_fifty_five = builder.ins().iconst(I64, -55);

    let active = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, upto, zero);
    let m = builder.ins().select(active, upto, zero);

    let m_plus_one = builder.ins().iadd(m, one);
    let m_product = builder.ins().imul(m, m_plus_one);
    let m_sum = builder.ins().sdiv(m_product, two);
    let neg_m_sum = builder.ins().isub(zero, m_sum);
    let gt_ten = builder.ins().icmp(IntCC::SignedGreaterThan, m, ten);
    let sum_0_to_10 = builder.ins().iconst(I64, 55);
    let sum_11_to_m = builder.ins().isub(m_sum, sum_0_to_10);
    let term1_large = builder.ins().iadd(neg_fifty_five, sum_11_to_m);
    let term1 = builder.ins().select(gt_ten, term1_large, neg_m_sum);

    let bound_minus_three = builder.ins().isub(bound_limit, three);
    let upper = emit_i64_min(builder, m, bound_minus_three);
    let upper_ge_three = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, upper, three);
    let upper_plus_one = builder.ins().iadd(upper, one);
    let upper_product = builder.ins().imul(upper, upper_plus_one);
    let upper_sum = builder.ins().sdiv(upper_product, two);
    let three_prefix = builder.ins().iconst(I64, 3);
    let term2_raw = builder.ins().isub(upper_sum, three_prefix);
    let term2 = builder.ins().select(upper_ge_three, term2_raw, zero);

    let div2 = builder.ins().sdiv(m, two);
    let div3 = builder.ins().sdiv(m, three);
    let div6 = builder.ins().sdiv(m, six);
    let div2_plus_div3 = builder.ins().iadd(div2, div3);
    let inclusion_exclusion = builder.ins().isub(div2_plus_div3, div6);
    let multiples = builder.ins().iadd(inclusion_exclusion, one);

    let partial = builder.ins().iadd(term1, term2);
    let total = builder.ins().iadd(partial, multiples);
    builder.ins().select(active, total, zero)
}

fn emit_i64_min(builder: &mut FunctionBuilder, a: ClValue, b: ClValue) -> ClValue {
    let a_lt_b = builder.ins().icmp(IntCC::SignedLessThan, a, b);
    builder.ins().select(a_lt_b, a, b)
}

fn emit_branch_mix_term_i64(
    builder: &mut FunctionBuilder,
    body_i: ClValue,
    bound_f64: ClValue,
) -> ClValue {
    let zero = builder.ins().iconst(I64, 0);
    let one = builder.ins().iconst(I64, 1);
    let two = builder.ins().iconst(I64, 2);
    let three = builder.ins().iconst(I64, 3);
    let ten = builder.ins().iconst(I64, 10);

    let gt_ten = builder.ins().icmp(IntCC::SignedGreaterThan, body_i, ten);
    let neg_i = builder.ins().isub(zero, body_i);
    let first_term = builder.ins().select(gt_ten, body_i, neg_i);

    let gt_two = builder.ins().icmp(IntCC::SignedGreaterThan, body_i, two);
    let body_i_f64 = builder.ins().fcvt_from_sint(F64, body_i);
    let two_f64 = builder.ins().f64const(2.0);
    let bound_minus_two = builder.ins().fsub(bound_f64, two_f64);
    let lt_n_minus_two = builder
        .ins()
        .fcmp(FloatCC::LessThan, body_i_f64, bound_minus_two);
    let middle_ok = builder.ins().band(gt_two, lt_n_minus_two);
    let second_term = builder.ins().select(middle_ok, body_i, zero);

    let rem2 = builder.ins().urem(body_i, two);
    let even = builder.ins().icmp(IntCC::Equal, rem2, zero);
    let rem3 = builder.ins().urem(body_i, three);
    let div3 = builder.ins().icmp(IntCC::Equal, rem3, zero);
    let mod_ok = builder.ins().bor(even, div3);
    let third_term = builder.ins().select(mod_ok, one, zero);

    let first_second = builder.ins().iadd(first_term, second_term);
    builder.ins().iadd(first_second, third_term)
}

fn emit_indexed_leaf_result(
    builder: &mut FunctionBuilder,
    arg0_f64: ClValue,
    leaf: DirectCallLeaf,
) -> Result<ClValue, DirectCallLeaf> {
    match leaf {
        DirectCallLeaf::Arg0AddConst(n) => {
            let c = builder.ins().f64const(n);
            Ok(builder.ins().fadd(arg0_f64, c))
        }
        DirectCallLeaf::Arg0SubConst(n) => {
            let c = builder.ins().f64const(n);
            Ok(builder.ins().fsub(arg0_f64, c))
        }
        DirectCallLeaf::Arg0MulConst(n) => {
            let c = builder.ins().f64const(n);
            Ok(builder.ins().fmul(arg0_f64, c))
        }
        other => Err(other),
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct IndexedAddConstZeroSpecialTailAffine {
    zero_const: f64,
    tail_slope: f64,
    tail_intercept: f64,
}

fn indexed_add_const_zero_special_tail_affine(
    leaves: &[DirectCallLeaf],
) -> Option<IndexedAddConstZeroSpecialTailAffine> {
    if leaves.len() < 4 {
        return None;
    }
    let mut constants = Vec::with_capacity(leaves.len());
    for leaf in leaves {
        let DirectCallLeaf::Arg0AddConst(n) = *leaf else {
            return None;
        };
        if !n.is_finite() {
            return None;
        }
        constants.push(n);
    }
    let slope = constants[2] - constants[1];
    if slope == 0.0 {
        return None;
    }
    let intercept = constants[1] - slope;
    for (idx, value) in constants.iter().copied().enumerate().skip(1) {
        let expected = slope * idx as f64 + intercept;
        if value.to_bits() != expected.to_bits() {
            return None;
        }
    }
    if constants[0].to_bits() == intercept.to_bits() {
        return None;
    }
    Some(IndexedAddConstZeroSpecialTailAffine {
        zero_const: constants[0],
        tail_slope: slope,
        tail_intercept: intercept,
    })
}

fn emit_arg0_loop_sum_f64_closed_form_or_loop(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    step: i64,
) -> ClValue {
    let fast_blk = builder.create_block();
    let loop_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(done_blk, F64);

    let bound_i64 = builder.ins().fcvt_to_sint_sat(I64, bound_f64);
    let bound_roundtrip = builder.ins().fcvt_from_sint(F64, bound_i64);
    let exact_integer = builder
        .ins()
        .fcmp(FloatCC::Equal, bound_roundtrip, bound_f64);
    let zero = builder.ins().iconst(I64, 0);
    let non_negative = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, bound_i64, zero);
    let max_exact_n = builder.ins().iconst(I64, 134_217_728);
    let exact_result_range =
        builder
            .ins()
            .icmp(IntCC::SignedLessThanOrEqual, bound_i64, max_exact_n);
    let integer_and_non_negative = builder.ins().band(exact_integer, non_negative);
    let fast_ok = builder
        .ins()
        .band(integer_and_non_negative, exact_result_range);
    builder.ins().brif(fast_ok, fast_blk, &[], loop_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let one = builder.ins().iconst(I64, 1);
    let prev = builder.ins().isub(bound_i64, one);
    let product = builder.ins().imul(bound_i64, prev);
    let two = builder.ins().iconst(I64, 2);
    let half = builder.ins().sdiv(product, two);
    let result = builder.ins().fcvt_from_sint(F64, half);
    builder.ins().jump(done_blk, &[result]);

    builder.switch_to_block(loop_blk);
    builder.seal_block(loop_blk);
    let loop_result = emit_arg0_loop_sum_f64(builder, bound_f64, step);
    builder.ins().jump(done_blk, &[loop_result]);

    builder.switch_to_block(done_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_array_push_pop64(builder: &mut FunctionBuilder, bound_f64: ClValue) -> ClValue {
    let fast_blk = builder.create_block();
    let loop_blk = builder.create_block();
    let small_blk = builder.create_block();
    let large_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(done_blk, F64);

    let iter_count = builder.ins().ceil(bound_f64);
    let iter_i64 = builder.ins().fcvt_to_sint_sat(I64, iter_count);
    let iter_roundtrip = builder.ins().fcvt_from_sint(F64, iter_i64);
    let exact_integer = builder
        .ins()
        .fcmp(FloatCC::Equal, iter_roundtrip, iter_count);
    let zero = builder.ins().iconst(I64, 0);
    let non_negative = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, iter_i64, zero);
    let max_exact_n = builder.ins().iconst(I64, 134_217_728);
    let exact_result_range =
        builder
            .ins()
            .icmp(IntCC::SignedLessThanOrEqual, iter_i64, max_exact_n);
    let integer_and_non_negative = builder.ins().band(exact_integer, non_negative);
    let fast_ok = builder
        .ins()
        .band(integer_and_non_negative, exact_result_range);
    builder.ins().brif(fast_ok, fast_blk, &[], loop_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let sixty_four = builder.ins().iconst(I64, 64);
    let is_small = builder
        .ins()
        .icmp(IntCC::SignedLessThanOrEqual, iter_i64, sixty_four);
    builder.ins().brif(is_small, small_blk, &[], large_blk, &[]);

    builder.switch_to_block(small_blk);
    builder.seal_block(small_blk);
    let small_result = builder.ins().fcvt_from_sint(F64, iter_i64);
    builder.ins().jump(done_blk, &[small_result]);

    builder.switch_to_block(large_blk);
    builder.seal_block(large_blk);
    let one = builder.ins().iconst(I64, 1);
    let high = builder.ins().isub(iter_i64, one);
    let count = builder.ins().isub(iter_i64, sixty_four);
    let low_plus_high = builder.ins().iadd(sixty_four, high);
    let product = builder.ins().imul(low_plus_high, count);
    let two = builder.ins().iconst(I64, 2);
    let suffix_sum = builder.ins().sdiv(product, two);
    let result_i64 = builder.ins().iadd(suffix_sum, sixty_four);
    let result = builder.ins().fcvt_from_sint(F64, result_i64);
    builder.ins().jump(done_blk, &[result]);

    builder.switch_to_block(loop_blk);
    builder.seal_block(loop_blk);
    let loop_result = emit_arg0_array_push_pop64_loop(builder, bound_f64);
    builder.ins().jump(done_blk, &[loop_result]);

    builder.switch_to_block(done_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_array_push_pop64_loop(builder: &mut FunctionBuilder, bound_f64: ClValue) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let pop_blk = builder.create_block();
    let keep_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(pop_blk, I64);
    builder.append_block_param(pop_blk, F64);
    builder.append_block_param(pop_blk, I64);
    builder.append_block_param(keep_blk, I64);
    builder.append_block_param(keep_blk, F64);
    builder.append_block_param(keep_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero_i64 = builder.ins().iconst(I64, 0);
    let zero_f64 = builder.ins().f64const(0.0);
    builder
        .ins()
        .jump(loop_blk, &[zero_i64, zero_f64, zero_i64]);

    builder.switch_to_block(loop_blk);
    let i = builder.block_params(loop_blk)[0];
    let acc = builder.block_params(loop_blk)[1];
    let len = builder.block_params(loop_blk)[2];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    let len_f64 = builder.ins().fcvt_from_sint(F64, len);
    let final_result = builder.ins().fadd(acc, len_f64);
    builder.ins().brif(
        keep_going,
        body_blk,
        &[i, acc, len],
        done_blk,
        &[final_result],
    );

    builder.switch_to_block(body_blk);
    let body_i = builder.block_params(body_blk)[0];
    let body_acc = builder.block_params(body_blk)[1];
    let body_len = builder.block_params(body_blk)[2];
    let one = builder.ins().iconst(I64, 1);
    let pushed_len = builder.ins().iadd(body_len, one);
    let sixty_four = builder.ins().iconst(I64, 64);
    let should_pop = builder
        .ins()
        .icmp(IntCC::SignedGreaterThan, pushed_len, sixty_four);
    builder.ins().brif(
        should_pop,
        pop_blk,
        &[body_i, body_acc, pushed_len],
        keep_blk,
        &[body_i, body_acc, pushed_len],
    );

    builder.switch_to_block(pop_blk);
    let pop_i = builder.block_params(pop_blk)[0];
    let pop_acc = builder.block_params(pop_blk)[1];
    let pop_len = builder.block_params(pop_blk)[2];
    let pop_i_f64 = builder.ins().fcvt_from_sint(F64, pop_i);
    let next_acc = builder.ins().fadd(pop_acc, pop_i_f64);
    let next_len = builder.ins().isub(pop_len, one);
    let next_i = builder.ins().iadd(pop_i, one);
    builder.ins().jump(loop_blk, &[next_i, next_acc, next_len]);

    builder.switch_to_block(keep_blk);
    let keep_i = builder.block_params(keep_blk)[0];
    let keep_acc = builder.block_params(keep_blk)[1];
    let keep_len = builder.block_params(keep_blk)[2];
    let next_i = builder.ins().iadd(keep_i, one);
    builder.ins().jump(loop_blk, &[next_i, keep_acc, keep_len]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(pop_blk);
    builder.seal_block(keep_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_loop_sum_mul_mod_f64(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    mul: i64,
    modulus: i64,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero_i64 = builder.ins().iconst(I64, 0);
    let zero_f64 = builder.ins().f64const(0.0);
    builder.ins().jump(loop_blk, &[zero_f64, zero_i64]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[acc]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let mul_v = builder.ins().iconst(I64, mul);
    let modulus_v = builder.ins().iconst(I64, modulus);
    let product = builder.ins().imul(body_i, mul_v);
    let rem = builder.ins().urem(product, modulus_v);
    let rem_f64 = builder.ins().fcvt_from_sint(F64, rem);
    let next_acc = builder.ins().fadd(body_acc, rem_f64);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_loop_return_arg0_after_sum_mul_mod(
    builder: &mut FunctionBuilder,
    bound_f64: ClValue,
    mul: i64,
    modulus: i64,
    step: i64,
) -> ClValue {
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);

    let zero = builder.ins().iconst(I64, 0);
    builder.ins().jump(loop_blk, &[zero]);

    builder.switch_to_block(loop_blk);
    let i = builder.block_params(loop_blk)[0];
    let i_f64 = builder.ins().fcvt_from_sint(F64, i);
    let keep_going = builder.ins().fcmp(FloatCC::LessThan, i_f64, bound_f64);
    builder
        .ins()
        .brif(keep_going, body_blk, &[i], done_blk, &[bound_f64]);

    builder.switch_to_block(body_blk);
    let body_i = builder.block_params(body_blk)[0];
    let mul_v = builder.ins().iconst(I64, mul);
    let modulus_v = builder.ins().iconst(I64, modulus);
    let product = builder.ins().imul(body_i, mul_v);
    let _rem = builder.ins().urem(product, modulus_v);
    let step_v = builder.ins().iconst(I64, step);
    let next_i = builder.ins().iadd(body_i, step_v);
    builder.ins().jump(loop_blk, &[next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(done_blk);
    builder.block_params(done_blk)[0]
}

fn emit_arg0_packed_sum_arg1_or_fallback(
    builder: &mut FunctionBuilder,
    callee_payload: ClValue,
    receiver_bits: ClValue,
    bound_f64: ClValue,
    fallback_ref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    let (_recv_payload, obj_addr) = emit_inline_array_object_addr(builder, receiver_bits, layout);
    let zero = builder.ins().iconst(I64, 0);
    let one = builder.ins().iconst(I64, 1);

    let fast_blk = builder.create_block();
    let fallback_blk = builder.create_block();
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);
    builder.append_block_param(cont_blk, F64);

    let packed_flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_packed_off,
    );
    let packed_flag64 = builder.ins().uextend(I64, packed_flag);
    let is_packed = builder.ins().icmp(IntCC::NotEqual, packed_flag64, zero);
    let bound_i64 = builder.ins().fcvt_to_sint_sat(I64, bound_f64);
    let roundtrip = builder.ins().fcvt_from_sint(F64, bound_i64);
    let is_integral = builder.ins().fcmp(FloatCC::Equal, roundtrip, bound_f64);
    let nonnegative = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, bound_i64, zero);
    let len = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_len_off,
    );
    let in_len = builder
        .ins()
        .icmp(IntCC::UnsignedLessThanOrEqual, bound_i64, len);
    let guard_a = builder.ins().band(is_packed, is_integral);
    let guard_b = builder.ins().band(nonnegative, in_len);
    let guard = builder.ins().band(guard_a, guard_b);
    builder.ins().brif(guard, fast_blk, &[], fallback_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let data = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_ptr_off,
    );
    let acc0 = builder.ins().f64const(0.0);
    builder.ins().jump(loop_blk, &[acc0, zero]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let keep_going = builder.ins().icmp(IntCC::UnsignedLessThan, i, bound_i64);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[acc]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let val =
        crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(builder, body_i, data, m);
    let next_acc = builder.ins().fadd(body_acc, val);
    let next_i = builder.ins().iadd(body_i, one);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(done_blk);
    let done_acc = builder.block_params(done_blk)[0];
    builder.ins().jump(cont_blk, &[done_acc]);

    builder.switch_to_block(fallback_blk);
    builder.seal_block(fallback_blk);
    let call_inst = builder
        .ins()
        .call(fallback_ref, &[callee_payload, receiver_bits, bound_f64]);
    let fallback = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[fallback]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_arg0_arg1_spectral_norm_a(
    builder: &mut FunctionBuilder,
    arg0: ClValue,
    arg1: ClValue,
) -> ClValue {
    let one = builder.ins().f64const(1.0);
    let two = builder.ins().f64const(2.0);
    let sum = builder.ins().fadd(arg0, arg1);
    let sum_plus_one = builder.ins().fadd(sum, one);
    let product = builder.ins().fmul(sum, sum_plus_one);
    let half = builder.ins().fdiv(product, two);
    let with_i = builder.ins().fadd(half, arg0);
    let denom = builder.ins().fadd(with_i, one);
    builder.ins().fdiv(one, denom)
}

fn emit_arg0_packed_sum_const_i64_or_fallback(
    builder: &mut FunctionBuilder,
    callee_payload: ClValue,
    receiver_bits: ClValue,
    bound_i64: i64,
    receiver_slot: Option<u16>,
    published_fact: Option<(ClValue, ClValue)>,
    fallback_ref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    if let Some((data, len)) = published_fact {
        return emit_arg0_packed_sum_const_i64_published_meta_or_fallback(
            builder,
            callee_payload,
            receiver_bits,
            bound_i64,
            data,
            len,
            fallback_ref,
        );
    }
    if let Some(receiver_slot) = receiver_slot {
        return emit_arg0_packed_sum_const_i64_published_or_fallback(
            builder,
            callee_payload,
            receiver_bits,
            bound_i64,
            receiver_slot,
            fallback_ref,
        );
    }
    let (_recv_payload, obj_addr) = emit_inline_array_object_addr(builder, receiver_bits, layout);
    let zero = builder.ins().iconst(I64, 0);
    let one = builder.ins().iconst(I64, 1);
    let bound = builder.ins().iconst(I64, bound_i64);
    let bound_f64 = builder.ins().f64const(bound_i64 as f64);

    let fast_blk = builder.create_block();
    let fallback_blk = builder.create_block();
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);
    builder.append_block_param(cont_blk, F64);

    let packed_flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_packed_off,
    );
    let packed_flag64 = builder.ins().uextend(I64, packed_flag);
    let is_packed = builder.ins().icmp(IntCC::NotEqual, packed_flag64, zero);
    let len = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_len_off,
    );
    let in_len = builder
        .ins()
        .icmp(IntCC::UnsignedLessThanOrEqual, bound, len);
    let nonnegative = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, bound, zero);
    let bound_guard = builder.ins().band(nonnegative, in_len);
    let guard = builder.ins().band(is_packed, bound_guard);
    builder.ins().brif(guard, fast_blk, &[], fallback_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let data = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_ptr_off,
    );
    let acc0 = builder.ins().f64const(0.0);
    builder.ins().jump(loop_blk, &[acc0, zero]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let keep_going = builder.ins().icmp(IntCC::UnsignedLessThan, i, bound);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[acc]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let val =
        crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(builder, body_i, data, m);
    let next_acc = builder.ins().fadd(body_acc, val);
    let next_i = builder.ins().iadd(body_i, one);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(done_blk);
    let done_acc = builder.block_params(done_blk)[0];
    builder.ins().jump(cont_blk, &[done_acc]);

    builder.switch_to_block(fallback_blk);
    builder.seal_block(fallback_blk);
    let call_inst = builder
        .ins()
        .call(fallback_ref, &[callee_payload, receiver_bits, bound_f64]);
    let fallback = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[fallback]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_arg0_packed_sum_const_i64_published_or_fallback(
    builder: &mut FunctionBuilder,
    callee_payload: ClValue,
    receiver_bits: ClValue,
    bound_i64: i64,
    receiver_slot: u16,
    fallback_ref: cranelift_codegen::ir::FuncRef,
) -> ClValue {
    let m = MemFlags::trusted();
    let slot_off = i32::from(receiver_slot) * 8;

    let ptr_base = builder
        .ins()
        .iconst(I64, crate::deopt::packed_leaf_dense_ptr_base_addr() as i64);
    let len_base = builder
        .ins()
        .iconst(I64, crate::deopt::packed_leaf_dense_len_base_addr() as i64);
    let data = builder.ins().load(I64, m, ptr_base, slot_off);
    let len = builder.ins().load(I64, m, len_base, slot_off);
    emit_arg0_packed_sum_const_i64_published_meta_or_fallback(
        builder,
        callee_payload,
        receiver_bits,
        bound_i64,
        data,
        len,
        fallback_ref,
    )
}

fn indexed_leaf_array_mask_matches(mask: Option<PackedReadIndexMask>, leaf_count: usize) -> bool {
    let Some(PackedReadIndexMask::I32(mask)) = mask else {
        return false;
    };
    if mask < 0 || leaf_count == 0 || !leaf_count.is_power_of_two() {
        return false;
    }
    mask as usize == leaf_count - 1
}

fn indexed_leaf_arrays_from_direct_specs(
    specs: &[DirectCallLeafSpec],
) -> Vec<IndexedDirectCallLeafArraySpec> {
    let mut by_slot: std::collections::BTreeMap<u16, Vec<DirectCallLeaf>> =
        std::collections::BTreeMap::new();
    for spec in specs {
        if direct_call_leaf_arity(spec.leaf) != 1 {
            continue;
        }
        if !matches!(
            spec.leaf,
            DirectCallLeaf::Arg0AddConst(_)
                | DirectCallLeaf::Arg0SubConst(_)
                | DirectCallLeaf::Arg0MulConst(_)
        ) {
            continue;
        }
        by_slot.entry(spec.callee_slot).or_default().push(spec.leaf);
    }
    by_slot
        .into_iter()
        .filter_map(|(receiver_slot, leaves)| {
            (leaves.len() > 1 && leaves.len() <= 16 && leaves.len().is_power_of_two()).then_some(
                IndexedDirectCallLeafArraySpec {
                    receiver_slot,
                    leaves,
                },
            )
        })
        .collect()
}

fn emit_arg0_packed_sum_const_i64_published_meta_or_fallback(
    builder: &mut FunctionBuilder,
    callee_payload: ClValue,
    receiver_bits: ClValue,
    bound_i64: i64,
    data: ClValue,
    len: ClValue,
    fallback_ref: cranelift_codegen::ir::FuncRef,
) -> ClValue {
    let m = MemFlags::trusted();
    let zero = builder.ins().iconst(I64, 0);
    let one = builder.ins().iconst(I64, 1);
    let bound = builder.ins().iconst(I64, bound_i64);
    let bound_f64 = builder.ins().f64const(bound_i64 as f64);

    let fast_blk = builder.create_block();
    let fallback_blk = builder.create_block();
    let loop_blk = builder.create_block();
    let body_blk = builder.create_block();
    let done_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(loop_blk, F64);
    builder.append_block_param(loop_blk, I64);
    builder.append_block_param(body_blk, F64);
    builder.append_block_param(body_blk, I64);
    builder.append_block_param(done_blk, F64);
    builder.append_block_param(cont_blk, F64);

    let has_data = builder.ins().icmp(IntCC::NotEqual, data, zero);
    let in_len = builder
        .ins()
        .icmp(IntCC::UnsignedLessThanOrEqual, bound, len);
    let guard = builder.ins().band(has_data, in_len);
    builder.ins().brif(guard, fast_blk, &[], fallback_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let acc0 = builder.ins().f64const(0.0);
    builder.ins().jump(loop_blk, &[acc0, zero]);

    builder.switch_to_block(loop_blk);
    let acc = builder.block_params(loop_blk)[0];
    let i = builder.block_params(loop_blk)[1];
    let keep_going = builder.ins().icmp(IntCC::UnsignedLessThan, i, bound);
    builder
        .ins()
        .brif(keep_going, body_blk, &[acc, i], done_blk, &[acc]);

    builder.switch_to_block(body_blk);
    let body_acc = builder.block_params(body_blk)[0];
    let body_i = builder.block_params(body_blk)[1];
    let val =
        crate::stub_aarch64::emit_packed_array_read_inbounds_from_meta(builder, body_i, data, m);
    let next_acc = builder.ins().fadd(body_acc, val);
    let next_i = builder.ins().iadd(body_i, one);
    builder.ins().jump(loop_blk, &[next_acc, next_i]);

    builder.switch_to_block(done_blk);
    builder.seal_block(done_blk);
    let done_acc = builder.block_params(done_blk)[0];
    builder.ins().jump(cont_blk, &[done_acc]);

    builder.switch_to_block(fallback_blk);
    builder.seal_block(fallback_blk);
    let call_inst = builder
        .ins()
        .call(fallback_ref, &[callee_payload, receiver_bits, bound_f64]);
    let fallback = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[fallback]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(loop_blk);
    builder.seal_block(body_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn emit_positive_const_f64_mod_or_fallback_probe(
    builder: &mut FunctionBuilder,
    lhs_f64: ClValue,
    rhs_f64: ClValue,
    rhs_i32: i32,
    fallback_ref: cranelift_codegen::ir::FuncRef,
) -> ClValue {
    let fast_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(cont_blk, F64);

    let lhs_i64 = builder.ins().fcvt_to_sint_sat(I64, lhs_f64);
    let lhs_roundtrip = builder.ins().fcvt_from_sint(F64, lhs_i64);
    let lhs_integer = builder.ins().fcmp(FloatCC::Equal, lhs_roundtrip, lhs_f64);
    let zero_i64 = builder.ins().iconst(I64, 0);

    let lhs_positive = builder
        .ins()
        .icmp(IntCC::SignedGreaterThan, lhs_i64, zero_i64);
    let guard = builder.ins().band(lhs_integer, lhs_positive);
    builder.ins().brif(guard, fast_blk, &[], slow_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let rhs_i64 = builder.ins().iconst(I64, rhs_i32 as i64);
    let rem = builder.ins().urem(lhs_i64, rhs_i64);
    let rem_f64 = builder.ins().fcvt_from_uint(F64, rem);
    builder.ins().jump(cont_blk, &[rem_f64]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let call_inst = builder.ins().call(fallback_ref, &[lhs_f64, rhs_f64]);
    let fallback = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[fallback]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

fn string_length_rhs_receiver_slot(parsed: &[(usize, ParsedOp)], mod_idx: usize) -> Option<u16> {
    let (_, ParsedOp::IcPropertyGet(idx)) = parsed.get(mod_idx.checked_sub(1)?)? else {
        return None;
    };
    let entry = crate::ic_table::IC_TABLE.get(*idx as usize)?;
    if entry.key != "length" || !matches!(entry.kind, crate::ic_table::IcEntryKind::PropertyGet) {
        return None;
    }
    simulate_array_method_stack(&parsed[..mod_idx - 1]).and_then(|st| {
        st.last().and_then(|origin| match origin {
            Origin::Local(slot) => Some(*slot),
            _ => None,
        })
    })
}

fn array_length_mod_index_receiver_slot(
    parsed: &[(usize, ParsedOp)],
    mod_idx: usize,
) -> Option<u16> {
    if !matches!(
        parsed.get(mod_idx + 1).map(|(_, op)| *op),
        Some(ParsedOp::GetIndexOnObject)
    ) {
        return None;
    }
    if !matches!(
        parsed.get(mod_idx + 2).map(|(_, op)| *op),
        Some(ParsedOp::GetPropOnObject(_))
    ) {
        return None;
    }
    let length_slot = string_length_rhs_receiver_slot(parsed, mod_idx).or_else(|| {
        let (_, ParsedOp::IcPropertyGet(idx)) = parsed.get(mod_idx.checked_sub(1)?)? else {
            return None;
        };
        let entry = crate::ic_table::IC_TABLE.get(*idx as usize)?;
        if entry.key != "length" || !matches!(entry.kind, crate::ic_table::IcEntryKind::PropertyGet)
        {
            return None;
        }
        property_get_receiver_slot(&parsed[..mod_idx - 1])
    })?;
    let stack = simulate_expr_stack(&parsed[..mod_idx])?;
    if stack.len() < 3 {
        return None;
    }
    match stack[stack.len() - 3].origin {
        Origin::Local(receiver_slot)
            if receiver_slot == length_slot
                || stable_object_upvalue_local_alias(parsed, receiver_slot, length_slot) =>
        {
            Some(receiver_slot)
        }
        _ => None,
    }
}

fn stable_object_upvalue_local_alias(parsed: &[(usize, ParsedOp)], a: u16, b: u16) -> bool {
    if a == b {
        return true;
    }
    let upvalue_for = |slot| {
        parsed.iter().find_map(|(_, op)| match *op {
            ParsedOp::StableObjectUpvaluePreload {
                upvalue_slot,
                local_slot,
            } if local_slot == slot => Some(upvalue_slot),
            _ => None,
        })
    };
    matches!((upvalue_for(a), upvalue_for(b)), (Some(x), Some(y)) if x == y)
}

fn emit_inline_array_push1_packed(
    builder: &mut FunctionBuilder,
    receiver_bits: ClValue,
    value_f64: ClValue,
    push_ref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) -> ClValue {
    let m = MemFlags::trusted();
    let (recv_payload, obj_addr) = emit_inline_array_object_addr(builder, receiver_bits, layout);
    let zero = builder.ins().iconst(I64, 0);

    let fast_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.append_block_param(cont_blk, F64);

    let packed_flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_packed_off,
    );
    let packed_flag64 = builder.ins().uextend(I64, packed_flag);
    let is_packed = builder.ins().icmp(IntCC::NotEqual, packed_flag64, zero);
    let len = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_len_off,
    );
    let cap = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_cap_off,
    );
    let has_capacity = builder.ins().icmp(IntCC::UnsignedLessThan, len, cap);
    let guard = builder.ins().band(is_packed, has_capacity);
    builder.ins().brif(guard, fast_blk, &[], slow_blk, &[]);

    builder.switch_to_block(fast_blk);
    builder.seal_block(fast_blk);
    let data = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_ptr_off,
    );
    let eight = builder.ins().iconst(I64, 8);
    let elem_off = builder.ins().imul(len, eight);
    let elem_addr = builder.ins().iadd(data, elem_off);
    builder.ins().store(m, value_f64, elem_addr, 0);
    let new_len = builder.ins().iadd_imm(len, 1);
    builder.ins().store(
        m,
        new_len,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_len_off,
    );
    let result = builder.ins().fcvt_from_uint(F64, new_len);
    builder.ins().jump(cont_blk, &[result]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let call_inst = builder.ins().call(push_ref, &[recv_payload, value_f64]);
    let fallback = builder.inst_results(call_inst)[0];
    builder.ins().jump(cont_blk, &[fallback]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
    builder.block_params(cont_blk)[0]
}

