fn emit_object_payload_from_bits(builder: &mut FunctionBuilder, receiver_bits: ClValue) -> ClValue {
    let payload_mask = builder.ins().iconst(I64, 0xFFFF_FFFF_FFFF);
    builder.ins().band(receiver_bits, payload_mask)
}

fn emit_inline_setindex_ic(
    builder: &mut FunctionBuilder,
    receiver: ClValue,
    index_i64: ClValue,
    value_f64: ClValue,
    siref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) {
    let m = MemFlags::trusted();
    let mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver, mask);
    let hb_addr = builder
        .ins()
        .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
    let heap_base = builder.ins().load(I64, m, hb_addr, 0);
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    let zero = builder.ins().iconst(I64, 0);

    let packed_blk = builder.create_block();
    let dense_chk_blk = builder.create_block();
    let dense_tag_blk = builder.create_block();
    let dense_store_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();

    let packed_flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_packed_off,
    );
    let packed_flag64 = builder.ins().uextend(I64, packed_flag);
    let is_packed = builder.ins().icmp(IntCC::NotEqual, packed_flag64, zero);
    let plen = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_len_off,
    );
    let p_in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index_i64, plen);
    let p_guard = builder.ins().band(is_packed, p_in_bounds);
    builder
        .ins()
        .brif(p_guard, packed_blk, &[], dense_chk_blk, &[]);

    builder.switch_to_block(packed_blk);
    builder.seal_block(packed_blk);
    let pdata = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_doubles_off + layout.vec_ptr_off,
    );
    let eight = builder.ins().iconst(I64, 8);
    let p_elem_off = builder.ins().imul(index_i64, eight);
    let p_elem_addr = builder.ins().iadd(pdata, p_elem_off);
    builder.ins().store(m, value_f64, p_elem_addr, 0);

    let old_safe_i8 = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_packed_all_safe_i64_off,
    );
    let old_safe64 = builder.ins().uextend(I64, old_safe_i8);
    let old_safe = builder.ins().icmp(IntCC::NotEqual, old_safe64, zero);
    let value_i64 = builder.ins().fcvt_to_sint_sat(I64, value_f64);
    let value_roundtrip = builder.ins().fcvt_from_sint(F64, value_i64);
    let value_integer = builder
        .ins()
        .fcmp(FloatCC::Equal, value_roundtrip, value_f64);
    let safe_hi = builder.ins().iconst(I64, 9_007_199_254_740_992);
    let safe_lo = builder.ins().iconst(I64, -9_007_199_254_740_992);
    let not_too_hi = builder
        .ins()
        .icmp(IntCC::SignedLessThanOrEqual, value_i64, safe_hi);
    let not_too_lo = builder
        .ins()
        .icmp(IntCC::SignedGreaterThanOrEqual, value_i64, safe_lo);
    let in_safe_range = builder.ins().band(not_too_hi, not_too_lo);
    let value_safe = builder.ins().band(value_integer, in_safe_range);
    let new_safe_i8 = builder.ins().band(old_safe, value_safe);
    builder.ins().store(
        m,
        new_safe_i8,
        obj_addr,
        layout.object_array_packed_all_safe_i64_off,
    );

    let false_i8 = builder.ins().iconst(cranelift_codegen::ir::types::I8, 0);
    builder.ins().store(
        m,
        false_i8,
        obj_addr,
        layout.object_dense_i64_sidecar_valid_off,
    );
    builder.ins().jump(cont_blk, &[]);

    builder.switch_to_block(dense_chk_blk);
    builder.seal_block(dense_chk_blk);
    let dense_flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        m,
        obj_addr,
        layout.object_array_dense_off,
    );
    let dense_flag64 = builder.ins().uextend(I64, dense_flag);
    let is_dense = builder.ins().icmp(IntCC::NotEqual, dense_flag64, zero);
    let len = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_elements_off + layout.vec_len_off,
    );
    let in_bounds = builder.ins().icmp(IntCC::UnsignedLessThan, index_i64, len);
    let d_guard = builder.ins().band(is_dense, in_bounds);
    builder
        .ins()
        .brif(d_guard, dense_tag_blk, &[], slow_blk, &[]);

    builder.switch_to_block(dense_tag_blk);
    builder.seal_block(dense_tag_blk);
    let data = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_dense_elements_off + layout.vec_ptr_off,
    );
    let vsize = builder.ins().iconst(I64, layout.value_size as i64);
    let elem_off = builder.ins().imul(index_i64, vsize);
    let elem_addr = builder.ins().iadd(data, elem_off);
    let tag = builder
        .ins()
        .load(cranelift_codegen::ir::types::I8, m, elem_addr, 0);
    let tag64 = builder.ins().uextend(I64, tag);
    let numtag = builder.ins().iconst(I64, layout.value_tag_number as i64);
    let is_num = builder.ins().icmp(IntCC::Equal, tag64, numtag);
    builder
        .ins()
        .brif(is_num, dense_store_blk, &[], slow_blk, &[]);

    builder.switch_to_block(dense_store_blk);
    builder.seal_block(dense_store_blk);
    builder.ins().store(
        m,
        value_f64,
        elem_addr,
        layout.value_number_payload_off as i32,
    );
    builder.ins().jump(cont_blk, &[]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    builder.ins().call(siref, &[receiver, index_i64, value_f64]);
    builder.ins().jump(cont_blk, &[]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
}

fn emit_inline_setprop_ic(
    builder: &mut FunctionBuilder,
    receiver: ClValue,
    prop_v: ClValue,
    value_f64: ClValue,
    site_id: crate::stub_aarch64::ICSiteId,
    spref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
) {
    let m = MemFlags::trusted();
    let mask = builder.ins().iconst(I64, 0x003F_FFFF);
    let id = builder.ins().band(receiver, mask);
    let hb_addr = builder
        .ins()
        .iconst(I64, crate::deopt::inline_ic_heap_base_addr() as i64);
    let heap_base = builder.ins().load(I64, m, hb_addr, 0);
    let stride = builder.ins().iconst(I64, layout.slot_stride as i64);
    let scaled = builder.ins().imul(id, stride);
    let obj0 = builder.ins().iadd(heap_base, scaled);
    let obj_addr = builder.ins().iadd_imm(obj0, layout.slot_payload_off as i64);
    let shape = builder
        .ins()
        .load(I64, m, obj_addr, layout.object_shape_off);
    let cs_addr = builder.ins().iconst(
        I64,
        (crate::deopt::inline_ic_shape_base_addr() + (site_id as usize) * 8) as i64,
    );
    let cached_shape = builder.ins().load(I64, m, cs_addr, 0);
    let csl_addr = builder.ins().iconst(
        I64,
        (crate::deopt::inline_ic_slot_base_addr() + (site_id as usize) * 4) as i64,
    );
    let cached_slot32 = builder
        .ins()
        .load(cranelift_codegen::ir::types::I32, m, csl_addr, 0);
    let cached_slot = builder.ins().uextend(I64, cached_slot32);
    let zero = builder.ins().iconst(I64, 0);
    let nonzero = builder.ins().icmp(IntCC::NotEqual, cached_shape, zero);
    let shape_eq = builder.ins().icmp(IntCC::Equal, shape, cached_shape);
    let guard = builder.ins().band(nonzero, shape_eq);

    let chk_blk = builder.create_block();
    let store_blk = builder.create_block();
    let slow_blk = builder.create_block();
    let cont_blk = builder.create_block();
    builder.ins().brif(guard, chk_blk, &[], slow_blk, &[]);

    builder.switch_to_block(chk_blk);
    builder.seal_block(chk_blk);
    let vals = builder.ins().load(
        I64,
        m,
        obj_addr,
        layout.object_shape_values_off + layout.vec_ptr_off,
    );
    let vsize = builder.ins().iconst(I64, layout.value_size as i64);
    let elem_off = builder.ins().imul(cached_slot, vsize);
    let elem_addr = builder.ins().iadd(vals, elem_off);
    let tag = builder
        .ins()
        .load(cranelift_codegen::ir::types::I8, m, elem_addr, 0);
    let tag64 = builder.ins().uextend(I64, tag);
    let numtag = builder.ins().iconst(I64, layout.value_tag_number as i64);
    let is_num = builder.ins().icmp(IntCC::Equal, tag64, numtag);
    builder.ins().brif(is_num, store_blk, &[], slow_blk, &[]);

    builder.switch_to_block(store_blk);
    builder.seal_block(store_blk);
    builder
        .ins()
        .store(m, value_f64, elem_addr, layout.value_number_payload_off);
    builder.ins().jump(cont_blk, &[]);

    builder.switch_to_block(slow_blk);
    builder.seal_block(slow_blk);
    let site_v = builder.ins().iconst(I64, site_id as i64);
    builder
        .ins()
        .call(spref, &[site_v, receiver, prop_v, value_f64]);
    builder.ins().jump(cont_blk, &[]);

    builder.switch_to_block(cont_blk);
    builder.seal_block(cont_blk);
}

fn emit_osr_deopt_check(
    builder: &mut FunctionBuilder,
    deopt_block: Block,
    local_vars: &[Variable],
) {
    let addr = builder
        .ins()
        .iconst(I64, crate::deopt::get_osr_deopt_flag_addr() as i64);
    let flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        MemFlags::trusted(),
        addr,
        0,
    );
    let flag64 = builder.ins().uextend(I64, flag);
    let zero = builder.ins().iconst(I64, 0);
    let tripped = builder.ins().icmp(IntCC::NotEqual, flag64, zero);
    let args: Vec<ClValue> = local_vars.iter().map(|v| builder.use_var(*v)).collect();
    let cont = builder.create_block();
    builder.ins().brif(tripped, deopt_block, &args, cont, &[]);
    builder.switch_to_block(cont);
    builder.seal_block(cont);
}

fn emit_osr_deopt_check_for_contract(
    builder: &mut FunctionBuilder,
    deopt_block: Block,
    local_vars: &[Variable],
    cwc_plan: Option<&CwcSuffixFrameBaseDeoptPlan>,
    cwc_trip_ref: Option<cranelift_codegen::ir::FuncRef>,
    cwc_site_id: Option<i64>,
) -> Result<(), String> {
    if let (Some(plan), Some(trip_ref), Some(site_id)) = (cwc_plan, cwc_trip_ref, cwc_site_id) {
        emit_cwc_suffix_frame_base_deopt_check(builder, plan, trip_ref, site_id, local_vars)?;
    } else {
        emit_osr_deopt_check(builder, deopt_block, local_vars);
    }
    Ok(())
}

fn emit_cwc_suffix_frame_base_deopt_check(
    builder: &mut FunctionBuilder,
    plan: &CwcSuffixFrameBaseDeoptPlan,
    trip_ref: cranelift_codegen::ir::FuncRef,
    site_id: i64,
    local_vars: &[Variable],
) -> Result<(), String> {
    let addr = builder
        .ins()
        .iconst(I64, crate::deopt::get_osr_deopt_flag_addr() as i64);
    let flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        MemFlags::trusted(),
        addr,
        0,
    );
    let flag64 = builder.ins().uextend(I64, flag);
    let zero = builder.ins().iconst(I64, 0);
    let tripped = builder.ins().icmp(IntCC::NotEqual, flag64, zero);
    let trip_block = builder.create_block();
    let cont = builder.create_block();
    builder.ins().brif(tripped, trip_block, &[], cont, &[]);

    builder.switch_to_block(trip_block);
    builder.seal_block(trip_block);
    let sentinel =
        emit_cwc_suffix_frame_base_deopt_trip(builder, plan, trip_ref, site_id, local_vars)?;
    let sentinel_f64 = builder.ins().fcvt_from_sint(F64, sentinel);
    builder.ins().return_(&[sentinel_f64]);

    builder.switch_to_block(cont);
    builder.seal_block(cont);
    Ok(())
}

fn emit_indexed_post_write_deopt_check(
    builder: &mut FunctionBuilder,
    candidate: &IndexedPostWriteDeoptSiteCandidate,
    trip_ref: cranelift_codegen::ir::FuncRef,
    site_id: i64,
    local_vars: &[Variable],
) -> Result<(), String> {
    if candidate.requires_spill_payload || candidate.requires_memory_payload {
        return Err(
            "indexed post-write fixed trip cannot carry spill or memory payload".to_string(),
        );
    }
    let addr = builder
        .ins()
        .iconst(I64, crate::deopt::get_osr_deopt_flag_addr() as i64);
    let flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        MemFlags::trusted(),
        addr,
        0,
    );
    let flag64 = builder.ins().uextend(I64, flag);
    let zero = builder.ins().iconst(I64, 0);
    let tripped = if indexed_post_write_force_edge_enabled() {
        let one = builder.ins().iconst(I64, 1);
        builder.ins().icmp(IntCC::Equal, one, one)
    } else {
        builder.ins().icmp(IntCC::NotEqual, flag64, zero)
    };
    let trip_block = builder.create_block();
    let cont = builder.create_block();
    builder.ins().brif(tripped, trip_block, &[], cont, &[]);

    builder.switch_to_block(trip_block);
    builder.seal_block(trip_block);
    let sentinel =
        emit_indexed_post_write_deopt_trip(builder, candidate, trip_ref, site_id, local_vars)?;
    let sentinel_f64 = builder.ins().fcvt_from_sint(F64, sentinel);
    builder.ins().return_(&[sentinel_f64]);

    builder.switch_to_block(cont);
    builder.seal_block(cont);
    Ok(())
}

fn emit_indexed_post_write_deopt_trip(
    builder: &mut FunctionBuilder,
    candidate: &IndexedPostWriteDeoptSiteCandidate,
    trip_ref: cranelift_codegen::ir::FuncRef,
    site_id: i64,
    local_vars: &[Variable],
) -> Result<ClValue, String> {
    let mut args = Vec::with_capacity(1 + crate::deopt::DEOPT_TRIP_FIXED_REGISTER_ARG_CAPACITY);
    args.push(builder.ins().iconst(I64, site_id));
    for local_slot in &candidate.argument_register_slots {
        let local = local_vars
            .get(*local_slot as usize)
            .ok_or_else(|| format!("indexed post-write local {local_slot} out of range"))?;
        let raw = builder.use_var(*local);
        if candidate.f64_bitcast_local_slots.contains(local_slot) {
            args.push(deopt_payload_f64_bits(builder, raw));
        } else {
            args.push(deopt_payload_i64(builder, raw));
        }
    }
    while args.len() < 1 + crate::deopt::DEOPT_TRIP_FIXED_REGISTER_ARG_CAPACITY {
        args.push(builder.ins().iconst(I64, 0));
    }
    if args.len() != 1 + crate::deopt::DEOPT_TRIP_FIXED_REGISTER_ARG_CAPACITY {
        return Err(format!(
            "indexed post-write deopt_trip arity must be {}, got {}",
            1 + crate::deopt::DEOPT_TRIP_FIXED_REGISTER_ARG_CAPACITY,
            args.len()
        ));
    }
    let call = builder.ins().call(trip_ref, &args);
    Ok(builder.inst_results(call)[0])
}

fn emit_cwc_suffix_frame_base_deopt_trip(
    builder: &mut FunctionBuilder,
    plan: &CwcSuffixFrameBaseDeoptPlan,
    trip_ref: cranelift_codegen::ir::FuncRef,
    site_id: i64,
    local_vars: &[Variable],
) -> Result<ClValue, String> {
    if plan.helper_arg_count != 10 {
        return Err(format!(
            "CWC frame-base deopt helper arity must be 10, got {}",
            plan.helper_arg_count
        ));
    }
    if plan.frame_base_arg_index != 9 {
        return Err(format!(
            "CWC frame-base arg index must be 9, got {}",
            plan.frame_base_arg_index
        ));
    }
    if plan.frame_slot_size_bytes != 8 {
        return Err(format!(
            "CWC frame slot size must be 8, got {}",
            plan.frame_slot_size_bytes
        ));
    }
    if plan.register_local_slots.len() != crate::deopt::DEOPT_CALL_FRAME_REGISTER_CAPACITY {
        return Err(format!(
            "CWC register payload must carry {} locals, got {}",
            crate::deopt::DEOPT_CALL_FRAME_REGISTER_CAPACITY,
            plan.register_local_slots.len()
        ));
    }

    let spill_size =
        (plan.memory_payload_local_slots.len() * usize::from(plan.frame_slot_size_bytes)) as u32;
    let spill_slot = if spill_size > 0 {
        Some(builder.create_sized_stack_slot(StackSlotData::new(
            StackSlotKind::ExplicitSlot,
            spill_size,
            3,
        )))
    } else {
        None
    };

    if let Some(slot) = spill_slot {
        for (i, local_slot) in plan.memory_payload_local_slots.iter().copied().enumerate() {
            let local = local_vars
                .get(local_slot as usize)
                .ok_or_else(|| format!("CWC memory payload local {local_slot} out of range"))?;
            let raw = builder.use_var(*local);
            let value = deopt_payload_i64(builder, raw);
            let offset = (i * usize::from(plan.frame_slot_size_bytes)) as i32;
            builder.ins().stack_store(value, slot, offset);
        }
    }

    let mut args = Vec::with_capacity(plan.helper_arg_count as usize);
    args.push(builder.ins().iconst(I64, site_id));
    for local_slot in &plan.register_local_slots {
        let local = local_vars
            .get(*local_slot as usize)
            .ok_or_else(|| format!("CWC register payload local {local_slot} out of range"))?;
        let raw = builder.use_var(*local);
        let value = deopt_payload_i64(builder, raw);
        args.push(value);
    }
    let frame_base = if let Some(slot) = spill_slot {
        builder.ins().stack_addr(I64, slot, 0)
    } else {
        builder.ins().iconst(I64, 0)
    };
    args.push(frame_base);

    let call = builder.ins().call(trip_ref, &args);
    Ok(builder.inst_results(call)[0])
}

fn slot_is_numeric_stable(parsed: &[(usize, ParsedOp)], slot: u16) -> bool {
    for i in 0..parsed.len() {
        if matches!(parsed[i].1, ParsedOp::StoreLocal(s) | ParsedOp::InitLocal(s) if s == slot) {
            if !store_local_source_is_numeric(parsed, i, slot) {
                return false;
            }
        }
    }
    true
}

fn store_local_source_is_numeric(parsed: &[(usize, ParsedOp)], i: usize, slot: u16) -> bool {
    if i >= 1
        && parsed
            .get(i - 1)
            .is_some_and(|(_, op)| is_numeric_result(op))
    {
        return true;
    }

    if i >= 3
        && matches!(parsed[i - 3].1, ParsedOp::LoadLocal(_))
        && matches!(parsed[i - 2].1, ParsedOp::ToNumeric)
        && matches!(parsed[i - 1].1, ParsedOp::Dup)
    {
        return true;
    }

    if i >= 2
        && matches!(parsed[i - 2].1, ParsedOp::LoadLocal(base_slot) if base_slot == slot)
        && matches!(parsed[i - 1].1, ParsedOp::ResetLocalCellNop)
    {
        return true;
    }

    if i >= 7
        && matches!(parsed[i - 7].1, ParsedOp::LoadLocal(base_slot) if base_slot == slot)
        && matches!(parsed[i - 6].1, ParsedOp::ToNumeric)
        && matches!(parsed[i - 5].1, ParsedOp::Dup)
        && matches!(parsed[i - 4].1, ParsedOp::StoreLocal(_))
        && matches!(
            parsed[i - 3].1,
            ParsedOp::Inc | ParsedOp::Dec | ParsedOp::IncI64 | ParsedOp::DecI64
        )
        && matches!(parsed[i - 2].1, ParsedOp::StoreLocal(new_slot)
            if matches!(parsed[i - 1].1, ParsedOp::LoadLocal(load_slot) if load_slot == new_slot))
    {
        return true;
    }

    false
}

fn arithmetic_operand_number_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut slots = Vec::new();
    for i in 0..parsed.len() {
        let required_depth = match parsed[i].1 {
            ParsedOp::ToNumeric
            | ParsedOp::Inc
            | ParsedOp::Dec
            | ParsedOp::IncI64
            | ParsedOp::DecI64
            | ParsedOp::Neg
            | ParsedOp::BitNot => 1,
            ParsedOp::BitOr
            | ParsedOp::BitAnd
            | ParsedOp::BitXor
            | ParsedOp::UShr
            | ParsedOp::Shl
            | ParsedOp::Shr
            | ParsedOp::Add
            | ParsedOp::AddConstTernaryI32 { .. }
            | ParsedOp::BitOrConstTernaryI32 { .. }
            | ParsedOp::Sub
            | ParsedOp::Mul
            | ParsedOp::Div
            | ParsedOp::Mod
            | ParsedOp::Lt
            | ParsedOp::Le
            | ParsedOp::Gt
            | ParsedOp::Ge
            | ParsedOp::Eq
            | ParsedOp::Ne
            | ParsedOp::StrictEq
            | ParsedOp::StrictNe
            | ParsedOp::AddI64
            | ParsedOp::SubI64
            | ParsedOp::MulI64
            | ParsedOp::LtI64
            | ParsedOp::LeI64
            | ParsedOp::GtI64
            | ParsedOp::GeI64
            | ParsedOp::EqI64
            | ParsedOp::NeI64 => 2,
            _ => 0,
        };
        if required_depth == 0 {
            continue;
        }

        let Some(stack) = simulate_expr_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < required_depth {
            continue;
        }
        for origin in &stack[stack.len() - required_depth..] {
            if let Origin::Local(slot) = origin.origin {
                push_unique_sorted(&mut slots, slot);
            }
        }
    }
    slots
}

fn boolean_literal_local_store_slot(bc: &[u8], next_pc: usize) -> Option<u16> {
    let mut p = next_pc;
    if matches!(bc.get(p).and_then(|b| op_from_byte(*b)), Some(Op::Dup)) {
        p += 1;
    }
    if !matches!(
        bc.get(p).and_then(|b| op_from_byte(*b)),
        Some(Op::StoreLocal | Op::InitLocal)
    ) {
        return None;
    }
    let lo = *bc.get(p + 1)?;
    let hi = *bc.get(p + 2)?;
    Some(u16::from_le_bytes([lo, hi]))
}

fn local_name_for_diag(locals: &[rusty_js_bytecode::compiler::LocalDescriptor], slot: u16) -> &str {
    locals
        .get(usize::from(slot))
        .map(|local| local.name.as_str())
        .unwrap_or("<unknown-local>")
}

fn bitwise_derived_branch_condition(parsed: &[(usize, ParsedOp)]) -> bool {
    fn is_bitwise(op: &ParsedOp) -> bool {
        matches!(
            op,
            ParsedOp::BitAnd
                | ParsedOp::BitOr
                | ParsedOp::BitXor
                | ParsedOp::Shl
                | ParsedOp::Shr
                | ParsedOp::UShr
                | ParsedOp::Mod
        )
    }

    let mut bitwise_slots: std::collections::HashSet<u16> = std::collections::HashSet::new();
    for i in 0..parsed.len() {
        if let ParsedOp::StoreLocal(s) | ParsedOp::InitLocal(s) = parsed[i].1 {
            let src = if i >= 1 && matches!(parsed[i - 1].1, ParsedOp::Dup) {
                parsed.get(i.wrapping_sub(2))
            } else {
                parsed.get(i.wrapping_sub(1))
            };
            if src.is_some_and(|(_, o)| is_bitwise(o)) {
                bitwise_slots.insert(s);
            }
        }
    }

    let pure_numeric = parsed.iter().all(|(_, op)| {
        matches!(
            op,
            ParsedOp::LoadLocal(_)
                | ParsedOp::LoadArg(_)
                | ParsedOp::PushI32(_)
                | ParsedOp::PushConst(_)
                | ParsedOp::BitAnd
                | ParsedOp::BitOr
                | ParsedOp::BitXor
                | ParsedOp::Shl
                | ParsedOp::Shr
                | ParsedOp::UShr
                | ParsedOp::Mod
                | ParsedOp::Add
                | ParsedOp::Sub
                | ParsedOp::Mul
                | ParsedOp::Div
                | ParsedOp::AddI64
                | ParsedOp::SubI64
                | ParsedOp::MulI64
                | ParsedOp::Inc
                | ParsedOp::Dec
                | ParsedOp::IncI64
                | ParsedOp::DecI64
                | ParsedOp::ToNumeric
                | ParsedOp::Lt
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Ge
                | ParsedOp::Eq
                | ParsedOp::Ne
                | ParsedOp::StrictEq
                | ParsedOp::StrictNe
                | ParsedOp::LtI64
                | ParsedOp::LeI64
                | ParsedOp::GtI64
                | ParsedOp::GeI64
                | ParsedOp::EqI64
                | ParsedOp::NeI64
                | ParsedOp::Dup
                | ParsedOp::Pop
                | ParsedOp::StoreLocal(_)
                | ParsedOp::InitLocal(_)
                | ParsedOp::JumpIfTrue(_)
                | ParsedOp::JumpIfFalse(_)
                | ParsedOp::Jump(_)
                | ParsedOp::Return
                | ParsedOp::ReturnUndef
        )
    });
    if !pure_numeric {
        return false;
    }

    let mut st: Vec<bool> = Vec::new();
    macro_rules! pop {
        () => {
            match st.pop() {
                Some(v) => v,
                None => return false,
            }
        };
    }
    for (_, op) in parsed {
        match op {
            ParsedOp::LoadLocal(s) => st.push(bitwise_slots.contains(s)),
            ParsedOp::LoadArg(_) | ParsedOp::PushI32(_) | ParsedOp::PushConst(_) => st.push(false),
            ParsedOp::BitAnd
            | ParsedOp::BitOr
            | ParsedOp::BitXor
            | ParsedOp::Shl
            | ParsedOp::Shr
            | ParsedOp::UShr
            | ParsedOp::Mod => {
                let _ = pop!();
                let _ = pop!();
                st.push(true);
            }
            ParsedOp::Add
            | ParsedOp::Sub
            | ParsedOp::Mul
            | ParsedOp::Div
            | ParsedOp::AddI64
            | ParsedOp::SubI64
            | ParsedOp::MulI64 => {
                let _ = pop!();
                let _ = pop!();
                st.push(false);
            }
            ParsedOp::Inc | ParsedOp::Dec | ParsedOp::IncI64 | ParsedOp::DecI64 => {
                let _ = pop!();
                st.push(false);
            }
            ParsedOp::ToNumeric => {   }
            ParsedOp::Lt
            | ParsedOp::Le
            | ParsedOp::Gt
            | ParsedOp::Ge
            | ParsedOp::Eq
            | ParsedOp::Ne
            | ParsedOp::StrictEq
            | ParsedOp::StrictNe
            | ParsedOp::LtI64
            | ParsedOp::LeI64
            | ParsedOp::GtI64
            | ParsedOp::GeI64
            | ParsedOp::EqI64
            | ParsedOp::NeI64 => {
                let a = pop!();
                let b = pop!();
                st.push(a || b);
            }
            ParsedOp::Dup => {
                let top = *st.last().unwrap_or(&false);
                st.push(top);
            }
            ParsedOp::Pop | ParsedOp::StoreLocal(_) | ParsedOp::InitLocal(_) => {
                let _ = pop!();
            }
            ParsedOp::JumpIfTrue(_) | ParsedOp::JumpIfFalse(_) => {
                if pop!() {
                    return true;
                }
            }
            ParsedOp::Jump(_) | ParsedOp::ReturnUndef => {}
            ParsedOp::Return => {
                let _ = pop!();
            }

            _ => return false,
        }
    }
    false
}

fn string_const_stored_to_local(parsed: &[(usize, ParsedOp)]) -> Option<usize> {
    for i in 0..parsed.len() {
        if !matches!(parsed[i].1, ParsedOp::PushStringConst { .. }) {
            continue;
        }
        let mut j = i + 1;
        if matches!(parsed.get(j).map(|(_, op)| op), Some(ParsedOp::Dup)) {
            j += 1;
        }
        if matches!(
            parsed.get(j).map(|(_, op)| op),
            Some(ParsedOp::StoreLocal(_) | ParsedOp::InitLocal(_))
        ) {
            return Some(i);
        }
    }
    None
}

fn nested_single_pwrite_osr_enabled() -> bool {
    env_flag_enabled_by_default("CRUFT_LEJIT_NESTED_PWRITE_OSR")
}

fn pure_property_numeric_region(parsed: &[(usize, ParsedOp)]) -> bool {
    parsed.iter().all(|(_, op)| {
        matches!(
            op,
            ParsedOp::LoadLocal(_)
                | ParsedOp::LoadArg(_)
                | ParsedOp::StoreLocal(_)
                | ParsedOp::InitLocal(_)
                | ParsedOp::PushI32(_)
                | ParsedOp::PushConst(_)
                | ParsedOp::Add
                | ParsedOp::Sub
                | ParsedOp::Mul
                | ParsedOp::Div
                | ParsedOp::Mod
                | ParsedOp::AddI64
                | ParsedOp::SubI64
                | ParsedOp::MulI64
                | ParsedOp::BitAnd
                | ParsedOp::BitOr
                | ParsedOp::BitXor
                | ParsedOp::Shl
                | ParsedOp::Shr
                | ParsedOp::UShr
                | ParsedOp::Inc
                | ParsedOp::Dec
                | ParsedOp::IncI64
                | ParsedOp::DecI64
                | ParsedOp::ToNumeric
                | ParsedOp::Lt
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Ge
                | ParsedOp::Eq
                | ParsedOp::Ne
                | ParsedOp::StrictEq
                | ParsedOp::StrictNe
                | ParsedOp::LtI64
                | ParsedOp::LeI64
                | ParsedOp::GtI64
                | ParsedOp::GeI64
                | ParsedOp::EqI64
                | ParsedOp::NeI64
                | ParsedOp::Dup
                | ParsedOp::Pop
                | ParsedOp::Jump(_)
                | ParsedOp::JumpIfTrue(_)
                | ParsedOp::JumpIfFalse(_)
                | ParsedOp::Return
                | ParsedOp::ReturnUndef
                | ParsedOp::GetPropOnObject(_)
                | ParsedOp::GetPropTruthyOnObject(_)
                | ParsedOp::SetPropOnObject(_)
        )
    })
}

fn nested_pwrite_receiver_stable(parsed: &[(usize, ParsedOp)]) -> bool {
    let Some(sp_idx) = parsed
        .iter()
        .position(|(_, o)| matches!(o, ParsedOp::SetPropOnObject(_)))
    else {
        return false;
    };
    let Some(st) = simulate_expr_stack(&parsed[..sp_idx]) else {
        return false;
    };
    if st.len() < 2 {
        return false;
    }
    let recv = &st[st.len() - 2];
    if recv.locals.len() != 1 {
        return false;
    }
    let recv_slot = recv.locals[0];
    if parsed.iter().any(
        |(_, o)| matches!(o, ParsedOp::StoreLocal(s) | ParsedOp::InitLocal(s) if *s == recv_slot),
    ) {
        return false;
    }
    true
}

fn is_comparison_result(op: &ParsedOp) -> bool {
    matches!(
        op,
        ParsedOp::Lt
            | ParsedOp::Le
            | ParsedOp::Gt
            | ParsedOp::Ge
            | ParsedOp::Eq
            | ParsedOp::Ne
            | ParsedOp::StrictEq
            | ParsedOp::StrictNe
            | ParsedOp::LtI64
            | ParsedOp::LeI64
            | ParsedOp::GtI64
            | ParsedOp::GeI64
            | ParsedOp::EqI64
            | ParsedOp::NeI64
    )
}

fn comparison_result_stored_to_local(parsed: &[(usize, ParsedOp)]) -> Option<usize> {
    for i in 0..parsed.len() {
        if !is_comparison_result(&parsed[i].1) {
            continue;
        }
        let mut j = i + 1;
        if matches!(parsed.get(j).map(|(_, op)| op), Some(ParsedOp::Dup)) {
            j += 1;
        }
        if matches!(
            parsed.get(j).map(|(_, op)| op),
            Some(ParsedOp::StoreLocal(_) | ParsedOp::InitLocal(_))
        ) {
            return Some(i);
        }
    }
    None
}

fn is_numeric_result(op: &ParsedOp) -> bool {
    matches!(
        op,
        ParsedOp::PushI32(_)
            | ParsedOp::PushConst(_)
            | ParsedOp::Add
            | ParsedOp::Sub
            | ParsedOp::Mul
            | ParsedOp::Div
            | ParsedOp::Mod
            | ParsedOp::ToNumeric
            | ParsedOp::Inc
            | ParsedOp::Dec
            | ParsedOp::AddI64
            | ParsedOp::SubI64
            | ParsedOp::MulI64
            | ParsedOp::IncI64
            | ParsedOp::DecI64
            | ParsedOp::Lt
            | ParsedOp::Le
            | ParsedOp::Gt
            | ParsedOp::Ge
            | ParsedOp::Eq
            | ParsedOp::Ne
            | ParsedOp::StrictEq
            | ParsedOp::StrictNe
            | ParsedOp::LtI64
            | ParsedOp::LeI64
            | ParsedOp::GtI64
            | ParsedOp::GeI64
            | ParsedOp::EqI64
            | ParsedOp::NeI64
            | ParsedOp::BitOr
            | ParsedOp::BitAnd
            | ParsedOp::BitXor
            | ParsedOp::UShr
    )
}

fn binop<F>(stack: &mut Vec<ClValue>, builder: &mut FunctionBuilder, f: F) -> Result<(), String>
where
    F: FnOnce(&mut FunctionBuilder, ClValue, ClValue) -> ClValue,
{
    let r = stack.pop().ok_or("binop: stack underflow (rhs)")?;
    let l = stack.pop().ok_or("binop: stack underflow (lhs)")?;
    let v = f(builder, l, r);
    stack.push(v);
    Ok(())
}

fn emit_bool_bitwise<F>(
    stack: &mut Vec<ClValue>,
    stack_domains: &mut Vec<LocalDomain>,
    builder: &mut FunctionBuilder,
    typed_i64: bool,
    mixed: bool,
    op: F,
) -> Result<(), String>
where
    F: FnOnce(&mut FunctionBuilder, ClValue, ClValue) -> ClValue,
{
    let rv = stack.pop().ok_or("bitwise: stack underflow (rhs)")?;
    let lv = stack.pop().ok_or("bitwise: stack underflow (lhs)")?;

    let (l_i64, r_i64) = if typed_i64 {
        (lv, rv)
    } else if mixed {

        let rd = stack_domains
            .pop()
            .ok_or("bitwise: domain underflow (rhs)")?;
        let ld = stack_domains
            .pop()
            .ok_or("bitwise: domain underflow (lhs)")?;
        (
            domain_value_to_i64(builder, lv, ld),
            domain_value_to_i64(builder, rv, rd),
        )
    } else {
        (
            builder.ins().fcvt_to_sint_sat(I64, lv),
            builder.ins().fcvt_to_sint_sat(I64, rv),
        )
    };
    let res = op(builder, l_i64, r_i64);
    let trunc = builder.ins().ireduce(I32, res);
    let sext = builder.ins().sextend(I64, trunc);

    if typed_i64 {
        stack.push(sext);
    } else if mixed {
        stack.push(sext);
        stack_domains.push(LocalDomain::SafeI64);
    } else {
        stack.push(builder.ins().fcvt_from_sint(F64, sext));
    }
    Ok(())
}

fn emit_unsigned_shift_right(
    stack: &mut Vec<ClValue>,
    stack_domains: &mut Vec<LocalDomain>,
    builder: &mut FunctionBuilder,
    typed_i64: bool,
    mixed: bool,
) -> Result<(), String> {
    let rv = stack.pop().ok_or("ushr: stack underflow (rhs)")?;
    let lv = stack.pop().ok_or("ushr: stack underflow (lhs)")?;
    let (l_i64, r_i64) = if typed_i64 {
        (lv, rv)
    } else if mixed {
        let rd = stack_domains.pop().ok_or("ushr: domain underflow (rhs)")?;
        let ld = stack_domains.pop().ok_or("ushr: domain underflow (lhs)")?;
        (
            domain_value_to_i64(builder, lv, ld),
            domain_value_to_i64(builder, rv, rd),
        )
    } else {
        (
            builder.ins().fcvt_to_sint_sat(I64, lv),
            builder.ins().fcvt_to_sint_sat(I64, rv),
        )
    };
    let l32 = builder.ins().ireduce(I32, l_i64);
    let r32 = builder.ins().ireduce(I32, r_i64);
    let mask = builder.ins().iconst(I32, 0x1f);
    let shift = builder.ins().band(r32, mask);
    let shifted = builder.ins().ushr(l32, shift);
    let result = builder.ins().uextend(I64, shifted);
    if typed_i64 {
        stack.push(result);
    } else if mixed {
        stack.push(result);
        stack_domains.push(LocalDomain::SafeI64);
    } else {
        stack.push(builder.ins().fcvt_from_uint(F64, result));
    }
    Ok(())
}

fn emit_signed_shift(
    stack: &mut Vec<ClValue>,
    stack_domains: &mut Vec<LocalDomain>,
    builder: &mut FunctionBuilder,
    typed_i64: bool,
    mixed: bool,
    left: bool,
) -> Result<(), String> {
    let rv = stack.pop().ok_or("shift: stack underflow (rhs)")?;
    let lv = stack.pop().ok_or("shift: stack underflow (lhs)")?;
    let (l_i64, r_i64) = if typed_i64 {
        (lv, rv)
    } else if mixed {
        let rd = stack_domains.pop().ok_or("shift: domain underflow (rhs)")?;
        let ld = stack_domains.pop().ok_or("shift: domain underflow (lhs)")?;
        (
            domain_value_to_i64(builder, lv, ld),
            domain_value_to_i64(builder, rv, rd),
        )
    } else {
        (
            builder.ins().fcvt_to_sint_sat(I64, lv),
            builder.ins().fcvt_to_sint_sat(I64, rv),
        )
    };
    let l32 = builder.ins().ireduce(I32, l_i64);
    let r32 = builder.ins().ireduce(I32, r_i64);
    let mask = builder.ins().iconst(I32, 0x1f);
    let shift = builder.ins().band(r32, mask);
    let shifted = if left {
        builder.ins().ishl(l32, shift)
    } else {
        builder.ins().sshr(l32, shift)
    };
    let result = builder.ins().sextend(I64, shifted);
    if typed_i64 {
        stack.push(result);
    } else if mixed {
        stack.push(result);
        stack_domains.push(LocalDomain::SafeI64);
    } else {
        stack.push(builder.ins().fcvt_from_sint(F64, result));
    }
    Ok(())
}

fn emit_bit_not(
    stack: &mut Vec<ClValue>,
    stack_domains: &mut Vec<LocalDomain>,
    builder: &mut FunctionBuilder,
    typed_i64: bool,
    mixed: bool,
) -> Result<(), String> {
    let v = stack.pop().ok_or("bitnot: stack underflow")?;
    let v_i64 = if typed_i64 {
        v
    } else if mixed {
        let domain = stack_domains.pop().ok_or("bitnot: domain underflow")?;
        domain_value_to_i64(builder, v, domain)
    } else {
        builder.ins().fcvt_to_sint_sat(I64, v)
    };
    let v32 = builder.ins().ireduce(I32, v_i64);
    let all_ones = builder.ins().iconst(I32, -1);
    let result32 = builder.ins().bxor(v32, all_ones);
    let result = builder.ins().sextend(I64, result32);
    if typed_i64 {
        stack.push(result);
    } else if mixed {
        stack.push(result);
        stack_domains.push(LocalDomain::SafeI64);
    } else {
        stack.push(builder.ins().fcvt_from_sint(F64, result));
    }
    Ok(())
}

fn emit_guarded_add(
    stack: &mut Vec<ClValue>,
    builder: &mut FunctionBuilder,
    trip_ref: cranelift_codegen::ir::FuncRef,
    pc: usize,
    local_vars: &[Variable],
    deopt_sites: &mut crate::deopt::DeoptSiteTable,
) -> Result<(), String> {
    use crate::deopt::{DeoptLiveLocal, DeoptReason, DeoptSite, JitLocation};

    let r = stack.pop().ok_or("guarded_add: stack underflow (rhs)")?;
    let l = stack.pop().ok_or("guarded_add: stack underflow (lhs)")?;

    let result = builder.ins().iadd(l, r);

    let xor_a = builder.ins().bxor(l, result);
    let xor_b = builder.ins().bxor(r, result);
    let combined = builder.ins().band(xor_a, xor_b);
    let zero = builder.ins().iconst(I64, 0);
    let overflowed = builder.ins().icmp(IntCC::SignedLessThan, combined, zero);

    let deopt_block = builder.create_block();
    let cont_block = builder.create_block();

    let cont_result = builder.append_block_param(cont_block, I64);

    builder
        .ins()
        .brif(overflowed, deopt_block, &[], cont_block, &[result]);

    builder.switch_to_block(deopt_block);
    builder.seal_block(deopt_block);
    let site_id = deopt_sites.len() as i64;
    let site_id_v = builder.ins().iconst(I64, site_id);

    let local0 = if !local_vars.is_empty() {
        let local = builder.use_var(local_vars[0]);
        deopt_payload_i64(builder, local)
    } else {
        builder.ins().iconst(I64, 0)
    };
    let local1 = if local_vars.len() > 1 {
        let local = builder.use_var(local_vars[1]);
        deopt_payload_i64(builder, local)
    } else {
        builder.ins().iconst(I64, 0)
    };
    let call_inst = builder
        .ins()
        .call(trip_ref, &[site_id_v, l, r, local0, local1]);
    let sentinel = builder.inst_results(call_inst)[0];

    let sentinel_f64 = builder.ins().fcvt_from_sint(F64, sentinel);
    builder.ins().return_(&[sentinel_f64]);

    deopt_sites.push(DeoptSite {
        reason: DeoptReason::IntegerOverflow { op_pc: pc as u32 },
        resume_pc: pc as u32,
        live_locals: vec![
            DeoptLiveLocal {
                interp_slot: 0,
                jit_location: JitLocation::Register(2),
            },
            DeoptLiveLocal {
                interp_slot: 1,
                jit_location: JitLocation::Register(3),
            },
        ],
        stack_depth: 2,
        stack_slots: vec![
            DeoptLiveLocal {
                interp_slot: 0,
                jit_location: JitLocation::Register(0),
            },
            DeoptLiveLocal {
                interp_slot: 1,
                jit_location: JitLocation::Register(1),
            },
        ],
    });

    builder.switch_to_block(cont_block);
    builder.seal_block(cont_block);
    stack.push(cont_result);
    Ok(())
}

fn cmpop(stack: &mut Vec<ClValue>, builder: &mut FunctionBuilder, cc: IntCC) -> Result<(), String> {
    let r = stack.pop().ok_or("cmp: stack underflow (rhs)")?;
    let l = stack.pop().ok_or("cmp: stack underflow (lhs)")?;
    let i8_result = builder.ins().icmp(cc, l, r);

    let i64_result = builder.ins().uextend(I64, i8_result);
    stack.push(i64_result);
    Ok(())
}

fn fcmpop(
    stack: &mut Vec<ClValue>,
    builder: &mut FunctionBuilder,
    cc: FloatCC,
) -> Result<(), String> {
    let r = stack.pop().ok_or("fcmp: stack underflow (rhs)")?;
    let l = stack.pop().ok_or("fcmp: stack underflow (lhs)")?;
    let i8_result = builder.ins().fcmp(cc, l, r);

    let i64_result = builder.ins().uextend(I64, i8_result);
    let f64_result = builder.ins().fcvt_from_uint(F64, i64_result);
    stack.push(f64_result);
    Ok(())
}

fn domain_binop_safe_i64_or_f64<FInt, FFloat>(
    stack: &mut Vec<ClValue>,
    stack_domains: &mut Vec<LocalDomain>,
    builder: &mut FunctionBuilder,
    trip_ref: cranelift_codegen::ir::FuncRef,
    pc: usize,
    deopt_sites: &mut crate::deopt::DeoptSiteTable,
    elide_safe_i64_guard: bool,
    opname: &'static str,
    int_op: FInt,
    float_op: FFloat,
) -> Result<(), String>
where
    FInt: FnOnce(&mut FunctionBuilder, ClValue, ClValue) -> ClValue,
    FFloat: FnOnce(&mut FunctionBuilder, ClValue, ClValue) -> ClValue,
{
    let r = stack
        .pop()
        .ok_or_else(|| format!("{opname}: stack underflow (rhs)"))?;
    let l = stack
        .pop()
        .ok_or_else(|| format!("{opname}: stack underflow (lhs)"))?;
    let rd = stack_domains
        .pop()
        .ok_or_else(|| format!("{opname}: domain underflow (rhs)"))?;
    let ld = stack_domains
        .pop()
        .ok_or_else(|| format!("{opname}: domain underflow (lhs)"))?;
    if ld == LocalDomain::SafeI64 && rd == LocalDomain::SafeI64 {
        let result = int_op(builder, l, r);
        let guarded =
            if elide_safe_i64_guard || env_flag_truthy("CRUFT_LEJIT_MDOA_STRIP_SAFE_GUARD") {
                result
            } else {
                emit_safe_int_guard(builder, result, trip_ref, pc, &[], deopt_sites, opname)
            };
        stack.push(guarded);
        stack_domains.push(LocalDomain::SafeI64);
    } else {
        let lf = domain_value_to_f64(builder, l, ld);
        let rf = domain_value_to_f64(builder, r, rd);
        stack.push(float_op(builder, lf, rf));
        stack_domains.push(LocalDomain::NumberF64);
    }
    Ok(())
}

fn elide_affine_index_value_materialization(
    stack: &mut Vec<ClValue>,
    stack_domains: &mut Vec<LocalDomain>,
    parsed: &[(usize, ParsedOp)],
    parsed_idx: usize,
    opname: &'static str,
) -> Result<(), String> {
    let r = stack
        .pop()
        .ok_or_else(|| format!("{opname}: stack underflow (rhs)"))?;
    let l = stack
        .pop()
        .ok_or_else(|| format!("{opname}: stack underflow (lhs)"))?;
    let rd = stack_domains
        .pop()
        .ok_or_else(|| format!("{opname}: domain underflow (rhs)"))?;
    let ld = stack_domains
        .pop()
        .ok_or_else(|| format!("{opname}: domain underflow (lhs)"))?;
    let expr_stack = simulate_expr_stack(&parsed[..parsed_idx])
        .ok_or_else(|| format!("{opname}: cannot simulate affine elision stack"))?;
    if expr_stack.len() < 2 {
        return Err(format!(
            "{opname}: affine elision expression stack underflow"
        ));
    }
    let lhs = &expr_stack[expr_stack.len() - 2];
    let rhs = &expr_stack[expr_stack.len() - 1];
    let use_rhs = matches!(parsed[parsed_idx].1, ParsedOp::Add | ParsedOp::AddI64)
        && rhs.affine_index.is_some()
        && lhs.const_i32.is_some();
    let use_lhs = lhs.affine_index.is_some() && rhs.const_i32.is_some();
    match (use_lhs, use_rhs) {
        (true, _) => {
            stack.push(l);
            stack_domains.push(ld);
        }
        (false, true) => {
            stack.push(r);
            stack_domains.push(rd);
        }
        _ => {
            return Err(format!(
                "{opname}: affine elision site did not expose affine+const operands"
            ));
        }
    }
    Ok(())
}

fn cmpop_mixed(
    stack: &mut Vec<ClValue>,
    stack_domains: &mut Vec<LocalDomain>,
    builder: &mut FunctionBuilder,
    fcc: FloatCC,
    icc: IntCC,
) -> Result<(), String> {
    let r = stack.pop().ok_or("cmp: stack underflow (rhs)")?;
    let l = stack.pop().ok_or("cmp: stack underflow (lhs)")?;
    let rd = stack_domains.pop().ok_or("cmp: domain underflow (rhs)")?;
    let ld = stack_domains.pop().ok_or("cmp: domain underflow (lhs)")?;
    let i8_result = if ld == LocalDomain::SafeI64 && rd == LocalDomain::SafeI64 {
        builder.ins().icmp(icc, l, r)
    } else if matches!(
        (ld, rd),
        (LocalDomain::ObjectOrNullBits, LocalDomain::Null)
            | (LocalDomain::Null, LocalDomain::ObjectOrNullBits)
    ) {
        let value = if ld == LocalDomain::ObjectOrNullBits {
            l
        } else {
            r
        };
        let normal_null = builder
            .ins()
            .iconst(I64, crate::deopt::REGEXP_EXEC_NORMAL_NULL_SENTINEL);
        match icc {
            IntCC::Equal => builder.ins().icmp(IntCC::Equal, value, normal_null),
            IntCC::NotEqual => builder.ins().icmp(IntCC::NotEqual, value, normal_null),
            _ => {
                return Err(format!(
                    "mixed-domain object-or-null comparison only supports strict equality, got {icc:?}"
                ));
            }
        }
    } else if matches!((ld, rd), (LocalDomain::Undefined, LocalDomain::Undefined)) {
        match icc {
            IntCC::Equal => builder.ins().iconst(I8, 1),
            IntCC::NotEqual => builder.ins().iconst(I8, 0),
            _ => {
                return Err(format!(
                    "mixed-domain undefined comparison only supports strict equality, got {icc:?}"
                ));
            }
        }
    } else if matches!(ld, LocalDomain::Undefined) || matches!(rd, LocalDomain::Undefined) {
        match icc {
            IntCC::Equal => builder.ins().iconst(I8, 0),
            IntCC::NotEqual => builder.ins().iconst(I8, 1),
            _ => {
                return Err(format!(
                    "mixed-domain undefined comparison unsupported for domains {ld:?}/{rd:?}"
                ));
            }
        }
    } else if matches!(
        (ld, rd),
        (LocalDomain::ObjectBits, LocalDomain::Null) | (LocalDomain::Null, LocalDomain::ObjectBits)
    ) {
        match icc {
            IntCC::Equal => builder.ins().iconst(I8, 0),
            IntCC::NotEqual => builder.ins().iconst(I8, 1),
            _ => {
                return Err(format!(
                    "mixed-domain null/object comparison only supports strict equality, got {icc:?}"
                ));
            }
        }
    } else if matches!(ld, LocalDomain::Null) || matches!(rd, LocalDomain::Null) {
        match icc {
            IntCC::Equal => builder.ins().iconst(I8, 0),
            IntCC::NotEqual => builder.ins().iconst(I8, 1),
            _ => {
                return Err(format!(
                    "mixed-domain null comparison unsupported for domains {ld:?}/{rd:?}"
                ));
            }
        }
    } else {
        let lf = domain_value_to_f64(builder, l, ld);
        let rf = domain_value_to_f64(builder, r, rd);
        builder.ins().fcmp(fcc, lf, rf)
    };
    let i64_result = builder.ins().uextend(I64, i8_result);
    stack.push(i64_result);
    stack_domains.push(LocalDomain::SafeI64);
    Ok(())
}

fn emit_safe_int_guard(
    builder: &mut FunctionBuilder,
    value: ClValue,
    trip_ref: cranelift_codegen::ir::FuncRef,
    pc: usize,
    local_vars: &[Variable],
    deopt_sites: &mut crate::deopt::DeoptSiteTable,
    owner: &'static str,
) -> ClValue {
    if env_flag_truthy("CRUFT_LEJIT_SAFE_INT_GUARD_TRACE") {
        eprintln!(
            "[safe-int-guard] owner={owner} pc={pc} local_vars={} existing_deopt_sites={}",
            local_vars.len(),
            deopt_sites.len()
        );
    }

    let hi = builder.ins().iconst(I64, 9_007_199_254_740_992);
    let lo = builder.ins().iconst(I64, -9_007_199_254_740_992);
    let too_hi = builder.ins().icmp(IntCC::SignedGreaterThan, value, hi);
    let too_lo = builder.ins().icmp(IntCC::SignedLessThan, value, lo);
    let unsafe_i8 = builder.ins().bor(too_hi, too_lo);
    emit_deopt_if(
        builder,
        unsafe_i8,
        value,
        trip_ref,
        pc,
        local_vars,
        deopt_sites,
    )
}

fn emit_safe_i64_packed_read_guard(
    builder: &mut FunctionBuilder,
    obj_addr: ClValue,
    value_f64: ClValue,
    trip_ref: cranelift_codegen::ir::FuncRef,
    layout: &crate::deopt::InlineIcLayout,
    local_vars: &[Variable],
    deopt_sites: &mut crate::deopt::DeoptSiteTable,
) -> ClValue {
    let flag = builder.ins().load(
        cranelift_codegen::ir::types::I8,
        MemFlags::trusted(),
        obj_addr,
        layout.object_array_packed_all_safe_i64_off,
    );
    let zero = builder.ins().iconst(I64, 0);
    let flag64 = builder.ins().uextend(I64, flag);
    let missing_fact = builder.ins().icmp(IntCC::Equal, flag64, zero);
    let value_i64 = builder.ins().fcvt_to_sint_sat(I64, value_f64);
    emit_deopt_if(
        builder,
        missing_fact,
        value_i64,
        trip_ref,
        0,
        local_vars,
        deopt_sites,
    )
}

fn emit_deopt_if(
    builder: &mut FunctionBuilder,
    bad_cond: ClValue,
    good: ClValue,
    trip_ref: cranelift_codegen::ir::FuncRef,
    pc: usize,
    local_vars: &[Variable],
    deopt_sites: &mut crate::deopt::DeoptSiteTable,
) -> ClValue {
    use crate::deopt::{DeoptReason, DeoptSite};
    let value = good;
    let unsafe_i8 = bad_cond;
    let deopt_block = builder.create_block();
    let cont_block = builder.create_block();
    let cont_val = builder.append_block_param(cont_block, I64);
    builder
        .ins()
        .brif(unsafe_i8, deopt_block, &[], cont_block, &[value]);

    builder.switch_to_block(deopt_block);
    builder.seal_block(deopt_block);
    let site_id = deopt_sites.len() as i64;
    let site_id_v = builder.ins().iconst(I64, site_id);
    let local0 = if !local_vars.is_empty() {
        let local = builder.use_var(local_vars[0]);
        deopt_payload_i64(builder, local)
    } else {
        builder.ins().iconst(I64, 0)
    };
    let local1 = if local_vars.len() > 1 {
        let local = builder.use_var(local_vars[1]);
        deopt_payload_i64(builder, local)
    } else {
        builder.ins().iconst(I64, 0)
    };
    let call_inst = builder
        .ins()
        .call(trip_ref, &[site_id_v, value, value, local0, local1]);
    let sentinel = builder.inst_results(call_inst)[0];
    let sentinel_f64 = builder.ins().fcvt_from_sint(F64, sentinel);
    builder.ins().return_(&[sentinel_f64]);

    deopt_sites.push(DeoptSite {
        reason: DeoptReason::IntegerOverflow { op_pc: pc as u32 },
        resume_pc: 0,
        live_locals: vec![],
        stack_depth: 0,
        stack_slots: vec![],
    });

    builder.switch_to_block(cont_block);
    builder.seal_block(cont_block);
    cont_val
}

fn deopt_payload_i64(builder: &mut FunctionBuilder, value: ClValue) -> ClValue {
    match builder.func.dfg.value_type(value) {
        I64 => value,
        F64 => builder.ins().fcvt_to_sint_sat(I64, value),
        ty if ty.bits() < 64 => builder.ins().sextend(I64, value),
        _ => value,
    }
}

fn deopt_payload_f64_bits(builder: &mut FunctionBuilder, value: ClValue) -> ClValue {
    match builder.func.dfg.value_type(value) {
        F64 => builder
            .ins()
            .bitcast(I64, cranelift_codegen::ir::MemFlags::new(), value),
        I64 => value,
        ty if ty.bits() < 64 => builder.ins().sextend(I64, value),
        _ => value,
    }
}

fn emit_guarded_sub(
    stack: &mut Vec<ClValue>,
    builder: &mut FunctionBuilder,
    trip_ref: cranelift_codegen::ir::FuncRef,
    pc: usize,
    local_vars: &[Variable],
    deopt_sites: &mut crate::deopt::DeoptSiteTable,
) -> Result<(), String> {
    use crate::deopt::{DeoptLiveLocal, DeoptReason, DeoptSite, JitLocation};

    let r = stack.pop().ok_or("guarded_sub: stack underflow (rhs)")?;
    let l = stack.pop().ok_or("guarded_sub: stack underflow (lhs)")?;

    let result = builder.ins().isub(l, r);
    let xor_lr = builder.ins().bxor(l, r);
    let xor_lres = builder.ins().bxor(l, result);
    let combined = builder.ins().band(xor_lr, xor_lres);
    let zero = builder.ins().iconst(I64, 0);
    let overflowed = builder.ins().icmp(IntCC::SignedLessThan, combined, zero);

    let deopt_block = builder.create_block();
    let cont_block = builder.create_block();
    let cont_result = builder.append_block_param(cont_block, I64);

    builder
        .ins()
        .brif(overflowed, deopt_block, &[], cont_block, &[result]);

    builder.switch_to_block(deopt_block);
    builder.seal_block(deopt_block);
    let site_id = deopt_sites.len() as i64;
    let site_id_v = builder.ins().iconst(I64, site_id);
    let local0 = if !local_vars.is_empty() {
        let local = builder.use_var(local_vars[0]);
        deopt_payload_i64(builder, local)
    } else {
        builder.ins().iconst(I64, 0)
    };
    let local1 = if local_vars.len() > 1 {
        let local = builder.use_var(local_vars[1]);
        deopt_payload_i64(builder, local)
    } else {
        builder.ins().iconst(I64, 0)
    };
    let call_inst = builder
        .ins()
        .call(trip_ref, &[site_id_v, l, r, local0, local1]);
    let sentinel = builder.inst_results(call_inst)[0];

    let sentinel_f64 = builder.ins().fcvt_from_sint(F64, sentinel);
    builder.ins().return_(&[sentinel_f64]);

    deopt_sites.push(DeoptSite {
        reason: DeoptReason::IntegerOverflow { op_pc: pc as u32 },
        resume_pc: pc as u32,
        live_locals: vec![
            DeoptLiveLocal {
                interp_slot: 0,
                jit_location: JitLocation::Register(2),
            },
            DeoptLiveLocal {
                interp_slot: 1,
                jit_location: JitLocation::Register(3),
            },
        ],
        stack_depth: 2,
        stack_slots: vec![
            DeoptLiveLocal {
                interp_slot: 0,
                jit_location: JitLocation::Register(0),
            },
            DeoptLiveLocal {
                interp_slot: 1,
                jit_location: JitLocation::Register(1),
            },
        ],
    });

    builder.switch_to_block(cont_block);
    builder.seal_block(cont_block);
    stack.push(cont_result);
    Ok(())
}

fn emit_guarded_mul(
    stack: &mut Vec<ClValue>,
    builder: &mut FunctionBuilder,
    trip_ref: cranelift_codegen::ir::FuncRef,
    pc: usize,
    local_vars: &[Variable],
    deopt_sites: &mut crate::deopt::DeoptSiteTable,
) -> Result<(), String> {
    use crate::deopt::{DeoptLiveLocal, DeoptReason, DeoptSite, JitLocation};

    let r = stack.pop().ok_or("guarded_mul: stack underflow (rhs)")?;
    let l = stack.pop().ok_or("guarded_mul: stack underflow (lhs)")?;

    let result = builder.ins().imul(l, r);
    let hi = builder.ins().smulhi(l, r);

    let sign_ext = builder.ins().sshr_imm(result, 63);
    let overflowed = builder.ins().icmp(IntCC::NotEqual, hi, sign_ext);

    let deopt_block = builder.create_block();
    let cont_block = builder.create_block();
    let cont_result = builder.append_block_param(cont_block, I64);

    builder
        .ins()
        .brif(overflowed, deopt_block, &[], cont_block, &[result]);

    builder.switch_to_block(deopt_block);
    builder.seal_block(deopt_block);
    let site_id = deopt_sites.len() as i64;
    let site_id_v = builder.ins().iconst(I64, site_id);
    let local0 = if !local_vars.is_empty() {
        let local = builder.use_var(local_vars[0]);
        deopt_payload_i64(builder, local)
    } else {
        builder.ins().iconst(I64, 0)
    };
    let local1 = if local_vars.len() > 1 {
        let local = builder.use_var(local_vars[1]);
        deopt_payload_i64(builder, local)
    } else {
        builder.ins().iconst(I64, 0)
    };
    let call_inst = builder
        .ins()
        .call(trip_ref, &[site_id_v, l, r, local0, local1]);
    let sentinel = builder.inst_results(call_inst)[0];

    let sentinel_f64 = builder.ins().fcvt_from_sint(F64, sentinel);
    builder.ins().return_(&[sentinel_f64]);

    deopt_sites.push(DeoptSite {
        reason: DeoptReason::IntegerOverflow { op_pc: pc as u32 },
        resume_pc: pc as u32,
        live_locals: vec![
            DeoptLiveLocal {
                interp_slot: 0,
                jit_location: JitLocation::Register(2),
            },
            DeoptLiveLocal {
                interp_slot: 1,
                jit_location: JitLocation::Register(3),
            },
        ],
        stack_depth: 2,
        stack_slots: vec![
            DeoptLiveLocal {
                interp_slot: 0,
                jit_location: JitLocation::Register(0),
            },
            DeoptLiveLocal {
                interp_slot: 1,
                jit_location: JitLocation::Register(1),
            },
        ],
    });

    builder.switch_to_block(cont_block);
    builder.seal_block(cont_block);
    stack.push(cont_result);
    Ok(())
}

fn find_next_block_pc(
    parsed: &[(usize, ParsedOp)],
    cur_pc: usize,
    blocks: &HashMap<usize, Block>,
) -> Result<usize, String> {
    let i = parsed
        .iter()
        .position(|(p, _)| *p == cur_pc)
        .expect("pc not found");
    for (p, _) in parsed[i + 1..].iter() {
        if blocks.contains_key(p) {
            return Ok(*p);
        }
    }
    Err(format!(
        "no fallthrough block after JumpIfX at pc={}",
        cur_pc
    ))
}

