impl ParsedOp {
    fn jump_target(&self) -> Option<usize> {
        match self {
            ParsedOp::Jump(t) | ParsedOp::JumpIfTrue(t) | ParsedOp::JumpIfFalse(t) => Some(*t),
            _ => None,
        }
    }
}

fn fold_const_ternary_binary_i32(parsed: &mut Vec<(usize, ParsedOp)>) {
    let mut i = 0;
    while i + 4 < parsed.len() {
        let (pc, op) = parsed[i];
        let Some((false_pc, true_value, join_pc, false_value, folded_op)) = (match (
            op,
            parsed[i + 1].1,
            parsed[i + 2].1,
            parsed[i + 3],
            parsed[i + 4],
        ) {
            (
                ParsedOp::JumpIfFalse(false_pc),
                ParsedOp::PushI32(true_value),
                ParsedOp::Jump(join_pc),
                (false_arm_pc, ParsedOp::PushI32(false_value)),
                (join_arm_pc, ParsedOp::Add),
            ) if false_arm_pc == false_pc && join_arm_pc == join_pc => Some((
                false_pc,
                true_value,
                join_pc,
                false_value,
                ParsedOp::AddConstTernaryI32 {
                    true_value,
                    false_value,
                },
            )),
            (
                ParsedOp::JumpIfFalse(false_pc),
                ParsedOp::PushI32(true_value),
                ParsedOp::Jump(join_pc),
                (false_arm_pc, ParsedOp::PushI32(false_value)),
                (join_arm_pc, ParsedOp::BitOr),
            ) if false_arm_pc == false_pc && join_arm_pc == join_pc => Some((
                false_pc,
                true_value,
                join_pc,
                false_value,
                ParsedOp::BitOrConstTernaryI32 {
                    true_value,
                    false_value,
                },
            )),
            _ => None,
        }) else {
            i += 1;
            continue;
        };
        let _ = (false_pc, join_pc);
        let _ = (true_value, false_value);
        parsed.splice(i..=i + 4, [(pc, folded_op)]);
        i += 1;
    }
}

#[derive(Default)]
struct CwcValueDomainFold {
    string_length_prop_indices: Vec<u16>,
    boolean_prop_indices: Vec<u16>,
}

fn constant_string_is(
    constants: &rusty_js_bytecode::ConstantsPool,
    idx: u16,
    expected: &str,
) -> bool {
    matches!(
        constants.get(idx),
        Some(Constant::String(s)) if s.as_str() == expected
    )
}

fn ic_property_get_is(idx: u8, expected: &str) -> bool {
    crate::ic_table::IC_TABLE
        .get(idx as usize)
        .is_some_and(|entry| {
            entry.key == expected && matches!(entry.kind, crate::ic_table::IcEntryKind::PropertyGet)
        })
}

fn cwc_following_length_read(
    parsed: &[(usize, ParsedOp)],
    constants: &rusty_js_bytecode::ConstantsPool,
    idx: usize,
) -> bool {
    match parsed.get(idx) {
        Some((_, ParsedOp::GetPropOnObject(length_idx))) => {
            constant_string_is(constants, *length_idx, "length")
        }
        Some((_, ParsedOp::IcPropertyGet(ic_idx))) => ic_property_get_is(*ic_idx, "length"),
        _ => false,
    }
}

fn fold_cwc_value_domain_reads(
    parsed: &mut Vec<(usize, ParsedOp)>,
    constants: &rusty_js_bytecode::ConstantsPool,
    candidate: &CommittedWriteContinuationCandidate,
) -> CwcValueDomainFold {
    let mut out = CwcValueDomainFold::default();
    let mut i = candidate.setprop_site_index + 1;
    while i + 2 < parsed.len() {
        let (pc, ParsedOp::LoadLocal(receiver_slot)) = parsed[i] else {
            i += 1;
            continue;
        };
        if receiver_slot != candidate.receiver_slot {
            i += 1;
            continue;
        }
        let (_, ParsedOp::GetPropOnObject(prop_idx)) = parsed[i + 1] else {
            i += 1;
            continue;
        };
        if !candidate.other_post_write_prop_indices.contains(&prop_idx) {
            i += 1;
            continue;
        }
        if cwc_following_length_read(parsed, constants, i + 2) {
            parsed.splice(
                i..=i + 2,
                [
                    (pc, ParsedOp::LoadLocal(receiver_slot)),
                    (pc, ParsedOp::CwcStringPropLength(prop_idx)),
                ],
            );
            push_unique_sorted(&mut out.string_length_prop_indices, prop_idx);
            i += 2;
            continue;
        }
        parsed.splice(
            i..=i + 1,
            [
                (pc, ParsedOp::LoadLocal(receiver_slot)),
                (pc, ParsedOp::CwcBooleanPropAsNumber(prop_idx)),
            ],
        );
        push_unique_sorted(&mut out.boolean_prop_indices, prop_idx);
        i += 2;
    }
    out
}

