                | ParsedOp::JumpIfTrue(_)
                | ParsedOp::JumpIfFalse(_)
                | ParsedOp::Return
                | ParsedOp::ReturnUndef
                | ParsedOp::AddI64
                | ParsedOp::SubI64
                | ParsedOp::MulI64
                | ParsedOp::IncI64
                | ParsedOp::DecI64
                | ParsedOp::LtI64
