fn exact_spectral_a_direct_leaf(op: &ParsedOp) -> bool {
    matches!(
        op,
        ParsedOp::CallDirectLeaf2 {
            leaf: DirectCallLeaf::Arg0Arg1SpectralNormA,
            ..
        }
    )
}

fn packed_read_length_preload_and_spectral_leaf_exclusion_reason(
    parsed: &[(usize, ParsedOp)],
    local_domains: Option<&[LocalDomain]>,
    receiver_slot: Option<u16>,
) -> String {
    let Some(receiver_slot) = receiver_slot else {
        return "no-direct-receiver-slot".to_string();
    };
    if !parsed
        .iter()
        .any(|(_, op)| matches!(op, ParsedOp::GetIndexOnObject))
    {
        return "no-getindex".to_string();
    }

    for (i, (_, op)) in parsed.iter().enumerate() {
        let allowed = matches!(
            op,
            ParsedOp::LoadArg(_)
                | ParsedOp::LoadLocal(_)
                | ParsedOp::StableCalleePreload { .. }
                | ParsedOp::StoreLocal(_)
                | ParsedOp::InitLocal(_)
                | ParsedOp::PushI32(_)
                | ParsedOp::PushConst(_)
                | ParsedOp::PushStringConst { .. }
                | ParsedOp::StringLocalConstStrictEq { .. }
                | ParsedOp::StringCommaIfTruthy { .. }
                | ParsedOp::NewArrayLiteral { .. }
                | ParsedOp::InitIndex { .. }
                | ParsedOp::Add
                | ParsedOp::Sub
                | ParsedOp::Mul
                | ParsedOp::Div
                | ParsedOp::Inc
                | ParsedOp::Dec
                | ParsedOp::Lt
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Ge
                | ParsedOp::Eq
                | ParsedOp::Ne
                | ParsedOp::StrictEq
                | ParsedOp::StrictNe
                | ParsedOp::Dup
                | ParsedOp::Pop
                | ParsedOp::Jump(_)
                | ParsedOp::JumpIfTrue(_)
                | ParsedOp::JumpIfFalse(_)
                | ParsedOp::Return
                | ParsedOp::ReturnUndef
                | ParsedOp::AddI64
                | ParsedOp::SubI64
                | ParsedOp::MulI64
                | ParsedOp::IncI64
                | ParsedOp::DecI64
                | ParsedOp::LtI64
                | ParsedOp::LeI64
                | ParsedOp::GtI64
                | ParsedOp::GeI64
                | ParsedOp::EqI64
                | ParsedOp::NeI64
                | ParsedOp::BitOr
                | ParsedOp::BitAnd
                | ParsedOp::BitXor
                | ParsedOp::UShr
                | ParsedOp::ResetLocalCellNop
                | ParsedOp::GetIndexOnObject
        ) || (matches!(op, ParsedOp::ToNumeric)
            && tonumeric_operands_proven_numeric(parsed, i, local_domains))
            || same_receiver_length_property_get(parsed, i, receiver_slot)
            || exact_spectral_a_direct_leaf(op);

        if !allowed {
            return format!("first-disallowed-op@{i}:{op:?}");
        }
    }

    "eligible".to_string()
}

fn site135_packed_read_bounds_prototype_fact(
    parsed: &[(usize, ParsedOp)],
    site_index: usize,
    receiver_slot: Option<u16>,
) -> String {
    let Some(receiver_slot) = receiver_slot else {
        return "receiver=none".to_string();
    };
    let Some(stack) = simulate_expr_stack(&parsed[..site_index]) else {
        return "expr_stack=unavailable".to_string();
    };
    if stack.len() < 2 {
        return format!("expr_stack=too-shallow depth={}", stack.len());
    }
    let index_origin = &stack[stack.len() - 1];
    let Some(index) = index_origin.affine_index else {
        return "index_affine=none".to_string();
    };
    let upper_bound = affine_exclusive_upper_bound_for_slot(parsed, index.slot);
    let same_receiver_upper = matches!(
        upper_bound,
        Some(PackedReadAffineUpperBound::TypedArrayLength {
            receiver_slot: bound_receiver
        }) if bound_receiver == receiver_slot
    );
    let mut compare_evidence = "none".to_string();
    for i in 0..site_index {
        let compare = parsed[i].1;
        if !matches!(
            compare,
            ParsedOp::Lt
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Ge
                | ParsedOp::LtI64
                | ParsedOp::LeI64
                | ParsedOp::GtI64
                | ParsedOp::GeI64
        ) {
            continue;
        }
        if !matches!(
            parsed.get(i + 1).map(|(_, op)| *op),
            Some(ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_))
        ) {
            continue;
        }
        let Some(compare_stack) = simulate_expr_stack(&parsed[..i]) else {
            continue;
        };
        if compare_stack.len() < 2 {
            continue;
        }
        let lhs = &compare_stack[compare_stack.len() - 2];
        let rhs = &compare_stack[compare_stack.len() - 1];
        let lhs_matches_index = lhs.affine_index
            == Some(PackedReadAffineIndex {
                slot: index.slot,
                offset: 0,
            });
        let rhs_same_receiver_length = rhs.typed_array_length_receiver_slot == Some(receiver_slot)
            || rhs.string_length_receiver_slot == Some(receiver_slot);
        if lhs_matches_index && rhs_same_receiver_length {
            compare_evidence = format!(
                "compare@{i}:{compare:?}->jump@{} lhs=index_slot:{} rhs=same_receiver_length:{}",
                i + 1,
                index.slot,
                receiver_slot
            );
            break;
        }
    }
    format!(
        "index_slot={} index_offset={} upper_bound={:?} same_receiver_upper={} compare_evidence={} helper_free_semantics=unproved-packed-array-hole-prototype",
        index.slot, index.offset, upper_bound, same_receiver_upper, compare_evidence
    )
}

fn site135_read_edge_admission_candidate(
    parsed: &[(usize, ParsedOp)],
    site_index: usize,
    local_domains: Option<&[LocalDomain]>,
    receiver_slot: Option<u16>,
    current_admitted: bool,
    current_generated_fast_path: bool,
    epoch_ref_available: bool,
) -> String {
    let Some(receiver_slot) = receiver_slot else {
        return "candidate=false reason=no-direct-receiver-slot action=refuse".to_string();
    };
    let alphabet = packed_read_length_preload_and_spectral_leaf_exclusion_reason(
        parsed,
        local_domains,
        Some(receiver_slot),
    );
    if alphabet != "eligible" {
        return format!("candidate=false reason=alphabet:{alphabet} action=refuse");
    }
    let Some(stack) = simulate_expr_stack(&parsed[..site_index]) else {
        return "candidate=false reason=expr-stack-unavailable action=refuse".to_string();
    };
    if stack.len() < 2 {
        return format!(
            "candidate=false reason=expr-stack-too-shallow:{} action=refuse",
            stack.len()
        );
    }
    let Some(index) = stack[stack.len() - 1].affine_index else {
        return "candidate=false reason=index-affine-missing action=refuse".to_string();
    };
    let same_receiver_upper = matches!(
        affine_exclusive_upper_bound_for_slot(parsed, index.slot),
        Some(PackedReadAffineUpperBound::TypedArrayLength {
            receiver_slot: bound_receiver
        }) if bound_receiver == receiver_slot
    );
    if !same_receiver_upper {
        return format!(
            "candidate=false reason=no-same-receiver-upper-bound receiver_slot={receiver_slot} index_slot={} action=refuse",
            index.slot
        );
    }
    let mut compare_guard = false;
    for i in 0..site_index {
        if !matches!(
            parsed[i].1,
            ParsedOp::Lt
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Ge
                | ParsedOp::LtI64
                | ParsedOp::LeI64
                | ParsedOp::GtI64
                | ParsedOp::GeI64
        ) || !matches!(
            parsed.get(i + 1).map(|(_, op)| *op),
            Some(ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_))
        ) {
            continue;
        }
        let Some(compare_stack) = simulate_expr_stack(&parsed[..i]) else {
            continue;
        };
        if compare_stack.len() < 2 {
            continue;
        }
        let lhs = &compare_stack[compare_stack.len() - 2];
        let rhs = &compare_stack[compare_stack.len() - 1];
        if lhs.affine_index
            == Some(PackedReadAffineIndex {
                slot: index.slot,
                offset: 0,
            })
            && (rhs.typed_array_length_receiver_slot == Some(receiver_slot)
                || rhs.string_length_receiver_slot == Some(receiver_slot))
        {
            compare_guard = true;
            break;
        }
    }
    if !compare_guard {
        return format!(
            "candidate=false reason=no-dominating-compare receiver_slot={receiver_slot} index_slot={} action=refuse",
            index.slot
        );
    }
    let action = if current_admitted && current_generated_fast_path {
        "consume-current-fast-path"
    } else if epoch_ref_available {
        "refuse-until-prototype-hole-or-deopt-contract"
    } else {
        "refuse-until-prototype-epoch-and-deopt-contract"
    };
    format!(
        "candidate=true kind=exact-spectral-read-edge receiver_slot={receiver_slot} index_slot={} current_admitted={current_admitted} generated_fast_path={current_generated_fast_path} epoch_ref_available={epoch_ref_available} action={action}",
        index.slot
    )
}

fn site135_exact_read_edge_candidate(
    parsed: &[(usize, ParsedOp)],
    site_index: usize,
    local_domains: Option<&[LocalDomain]>,
    receiver_slot: u16,
) -> bool {
    if packed_read_length_preload_and_spectral_leaf_exclusion_reason(
        parsed,
        local_domains,
        Some(receiver_slot),
    ) != "eligible"
    {
        return false;
    }
    let Some(stack) = simulate_expr_stack(&parsed[..site_index]) else {
        return false;
    };
    if stack.len() < 2 {
        return false;
    }
    let Some(index) = stack[stack.len() - 1].affine_index else {
        return false;
    };
    let same_receiver_upper = matches!(
        affine_exclusive_upper_bound_for_slot(parsed, index.slot),
        Some(PackedReadAffineUpperBound::TypedArrayLength {
            receiver_slot: bound_receiver
        }) if bound_receiver == receiver_slot
    );
    if !same_receiver_upper {
        return false;
    }
    (0..site_index).any(|i| {
        if !matches!(
            parsed[i].1,
            ParsedOp::Lt
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Ge
                | ParsedOp::LtI64
                | ParsedOp::LeI64
                | ParsedOp::GtI64
                | ParsedOp::GeI64
        ) || !matches!(
            parsed.get(i + 1).map(|(_, op)| *op),
            Some(ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_))
        ) {
            return false;
        }
        let Some(compare_stack) = simulate_expr_stack(&parsed[..i]) else {
            return false;
        };
        if compare_stack.len() < 2 {
            return false;
        }
        let lhs = &compare_stack[compare_stack.len() - 2];
        let rhs = &compare_stack[compare_stack.len() - 1];
        lhs.affine_index
            == Some(PackedReadAffineIndex {
                slot: index.slot,
                offset: 0,
            })
            && (rhs.typed_array_length_receiver_slot == Some(receiver_slot)
                || rhs.string_length_receiver_slot == Some(receiver_slot))
    })
}

fn frame_array_packed_metadata_receiver_slots(
    parsed: &[(usize, ParsedOp)],
    local_domains: Option<&[LocalDomain]>,
) -> Vec<u16> {
    let mut slots = Vec::new();
    for i in 0..parsed.len() {
        if !matches!(parsed[i].1, ParsedOp::GetIndexOnObject) {
            continue;
        }
        let Some(stack) = simulate_block_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < 2 {
            continue;
        }
        let Origin::Local(receiver_slot) = stack[stack.len() - 2] else {
            continue;
        };
        if site135_exact_read_edge_candidate(parsed, i, local_domains, receiver_slot) {
            push_unique_sorted(&mut slots, receiver_slot);
        }
    }
    slots
}

fn site135_read_edge_admission_site_indices(
    parsed: &[(usize, ParsedOp)],
    local_domains: Option<&[LocalDomain]>,
) -> std::collections::HashSet<usize> {
    let mut sites = std::collections::HashSet::new();
    for i in 0..parsed.len() {
        if !matches!(parsed[i].1, ParsedOp::GetIndexOnObject) {
            continue;
        }
        let Some(stack) = simulate_block_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < 2 {
            continue;
        }
        let Origin::Local(receiver_slot) = stack[stack.len() - 2] else {
            continue;
        };
        if site135_exact_read_edge_candidate(parsed, i, local_domains, receiver_slot) {
            sites.insert(i);
        }
    }
    sites
}

fn site135_prototype_hole_or_deopt_contract(
    parsed: &[(usize, ParsedOp)],
    site_index: usize,
    receiver_slot: Option<u16>,
    current_admitted: bool,
    current_generated_fast_path: bool,
    epoch_ref_available: bool,
    osr_deopt_block_available: bool,
    static_deopt_sites: usize,
) -> String {
    let Some(receiver_slot) = receiver_slot else {
        return "contract=false reason=no-direct-receiver-slot action=refuse".to_string();
    };
    let Some(stack) = simulate_expr_stack(&parsed[..site_index]) else {
        return "contract=false reason=expr-stack-unavailable action=refuse".to_string();
    };
    if stack.len() < 2 {
        return format!(
            "contract=false reason=expr-stack-too-shallow:{} action=refuse",
            stack.len()
        );
    }
    let Some(index) = stack[stack.len() - 1].affine_index else {
        return "contract=false reason=index-affine-missing action=refuse".to_string();
    };
    let same_receiver_upper = matches!(
        affine_exclusive_upper_bound_for_slot(parsed, index.slot),
        Some(PackedReadAffineUpperBound::TypedArrayLength {
            receiver_slot: bound_receiver
        }) if bound_receiver == receiver_slot
    );
    if !same_receiver_upper {
        return format!(
            "contract=false reason=no-same-receiver-upper-bound receiver_slot={receiver_slot} index_slot={} action=refuse",
            index.slot
        );
    }
    let action = if current_generated_fast_path {
        "consume-current-generated-fast-path"
    } else if osr_deopt_block_available || static_deopt_sites > 0 {
        "derive-packed-read-deopt-consumption"
    } else if current_admitted && epoch_ref_available {
        "guarded-meta-preserves-value-but-retains-static-helper"
    } else if epoch_ref_available {
        "derive-admission-plus-deopt-materialization"
    } else {
        "derive-prototype-epoch-and-deopt-materialization"
    };
    format!(
        "contract=false receiver_slot={receiver_slot} index_slot={} same_receiver_upper=true current_admitted={current_admitted} current_generated_fast_path={current_generated_fast_path} epoch_ref_available={epoch_ref_available} osr_deopt_block_available={osr_deopt_block_available} static_deopt_sites={static_deopt_sites} guarded_meta_value_safe=true guarded_meta_sheds_static_helper=false raw_inbounds_sheds_static_helper=true raw_inbounds_parity=failed-rung212 action={action}",
        index.slot
    )
}

