fn local_mask_assignment_bound(
    parsed: &[(usize, ParsedOp)],
    slot: u16,
) -> Option<PackedReadIndexMask> {
    let mut bound = None;
    let mut saw_assignment = false;
    for i in 0..parsed.len() {
        if !matches!(parsed[i].1, ParsedOp::StoreLocal(s) | ParsedOp::InitLocal(s) if s == slot) {
            continue;
        }
        saw_assignment = true;
        let stack = simulate_expr_stack(&parsed[..i])?;
        let mask = stack.last()?.bitand_mask?;
        match bound {
            Some(existing) if existing != mask => return None,
            Some(_) => {}
            None => bound = Some(mask),
        }
    }
    saw_assignment.then_some(bound?)
}

