fn packed_read_accumulator_range_guards(
    parsed: &[(usize, ParsedOp)],
) -> Vec<PackedReadAccumulatorRangeGuard> {
    let Some((induction_slot, bound_const)) = literal_lt_loop_bound(parsed) else {
        return Vec::new();
    };
    if !has_unit_induction_update(parsed, induction_slot) {
        return Vec::new();
    }

    let mut out = Vec::new();
    for add_idx in 1..parsed.len().saturating_sub(2) {
        if !matches!(parsed[add_idx].1, ParsedOp::Add) {
            continue;
        }
        let read_site_index = add_idx - 1;
        if !matches!(parsed[read_site_index].1, ParsedOp::GetIndexOnObject) {
            continue;
        }
        let Some(stack) = simulate_block_stack(&parsed[..read_site_index]) else {
            continue;
        };
        if stack.len() < 3 {
            continue;
        }
        let Origin::Local(accumulator_slot) = stack[stack.len() - 3] else {
            continue;
        };
        let Origin::Local(receiver_slot) = stack[stack.len() - 2] else {
            continue;
        };
        if !matches!(parsed[add_idx + 1].1, ParsedOp::Dup) {
            continue;
        }
        if !matches!(parsed[add_idx + 2].1, ParsedOp::StoreLocal(slot) if slot == accumulator_slot)
        {
            continue;
        }
        out.push(PackedReadAccumulatorRangeGuard {
            accumulator_slot,
            induction_slot,
            bound_slot: 0,
            bound_const: Some(bound_const),
            receiver_slot,
            read_site_index,
            add_site_index: add_idx,
        });
    }
    out.sort_by_key(|guard| guard.add_site_index);
    out.dedup();
    out
}

fn bounded_const_direct_leaf_delta(
    parsed: &[(usize, ParsedOp)],
    add_idx: usize,
) -> Option<(u16, i64, bool)> {
    let ParsedOp::CallDirectLeafConstI32 {
        callee_slot,
        leaf,
        arg0,
    } = parsed.get(add_idx.checked_sub(1)?)?.1
    else {
        return None;
    };
    let delta = direct_call_leaf_const_i32_result(leaf, arg0)?;
    if !delta.is_finite() || delta.fract() != 0.0 || delta <= 0.0 {
        return None;
    }
    let Some(ParsedOp::PushI32(pushed_arg)) =
        parsed.get(add_idx.checked_sub(2)?).map(|(_, op)| *op)
    else {
        return None;
    };
    if pushed_arg != arg0 {
        return None;
    }
    let Some(ParsedOp::LoadLocal(loaded_callee_slot)) =
        parsed.get(add_idx.checked_sub(3)?).map(|(_, op)| *op)
    else {
        return None;
    };
    if loaded_callee_slot != callee_slot {
        return None;
    }
    let Some(ParsedOp::LoadLocal(accumulator_slot)) =
        parsed.get(add_idx.checked_sub(4)?).map(|(_, op)| *op)
    else {
        return None;
    };
    if matches!(
        (
            parsed.get(add_idx + 1).map(|(_, op)| *op),
            parsed.get(add_idx + 2).map(|(_, op)| *op)
        ),
        (Some(ParsedOp::Dup), Some(ParsedOp::StoreLocal(slot))) if slot == accumulator_slot
    ) {
        return Some((accumulator_slot, delta as i64, false));
    }
    if matches!(
        (
            parsed.get(add_idx + 1).map(|(_, op)| *op),
            parsed.get(add_idx + 2).map(|(_, op)| *op),
            parsed.get(add_idx + 3).map(|(_, op)| *op),
            parsed.get(add_idx + 4).map(|(_, op)| *op)
        ),
        (
            Some(ParsedOp::PushI32(0)),
            Some(ParsedOp::BitOr),
            Some(ParsedOp::Dup),
            Some(ParsedOp::StoreLocal(slot))
        ) if slot == accumulator_slot
    ) {
        return Some((accumulator_slot, delta as i64, true));
    }
    None
}

fn bounded_direct_leaf_delta(
    parsed: &[(usize, ParsedOp)],
    add_idx: usize,
) -> Option<(u16, i64, bool)> {
    let ParsedOp::CallDirectLeaf {
        leaf: DirectCallLeaf::Arg0AddConst(delta),
        ..
    } = parsed.get(add_idx.checked_sub(1)?)?.1
    else {
        return None;
    };
    if !delta.is_finite() || delta.fract() != 0.0 || delta < 0.0 {
        return None;
    }
    let Some(ParsedOp::BitAnd) = parsed.get(add_idx.checked_sub(2)?).map(|(_, op)| *op) else {
        return None;
    };
    let Some(ParsedOp::PushI32(mask)) = parsed.get(add_idx.checked_sub(3)?).map(|(_, op)| *op)
    else {
        return None;
    };
    if mask < 0 {
        return None;
    }
    let Some(ParsedOp::LoadLocal(accumulator_slot)) =
        parsed.get(add_idx.checked_sub(6)?).map(|(_, op)| *op)
    else {
        return None;
    };
    if !matches!(
        parsed.get(add_idx + 1).map(|(_, op)| *op),
        Some(ParsedOp::Dup)
    ) {
        return None;
    }
    if !matches!(
        parsed.get(add_idx + 2).map(|(_, op)| *op),
        Some(ParsedOp::StoreLocal(slot)) if slot == accumulator_slot
    ) {
        return None;
    }
    Some((accumulator_slot, i64::from(mask) + delta as i64, false))
}

fn bounded_masked_delta(parsed: &[(usize, ParsedOp)], add_idx: usize) -> Option<(u16, i64, bool)> {
    if !matches!(
        parsed.get(add_idx).map(|(_, op)| *op),
        Some(ParsedOp::Add | ParsedOp::AddI64)
    ) {
        return None;
    }
    let Some(ParsedOp::BitAnd) = parsed.get(add_idx.checked_sub(1)?).map(|(_, op)| *op) else {
        return None;
    };
    let Some(ParsedOp::PushI32(mask)) = parsed.get(add_idx.checked_sub(2)?).map(|(_, op)| *op)
    else {
        return None;
    };
    if mask < 0 {
        return None;
    }
    let Some(ParsedOp::LoadLocal(accumulator_slot)) =
        parsed.get(add_idx.checked_sub(4)?).map(|(_, op)| *op)
    else {
        return None;
    };
    if !matches!(
        parsed.get(add_idx + 1).map(|(_, op)| *op),
        Some(ParsedOp::Dup)
    ) {
        return None;
    }
    if !matches!(
        parsed.get(add_idx + 2).map(|(_, op)| *op),
        Some(ParsedOp::StoreLocal(slot)) if slot == accumulator_slot
    ) {
        return None;
    }
    Some((accumulator_slot, i64::from(mask), false))
}

fn literal_lt_loop_bound(parsed: &[(usize, ParsedOp)]) -> Option<(u16, i64)> {
    lt_loop_bound_at(parsed, 0).and_then(|(induction_slot, _bound_slot, bound_const)| {
        bound_const.map(|bound| (induction_slot, bound))
    })
}

fn lt_loop_bound_starts(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    let mut starts = Vec::new();
    for start in 0..parsed.len().saturating_sub(3) {
        if lt_loop_bound_at(parsed, start).is_some() {
            starts.push(start);
        }
    }
    starts
}

fn lt_loop_bound_at(parsed: &[(usize, ParsedOp)], start: usize) -> Option<(u16, u16, Option<i64>)> {
    match (
        parsed.get(start).map(|(_, op)| *op),
        parsed.get(start + 1).map(|(_, op)| *op),
        parsed.get(start + 2).map(|(_, op)| *op),
        parsed.get(start + 3).map(|(_, op)| *op),
    ) {
        (
            Some(ParsedOp::LoadLocal(induction_slot)),
            Some(ParsedOp::PushI32(bound)),
            Some(ParsedOp::Lt | ParsedOp::LtI64),
            Some(ParsedOp::JumpIfFalse(_)),
        ) if bound >= 0 => Some((induction_slot, 0, Some(i64::from(bound)))),
        (
            Some(ParsedOp::LoadLocal(induction_slot)),
            Some(ParsedOp::LoadLocal(bound_slot)),
            Some(ParsedOp::Lt | ParsedOp::LtI64),
            Some(ParsedOp::JumpIfFalse(_)),
        ) if bound_slot != induction_slot => Some((induction_slot, bound_slot, None)),
        _ => None,
    }
}

fn has_unit_induction_update(parsed: &[(usize, ParsedOp)], induction_slot: u16) -> bool {
    has_unit_induction_update_from(parsed, 0, induction_slot)
}

fn has_unit_induction_update_from(
    parsed: &[(usize, ParsedOp)],
    start: usize,
    induction_slot: u16,
) -> bool {
    positive_literal_induction_update_from(parsed, start, induction_slot) == Some(1)
}

fn positive_literal_induction_update_from(
    parsed: &[(usize, ParsedOp)],
    start: usize,
    induction_slot: u16,
) -> Option<i64> {
    for idx in start..parsed.len() {
        if idx + 7 < parsed.len() {
            if let (
                ParsedOp::LoadLocal(load_slot),
                ParsedOp::ToNumeric,
                ParsedOp::Dup,
                ParsedOp::StoreLocal(_old_temp),
                ParsedOp::Inc,
                ParsedOp::StoreLocal(new_temp),
                ParsedOp::LoadLocal(load_temp),
                ParsedOp::StoreLocal(store_slot),
            ) = (
                parsed[idx].1,
                parsed[idx + 1].1,
                parsed[idx + 2].1,
                parsed[idx + 3].1,
                parsed[idx + 4].1,
                parsed[idx + 5].1,
                parsed[idx + 6].1,
                parsed[idx + 7].1,
            ) {
                if load_slot == induction_slot
                    && load_temp == new_temp
                    && store_slot == induction_slot
                {
                    return Some(1);
                }
            }
        }
        if idx + 4 < parsed.len()
            && matches!(parsed[idx].1, ParsedOp::LoadLocal(slot) if slot == induction_slot)
            && matches!(parsed[idx + 1].1, ParsedOp::PushI32(delta) if delta > 0)
            && matches!(parsed[idx + 2].1, ParsedOp::Add | ParsedOp::AddI64)
            && matches!(parsed[idx + 3].1, ParsedOp::Dup)
            && matches!(parsed[idx + 4].1, ParsedOp::StoreLocal(slot) if slot == induction_slot)
        {
            if let ParsedOp::PushI32(delta) = parsed[idx + 1].1 {
                return Some(i64::from(delta));
            }
        }
    }
    None
}

fn masked_accumulator_u30_guards(
    parsed: &[(usize, ParsedOp)],
    packed_read_i64_sites: &std::collections::HashSet<usize>,
) -> Vec<MaskedAccumulatorU30Guard> {
    let mut out = Vec::new();
    for bitand_idx in 0..parsed.len() {
        if !matches!(parsed[bitand_idx].1, ParsedOp::BitAnd) {
            continue;
        }
        if bitand_idx + 2 >= parsed.len() || !matches!(parsed[bitand_idx + 1].1, ParsedOp::Dup) {
            continue;
        }
        let ParsedOp::StoreLocal(accumulator_slot) = parsed[bitand_idx + 2].1 else {
            continue;
        };
        if !matches!(
            parsed.get(bitand_idx.wrapping_sub(1)).map(|(_, op)| op),
            Some(ParsedOp::PushI32(1_073_741_823))
        ) {
            continue;
        }

        let mut start = 0;
        for j in (0..bitand_idx).rev() {
            if matches!(
                parsed[j].1,
                ParsedOp::StoreLocal(_)
                    | ParsedOp::InitLocal(_)
                    | ParsedOp::Jump(_)
                    | ParsedOp::JumpIfTrue(_)
                    | ParsedOp::JumpIfFalse(_)
                    | ParsedOp::Pop
            ) {
                start = j + 1;
                break;
            }
        }

        let mut receiver_slots = Vec::new();
        let mut add_site_indices = Vec::new();
        let mut rejected = false;
        for add_idx in start..bitand_idx {
            if !matches!(parsed[add_idx].1, ParsedOp::Add) {
                continue;
            }
            if add_idx == 0 || !matches!(parsed[add_idx - 1].1, ParsedOp::GetIndexOnObject) {
                continue;
            }
            let get_index_site = add_idx - 1;
            if !packed_read_i64_sites.contains(&get_index_site) {
                rejected = true;
                break;
            }
            let Some(stack) = simulate_block_stack(&parsed[..get_index_site]) else {
                rejected = true;
                break;
            };
            if stack.len() < 2 {
                rejected = true;
                break;
            }
            let Origin::Local(receiver_slot) = stack[stack.len() - 2] else {
                rejected = true;
                break;
            };
            push_unique_sorted(&mut receiver_slots, receiver_slot);
            add_site_indices.push(add_idx);
        }
        if rejected
            || receiver_slots.is_empty()
            || add_site_indices.is_empty()
            || add_site_indices.len() > 8
        {
            continue;
        }
        out.push(MaskedAccumulatorU30Guard {
            accumulator_slot,
            receiver_slots,
            add_site_indices,
        });
    }
    out.sort_by_key(|guard| guard.accumulator_slot);
    out.dedup();
    out
}

fn pure_numeric_masked_accumulator_guard_elision_sites(
    parsed: &[(usize, ParsedOp)],
) -> std::collections::HashSet<usize> {
    let mut out = std::collections::HashSet::new();
    if parsed.iter().any(|(_, op)| {
        matches!(
            op,
            ParsedOp::GetIndexOnObject
                | ParsedOp::SetIndexOnObject
                | ParsedOp::GetPropOnObject(_)
                | ParsedOp::SetPropOnObject(_)
                | ParsedOp::IcPropertyGet(_)
                | ParsedOp::IcMethodResolve(_)
                | ParsedOp::IcMethodCall(_)
                | ParsedOp::HostNativeMethod1ObjRet { .. }
                | ParsedOp::HostNativeMethod2ObjRet { .. }
                | ParsedOp::HostNativeMethod1NumRet { .. }
                | ParsedOp::ArrayIsArrayStatic
                | ParsedOp::HostNativeMethod1String { .. }
                | ParsedOp::HostNativeMethod2String { .. }
                | ParsedOp::HostNativeMethod4String { .. }
                | ParsedOp::HostNativeObjectMethod0 { .. }
                | ParsedOp::HostNativeObjectMethod1String { .. }
                | ParsedOp::HostNativeConstructor1ObjRet { .. }
                | ParsedOp::CallDirect { .. }
                | ParsedOp::CallDirectLeaf { .. }
                | ParsedOp::CallDirectLeafConstI32 { .. }
                | ParsedOp::CallDirectLeaf2 { .. }
                | ParsedOp::CallDirectLeaf2ConstI32 { .. }
        )
    }) {
        return out;
    }

    for bitand_idx in 0..parsed.len() {
        if !matches!(parsed[bitand_idx].1, ParsedOp::BitAnd) {
            continue;
        }
        if bitand_idx + 2 >= parsed.len() || !matches!(parsed[bitand_idx + 1].1, ParsedOp::Dup) {
            continue;
        }
        let ParsedOp::StoreLocal(accumulator_slot) = parsed[bitand_idx + 2].1 else {
            continue;
        };
        if !matches!(
            parsed.get(bitand_idx.wrapping_sub(1)).map(|(_, op)| op),
            Some(ParsedOp::PushI32(1_073_741_823))
        ) {
            continue;
        }
        let Some(expr_stack) = simulate_expr_stack(&parsed[..bitand_idx]) else {
            continue;
        };
        if expr_stack.len() < 2 {
            continue;
        }
        let lhs = &expr_stack[expr_stack.len() - 2];
        let rhs = &expr_stack[expr_stack.len() - 1];
        let masked_expr = if rhs.const_i32 == Some(1_073_741_823) {
            lhs
        } else if lhs.const_i32 == Some(1_073_741_823) {
            rhs
        } else {
            continue;
        };
        if masked_expr.masked_index_guard_op_sites.is_empty() {
            continue;
        }
        let mask_slots = local_bitand_mask_slots_in_region(parsed, 0, bitand_idx);
        if !masked_expr.locals.iter().all(|slot| {
            *slot == accumulator_slot
                || mask_slots.contains(slot)
                || affine_exclusive_upper_bound_for_slot(parsed, *slot).is_some()
        }) {
            continue;
        }
        for site in &masked_expr.masked_index_guard_op_sites {
            if matches!(
                parsed.get(site.site_index).map(|(_, op)| op),
                Some(ParsedOp::Add | ParsedOp::AddI64 | ParsedOp::Mul | ParsedOp::MulI64)
            ) {
                out.insert(site.site_index);
            }
        }
    }
    out
}

fn local_bitand_mask_slots_in_region(
    parsed: &[(usize, ParsedOp)],
    start: usize,
    end: usize,
) -> Vec<u16> {
    let mut out = Vec::new();
    for i in start..end.min(parsed.len()) {
        if !matches!(parsed[i].1, ParsedOp::BitAnd) {
            continue;
        }
        let Some(stack) = simulate_expr_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < 2 {
            continue;
        }
        let lhs = &stack[stack.len() - 2];
        let rhs = &stack[stack.len() - 1];
        match (lhs.origin, rhs.origin) {
            (_, Origin::Local(slot)) => push_unique_sorted(&mut out, slot),
            (Origin::Local(slot), _) => push_unique_sorted(&mut out, slot),
            _ => {}
        }
    }
    out
}

fn object_receiver_slots_in_block(parsed: &[(usize, ParsedOp)]) -> std::collections::HashSet<u16> {
    let mut object_slots = std::collections::HashSet::new();
    for (_, _, slot) in direct_call0_object_return_store_sites(parsed) {
        object_slots.insert(slot);
    }
    for i in 0..parsed.len() {
        if !matches!(
            parsed[i].1,
            ParsedOp::GetIndexOnObject | ParsedOp::GetPropOnObject(_)
        ) {
            continue;
        }
        let Some(stack) = simulate_block_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < 2 {
            continue;
        }
        if let Origin::Local(slot) = stack[stack.len() - 2] {
            object_slots.insert(slot);
        }
    }
    object_slots
}

fn direct_call_object_arg_sites(parsed: &[(usize, ParsedOp)]) -> Vec<(usize, u16, u16)> {
    let object_slots = object_receiver_slots_in_block(parsed);
    let mut sites = Vec::new();
    for i in 0..parsed.len() {
        let ParsedOp::CallDirect {
            arity: 1,
            callee_slot,
        } = parsed[i].1
        else {
            continue;
        };
        let Some(stack) = simulate_block_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < 2 {
            continue;
        }
        if let Origin::Local(arg_slot) = stack[stack.len() - 1] {
            if object_slots.contains(&arg_slot) {
                sites.push((parsed[i].0, callee_slot, arg_slot));
            }
        }
    }
    sites
}

fn direct_call2_object_numeric_arg_sites(parsed: &[(usize, ParsedOp)]) -> Vec<(usize, u16, u16)> {
    let object_slots = object_receiver_slots_in_block(parsed);
    let mut sites = Vec::new();
    for i in 0..parsed.len() {
        let callee_slot = match parsed[i].1 {
            ParsedOp::CallDirect {
                arity: 2,
                callee_slot,
            }
            | ParsedOp::CallDirectLeaf2 { callee_slot, .. } => callee_slot,
            ParsedOp::CallDirectLeaf2ConstI32 { callee_slot, .. } => callee_slot,
            _ => continue,
        };
        let Some(stack) = simulate_block_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < 3 {
            continue;
        }
        if let Origin::Local(arg_slot) = stack[stack.len() - 2] {
            if object_slots.contains(&arg_slot) {
                sites.push((parsed[i].0, callee_slot, arg_slot));
            }
        }
    }
    sites
}

fn direct_call2_receiver_slot(parsed_prefix: &[(usize, ParsedOp)]) -> Option<u16> {
    let stack = simulate_block_stack(parsed_prefix)?;
    if stack.len() < 3 {
        return None;
    }
    match stack[stack.len() - 2] {
        Origin::Local(slot) => Some(slot),
        _ => None,
    }
}

fn direct_call_packed_sum_receiver_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut slots = Vec::new();
    for (_, op) in parsed {
        let ParsedOp::CallDirectLeaf2ConstI32 {
            leaf: DirectCallLeaf::Arg0PackedSumArg1,
            receiver_slot: Some(slot),
            ..
        } = op
        else {
            continue;
        };
        if !slot_is_assigned_in_body(parsed, *slot) && !slots.contains(slot) {
            slots.push(*slot);
        }
    }
    slots.sort_unstable();
    slots
}

fn slot_is_assigned_in_body(parsed: &[(usize, ParsedOp)], slot: u16) -> bool {
    parsed.iter().any(|(_, op)| {
        matches!(
            op,
            ParsedOp::StoreLocal(s) | ParsedOp::InitLocal(s) | ParsedOp::TdzSeedLocal(s)
                if *s == slot
        )
    })
}

fn direct_call0_object_return_store_sites(parsed: &[(usize, ParsedOp)]) -> Vec<(usize, u16, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(1) {
        let ParsedOp::CallDirect {
            arity: 0,
            callee_slot,
        } = parsed[i].1
        else {
            continue;
        };
        if let ParsedOp::StoreLocal(dst_slot) | ParsedOp::InitLocal(dst_slot) = parsed[i + 1].1 {
            sites.push((parsed[i].0, callee_slot, dst_slot));
        }
    }
    sites
}

fn direct_call1_object_return_sites(parsed: &[(usize, ParsedOp)]) -> Vec<(usize, u16, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(1) {
        let ParsedOp::CallDirect {
            arity: 1,
            callee_slot,
        } = parsed[i].1
        else {
            continue;
        };
        let next = if matches!(parsed[i + 1].1, ParsedOp::IcMethodResolve(_)) {
            parsed.get(i + 2).map(|(_, op)| op)
        } else {
            parsed.get(i + 1).map(|(_, op)| op)
        };
        match next {
            Some(ParsedOp::StoreLocal(dst_slot)) | Some(ParsedOp::InitLocal(dst_slot)) => {
                sites.push((parsed[i].0, callee_slot, *dst_slot));
            }
            Some(ParsedOp::IcMethodCall(_)) => {
                sites.push((parsed[i].0, callee_slot, u16::MAX));
            }
            Some(ParsedOp::CallDirect { arity: 1, .. }) => {
                sites.push((parsed[i].0, callee_slot, u16::MAX));
            }
            _ => {}
        }
    }
    sites
}

fn direct_call2_object_return_sites(parsed: &[(usize, ParsedOp)]) -> Vec<(usize, u16, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(1) {
        let ParsedOp::CallDirect {
            arity: 2,
            callee_slot,
        } = parsed[i].1
        else {
            continue;
        };
        match parsed.get(i + 1).map(|(_, op)| op) {
            Some(ParsedOp::StoreLocal(dst_slot)) | Some(ParsedOp::InitLocal(dst_slot)) => {
                sites.push((parsed[i].0, callee_slot, *dst_slot));
            }
            _ => {}
        }
    }
    sites
}

fn materialized_helper_object_return_arg_sites(
    parsed: &[(usize, ParsedOp)],
) -> Vec<(usize, u16, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(3) {
        let (arity, callee_slot) = match parsed[i].1 {
            ParsedOp::CallDirect {
                arity: 1 | 2,
                callee_slot,
            } => {
                let ParsedOp::CallDirect { arity, .. } = parsed[i].1 else {
                    unreachable!()
                };
                (arity, callee_slot)
            }
            _ => continue,
        };
        let Some(stack) = simulate_block_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < usize::from(arity) + 1 {
            continue;
        }
        let Some(arg0_stack_index) = stack.len().checked_sub(usize::from(arity)) else {
            continue;
        };
        let Origin::Local(arg0_slot) = stack[arg0_stack_index] else {
            continue;
        };
        let (ParsedOp::StoreLocal(dst_slot) | ParsedOp::InitLocal(dst_slot)) = parsed[i + 1].1
        else {
            continue;
        };
        if !matches!(parsed[i + 2].1, ParsedOp::LoadLocal(slot) if slot == dst_slot) {
            continue;
        }
        if !matches!(parsed[i + 3].1, ParsedOp::JumpIfFalse(_)) {
            continue;
        }
        sites.push((parsed[i].0, callee_slot, arg0_slot));
    }
    sites
}

fn direct_call1_stack_fed_direct_call_object_return_sites(
    parsed: &[(usize, ParsedOp)],
) -> Vec<(usize, u16, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(1) {
        let ParsedOp::CallDirect {
            arity: 1,
            callee_slot,
        } = parsed[i].1
        else {
            continue;
        };
        if let ParsedOp::CallDirect {
            arity: 1,
            callee_slot: consumer_slot,
        } = parsed[i + 1].1
        {
            sites.push((parsed[i].0, callee_slot, consumer_slot));
        }
    }
    sites
}

fn direct_call1_object_return_nonnull_guard_sites(
    parsed: &[(usize, ParsedOp)],
) -> Vec<(usize, u16, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(1) {
        let ParsedOp::CallDirect {
            arity: 1,
            callee_slot,
        } = parsed[i].1
        else {
            continue;
        };
        let (ParsedOp::StoreLocal(dst_slot) | ParsedOp::InitLocal(dst_slot)) = parsed[i + 1].1
        else {
            continue;
        };
        for j in (i + 2)..parsed.len().saturating_sub(2) {
            if matches!(
                parsed[j].1,
                ParsedOp::Jump(_)
                    | ParsedOp::JumpIfTrue(_)
                    | ParsedOp::JumpIfFalse(_)
                    | ParsedOp::Return
                    | ParsedOp::ReturnUndef
            ) {
                break;
            }
            if matches!(parsed[j].1, ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) if slot == dst_slot)
            {
                break;
            }
            if !matches!(parsed[j].1, ParsedOp::LoadLocal(slot) if slot == dst_slot) {
                continue;
            }
            if matches!(parsed[j + 1].1, ParsedOp::PushNull)
                && matches!(
                    parsed[j + 2].1,
                    ParsedOp::Eq | ParsedOp::StrictEq | ParsedOp::Ne | ParsedOp::StrictNe
                )
                && !parsed[j + 3..].iter().any(|(_, later_op)| {
                    matches!(later_op, ParsedOp::LoadLocal(slot) if *slot == dst_slot)
                })
            {
                sites.push((parsed[i].0, callee_slot, dst_slot));
            }
            break;
        }
    }
    sites
}

fn regexp_exec_object_or_null_nonnull_region_sites(
    parsed: &[(usize, ParsedOp)],
) -> Vec<(usize, u16, usize)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(5) {
        if !matches!(parsed[i].1, ParsedOp::IcMethodCall(idx)
            if crate::ic_table::IC_TABLE.get(idx as usize).is_some_and(|entry| entry.key == "exec"))
        {
            continue;
        }
        let (store_idx, dst_slot) = match parsed.get(i + 1).map(|(_, op)| op) {
            Some(ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot)) => (i + 1, *slot),
            Some(ParsedOp::Dup) => match parsed.get(i + 2).map(|(_, op)| op) {
                Some(ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot)) => (i + 2, *slot),
                _ => continue,
            },
            _ => continue,
        };
        if matches!(
            parsed.get(store_idx + 1).map(|(_, op)| op),
            Some(ParsedOp::PushNull)
        ) && matches!(
            parsed.get(store_idx + 2).map(|(_, op)| op),
            Some(ParsedOp::StrictNe | ParsedOp::Ne)
        ) {
            let Some((_, ParsedOp::JumpIfFalse(exit_pc))) = parsed.get(store_idx + 3) else {
                continue;
            };
            let exit_idx =
                regexp_exec_object_or_null_region_exit_idx(parsed, store_idx + 3, *exit_pc);
            if exit_idx <= store_idx + 4 {
                continue;
            }
            let mut read_inside_nonnull_region = false;
            let mut unsafe_write_inside_region = false;
            for k in (store_idx + 4)..exit_idx {
                if matches!(parsed[k].1, ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) if slot == dst_slot)
                {
                    unsafe_write_inside_region = true;
                    break;
                }
                if matches!(parsed[k].1, ParsedOp::LoadLocal(slot) if slot == dst_slot) {
                    read_inside_nonnull_region = true;
                }
            }
            if read_inside_nonnull_region && !unsafe_write_inside_region {
                sites.push((parsed[i].0, dst_slot, parsed[store_idx + 1].0));
            }
            continue;
        }
        for j in (store_idx + 1)..parsed.len().saturating_sub(3) {
            if matches!(parsed[j].1, ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) if slot == dst_slot)
            {
                break;
            }
            if !matches!(parsed[j].1, ParsedOp::LoadLocal(slot) if slot == dst_slot) {
                continue;
            }
            if !matches!(parsed[j + 1].1, ParsedOp::PushNull)
                || !matches!(parsed[j + 2].1, ParsedOp::StrictNe | ParsedOp::Ne)
            {
                continue;
            }
            let ParsedOp::JumpIfFalse(exit_pc) = parsed[j + 3].1 else {
                continue;
            };
            let exit_idx = regexp_exec_object_or_null_region_exit_idx(parsed, j + 3, exit_pc);
            if exit_idx <= j + 4 {
                continue;
            }
            let mut read_inside_nonnull_region = false;
            let mut unsafe_write_inside_region = false;
            for k in (j + 4)..exit_idx {
                if matches!(parsed[k].1, ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) if slot == dst_slot)
                {
                    unsafe_write_inside_region = true;
                    break;
                }
                if matches!(parsed[k].1, ParsedOp::LoadLocal(slot) if slot == dst_slot) {
                    read_inside_nonnull_region = true;
                }
            }
            if read_inside_nonnull_region && !unsafe_write_inside_region {
                sites.push((parsed[i].0, dst_slot, parsed[j].0));
            }
            break;
        }
    }
    sites
}

fn regexp_exec_object_or_null_domain_enabled(parsed: &[(usize, ParsedOp)]) -> bool {
    match std::env::var("CRUFT_LEJIT_REGEXP_EXEC_OBJECT_OR_NULL_DOMAIN") {
        Ok(v) if v == "0" || v.eq_ignore_ascii_case("false") || v.eq_ignore_ascii_case("off") => {
            false
        }
        Ok(_) => true,
        Err(_) => !regexp_exec_object_or_null_length_consumers(parsed).is_empty(),
    }
}

fn regexp_exec_object_or_null_region_exit_idx(
    parsed: &[(usize, ParsedOp)],
    jump_idx: usize,
    exit_pc: usize,
) -> usize {
    parsed
        .iter()
        .position(|(pc, _)| *pc == exit_pc)
        .filter(|idx| *idx > jump_idx)
        .or_else(|| {
            parsed[jump_idx + 1..]
                .iter()
                .position(|(_, op)| {
                    matches!(
                        op,
                        ParsedOp::Jump(_)
                            | ParsedOp::JumpIfTrue(_)
                            | ParsedOp::JumpIfFalse(_)
                            | ParsedOp::Return
                            | ParsedOp::ReturnUndef
                    )
                })
                .map(|rel| jump_idx + 1 + rel)
        })
        .unwrap_or(parsed.len())
}

fn regexp_exec_object_or_null_narrowed_receiver_sites(
    parsed: &[(usize, ParsedOp)],
    want_getindex: bool,
) -> Vec<usize> {
    let mut sites = Vec::new();
    for (_, dst_slot, guard_pc) in regexp_exec_object_or_null_nonnull_region_sites(parsed) {
        let Some(guard_idx) = parsed.iter().position(|(pc, _)| *pc == guard_pc) else {
            continue;
        };
        let Some((_, ParsedOp::JumpIfFalse(exit_pc))) = parsed.get(guard_idx + 3) else {
            continue;
        };
        let Some(exit_idx) = parsed.iter().position(|(pc, _)| *pc == *exit_pc) else {
            continue;
        };
        for site_idx in (guard_idx + 4)..exit_idx {
            if want_getindex {
                if !matches!(parsed[site_idx].1, ParsedOp::GetIndexOnObject) {
                    continue;
                }
                let Some(st) = simulate_block_stack(&parsed[(guard_idx + 4)..site_idx]) else {
                    continue;
                };
                let n = st.len();
                if n >= 2 && st[n - 2] == Origin::Local(dst_slot) {
                    sites.push(site_idx);
                }
            } else {
                if !matches!(parsed[site_idx].1, ParsedOp::GetPropOnObject(_)) {
                    continue;
                }
                let Some(st) = simulate_block_stack(&parsed[(guard_idx + 4)..site_idx]) else {
                    continue;
                };
                if st.last().copied() == Some(Origin::Local(dst_slot)) {
                    sites.push(site_idx);
                }
            }
        }
    }
    sites.sort_unstable();
    sites.dedup();
    sites
}

fn regexp_exec_object_or_null_narrowed_getindex_sites(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    regexp_exec_object_or_null_narrowed_receiver_sites(parsed, true)
}

fn regexp_exec_object_or_null_narrowed_getprop_sites(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    regexp_exec_object_or_null_narrowed_receiver_sites(parsed, false)
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RegexpObjectOrNullLengthConsumer {
    exec_pc: usize,
    match_slot: u16,
    getindex_pc: usize,
    getindex_op_index: usize,
    getprop_pc: usize,
    prop_idx: u16,
}

fn regexp_exec_object_or_null_guard_window(
    parsed: &[(usize, ParsedOp)],
    guard_pc: usize,
) -> Option<(usize, usize)> {
    let guard_idx = parsed.iter().position(|(pc, _)| *pc == guard_pc)?;
    let jump_idx = match parsed.get(guard_idx).map(|(_, op)| op) {
        Some(ParsedOp::PushNull) => guard_idx + 2,
        Some(ParsedOp::LoadLocal(_)) => guard_idx + 3,
        _ => (guard_idx + 1..=guard_idx + 3).find(|idx| {
            matches!(
                parsed.get(*idx).map(|(_, op)| op),
                Some(ParsedOp::JumpIfFalse(_))
            )
        })?,
    };
    let exit_pc = match parsed.get(jump_idx).map(|(_, op)| op)? {
        ParsedOp::JumpIfFalse(exit_pc) => *exit_pc,
        _ => return None,
    };
    let exit_idx = parsed
        .iter()
        .position(|(pc, _)| *pc == exit_pc)
        .filter(|idx| *idx > jump_idx)
        .or_else(|| {
            parsed[jump_idx + 1..]
                .iter()
                .position(|(_, op)| {
                    matches!(
                        op,
                        ParsedOp::Jump(_) | ParsedOp::Return | ParsedOp::ReturnUndef
                    )
                })
                .map(|rel| jump_idx + 1 + rel)
        })
        .unwrap_or(parsed.len());
    Some((jump_idx + 1, exit_idx.max(jump_idx + 1)))
}

fn regexp_exec_object_or_null_length_consumers(
    parsed: &[(usize, ParsedOp)],
) -> Vec<RegexpObjectOrNullLengthConsumer> {
    let mut sites = Vec::new();
    for (exec_pc, dst_slot, guard_pc) in regexp_exec_object_or_null_nonnull_region_sites(parsed) {
        let Some((body_start, body_end)) =
            regexp_exec_object_or_null_guard_window(parsed, guard_pc)
        else {
            continue;
        };
        for site_idx in body_start..body_end.saturating_sub(1) {
            if !matches!(parsed[site_idx].1, ParsedOp::GetIndexOnObject) {
                continue;
            }
            let Some((getprop_pc, prop_idx)) =
                regexp_exec_object_or_null_length_prop(parsed.get(site_idx + 1))
            else {
                continue;
            };
            let receiver_is_exec_result = simulate_block_stack(&parsed[body_start..site_idx])
                .and_then(|st| {
                    let n = st.len();
                    (n >= 2).then_some(st[n - 2])
                })
                .is_some_and(|origin| origin == Origin::Local(dst_slot));
            if receiver_is_exec_result {
                sites.push(RegexpObjectOrNullLengthConsumer {
                    exec_pc,
                    match_slot: dst_slot,
                    getindex_pc: parsed[site_idx].0,
                    getindex_op_index: site_idx,
                    getprop_pc: *getprop_pc,
                    prop_idx,
                });
            }
        }
    }
    sites
}

#[cfg(test)]
fn regexp_exec_object_or_null_indexed_length_sites(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    regexp_exec_object_or_null_indexed_length_sites_from_consumers(
        &regexp_exec_object_or_null_length_consumers(parsed),
    )
}

fn regexp_exec_object_or_null_indexed_length_sites_from_consumers(
    consumers: &[RegexpObjectOrNullLengthConsumer],
) -> Vec<usize> {
    let mut sites: Vec<usize> = consumers
        .iter()
        .map(|site| site.getindex_op_index)
        .collect();
    sites.sort_unstable();
    sites.dedup();
    sites
}

fn regexp_exec_object_or_null_length_prop(
    next: Option<&(usize, ParsedOp)>,
) -> Option<(&usize, u16)> {
    match next {
        Some((pc, ParsedOp::GetPropOnObject(prop_idx))) => Some((pc, *prop_idx)),
        Some((pc, ParsedOp::IcPropertyGet(prop_idx))) => Some((pc, u16::from(*prop_idx))),
        _ => None,
    }
}

fn direct_call1_void_return_sites(parsed: &[(usize, ParsedOp)]) -> Vec<(usize, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(1) {
        let ParsedOp::CallDirect {
            arity: 1,
            callee_slot,
        } = parsed[i].1
        else {
            continue;
        };
        if matches!(parsed[i + 1].1, ParsedOp::Return | ParsedOp::Pop)
            || matches!(
                (
                    parsed.get(i + 1).map(|(_, op)| op),
                    parsed.get(i + 2).map(|(_, op)| op)
                ),
                (Some(ParsedOp::Pop), Some(ParsedOp::ReturnUndef))
            )
        {
            sites.push((parsed[i].0, callee_slot));
        }
    }
    sites
}

fn host_native_constructor_object_return_store_sites(
    parsed: &[(usize, ParsedOp)],
) -> Vec<(usize, u16, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(1) {
        let ParsedOp::HostNativeConstructor1ObjRet { ctor_slot, .. } = parsed[i].1 else {
            continue;
        };
        match parsed[i + 1].1 {
            ParsedOp::StoreLocal(dst_slot)
            | ParsedOp::InitLocal(dst_slot)
            | ParsedOp::StoreScriptGlobalVar { slot: dst_slot, .. } => {
                sites.push((parsed[i].0, ctor_slot, dst_slot));
            }
            _ => {}
        }
    }
    sites
}

fn object_index_read_result_sites(parsed: &[(usize, ParsedOp)]) -> Vec<(usize, u16)> {
    let mut sites = Vec::new();
    for i in 0..parsed.len().saturating_sub(1) {
        if !matches!(parsed[i].1, ParsedOp::GetIndexOnObject) {
            continue;
        }
        let dst_slot = match parsed[i + 1].1 {
            ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) => slot,
            _ => continue,
        };
        let later_receiver_use = parsed[i + 2..].iter().enumerate().any(|(rel, (_, op))| {
            let j = i + 2 + rel;
            match op {
                ParsedOp::GetPropOnObject(_) => simulate_block_stack(&parsed[..j])
                    .and_then(|st| st.last().copied())
                    .is_some_and(|origin| origin == Origin::Local(dst_slot)),
                ParsedOp::SetPropOnObject(_) => simulate_block_stack(&parsed[..j])
                    .and_then(|st| {
                        let n = st.len();
                        if n >= 2 {
                            Some(st[n - 2])
                        } else {
                            None
                        }
                    })
                    .is_some_and(|origin| origin == Origin::Local(dst_slot)),
                _ => false,
            }
        });
        if later_receiver_use {
            sites.push((parsed[i].0, dst_slot));
        }
    }
    sites
}

fn object_index_read_result_pcs(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    let mut out = object_index_read_result_sites(parsed)
        .into_iter()
        .map(|(pc, _)| pc)
        .collect::<Vec<_>>();
    for i in 0..parsed.len().saturating_sub(1) {
        if matches!(parsed[i].1, ParsedOp::GetIndexOnObject)
            && matches!(parsed[i + 1].1, ParsedOp::GetPropOnObject(_))
            && !out.contains(&parsed[i].0)
        {
            out.push(parsed[i].0);
        }
    }
    out.sort_unstable();
    out
}

fn getindex_result_flows_to_object_local(
    parsed: &[(usize, ParsedOp)],
    getindex_idx: usize,
    local_domains: Option<&[LocalDomain]>,
) -> bool {
    if !matches!(
        parsed.get(getindex_idx).map(|(_, op)| op),
        Some(ParsedOp::GetIndexOnObject)
    ) {
        return false;
    }
    let Some(local_domains) = local_domains else {
        return false;
    };
    let Some((_, ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot))) =
        parsed.get(getindex_idx + 1)
    else {
        return false;
    };
    local_domains.get(*slot as usize) == Some(&LocalDomain::ObjectBits)
}

fn getindex_result_flows_to_property_read(
    parsed: &[(usize, ParsedOp)],
    getindex_idx: usize,
) -> bool {
    matches!(
        (
            parsed.get(getindex_idx).map(|(_, op)| op),
            parsed.get(getindex_idx + 1).map(|(_, op)| op),
        ),
        (
            Some(ParsedOp::GetIndexOnObject),
            Some(ParsedOp::GetPropOnObject(_))
        )
    )
}

fn getindex_result_flows_to_indexed_direct_call(
    parsed: &[(usize, ParsedOp)],
    getindex_idx: usize,
) -> bool {
    if !matches!(
        parsed.get(getindex_idx).map(|(_, op)| op),
        Some(ParsedOp::GetIndexOnObject)
    ) {
        return false;
    }
    let mut depth = 1usize;
    for (_, op) in parsed.iter().skip(getindex_idx + 1) {
        match op {
            ParsedOp::CallIndexedDirect1
            | ParsedOp::CallIndexedDirectLeaf1 { .. }
            | ParsedOp::CallIndexedDirectLeafSwitch1 { .. } => return depth >= 2,
            ParsedOp::LoadArg(_)
            | ParsedOp::LoadLocal(_)
            | ParsedOp::PushI32(_)
            | ParsedOp::PushConst(_)
            | ParsedOp::PushStringConst { .. }
            | ParsedOp::GlobalThis
            | ParsedOp::PendingStringGlobal
            | ParsedOp::PendingNumberGlobal
            | ParsedOp::StringFromCharCodeReceiver
            | ParsedOp::StringFromCharCodeCallee
            | ParsedOp::NewArrayEmpty
            | ParsedOp::NewArrayLiteral { .. } => {
                depth += 1;
            }
            ParsedOp::Inc
            | ParsedOp::Dec
            | ParsedOp::IncI64
            | ParsedOp::DecI64
            | ParsedOp::ToNumeric
            | ParsedOp::IcPropertyGet(_)
            | ParsedOp::GetPropOnObject(_)
            | ParsedOp::CwcStringPropLength(_)
            | ParsedOp::CwcBooleanPropAsNumber(_) => {
                if depth == 0 {
                    return false;
                }
            }
            ParsedOp::StringPropStrictEq { .. } => {
                depth += 1;
            }
            ParsedOp::CallDirect2PropPredicate { .. } => {
                depth += 1;
            }
            ParsedOp::AriaParentPredicateFusion { .. } => {
                depth += 1;
            }
            ParsedOp::Add
            | ParsedOp::AddConstTernaryI32 { .. }
            | ParsedOp::BitOrConstTernaryI32 { .. }
            | ParsedOp::Sub
            | ParsedOp::Mul
            | ParsedOp::Div
            | ParsedOp::Mod
            | ParsedOp::BitOr
            | ParsedOp::BitAnd
            | ParsedOp::BitXor
            | ParsedOp::UShr
            | ParsedOp::Lt
            | ParsedOp::Le
            | ParsedOp::Gt
            | ParsedOp::Ge
            | ParsedOp::Eq
            | ParsedOp::Ne
            | ParsedOp::StrictEq
            | ParsedOp::StrictNe
            | ParsedOp::AddI64
            | ParsedOp::SubI64
            | ParsedOp::MulI64
            | ParsedOp::LtI64
            | ParsedOp::LeI64
            | ParsedOp::GtI64
            | ParsedOp::GeI64
            | ParsedOp::EqI64
            | ParsedOp::NeI64
            | ParsedOp::GetIndexOnObject
            | ParsedOp::GetIndexStringOnObject
            | ParsedOp::StringConcatOwnedResult { .. }
            | ParsedOp::StringConcatLocalValue { .. }
            | ParsedOp::StringConcatLocalValuePreserveRight { .. }
            | ParsedOp::StringConcatOwnedPair
            | ParsedOp::StringConcatOwnedValue
            | ParsedOp::CallStringFromCharCode
            | ParsedOp::CallStringCtor => {
                if depth < 2 {
                    return false;
                }
                depth -= 1;
            }
            ParsedOp::Dup => {
                if depth == 0 {
                    return false;
                }
                depth += 1;
            }
            ParsedOp::Pop | ParsedOp::StoreLocal(_) | ParsedOp::InitLocal(_) => {
                if depth == 0 {
                    return false;
                }
                depth -= 1;
                if depth == 0 {
                    return false;
                }
            }
            ParsedOp::Jump(_)
            | ParsedOp::JumpIfTrue(_)
            | ParsedOp::JumpIfFalse(_)
            | ParsedOp::JumpIfFalseKeep(_)
            | ParsedOp::JumpIfTrueKeep(_)
            | ParsedOp::ScannerPredicateEnvelope { .. }
            | ParsedOp::Return
            | ParsedOp::ReturnUndef => return false,
            _ => return false,
        }
    }
    false
}

fn typed_array_length_bound_index_sites(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    let sites = typed_array_affine_index_sites(parsed);
    if sites.is_empty() {
        return Vec::new();
    }
    let groups = packed_read_affine_index_groups(&sites);
    let proofs = packed_read_affine_loop_bound_proofs(parsed, &groups);
    sites
        .into_iter()
        .filter(|site| {
            site.index.offset == 0
                && proofs.iter().any(|proof| {
                    proof.receiver_slot == site.receiver_slot
                        && proof.index_slot == site.index.slot
                        && proof.max_non_negative_offset == 0
                        && matches!(
                            proof.exclusive_upper_bound,
                            PackedReadAffineUpperBound::TypedArrayLength { receiver_slot }
                                if receiver_slot == site.receiver_slot
                        )
                })
        })
        .map(|site| site.site_index)
        .collect()
}

fn string_charcode_length_bound_sites(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    let string_slots = hoistable_string_charcode_receiver_slots(parsed);
    if string_slots.is_empty() {
        return Vec::new();
    }

    let mut sites = Vec::new();
    for i in 0..parsed.len() {
        let ParsedOp::IcMethodCall(idx) = parsed[i].1 else {
            continue;
        };
        let Some(entry) = crate::ic_table::IC_TABLE.get(idx as usize) else {
            continue;
        };
        if entry.key != "charCodeAt"
            || !matches!(
                entry.kind,
                crate::ic_table::IcEntryKind::MethodCall { arity: 1 }
            )
        {
            continue;
        }
        let Some(receiver_slot) = string_charcode_receiver_slot(&parsed[..i]) else {
            continue;
        };
        if !string_slots.contains(&receiver_slot) {
            continue;
        }
        let Some(expr_stack) = simulate_expr_stack(&parsed[..i]) else {
            continue;
        };
        let Some(index_expr) = expr_stack.last() else {
            continue;
        };
        let Some(index) = index_expr.affine_index else {
            continue;
        };
        if index.offset != 0 || !slot_has_nonnegative_integer_flow(parsed, index.slot) {
            continue;
        }
        if string_slot_bounds_index_slot(parsed, receiver_slot, index.slot) {
            sites.push(i);
        }
    }
    sites
}

fn string_charcode_length_bound_index_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut slots = Vec::new();
    for site in string_charcode_inbounds_sites(parsed) {
        if let Some(slot) = string_charcode_index_slot_for_site(parsed, site) {
            push_unique_sorted(&mut slots, slot);
        }
    }
    slots
}

fn string_charcode_inbounds_sites(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    let mut sites = string_charcode_length_bound_sites(parsed);
    for site in string_charcode_mod_length_bound_sites(parsed) {
        if !sites.contains(&site) {
            sites.push(site);
        }
    }
    sites.sort_unstable();
    sites
}

fn string_charcode_index_slot_for_site(parsed: &[(usize, ParsedOp)], site: usize) -> Option<u16> {
    let expr_stack = simulate_expr_stack(&parsed[..site])?;
    let expr = expr_stack.last()?;
    if let Some(index) = expr.affine_index {
        return (index.offset == 0).then_some(index.slot);
    }
    expr.string_mod_length_index
        .map(|(index_slot, _)| index_slot)
}

fn string_charcode_mod_length_bound_sites(parsed: &[(usize, ParsedOp)]) -> Vec<usize> {
    let string_slots = hoistable_string_charcode_receiver_slots(parsed);
    if string_slots.is_empty() {
        return Vec::new();
    }

    let mut sites = Vec::new();
    for i in 0..parsed.len() {
        let ParsedOp::IcMethodCall(idx) = parsed[i].1 else {
            continue;
        };
        let Some(entry) = crate::ic_table::IC_TABLE.get(idx as usize) else {
            continue;
        };
        if entry.key != "charCodeAt"
            || !matches!(
                entry.kind,
                crate::ic_table::IcEntryKind::MethodCall { arity: 1 }
            )
        {
            continue;
        }
        let Some(receiver_slot) = string_charcode_receiver_slot(&parsed[..i]) else {
            continue;
        };
        if !string_slots.contains(&receiver_slot) {
            continue;
        }
        let Some(expr_stack) = simulate_expr_stack(&parsed[..i]) else {
            continue;
        };
        let Some(index_expr) = expr_stack.last() else {
            continue;
        };
        if matches!(
            index_expr.string_mod_length_index,
            Some((index_slot, rhs_receiver_slot))
                if rhs_receiver_slot == receiver_slot
                    && slot_has_nonnegative_integer_flow(parsed, index_slot)
        ) {
            sites.push(i);
        }
    }
    sites
}

fn string_slot_bounds_index_slot(
    parsed: &[(usize, ParsedOp)],
    receiver_slot: u16,
    index_slot: u16,
) -> bool {
    for i in 0..parsed.len() {
        let compare = parsed[i].1;
        if !matches!(
            compare,
            ParsedOp::Lt
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Ge
                | ParsedOp::LtI64
                | ParsedOp::LeI64
                | ParsedOp::GtI64
                | ParsedOp::GeI64
        ) {
            continue;
        }
        if !matches!(
            parsed.get(i + 1).map(|(_, op)| *op),
            Some(ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_))
        ) {
            continue;
        }
        let Some(stack) = simulate_expr_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < 2 {
            continue;
        }
        let lhs = &stack[stack.len() - 2];
        let rhs = &stack[stack.len() - 1];
        let ordered = match compare {
            ParsedOp::Lt | ParsedOp::LtI64 | ParsedOp::Le | ParsedOp::LeI64 => {
                (lhs, rhs, matches!(compare, ParsedOp::Lt | ParsedOp::LtI64))
            }
            ParsedOp::Gt | ParsedOp::GtI64 | ParsedOp::Ge | ParsedOp::GeI64 => {
                (rhs, lhs, matches!(compare, ParsedOp::Gt | ParsedOp::GtI64))
            }
            _ => continue,
        };
        let (idx_expr, bound_expr, strict) = ordered;
        if !strict {
            continue;
        }
        if idx_expr.affine_index
            != Some(PackedReadAffineIndex {
                slot: index_slot,
                offset: 0,
            })
        {
            continue;
        }
        if bound_expr.string_length_receiver_slot == Some(receiver_slot) {
            return true;
        }
    }
    false
}

fn slot_has_nonnegative_integer_flow(parsed: &[(usize, ParsedOp)], slot: u16) -> bool {
    let mut saw_store = false;
    for i in 0..parsed.len() {
        let (ParsedOp::StoreLocal(store_slot) | ParsedOp::InitLocal(store_slot)) = parsed[i].1
        else {
            continue;
        };
        if store_slot != slot {
            continue;
        }
        saw_store = true;
        let int_literal_init = i >= 1 && matches!(parsed[i - 1].1, ParsedOp::PushI32(n) if n >= 0);
        let self_incdec = i >= 2
            && matches!(parsed[i - 1].1, ParsedOp::Inc | ParsedOp::IncI64)
            && matches!(parsed[i - 2].1, ParsedOp::LoadLocal(s) if s == slot);
        let post_inc = i >= 3
            && matches!(parsed[i - 1].1, ParsedOp::Inc | ParsedOp::IncI64)
            && matches!(parsed[i - 2].1, ParsedOp::Dup)
            && matches!(parsed[i - 3].1, ParsedOp::LoadLocal(s) if s == slot);
        let add_positive_const = i >= 3
            && matches!(parsed[i - 1].1, ParsedOp::Add | ParsedOp::AddI64)
            && matches!(parsed[i - 2].1, ParsedOp::PushI32(n) if n >= 0)
            && matches!(parsed[i - 3].1, ParsedOp::LoadLocal(s) if s == slot);
        let add_positive_const_with_dup = i >= 4
            && matches!(parsed[i - 1].1, ParsedOp::Dup)
            && matches!(parsed[i - 2].1, ParsedOp::Add | ParsedOp::AddI64)
            && matches!(parsed[i - 3].1, ParsedOp::PushI32(n) if n >= 0)
            && matches!(parsed[i - 4].1, ParsedOp::LoadLocal(s) if s == slot);
        let compiler_postinc_base_store = i >= 7
            && matches!(parsed[i - 7].1, ParsedOp::LoadLocal(s) if s == slot)
            && matches!(parsed[i - 6].1, ParsedOp::ToNumeric)
            && matches!(parsed[i - 5].1, ParsedOp::Dup)
            && matches!(parsed[i - 4].1, ParsedOp::StoreLocal(_))
            && matches!(parsed[i - 3].1, ParsedOp::Inc | ParsedOp::IncI64)
            && matches!(parsed[i - 2].1, ParsedOp::StoreLocal(new_slot)
                if matches!(parsed[i - 1].1, ParsedOp::LoadLocal(load_slot) if load_slot == new_slot));
        if !(int_literal_init
            || self_incdec
            || post_inc
            || add_positive_const
            || add_positive_const_with_dup
            || compiler_postinc_base_store)
        {
            return false;
        }
    }
    saw_store
}

fn typed_array_reduction_sites(parsed: &[(usize, ParsedOp)]) -> Vec<TypedArrayReductionSite> {
    let affine_sites = typed_array_affine_index_sites(parsed);
    if affine_sites.is_empty() {
        return Vec::new();
    }
    let bound_sites: std::collections::HashSet<usize> =
        typed_array_length_bound_index_sites(parsed)
            .into_iter()
            .collect();
    let mut reductions = Vec::new();

    for site in affine_sites {
        let i = site.site_index;
        if i < 3 || i + 4 >= parsed.len() {
            continue;
        }
        let ParsedOp::LoadLocal(accumulator_slot) = parsed[i - 3].1 else {
            continue;
        };
        if !matches!(parsed[i - 2].1, ParsedOp::LoadLocal(slot) if slot == site.receiver_slot) {
            continue;
        }
        if !matches!(parsed[i - 1].1, ParsedOp::LoadLocal(slot) if slot == site.index.slot) {
            continue;
        }
        if !matches!(parsed[i + 1].1, ParsedOp::Add) {
            continue;
        }
        if !matches!(parsed[i + 2].1, ParsedOp::Dup) {
            continue;
        }
        if !matches!(parsed[i + 3].1, ParsedOp::StoreLocal(slot) if slot == accumulator_slot) {
            continue;
        }
        if !matches!(parsed[i + 4].1, ParsedOp::Pop) {
            continue;
        }
        reductions.push(TypedArrayReductionSite {
            get_index_site: i,
            add_site: i + 1,
            receiver_slot: site.receiver_slot,
            index_slot: site.index.slot,
            index_offset: site.index.offset,
            accumulator_slot,
            bound_elided: bound_sites.contains(&i),
        });
    }

    reductions
}

fn typed_array_direct_entry_candidates(
    parsed: &[(usize, ParsedOp)],
    typed_array_kind_specs: &[TypedArrayKindSpec],
) -> Vec<TypedArrayDirectEntryCandidate> {
    typed_array_reduction_sites(parsed)
        .into_iter()
        .filter_map(|site| {
            let kind = typed_array_kind_specs
                .iter()
                .find(|spec| spec.receiver_slot == site.receiver_slot)
                .map(|spec| spec.kind)?;
            Some(TypedArrayDirectEntryCandidate {
                get_index_site: site.get_index_site,
                add_site: site.add_site,
                receiver_slot: site.receiver_slot,
                index_slot: site.index_slot,
                accumulator_slot: site.accumulator_slot,
                kind,
                bound_elided: site.bound_elided,
            })
        })
        .collect()
}

fn entry_stable_typed_array_kind_specs(
    parsed: &[(usize, ParsedOp)],
    typed_array_kind_specs: &[TypedArrayKindSpec],
) -> Vec<TypedArrayKindSpec> {
    let written_receiver_slots: std::collections::HashSet<u16> = parsed
        .iter()
        .filter_map(|(_, op)| match op {
            ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) => Some(*slot),
            _ => None,
        })
        .collect();
    typed_array_kind_specs
        .iter()
        .copied()
        .filter(|spec| !written_receiver_slots.contains(&spec.receiver_slot))
        .collect()
}

fn string_charcode_reduction_sites(
    parsed: &[(usize, ParsedOp)],
) -> Vec<StringCharCodeReductionSite> {
    let bound_sites: std::collections::HashSet<usize> =
        string_charcode_inbounds_sites(parsed).into_iter().collect();
    if bound_sites.is_empty() {
        return Vec::new();
    }

    let mut reductions = Vec::new();
    for &charcode_site in &bound_sites {
        let i = charcode_site;
        if i + 4 >= parsed.len() {
            continue;
        }
        let Some(add_stack) = simulate_expr_stack(&parsed[..i + 1]) else {
            continue;
        };
        if add_stack.len() < 2 {
            continue;
        }
        let Origin::Local(accumulator_slot) = add_stack[add_stack.len() - 2].origin else {
            continue;
        };
        let Some(receiver_slot) = string_charcode_receiver_slot(&parsed[..i]) else {
            continue;
        };
        let Some(index_slot) = string_charcode_index_slot_for_site(parsed, i) else {
            continue;
        };
        if !matches!(parsed[i + 1].1, ParsedOp::Add) {
            continue;
        }
        if !matches!(parsed[i + 2].1, ParsedOp::Dup) {
            continue;
        }
        if !matches!(parsed[i + 3].1, ParsedOp::StoreLocal(slot) if slot == accumulator_slot) {
            continue;
        }
        if !matches!(parsed[i + 4].1, ParsedOp::Pop) {
            continue;
        }
        reductions.push(StringCharCodeReductionSite {
            charcode_site: i,
            add_site: i + 1,
            receiver_slot,
            index_slot,
            accumulator_slot,
        });
    }
    reductions.sort_by_key(|site| site.charcode_site);
    reductions
}

fn typed_array_affine_index_sites(parsed: &[(usize, ParsedOp)]) -> Vec<PackedReadAffineIndexSite> {
    let mut sites = Vec::new();
    for i in 0..parsed.len() {
        if !matches!(parsed[i].1, ParsedOp::GetIndexOnObject) {
            continue;
        }
        let Some(origin_stack) = simulate_block_stack(&parsed[0..i]) else {
            continue;
        };
        let Some(expr_stack) = simulate_expr_stack(&parsed[0..i]) else {
            continue;
        };
        let n = origin_stack.len();
        if n < 2 || expr_stack.len() < 2 {
            continue;
        }
        let Origin::Local(receiver_slot) = origin_stack[n - 2] else {
            continue;
        };
        let Some(index) = expr_stack[expr_stack.len() - 1].affine_index else {
            continue;
        };
        sites.push(PackedReadAffineIndexSite {
            site_index: i,
            receiver_slot,
            index,
        });
    }
    sites
}

fn packed_read_affine_loop_bound_proofs(
    parsed: &[(usize, ParsedOp)],
    groups: &[PackedReadAffineIndexGroup],
) -> Vec<PackedReadAffineLoopBoundProof> {
    let mut proofs = Vec::new();
    for group in groups {
        let Some(exclusive_upper_bound) =
            affine_exclusive_upper_bound_for_slot(parsed, group.index_slot)
        else {
            continue;
        };
        match exclusive_upper_bound {
            PackedReadAffineUpperBound::TypedArrayLength { receiver_slot } => {
                if receiver_slot != group.receiver_slot {
                    continue;
                }
            }
            PackedReadAffineUpperBound::StringLength { .. } => continue,
            _ => {}
        }
        if !exclusive_upper_bound.can_fit_offset(group.max_non_negative_offset) {
            continue;
        }
        proofs.push(PackedReadAffineLoopBoundProof {
            receiver_slot: group.receiver_slot,
            index_slot: group.index_slot,
            max_non_negative_offset: group.max_non_negative_offset,
            exclusive_upper_bound,
        });
    }
    proofs.sort_by_key(|proof| (proof.receiver_slot, proof.index_slot));
    proofs
}

impl PackedReadAffineUpperBound {
    fn can_fit_offset(self, max_offset: i32) -> bool {
        match self {
            PackedReadAffineUpperBound::Constant(bound) => {
                bound > 0 && bound.checked_add(max_offset).is_some()
            }
            PackedReadAffineUpperBound::LocalMinusI32 { subtrahend, .. } => {
                subtrahend >= 0 && subtrahend.checked_sub(max_offset).is_some()
            }
            PackedReadAffineUpperBound::TypedArrayLength { .. } => max_offset == 0,
            PackedReadAffineUpperBound::StringLength { .. } => max_offset == 0,
        }
    }
}

fn affine_exclusive_upper_bound_for_slot(
    parsed: &[(usize, ParsedOp)],
    slot: u16,
) -> Option<PackedReadAffineUpperBound> {
    let mut best: Option<PackedReadAffineUpperBound> = None;
    for i in 0..parsed.len() {
        let compare = parsed[i].1;
        if !matches!(
            compare,
            ParsedOp::Lt
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Ge
                | ParsedOp::LtI64
                | ParsedOp::LeI64
                | ParsedOp::GtI64
                | ParsedOp::GeI64
        ) {
            continue;
        }
        if !matches!(
            parsed.get(i + 1).map(|(_, op)| *op),
            Some(ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_))
        ) {
            continue;
        }
        let Some(stack) = simulate_expr_stack(&parsed[..i]) else {
            continue;
        };
        if stack.len() < 2 {
            continue;
        }
        let lhs = &stack[stack.len() - 2];
        let rhs = &stack[stack.len() - 1];
        let bound = match compare {
            ParsedOp::Lt | ParsedOp::LtI64 => upper_bound_from_less_than(lhs, rhs, slot, 0),
            ParsedOp::Le | ParsedOp::LeI64 => upper_bound_from_less_than(lhs, rhs, slot, 1),
            ParsedOp::Gt | ParsedOp::GtI64 => upper_bound_from_less_than(rhs, lhs, slot, 0),
            ParsedOp::Ge | ParsedOp::GeI64 => upper_bound_from_less_than(rhs, lhs, slot, 1),
            _ => None,
        };
        if let Some(bound) = bound {
            best = Some(match (best, bound) {
                (
                    Some(PackedReadAffineUpperBound::Constant(a)),
                    PackedReadAffineUpperBound::Constant(b),
                ) => PackedReadAffineUpperBound::Constant(a.min(b)),
                (_, bound) => bound,
            });
        }
    }
    best
}

fn upper_bound_from_less_than(
    lhs: &ExprOrigin,
    rhs: &ExprOrigin,
    index_slot: u16,
    inclusive_adjust: i32,
) -> Option<PackedReadAffineUpperBound> {
    if lhs.affine_index
        != Some(PackedReadAffineIndex {
            slot: index_slot,
            offset: 0,
        })
    {
        return None;
    }
    if let Some(bound) = rhs
        .const_i32
        .and_then(|bound| bound.checked_add(inclusive_adjust))
    {
        return Some(PackedReadAffineUpperBound::Constant(bound));
    }
    if inclusive_adjust == 0 {
        if let Some(receiver_slot) = rhs.typed_array_length_receiver_slot {
            return Some(PackedReadAffineUpperBound::TypedArrayLength { receiver_slot });
        }
        if let Some(receiver_slot) = rhs.string_length_receiver_slot {
            return Some(PackedReadAffineUpperBound::StringLength { receiver_slot });
        }
    }
    let affine = rhs.affine_index?;
    if affine.slot == index_slot || affine.offset > 0 {
        return None;
    }
    let subtrahend = affine.offset.checked_neg()?.checked_sub(inclusive_adjust)?;
    Some(PackedReadAffineUpperBound::LocalMinusI32 {
        slot: affine.slot,
        subtrahend,
    })
}

fn has_side_effecting_array_method_call(parsed: &[(usize, ParsedOp)]) -> bool {
    parsed.iter().any(|(_, op)| {
        let ParsedOp::IcMethodCall(idx) = op else {
            return false;
        };
        let Some(entry) = crate::ic_table::IC_TABLE.get(*idx as usize) else {
            return false;
        };
        matches!(entry.receiver, crate::ic_table::ReceiverKind::Array)
            && matches!(entry.key, "push" | "pop")
    })
}

fn multi_write_osr_candidate(parsed: &[(usize, ParsedOp)]) -> Option<MultiWriteOsrCandidate> {
    let setprop_count = parsed
        .iter()
        .filter(|(_, op)| matches!(op, ParsedOp::SetPropOnObject(_)))
        .count();
    if setprop_count == 0 {
        return None;
    }
    if parsed.iter().any(|(_, op)| {
        matches!(
            op,
            ParsedOp::GetIndexOnObject
                | ParsedOp::SetIndexOnObject
                | ParsedOp::IcMethodResolve(_)
                | ParsedOp::IcMethodCall(_)
        )
    }) {
        return None;
    }
    let has_nested_backward_jump = parsed.iter().any(|(pc, op)| match op {
        ParsedOp::Jump(t) | ParsedOp::JumpIfTrue(t) | ParsedOp::JumpIfFalse(t) => {
            *t <= *pc && *t != 0
        }
        _ => false,
    });
    if has_nested_backward_jump {
        return None;
    }

    let mut out = MultiWriteOsrCandidate::default();
    for i in 0..parsed.len() {
        match parsed[i].1 {
            ParsedOp::GetPropOnObject(prop_idx) => {
                let Some(st) = simulate_block_stack(&parsed[0..i]) else {
                    return None;
                };
                let Some(Origin::Local(slot)) = st.last().copied() else {
                    return None;
                };
                push_unique_sorted(&mut out.receiver_slots, slot);
                push_unique_sorted(&mut out.prop_indices, prop_idx);
                out.getprop_site_indices.push(i);
            }
            ParsedOp::SetPropOnObject(prop_idx) => {
                let Some(st) = simulate_block_stack(&parsed[0..i]) else {
                    return None;
                };
                let n = st.len();
                if n < 2 {
                    return None;
                }
                let Origin::Local(slot) = st[n - 2] else {
                    return None;
                };
                push_unique_sorted(&mut out.receiver_slots, slot);
                push_unique_sorted(&mut out.prop_indices, prop_idx);
                out.setprop_site_indices.push(i);
            }
            _ => {}
        }
    }

    if out.receiver_slots.is_empty() || out.prop_indices.is_empty() {
        None
    } else {
        Some(out)
    }
}

fn committed_write_continuation_candidate(
    parsed: &[(usize, ParsedOp)],
) -> Option<CommittedWriteContinuationCandidate> {
    if parsed.iter().any(|(_, op)| {
        matches!(
            op,
            ParsedOp::SetIndexOnObject
                | ParsedOp::IcMethodResolve(_)
                | ParsedOp::IcMethodCall(_)
                | ParsedOp::CallDirect { .. }
                | ParsedOp::CallDirectLeaf { .. }
                | ParsedOp::CallDirectLeafConstI32 { .. }
                | ParsedOp::CallDirectLeaf2 { .. }
                | ParsedOp::CallDirectLeaf2ConstI32 { .. }
        )
    }) {
        return None;
    }

    let mut setprop: Option<(usize, u16, u16)> = None;
    for i in 0..parsed.len() {
        let ParsedOp::SetPropOnObject(prop_idx) = parsed[i].1 else {
            continue;
        };
        if setprop.is_some() {
            return None;
        }
        let st = simulate_block_stack(&parsed[0..i])?;
        let n = st.len();
        if n < 2 {
            return None;
        }
        let Origin::Local(receiver_slot) = st[n - 2] else {
            return None;
        };
        setprop = Some((i, receiver_slot, prop_idx));
    }

    let (setprop_site_index, receiver_slot, prop_idx) = setprop?;
    let mut post_write_getprop_site_indices = Vec::new();
    let mut other_post_write_getprop_site_indices = Vec::new();
    let mut other_post_write_prop_indices = Vec::new();
    for i in (setprop_site_index + 1)..parsed.len() {
        let ParsedOp::GetPropOnObject(read_prop_idx) = parsed[i].1 else {
            continue;
        };
        let st = simulate_block_stack(&parsed[0..i])?;
        let Some(Origin::Local(read_receiver_slot)) = st.last().copied() else {
            return None;
        };
        if read_receiver_slot != receiver_slot {
            return None;
        }
        if read_prop_idx == prop_idx {
            post_write_getprop_site_indices.push(i);
        } else {
            other_post_write_getprop_site_indices.push(i);
            push_unique_sorted(&mut other_post_write_prop_indices, read_prop_idx);
        }
    }

    if post_write_getprop_site_indices.is_empty() {
        return None;
    }

    Some(CommittedWriteContinuationCandidate {
        receiver_slot,
        prop_idx,
        setprop_site_index,
        post_write_getprop_site_indices,
        other_post_write_getprop_site_indices,
        other_post_write_prop_indices,
        string_length_prop_indices: Vec::new(),
        boolean_prop_indices: Vec::new(),
    })
}

fn nested_indexed_rmw_candidate(parsed: &[(usize, ParsedOp)]) -> Option<NestedIndexedRmwCandidate> {
    if parsed.iter().any(|(_, op)| {
        matches!(
            op,
            ParsedOp::SetPropOnObject(_) | ParsedOp::StoreScriptGlobalVar { .. }
        )
    }) {
        return None;
    }

    let mut setindex_site: Option<(usize, u16, u16, u16)> = None;
    let mut read_site_indices = Vec::new();
    for i in 0..parsed.len() {
        match parsed[i].1 {
            ParsedOp::GetPropOnObject(_)
            | ParsedOp::CwcStringPropLength(_)
            | ParsedOp::CwcBooleanPropAsNumber(_)
            | ParsedOp::GetIndexOnObject
            | ParsedOp::GetIndexStringOnObject => read_site_indices.push(i),
            ParsedOp::SetIndexOnObject => {
                if setindex_site.is_some() {
                    return None;
                }
                let block_start = parsed[..i]
                    .iter()
                    .rposition(|(_, op)| {
                        matches!(
                            op,
                            ParsedOp::Jump(_)
                                | ParsedOp::JumpIfTrue(_)
                                | ParsedOp::JumpIfFalse(_)
                                | ParsedOp::JumpIfTrueKeep(_)
                                | ParsedOp::JumpIfFalseKeep(_)
                                | ParsedOp::Return
                                | ParsedOp::ReturnUndef
                        )
                    })
                    .map_or(0, |idx| idx + 1);
                let st = simulate_block_stack(&parsed[block_start..i])?;
                let n = st.len();
                if n < 3 {
                    return None;
                }
                let Origin::Local(receiver_slot) = st[n - 3] else {
                    return None;
                };
                let Origin::Local(index_slot) = st[n - 2] else {
                    return None;
                };
                let Origin::Local(value_slot) = st[n - 1] else {
                    return None;
                };
                setindex_site = Some((i, receiver_slot, index_slot, value_slot));
            }
            _ => {}
        }
    }

    let (setindex_site_index, receiver_slot, index_slot, value_slot) = setindex_site?;
    if read_site_indices.is_empty()
        || read_site_indices
            .iter()
            .any(|read_site| *read_site > setindex_site_index)
    {
        return None;
    }

    let nested_backedge_site_index = parsed
        .iter()
        .enumerate()
        .filter_map(|(i, (pc, op))| match op {
            ParsedOp::Jump(t) | ParsedOp::JumpIfTrue(t) | ParsedOp::JumpIfFalse(t)
                if *t <= *pc && *t != 0 && i < setindex_site_index =>
            {
                Some(i)
            }
            _ => None,
        })
        .next()?;

    Some(NestedIndexedRmwCandidate {
        receiver_slot,
        index_slot,
        value_slot,
        setindex_site_index,
        nested_backedge_site_index,
        read_site_indices,
    })
}

fn indexed_overwrite_bound_evidence(
    parsed: &[(usize, ParsedOp)],
    constants: &rusty_js_bytecode::ConstantsPool,
    candidate: &NestedIndexedRmwCandidate,
) -> Option<IndexedOverwriteBoundEvidence> {
    let mut best: Option<(usize, IndexedOverwriteBoundEvidence)> = None;
    for i in 0..parsed.len().saturating_sub(3) {
        let Some((index_slot, bound_receiver_slot)) = (match &parsed[i..i + 4] {
            [(_, ParsedOp::LoadLocal(index_slot)), (_, ParsedOp::LoadLocal(bound_receiver_slot)), (_, ParsedOp::GetPropOnObject(prop_idx)), (_, ParsedOp::Lt | ParsedOp::Le)]
                if constant_string_is(constants, *prop_idx, "length") =>
            {
                Some((*index_slot, *bound_receiver_slot))
            }
            [(_, ParsedOp::LoadLocal(index_slot)), (_, ParsedOp::LoadLocal(bound_receiver_slot)), (_, ParsedOp::IcPropertyGet(ic_idx)), (_, ParsedOp::Lt | ParsedOp::Le)]
                if ic_property_get_is(*ic_idx, "length") =>
            {
                Some((*index_slot, *bound_receiver_slot))
            }
            _ => None,
        }) else {
            continue;
        };
        if index_slot != candidate.index_slot {
            continue;
        }
        let evidence = IndexedOverwriteBoundEvidence {
            receiver_slot: candidate.receiver_slot,
            index_slot: candidate.index_slot,
            value_slot: candidate.value_slot,
            setindex_site_index: candidate.setindex_site_index,
            bound_receiver_slot,
            bound_site_index: i + 3,
            bound_matches_write_receiver: bound_receiver_slot == candidate.receiver_slot,
        };
        let distance = candidate.setindex_site_index.saturating_sub(i);
        let replace = best
            .as_ref()
            .is_none_or(|(best_distance, _)| distance < *best_distance);
        if replace {
            best = Some((distance, evidence));
        }
    }
    best.map(|(_, evidence)| evidence)
}

fn paired_length_equality_evidence(
    parsed: &[(usize, ParsedOp)],
    constants: &rusty_js_bytecode::ConstantsPool,
    bound: &IndexedOverwriteBoundEvidence,
) -> Option<PairedLengthEqualityEvidence> {
    let mut best: Option<(usize, PairedLengthEqualityEvidence)> = None;
    for i in 0..parsed.len().saturating_sub(4) {
        let Some((lhs_slot, rhs_slot)) = (match &parsed[i..i + 5] {
            [(_, ParsedOp::LoadLocal(lhs_slot)), (_, ParsedOp::GetPropOnObject(lhs_prop_idx)), (_, ParsedOp::LoadLocal(rhs_slot)), (_, ParsedOp::GetPropOnObject(rhs_prop_idx)), (_, ParsedOp::Eq | ParsedOp::StrictEq)]
                if constant_string_is(constants, *lhs_prop_idx, "length")
                    && constant_string_is(constants, *rhs_prop_idx, "length") =>
            {
                Some((*lhs_slot, *rhs_slot))
            }
            [(_, ParsedOp::LoadLocal(lhs_slot)), (_, ParsedOp::IcPropertyGet(lhs_ic_idx)), (_, ParsedOp::LoadLocal(rhs_slot)), (_, ParsedOp::IcPropertyGet(rhs_ic_idx)), (_, ParsedOp::Eq | ParsedOp::StrictEq)]
                if ic_property_get_is(*lhs_ic_idx, "length")
                    && ic_property_get_is(*rhs_ic_idx, "length") =>
            {
                Some((*lhs_slot, *rhs_slot))
            }
            _ => None,
        }) else {
            continue;
        };
        let proves_bound_to_write_pair = (lhs_slot == bound.bound_receiver_slot
            && rhs_slot == bound.receiver_slot)
            || (lhs_slot == bound.receiver_slot && rhs_slot == bound.bound_receiver_slot);
        let equality = PairedLengthEqualityEvidence {
            lhs_slot,
            rhs_slot,
            equality_site_index: i + 4,
            proves_bound_to_write_pair,
        };
        let distance = bound.setindex_site_index.saturating_sub(i);
        let replace = best
            .as_ref()
            .is_none_or(|(best_distance, _)| distance < *best_distance);
        if replace {
            best = Some((distance, equality));
        }
    }
    best.map(|(_, equality)| equality)
}

fn spectral_pair_length_fact_requirements(
    bound: Option<&IndexedOverwriteBoundEvidence>,
) -> Vec<SpectralPairLengthFactRequirement> {
    let Some(bound) = bound else {
        return Vec::new();
    };
    if bound.bound_matches_write_receiver {
        return Vec::new();
    }
    vec![SpectralPairLengthFactRequirement {
        bound_receiver_slot: bound.bound_receiver_slot,
        write_receiver_slot: bound.receiver_slot,
        index_slot: bound.index_slot,
        value_slot: bound.value_slot,
        setindex_site_index: bound.setindex_site_index,
        bound_site_index: bound.bound_site_index,
    }]
}

fn spectral_pair_length_fact_for_setindex(
    requirements: &[SpectralPairLengthFactRequirement],
    setindex_site_index: usize,
) -> Option<&SpectralPairLengthFactRequirement> {
    requirements
        .iter()
        .find(|requirement| requirement.setindex_site_index == setindex_site_index)
}

fn indexed_post_write_pair_no_deopt_gate_diagnostic(
    env_enabled: bool,
    resume_probe: bool,
    spectral_pair_requirement_count: usize,
    fixed_deopt_candidate: bool,
) -> String {
    format!(
        "Some(env_enabled={}, resume_probe={}, spectral_pair_requirement_count={}, fixed_deopt_candidate={})",
        env_enabled, resume_probe, spectral_pair_requirement_count, fixed_deopt_candidate,
    )
}

fn indexed_post_write_pair_no_deopt_admitted(
    env_enabled: bool,
    spectral_pair_requirement_count: usize,
    fixed_deopt_candidate: bool,
) -> bool {
    env_enabled && spectral_pair_requirement_count > 0 && fixed_deopt_candidate
}

fn indexed_post_write_resume_evidence(
    parsed: &[(usize, ParsedOp)],
    candidate: &NestedIndexedRmwCandidate,
) -> Option<IndexedPostWriteResumeEvidence> {
    let setindex_site_index = candidate.setindex_site_index;
    let (setindex_pc, _) = parsed.get(setindex_site_index)?;
    let pop_site_index = setindex_site_index + 1;
    let (_, pop_op) = parsed.get(pop_site_index)?;
    if !matches!(pop_op, ParsedOp::Pop) {
        return None;
    }
    let resume_site_index = pop_site_index + 1;
    let (resume_pc_after_pop, _) = parsed.get(resume_site_index)?;
    let mut live_after_pop_slots = first_read_local_slots(&parsed[resume_site_index..]);
    push_unique_sorted(&mut live_after_pop_slots, candidate.value_slot);
    Some(IndexedPostWriteResumeEvidence {
        setindex_site_index,
        setindex_pc: *setindex_pc,
        pop_site_index,
        resume_pc_after_pop: *resume_pc_after_pop,
        live_after_pop_slots,
        value_slot: candidate.value_slot,
        stack_value_discarded: true,
    })
}

fn indexed_post_write_deopt_site_candidate(
    evidence: &IndexedPostWriteResumeEvidence,
) -> IndexedPostWriteDeoptSiteCandidate {
    let candidate = cwc_suffix_deopt_site_candidate(
        evidence.resume_pc_after_pop,
        &evidence.live_after_pop_slots,
    );
    IndexedPostWriteDeoptSiteCandidate {
        resume_pc: candidate.resume_pc,
        live_local_slots: candidate.live_local_slots,
        argument_register_slots: candidate.argument_register_slots,
        f64_bitcast_local_slots: vec![evidence.value_slot],
        fixed_register_arg_capacity: candidate.fixed_register_arg_capacity,
        overflow_local_slots: candidate.overflow_local_slots,
        requires_spill_payload: candidate.requires_spill_payload,
        call_frame_register_capacity: candidate.call_frame_register_capacity,
        memory_payload_local_slots: candidate.memory_payload_local_slots,
        requires_memory_payload: candidate.requires_memory_payload,
        deopt_live_local_table: candidate.deopt_live_local_table,
        stack_depth: candidate.stack_depth,
    }
}

fn indexed_post_write_deopt_site_from_candidate(
    candidate: &IndexedPostWriteDeoptSiteCandidate,
) -> crate::deopt::DeoptSite {
    crate::deopt::DeoptSite {
        reason: crate::deopt::DeoptReason::ICShapeMismatch { ic_id: 0 },
        resume_pc: candidate.resume_pc,
        live_locals: candidate.deopt_live_local_table.clone(),
        stack_depth: candidate.stack_depth,
        stack_slots: Vec::new(),
    }
}

fn committed_write_continuation_suffix_candidate(
    parsed: &[(usize, ParsedOp)],
) -> Option<CommittedWriteContinuationSuffixContract> {
    let mut best: Option<(
        usize,
        usize,
        usize,
        CommittedWriteContinuationSuffixContract,
    )> = None;
    for start in 1..parsed.len() {
        let suffix = &parsed[start..];
        let Some(mut candidate) = committed_write_continuation_candidate(suffix) else {
            continue;
        };
        candidate.setprop_site_index += start;
        for site in &mut candidate.post_write_getprop_site_indices {
            *site += start;
        }
        for site in &mut candidate.other_post_write_getprop_site_indices {
            *site += start;
        }
        let live_ins = first_read_local_slots(suffix);
        let storebacks = store_local_slots(suffix);
        let read_after_storebacks = storebacks_read_after_store(suffix);
        let dead_storebacks = dead_storeback_slots(suffix);
        let mut deopt_live_slots = live_ins.clone();
        for slot in &read_after_storebacks {
            push_unique_sorted(&mut deopt_live_slots, *slot);
        }
        let suffix_entry_pc = parsed[start].0;
        let resume_pc = parsed[0].0;
        let deopt_site_candidate = cwc_suffix_deopt_site_candidate(resume_pc, &deopt_live_slots);
        let frame_base_deopt_plan = cwc_suffix_frame_base_deopt_plan(&deopt_site_candidate);
        let score = live_ins.len() + read_after_storebacks.len();
        let contract = CommittedWriteContinuationSuffixContract {
            start,
            suffix_entry_pc,
            candidate,
            live_ins,
            storebacks,
            read_after_storebacks,
            dead_storebacks,
            deopt_live_slots,
            deopt_site_candidate,
            frame_base_deopt_plan,
        };
        let replace = match best.as_ref() {
            None => true,
            Some((best_score, best_live_ins, best_start, _)) => {
                score < *best_score
                    || (score == *best_score
                        && (contract.live_ins.len() < *best_live_ins
                            || (contract.live_ins.len() == *best_live_ins && start > *best_start)))
            }
        };
        if replace {
            best = Some((score, contract.live_ins.len(), start, contract));
        }
    }
    best.map(|(_, _, _, contract)| contract)
}

fn cwc_suffix_frame_base_deopt_plan(
    candidate: &CommittedWriteContinuationSuffixDeoptSiteCandidate,
) -> Option<CwcSuffixFrameBaseDeoptPlan> {
    if !candidate.requires_memory_payload {
        return None;
    }
    Some(CwcSuffixFrameBaseDeoptPlan {
        helper_name: "deopt_trip_with_frame_base",
        helper_arg_count: 10,
        register_local_slots: candidate
            .live_local_slots
            .iter()
            .take(crate::deopt::DEOPT_CALL_FRAME_REGISTER_CAPACITY)
            .copied()
            .collect(),
        memory_payload_local_slots: candidate.memory_payload_local_slots.clone(),
        frame_base_arg_index: 9,
        frame_slot_size_bytes: 8,
    })
}

fn cwc_suffix_deopt_site_from_candidate(
    candidate: &CommittedWriteContinuationSuffixDeoptSiteCandidate,
) -> crate::deopt::DeoptSite {
    crate::deopt::DeoptSite {
        reason: crate::deopt::DeoptReason::ICShapeMismatch { ic_id: 0 },
        resume_pc: candidate.resume_pc,
        live_locals: candidate.deopt_live_local_table.clone(),
        stack_depth: candidate.stack_depth,
        stack_slots: vec![],
    }
}

fn cwc_suffix_deopt_site_candidate(
    resume_pc: usize,
    deopt_live_slots: &[u16],
) -> CommittedWriteContinuationSuffixDeoptSiteCandidate {
    let fixed_register_arg_capacity = crate::deopt::DEOPT_TRIP_FIXED_REGISTER_ARG_CAPACITY as u8;
    let call_frame_register_capacity = crate::deopt::DEOPT_CALL_FRAME_REGISTER_CAPACITY as u8;
    let overflow_local_slots = deopt_live_slots
        .iter()
        .skip(fixed_register_arg_capacity as usize)
        .copied()
        .collect::<Vec<_>>();
    let memory_payload_local_slots = deopt_live_slots
        .iter()
        .skip(call_frame_register_capacity as usize)
        .copied()
        .collect::<Vec<_>>();
    let deopt_live_local_table = deopt_live_slots
        .iter()
        .enumerate()
        .map(|(payload_index, interp_slot)| {
            let jit_location = if payload_index < call_frame_register_capacity as usize {
                crate::deopt::JitLocation::Register(payload_index as u8)
            } else {
                let overflow_index = payload_index - call_frame_register_capacity as usize;
                crate::deopt::JitLocation::StackSlot((overflow_index * 8) as i32)
            };
            crate::deopt::DeoptLiveLocal {
                interp_slot: *interp_slot,
                jit_location,
            }
        })
        .collect::<Vec<_>>();
    CommittedWriteContinuationSuffixDeoptSiteCandidate {
        resume_pc: resume_pc as u32,
        live_local_slots: deopt_live_slots.to_vec(),
        argument_register_slots: deopt_live_slots.to_vec(),
        fixed_register_arg_capacity,
        requires_spill_payload: !overflow_local_slots.is_empty(),
        overflow_local_slots,
        call_frame_register_capacity,
        requires_memory_payload: !memory_payload_local_slots.is_empty(),
        memory_payload_local_slots,
        deopt_live_local_table,
        stack_depth: 0,
    }
}

fn first_read_local_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut seen = std::collections::HashSet::new();
    let mut out = Vec::new();
    for (_, op) in parsed {
        match op {
            ParsedOp::LoadLocal(slot) => {
                if seen.insert(*slot) {
                    push_unique_sorted(&mut out, *slot);
                }
            }
            ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) => {
                seen.insert(*slot);
            }
            _ => {}
        }
    }
    out
}

fn store_local_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut out = Vec::new();
    for (_, op) in parsed {
        if let ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) = op {
            push_unique_sorted(&mut out, *slot);
        }
    }
    out
}

fn storebacks_read_after_store(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut stored = std::collections::HashSet::new();
    let mut out = Vec::new();
    for (_, op) in parsed {
        match op {
            ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) => {
                stored.insert(*slot);
            }
            ParsedOp::LoadLocal(slot) if stored.contains(slot) => {
                push_unique_sorted(&mut out, *slot);
            }
            _ => {}
        }
    }
    out
}

fn dead_storeback_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let required = storebacks_read_after_store(parsed);
    store_local_slots(parsed)
        .into_iter()
        .filter(|slot| !required.contains(slot))
        .collect()
}

fn monomorphic_property_read_candidate(
    parsed: &[(usize, ParsedOp)],
) -> Option<MonomorphicPropertyReadCandidate> {
    if parsed.iter().any(|(_, op)| {
        matches!(
            op,
            ParsedOp::SetPropOnObject(_)
                | ParsedOp::SetIndexOnObject
                | ParsedOp::GetIndexOnObject
                | ParsedOp::StoreScriptGlobalVar { .. }
                | ParsedOp::IcMethodResolve(_)
                | ParsedOp::IcMethodCall(_)
                | ParsedOp::CallDirect { .. }
                | ParsedOp::CallDirectLeaf { .. }
                | ParsedOp::CallDirectLeafConstI32 { .. }
                | ParsedOp::CallDirectLeaf2 { .. }
                | ParsedOp::CallDirectLeaf2ConstI32 { .. }
        )
    }) {
        return None;
    }

    let assigned: std::collections::HashSet<u16> = parsed
        .iter()
        .filter_map(|(_, op)| match op {
            ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) => Some(*slot),
            _ => None,
        })
        .collect();

    let mut receiver_slot: Option<u16> = None;
    let mut prop_indices: Vec<u16> = Vec::new();
    let mut getprop_site_indices: Vec<usize> = Vec::new();
    for i in 0..parsed.len() {
        let ParsedOp::GetPropOnObject(prop_idx) = parsed[i].1 else {
            continue;
        };
        let Some(st) = simulate_block_stack(&parsed[0..i]) else {
            return None;
        };
        let Some(Origin::Local(slot)) = st.last().copied() else {
            return None;
        };
        if assigned.contains(&slot) {
            return None;
        }
        if receiver_slot
            .replace(slot)
            .is_some_and(|prior| prior != slot)
        {
            return None;
        }
        push_unique_sorted(&mut prop_indices, prop_idx);
        getprop_site_indices.push(i);
    }

    Some(MonomorphicPropertyReadCandidate {
        receiver_slot: receiver_slot?,
        prop_indices,
        getprop_site_indices,
    })
}

fn object_or_undefined_entry_return_candidate(
    parsed: &[(usize, ParsedOp)],
    mixed_domain_slots: &MixedDomainSlots,
) -> bool {
    let mut saw_object_return = false;
    let mut saw_undefined_return = false;
    for i in 0..parsed.len() {
        match parsed[i].1 {
            ParsedOp::Return => {
                let Some(stack) = simulate_block_stack(&parsed[..i]) else {
                    return false;
                };
                let Some(Origin::Local(slot)) = stack.last().copied() else {
                    return false;
                };
                if mixed_domain_slots.object_slots.contains(&slot)
                    || mixed_domain_slots.object_or_null_slots.contains(&slot)
                {
                    saw_object_return = true;
                } else {
                    return false;
                }
            }
            ParsedOp::ReturnUndef => {
                saw_undefined_return = true;
            }
            _ => {}
        }
    }
    saw_object_return && saw_undefined_return
}

fn object_entry_return_candidate(
    parsed: &[(usize, ParsedOp)],
    mixed_domain_slots: &MixedDomainSlots,
) -> bool {
    let mut saw_object_return = false;
    for i in 0..parsed.len() {
        match parsed[i].1 {
            ParsedOp::Return => {
                let Some(stack) = simulate_block_stack(&parsed[..i]) else {
                    return false;
                };
                match stack.last().copied() {
                    Some(Origin::Local(slot)) => {
                        if mixed_domain_slots.object_slots.contains(&slot)
                            || mixed_domain_slots.object_or_null_slots.contains(&slot)
                        {
                            saw_object_return = true;
                        } else {
                            return false;
                        }
                    }
                    Some(Origin::FreshObjectLiteral) => {
                        saw_object_return = true;
                    }
                    _ => return false,
                }
            }
            ParsedOp::ReturnUndef => return false,
            _ => {}
        }
    }
    saw_object_return
}

fn direct_call_entry_return_candidate(parsed: &[(usize, ParsedOp)]) -> bool {
    let mut saw_direct_call_return = false;
    for i in 0..parsed.len() {
        match parsed[i].1 {
            ParsedOp::Return => {
                if matches!(
                    parsed.get(i.saturating_sub(1)).map(|(_, op)| op),
                    Some(ParsedOp::CallDirect { .. })
                ) {
                    saw_direct_call_return = true;
                } else {
                    return false;
                }
            }
            ParsedOp::ReturnUndef => {}
            _ => {}
        }
    }
    saw_direct_call_return
}

fn materialized_object_or_undefined_entry_return_candidate(
    parsed: &[(usize, ParsedOp)],
    mixed_domain_slots: &MixedDomainSlots,
) -> bool {
    let mut saw_object_return = false;
    let mut saw_undefined_return = false;
    for i in 0..parsed.len() {
        match parsed[i].1 {
            ParsedOp::Return => {
                if saw_undefined_return
                    && matches!(
                        i.checked_sub(1).and_then(|j| parsed.get(j)),
                        Some((_, ParsedOp::PushI32(0)))
                    )
                {
                    continue;
                }
                let Some((_, ParsedOp::LoadLocal(slot))) =
                    i.checked_sub(1).and_then(|j| parsed.get(j))
                else {
                    return false;
                };
                if mixed_domain_slots.object_slots.contains(slot)
                    || mixed_domain_slots.object_or_null_slots.contains(slot)
                {
                    saw_object_return = true;
                } else {
                    return false;
                }
            }
            ParsedOp::ReturnUndef => saw_undefined_return = true,
            _ => {}
        }
    }
    saw_object_return && saw_undefined_return
}

fn interop_require_default_value_return_object_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut slots = Vec::new();
    for window in parsed.windows(7) {
        let [(_, ParsedOp::LoadLocal(test_slot)), (_, ParsedOp::JumpIfFalseKeep(fallback_pc)), (_, ParsedOp::Pop), (_, ParsedOp::LoadLocal(prop_slot)), (_, ParsedOp::GetPropOnObject(_) | ParsedOp::GetPropTruthyOnObject(_)), (_, ParsedOp::JumpIfFalse(prop_fallback_pc)), (_, ParsedOp::LoadLocal(return_slot))] =
            window
        else {
            continue;
        };
        if test_slot == prop_slot && prop_slot == return_slot && fallback_pc == prop_fallback_pc {
            push_unique_sorted(&mut slots, *return_slot);
        }
    }
    for window in parsed.windows(6) {
        let [(_, ParsedOp::LoadLocal(test_slot)), (_, ParsedOp::JumpIfFalse(fallback_pc)), (_, ParsedOp::LoadLocal(prop_slot)), (_, ParsedOp::GetPropOnObject(_) | ParsedOp::GetPropTruthyOnObject(_)), (_, ParsedOp::JumpIfFalse(prop_fallback_pc)), (_, ParsedOp::LoadLocal(return_slot))] =
            window
        else {
            continue;
        };
        if test_slot == prop_slot && prop_slot == return_slot && fallback_pc == prop_fallback_pc {
            push_unique_sorted(&mut slots, *return_slot);
        }
    }
    slots
}

fn interop_require_default_object_entry_return_candidate(
    parsed: &[(usize, ParsedOp)],
    mixed_domain_slots: &MixedDomainSlots,
) -> bool {
    if interop_require_default_value_return_object_slots(parsed).is_empty() {
        return false;
    }
    let mut saw_object_return = false;
    for i in 0..parsed.len() {
        match parsed[i].1 {
            ParsedOp::Return => {
                let Some(stack) = simulate_block_stack(&parsed[..i]) else {
                    return false;
                };
                match stack.last().copied() {
                    Some(Origin::Local(slot))
                        if mixed_domain_slots.object_slots.contains(&slot)
                            || mixed_domain_slots.object_or_null_slots.contains(&slot) =>
                    {
                        saw_object_return = true;
                    }
                    Some(Origin::FreshObjectLiteral) => {
                        saw_object_return = true;
                    }
                    _ => return false,
                }
            }
            ParsedOp::ReturnUndef => {
                if parsed.get(i + 1).is_some() {
                    return false;
                }
            }
            _ => {}
        }
    }
    saw_object_return
}

fn mixed_domain_slots(
    parsed: &[(usize, ParsedOp)],
    typed_array_kind_specs: &[TypedArrayKindSpec],
) -> MixedDomainSlots {
    let mut out = MixedDomainSlots::default();

    let mut stored_any: std::collections::HashSet<u16> = std::collections::HashSet::new();
    let mut disqualified: std::collections::HashSet<u16> = std::collections::HashSet::new();
    let mut loaded_any: std::collections::HashSet<u16> = std::collections::HashSet::new();
    for i in 0..parsed.len() {
        if let ParsedOp::StableHostGlobalObjectPreload { local_slot, .. }
        | ParsedOp::StableHostObjectPreload { local_slot, .. }
        | ParsedOp::StableObjectUpvaluePreload { local_slot, .. }
        | ParsedOp::StableCalleePreload { local_slot, .. } = parsed[i].1
        {
            push_unique_sorted(&mut out.object_slots, local_slot);
        }
        if let ParsedOp::LoadLocal(slot) = parsed[i].1 {
            loaded_any.insert(slot);
        }
        if let ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) = parsed[i].1 {
            stored_any.insert(slot);

            let prev_is_incdec = i >= 1
                && matches!(
                    parsed[i - 1].1,
                    ParsedOp::Inc | ParsedOp::Dec | ParsedOp::IncI64 | ParsedOp::DecI64
                );
            let self_incdec = prev_is_incdec
                && ((i >= 2 && matches!(parsed[i - 2].1, ParsedOp::LoadLocal(s) if s == slot))
                    || (i >= 3
                        && matches!(parsed[i - 2].1, ParsedOp::Dup)
                        && matches!(parsed[i - 3].1, ParsedOp::LoadLocal(s) if s == slot)));
            let compiler_postinc_base_store = i >= 7
                && matches!(parsed[i - 7].1, ParsedOp::LoadLocal(s) if s == slot)
                && matches!(parsed[i - 6].1, ParsedOp::ToNumeric)
                && matches!(parsed[i - 5].1, ParsedOp::Dup)
                && matches!(parsed[i - 4].1, ParsedOp::StoreLocal(_))
                && matches!(
                    parsed[i - 3].1,
                    ParsedOp::Inc | ParsedOp::Dec | ParsedOp::IncI64 | ParsedOp::DecI64
                )
                && matches!(parsed[i - 2].1, ParsedOp::StoreLocal(new_slot)
                    if matches!(parsed[i - 1].1, ParsedOp::LoadLocal(load_slot) if load_slot == new_slot));
            let additive_self_update = (i >= 3
                && matches!(
                    parsed[i - 1].1,
                    ParsedOp::Add | ParsedOp::AddI64 | ParsedOp::Sub | ParsedOp::SubI64
                )
                && matches!(parsed[i - 2].1, ParsedOp::PushI32(_))
                && matches!(parsed[i - 3].1, ParsedOp::LoadLocal(s) if s == slot))
                || (i >= 3
                    && matches!(parsed[i - 1].1, ParsedOp::Add | ParsedOp::AddI64)
                    && matches!(parsed[i - 2].1, ParsedOp::LoadLocal(s) if s == slot)
                    && matches!(parsed[i - 3].1, ParsedOp::PushI32(_)))
                || (i >= 4
                    && matches!(
                        parsed[i - 1].1,
                        ParsedOp::Add | ParsedOp::AddI64 | ParsedOp::Sub | ParsedOp::SubI64
                    )
                    && matches!(parsed[i - 2].1, ParsedOp::PushI32(_))
                    && matches!(parsed[i - 3].1, ParsedOp::ToNumeric)
                    && matches!(parsed[i - 4].1, ParsedOp::LoadLocal(s) if s == slot))
                || (i >= 4
                    && matches!(parsed[i - 1].1, ParsedOp::Add | ParsedOp::AddI64)
                    && matches!(parsed[i - 2].1, ParsedOp::ToNumeric)
                    && matches!(parsed[i - 3].1, ParsedOp::LoadLocal(s) if s == slot)
                    && matches!(parsed[i - 4].1, ParsedOp::PushI32(_)))
                || (i >= 4
                    && matches!(parsed[i - 1].1, ParsedOp::Dup)
                    && matches!(
                        parsed[i - 2].1,
                        ParsedOp::Add | ParsedOp::AddI64 | ParsedOp::Sub | ParsedOp::SubI64
                    )
                    && matches!(parsed[i - 3].1, ParsedOp::PushI32(_))
                    && matches!(parsed[i - 4].1, ParsedOp::LoadLocal(s) if s == slot))
                || (i >= 4
                    && matches!(parsed[i - 1].1, ParsedOp::Dup)
                    && matches!(parsed[i - 2].1, ParsedOp::Add | ParsedOp::AddI64)
                    && matches!(parsed[i - 3].1, ParsedOp::LoadLocal(s) if s == slot)
                    && matches!(parsed[i - 4].1, ParsedOp::PushI32(_)))
                || (i >= 5
                    && matches!(parsed[i - 1].1, ParsedOp::Dup)
                    && matches!(
                        parsed[i - 2].1,
                        ParsedOp::Add | ParsedOp::AddI64 | ParsedOp::Sub | ParsedOp::SubI64
                    )
                    && matches!(parsed[i - 3].1, ParsedOp::PushI32(_))
                    && matches!(parsed[i - 4].1, ParsedOp::ToNumeric)
                    && matches!(parsed[i - 5].1, ParsedOp::LoadLocal(s) if s == slot))
                || (i >= 5
                    && matches!(parsed[i - 1].1, ParsedOp::Dup)
                    && matches!(parsed[i - 2].1, ParsedOp::Add | ParsedOp::AddI64)
                    && matches!(parsed[i - 3].1, ParsedOp::ToNumeric)
                    && matches!(parsed[i - 4].1, ParsedOp::LoadLocal(s) if s == slot)
                    && matches!(parsed[i - 5].1, ParsedOp::PushI32(_)));
            let int_literal_init = i >= 1 && matches!(parsed[i - 1].1, ParsedOp::PushI32(_));
            if !(self_incdec
                || compiler_postinc_base_store
                || additive_self_update
                || int_literal_init)
            {
                disqualified.insert(slot);
            }
        }
    }
    let induction: Vec<u16> = stored_any
        .into_iter()
        .filter(|s| !disqualified.contains(s))
        .collect();
    let read_only: std::collections::HashSet<u16> = loaded_any
        .into_iter()
        .filter(|s| !disqualified.contains(s))
        .filter(|s| !induction.contains(s))
        .collect();
    let postinc_temp_candidates = postinc_update_temp_candidates(parsed);

    for i in 0..parsed.len() {
        if let ParsedOp::CallDirect { callee_slot, .. } = parsed[i].1 {
            push_unique_sorted(&mut out.object_slots, callee_slot);
        }
        if let ParsedOp::CallDirectLeaf { callee_slot, .. } = parsed[i].1 {
            push_unique_sorted(&mut out.object_slots, callee_slot);
        }
        if let ParsedOp::CallDirectLeafConstI32 { callee_slot, .. } = parsed[i].1 {
            push_unique_sorted(&mut out.object_slots, callee_slot);
        }
        if let ParsedOp::CallDirectLeaf2 { callee_slot, .. } = parsed[i].1 {
            push_unique_sorted(&mut out.object_slots, callee_slot);
        }
        if let ParsedOp::CallDirectLeaf2ConstI32 { callee_slot, .. } = parsed[i].1 {
            push_unique_sorted(&mut out.object_slots, callee_slot);
        }
        if let ParsedOp::CallDirect2PropPredicate {
            callee_slot,
            lhs_slot,
            rhs_slot,
            ..
        } = parsed[i].1
        {
            push_unique_sorted(&mut out.object_slots, callee_slot);
            push_unique_sorted(&mut out.object_slots, lhs_slot);
            push_unique_sorted(&mut out.object_slots, rhs_slot);
        }
        if let ParsedOp::AriaParentPredicateFusion {
            constraints_callee_slot,
            attributes_callee_slot,
            lhs_slot,
            rhs_slot,
            ..
        } = parsed[i].1
        {
            push_unique_sorted(&mut out.object_slots, constraints_callee_slot);
            push_unique_sorted(&mut out.object_slots, attributes_callee_slot);
            push_unique_sorted(&mut out.object_slots, lhs_slot);
            push_unique_sorted(&mut out.object_slots, rhs_slot);
        }
        if let ParsedOp::ArrayIsArrayStatic = parsed[i].1 {
            if let Some(st) = simulate_block_stack(&parsed[..i]) {
                if let Some(Origin::Local(slot)) = st.last().copied() {
                    push_unique_sorted(&mut out.object_slots, slot);
                }
            }
        }
        if let ParsedOp::StringConcatOwnedResult { left_slot }
        | ParsedOp::StringConcatLocalValue { left_slot }
        | ParsedOp::StringConcatLocalValuePreserveRight { left_slot } = parsed[i].1
        {
            push_unique_sorted(&mut out.string_slots, left_slot);
        }
        if let ParsedOp::Site874TokenFinalizationAggregateProduce { token_slot, .. } = parsed[i].1 {
            push_unique_sorted(&mut out.string_slots, token_slot);
        }
        if i >= 1 {
            if let ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) = parsed[i].1 {
                if matches!(
                    parsed[i - 1].1,
                    ParsedOp::StringConcatOwnedPair
                        | ParsedOp::CallStringCtor
                        | ParsedOp::CallStringFromCharCode
                        | ParsedOp::CallStringFromCharCodeMethod
                        | ParsedOp::PrimitiveStringIndexRead { .. }
                ) {
                    push_unique_sorted(&mut out.string_slots, slot);
                }
            }
        }
        if let ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) = parsed[i].1 {
            let segment_start = parsed[..i]
                .iter()
                .rposition(|(_, op)| {
                    matches!(
                        op,
                        ParsedOp::StoreLocal(_)
                            | ParsedOp::InitLocal(_)
                            | ParsedOp::Pop
                            | ParsedOp::Jump(_)
                            | ParsedOp::JumpIfTrue(_)
                            | ParsedOp::JumpIfFalse(_)
                    )
                })
                .map(|idx| idx + 1)
                .unwrap_or(0);
            let segment = &parsed[segment_start..i];
            let segment_has_primitive_index = segment
                .iter()
                .any(|(_, op)| matches!(op, ParsedOp::PrimitiveStringIndexRead { .. }));
            let store_is_owned_string_top = simulate_array_method_stack(&parsed[..i])
                .and_then(|stack| stack.last().copied())
                .is_some_and(|origin| origin == Origin::OwnedStringResult);
            if segment_has_primitive_index && store_is_owned_string_top {
                push_unique_sorted(&mut out.string_slots, slot);
            }
        }
        if let ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) = parsed[i].1 {
            if simulate_block_stack(&parsed[..i])
                .and_then(|stack| stack.last().copied())
                .is_some_and(|origin| matches!(origin, Origin::HostNativeObject(_)))
            {
                push_unique_sorted(&mut out.object_slots, slot);
            }
        }

        if i >= 1 {
            if let ParsedOp::IcMethodResolve(idx) = parsed[i].1 {
                if crate::ic_table::IC_TABLE
                    .get(idx as usize)
                    .is_some_and(|e| e.key == "exec")
                {

                    if let ParsedOp::LoadLocal(slot) = parsed[i - 1].1 {
                        push_unique_sorted(&mut out.object_slots, slot);
                    } else if i >= 2 && matches!(parsed[i - 1].1, ParsedOp::Dup) {
                        if let ParsedOp::LoadLocal(slot) = parsed[i - 2].1 {
                            push_unique_sorted(&mut out.object_slots, slot);
                        }
                    }
                }
            }
            if let ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) = parsed[i].1 {
                let fed_by_exec_call = matches!(parsed[i - 1].1, ParsedOp::IcMethodCall(idx)
                    if crate::ic_table::IC_TABLE.get(idx as usize).is_some_and(|e| e.key == "exec"))
                    || (i >= 2
                        && matches!(parsed[i - 1].1, ParsedOp::Dup)
                        && matches!(parsed[i - 2].1, ParsedOp::IcMethodCall(idx)
                            if crate::ic_table::IC_TABLE.get(idx as usize).is_some_and(|e| e.key == "exec")));
                if fed_by_exec_call {
                    if env_flag_truthy("CRUFT_LEJIT_REGEXP_EXEC_OBJECT_OR_NULL_DOMAIN") {
                        push_unique_sorted(&mut out.object_or_null_slots, slot);
                    } else {
                        push_unique_sorted(&mut out.object_slots, slot);
                    }
                }
            }
        }
        if let ParsedOp::IcMethodCall(idx) = parsed[i].1 {
            if crate::ic_table::IC_TABLE
                .get(idx as usize)
                .is_some_and(|e| {
                    matches!(
                        e.kind,
                        crate::ic_table::IcEntryKind::MethodCall { arity: 1 }
                    ) && e.key == "exec"
                })
            {
                if let Some(st) = simulate_block_stack(&parsed[..i]) {
                    let receiver_depth = 3usize;
                    if st.len() >= receiver_depth {
                        if let Origin::Local(slot) = st[st.len() - receiver_depth] {
                            push_unique_sorted(&mut out.object_slots, slot);
                        }
                    }
                }
            }
            if crate::ic_table::IC_TABLE
                .get(idx as usize)
                .is_some_and(|e| {
                    matches!(e.kind, crate::ic_table::IcEntryKind::MethodCall { .. })
                        && (buffer_uint_write_method_bridge_symbol(e.key).is_some()
                            || buffer_numeric_read_method_bridge_symbol(e.key).is_some())
                })
            {
                if let Some(st) = simulate_block_stack(&parsed[..i]) {
                    let arity = match crate::ic_table::IC_TABLE[idx as usize].kind {
                        crate::ic_table::IcEntryKind::MethodCall { arity } => arity,
                        _ => 0,
                    };
                    let receiver_depth = arity as usize + 2;
                    if st.len() >= receiver_depth {
                        if let Origin::Local(slot) = st[st.len() - receiver_depth] {
                            if typed_array_kind_specs
                                .iter()
                                .any(|spec| spec.receiver_slot == slot)
                            {
                                push_unique_sorted(&mut out.object_slots, slot);
                            }
                        }
                    }
                }
            }
        }
        if let ParsedOp::SetIndexOnObject = parsed[i].1 {
            let Some(st) = simulate_block_stack(&parsed[0..i]) else {
                continue;
            };
            let n = st.len();
            if n >= 3 {
                if let Origin::Local(slot) = st[n - 3] {
                    push_unique_sorted(&mut out.object_slots, slot);
                }
            }
        }
        if let ParsedOp::GetPropOnObject(_) = parsed[i].1 {
            let Some(st) = simulate_block_stack(&parsed[0..i]) else {
                continue;
            };
            let n = st.len();
            if n >= 1 {
                if let Origin::Local(slot) = st[n - 1] {
                    push_unique_sorted(&mut out.object_slots, slot);
                }
            }
        }

        if let ParsedOp::IcPropertyGet(idx) = parsed[i].1 {
            if ic_property_get_is(idx, "length") {
                if let Some(slot) = property_get_receiver_slot(&parsed[0..i]) {
                    push_unique_sorted(&mut out.object_slots, slot);
                }
            }
        }
        if !matches!(
            parsed[i].1,
            ParsedOp::GetIndexOnObject | ParsedOp::GetIndexStringOnObject
        ) {
            continue;
        }
        let Some(st) = simulate_block_stack(&parsed[0..i]) else {
            continue;
        };
        let n = st.len();
        if n < 2 {
            continue;
        }
        if let Origin::Local(slot) = st[n - 2] {
            push_unique_sorted(&mut out.object_slots, slot);
        }

        if let Origin::Local(slot) = st[n - 1] {
            push_unique_sorted(&mut out.i64_slots, slot);
        }

        if let Some(est) = simulate_expr_stack(&parsed[0..i]) {
            if est.len() >= 2 {
                let index = &est[est.len() - 1];
                let contains_induction = index.locals.iter().any(|s| induction.contains(s));
                if index.integer_rooted && contains_induction {
                    for slot in &index.locals {
                        if read_only.contains(slot) && !out.object_slots.contains(slot) {
                            push_unique_sorted(&mut out.i64_slots, *slot);
                        }
                    }
                }
            }
        }
    }
    for (_, _, dst_slot) in direct_call0_object_return_store_sites(parsed) {
        push_unique_sorted(&mut out.object_slots, dst_slot);
    }
    for (_, _, dst_slot) in host_native_constructor_object_return_store_sites(parsed) {
        push_unique_sorted(&mut out.object_slots, dst_slot);
    }
    for (_, dst_slot) in object_index_read_result_sites(parsed) {
        push_unique_sorted(&mut out.object_slots, dst_slot);
    }
    for (_, _, arg_slot) in direct_call_object_arg_sites(parsed) {
        push_unique_sorted(&mut out.object_slots, arg_slot);
    }
    for (_, _, arg_slot) in direct_call2_object_numeric_arg_sites(parsed) {
        push_unique_sorted(&mut out.object_slots, arg_slot);
    }
    if env_flag_enabled_by_default("CRUFT_LEJIT_MWOR_MDOA") {
        if let Some(candidate) = multi_write_osr_candidate(parsed) {
            for slot in candidate.receiver_slots {
                push_unique_sorted(&mut out.object_slots, slot);
            }
            for slot in pure_i64_control_read_only_slots(parsed, &read_only, &induction) {
                if !out.object_slots.contains(&slot) {
                    push_unique_sorted(&mut out.i64_slots, slot);
                }
            }
        }
    }

    for &slot in &induction {
        if !out.object_slots.contains(&slot) {
            push_unique_sorted(&mut out.i64_slots, slot);
        }
    }

    if env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_POSTINC_TEMPS") {
        for (base_slot, old_slot, new_slot) in postinc_temp_candidates {
            if out.i64_slots.contains(&base_slot) && !out.object_slots.contains(&base_slot) {
                push_unique_sorted(&mut out.i64_slots, old_slot);
                push_unique_sorted(&mut out.i64_slots, new_slot);
            }
        }
    }

    if env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_INT_REDUCTION") {
        for site in typed_array_reduction_sites(parsed) {
            if !site.bound_elided {
                continue;
            }
            let int_typed_array_receiver = typed_array_kind_specs.iter().any(|spec| {
                spec.receiver_slot == site.receiver_slot && (spec.kind == 1 || spec.kind == 2)
            });
            if int_typed_array_receiver && !out.object_slots.contains(&site.accumulator_slot) {
                push_unique_sorted(&mut out.i64_slots, site.accumulator_slot);
            }
        }
    }

    if env_flag_truthy("CRUFT_LEJIT_TYPED_ARRAY_MIXED_BOUND_ABI")
        && !typed_array_kind_specs.is_empty()
        && typed_array_reduction_sites(parsed)
            .iter()
            .any(|site| site.bound_elided)
    {
        for slot in pure_i64_control_read_only_slots(parsed, &read_only, &induction) {
            if !out.object_slots.contains(&slot) {
                push_unique_sorted(&mut out.i64_slots, slot);
            }
        }
        for slot in read_only.iter().copied() {
            if !out.object_slots.contains(&slot) {
                push_unique_sorted(&mut out.i64_slots, slot);
            }
        }
    }

    if out.object_slots.is_empty()
        && env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_PURE_I64_CONTROL")
        && pure_i64_control_loop_candidate(parsed)
    {
        for slot in pure_i64_control_read_only_slots(parsed, &read_only, &induction) {
            if !out.object_slots.contains(&slot) {
                push_unique_sorted(&mut out.i64_slots, slot);
            }
        }
    }

    if out.object_slots.is_empty()
        && env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_PLAIN_ADD_RECURRENCE")
        && plain_add_recurrence_loop_candidate(parsed)
    {
        for slot in pure_i64_control_read_only_slots(parsed, &read_only, &induction) {
            if !out.object_slots.contains(&slot) {
                push_unique_sorted(&mut out.i64_slots, slot);
            }
        }
    }

    if out.object_slots.is_empty()
        && env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_BITWISE_INT_CONTROL")
        && bitwise_int_control_loop_candidate(parsed)
    {
        for slot in pure_i64_control_read_only_slots(parsed, &read_only, &induction) {
            if !out.object_slots.contains(&slot) {
                push_unique_sorted(&mut out.i64_slots, slot);
            }
        }
    }

    if env_flag_enabled_by_default("CRUFT_LEJIT_STRING_CHARCODE_I64_INDEX") {
        for slot in string_charcode_length_bound_index_slots(parsed) {
            if !out.object_slots.contains(&slot) {
                push_unique_sorted(&mut out.i64_slots, slot);
            }
        }
    }

    if env_flag_enabled_by_default("CRUFT_LEJIT_STRING_CHARCODE_I64_REDUCTION") {
        for site in string_charcode_reduction_sites(parsed) {
            if !out.object_slots.contains(&site.accumulator_slot) {
                push_unique_sorted(&mut out.i64_slots, site.accumulator_slot);
            }
        }
    }

    if env_flag_enabled_by_default("CRUFT_LEJIT_PACKED_READ_I64_REDUCTION_PROBE") {
        for i in 0..parsed.len() {
            let (ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot)) = parsed[i].1 else {
                continue;
            };
            if out.object_slots.contains(&slot) {
                continue;
            }
            let Some(expr_stack) = simulate_expr_stack(&parsed[..i]) else {
                continue;
            };
            let Some(top) = expr_stack.last() else {
                continue;
            };
            if top.integer_rooted {
                push_unique_sorted(&mut out.i64_slots, slot);
            }
        }
    }

    if parsed
        .iter()
        .any(|(_, op)| matches!(op, ParsedOp::PrimitiveStringIndexRead { .. }))
    {
        for slot in primitive_string_index_receiver_slots(parsed) {
            push_unique_sorted(&mut out.string_slots, slot);
        }
        for slot in assigned_local_string_charcode_receiver_slots(parsed) {
            push_unique_sorted(&mut out.string_slots, slot);
        }
    }

    let pure_i64_control_ok = env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_PURE_I64_CONTROL")
        && pure_i64_control_loop_candidate(parsed);
    let plain_add_recurrence_ok =
        env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_PLAIN_ADD_RECURRENCE")
            && plain_add_recurrence_loop_candidate(parsed);
    let bitwise_int_control_ok =
        env_flag_enabled_by_default("CRUFT_LEJIT_MDOA_BITWISE_INT_CONTROL")
            && bitwise_int_control_loop_candidate(parsed);
    let string_charcode_i64_index_ok =
        env_flag_enabled_by_default("CRUFT_LEJIT_STRING_CHARCODE_I64_INDEX")
            && !string_charcode_length_bound_index_slots(parsed).is_empty();
    for slot in call_direct_leaf2_f64_accumulator_store_slots(parsed) {
        out.i64_slots.retain(|i64_slot| *i64_slot != slot);
    }
    for slot in param1_numeric_listener_writeback_f64_slots(parsed) {
        if !out.object_slots.contains(&slot)
            && !out.object_or_null_slots.contains(&slot)
            && !out.i64_slots.contains(&slot)
            && !out.string_slots.contains(&slot)
        {
            push_unique_sorted(&mut out.f64_slots, slot);
        }
    }
    if out.object_slots.is_empty()
        && out.object_or_null_slots.is_empty()
        && out.i64_slots.is_empty()
        && out.f64_slots.is_empty()
        && out.string_slots.is_empty()
        && !pure_i64_control_ok
        && !plain_add_recurrence_ok
        && !bitwise_int_control_ok
        && !string_charcode_i64_index_ok
    {
        return MixedDomainSlots::default();
    }

    for (_, op) in parsed {
        if let ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot) = *op {
            if !out.object_slots.contains(&slot)
                && !out.object_or_null_slots.contains(&slot)
                && !out.i64_slots.contains(&slot)
                && !out.string_slots.contains(&slot)
            {
                push_unique_sorted(&mut out.f64_slots, slot);
            }
        }
    }
    out
}

fn call_direct_leaf2_f64_accumulator_store_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut out = Vec::new();
    for i in 0..parsed.len() {
        let ParsedOp::StoreLocal(slot) = parsed[i].1 else {
            continue;
        };
        if !matches!(
            parsed.get(i.wrapping_sub(1)).map(|(_, op)| *op),
            Some(ParsedOp::Dup)
        ) {
            continue;
        }
        let start = parsed[..i]
            .iter()
            .rposition(|(_, op)| {
                matches!(
                    op,
                    ParsedOp::StoreLocal(_)
                        | ParsedOp::InitLocal(_)
                        | ParsedOp::Jump(_)
                        | ParsedOp::JumpIfTrue(_)
                        | ParsedOp::JumpIfFalse(_)
                        | ParsedOp::Pop
                )
            })
            .map(|idx| idx + 1)
            .unwrap_or(0);
        let window = &parsed[start..i];
        let has_leaf2 = window
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::CallDirectLeaf2 { .. }));
        let has_stable_call2 = window
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::CallDirect { arity: 2, .. }));
        if !(has_leaf2 || has_stable_call2)
            || !window
                .iter()
                .any(|(_, op)| matches!(op, ParsedOp::GetIndexOnObject))
            || !window.iter().any(|(_, op)| matches!(op, ParsedOp::Mul))
            || !window.iter().any(|(_, op)| matches!(op, ParsedOp::Add))
        {
            continue;
        }
        if !has_stable_call2 {
            let Some(expr_stack) = simulate_expr_stack(&parsed[..i]) else {
                continue;
            };
            let Some(top) = expr_stack.last() else {
                continue;
            };
            if top.integer_rooted {
                continue;
            }
        }
        push_unique_sorted(&mut out, slot);
    }
    out
}

fn param1_numeric_listener_writeback_f64_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut out = Vec::new();
    for window in parsed.windows(2) {
        let [(_, ParsedOp::LoadArg(arg_slot)), (_, ParsedOp::InitLocal(state_slot))] = window
        else {
            continue;
        };
        if *arg_slot == 0 {
            continue;
        }
        let has_add_storeback = parsed.windows(5).any(|w| {
            matches!(
                w,
                [
                    (_, ParsedOp::LoadLocal(a)),
                    (_, ParsedOp::LoadLocal(b)),
                    (_, ParsedOp::Add),
                    (_, ParsedOp::Dup),
                    (_, ParsedOp::StoreLocal(dst)),
                ] if dst == state_slot && (a == state_slot || b == state_slot)
            )
        });
        if !has_add_storeback {
            continue;
        }
        let returns_state = parsed.windows(2).any(|w| {
            matches!(
                w,
                [(_, ParsedOp::LoadLocal(s)), (_, ParsedOp::Return)] if s == state_slot
            )
        });
        if !returns_state {
            continue;
        }
        push_unique_sorted(&mut out, *arg_slot);
        push_unique_sorted(&mut out, *state_slot);
        for window in parsed.windows(5) {
            let [(_, ParsedOp::LoadLocal(a)), (_, ParsedOp::LoadLocal(b)), (_, ParsedOp::Add), (_, ParsedOp::Dup), (_, ParsedOp::StoreLocal(dst))] =
                window
            else {
                continue;
            };
            if dst == state_slot {
                push_unique_sorted(&mut out, *a);
                push_unique_sorted(&mut out, *b);
            }
        }
    }
    out
}

fn pure_i64_control_read_only_slots(
    parsed: &[(usize, ParsedOp)],
    read_only: &std::collections::HashSet<u16>,
    induction: &[u16],
) -> Vec<u16> {
    let mut out = Vec::new();
    for i in 0..parsed.len() {
        match parsed[i].1 {
            ParsedOp::BitAnd | ParsedOp::BitOr | ParsedOp::BitXor | ParsedOp::UShr => {
                let Some(stack) = simulate_expr_stack(&parsed[..i]) else {
                    continue;
                };
                if stack.len() < 2 {
                    continue;
                }
                let lhs = &stack[stack.len() - 2];
                let rhs = &stack[stack.len() - 1];
                if lhs.integer_rooted
                    || rhs.integer_rooted
                    || lhs.bitand_mask.is_some()
                    || rhs.bitand_mask.is_some()
                {
                    for slot in lhs.locals.iter().chain(rhs.locals.iter()) {
                        if read_only.contains(slot) {
                            push_unique_sorted(&mut out, *slot);
                        }
                    }
                }
            }
            ParsedOp::Lt
            | ParsedOp::Le
            | ParsedOp::Gt
            | ParsedOp::Ge
            | ParsedOp::LtI64
            | ParsedOp::LeI64
            | ParsedOp::GtI64
            | ParsedOp::GeI64 => {
                let Some(stack) = simulate_expr_stack(&parsed[..i]) else {
                    continue;
                };
                if stack.len() < 2 {
                    continue;
                }
                let lhs = &stack[stack.len() - 2];
                let rhs = &stack[stack.len() - 1];
                let lhs_induction = lhs.locals.iter().any(|slot| induction.contains(slot));
                let rhs_induction = rhs.locals.iter().any(|slot| induction.contains(slot));
                if lhs_induction || rhs_induction {
                    for slot in lhs.locals.iter().chain(rhs.locals.iter()) {
                        if read_only.contains(slot) {
                            push_unique_sorted(&mut out, *slot);
                        }
                    }
                }
            }
            _ => {}
        }
    }
    out
}

fn pure_i64_control_loop_candidate(parsed: &[(usize, ParsedOp)]) -> bool {
    let has_backward_jump = parsed.iter().any(|(pc, op)| match op {
        ParsedOp::Jump(t) | ParsedOp::JumpIfTrue(t) | ParsedOp::JumpIfFalse(t) => *t <= *pc,
        _ => false,
    });
    if !has_backward_jump {
        return false;
    }
    parsed.windows(3).any(|window| {
        matches!(
            window,
            [
                (_, ParsedOp::BitAnd),
                (_, ParsedOp::Dup),
                (_, ParsedOp::StoreLocal(_))
            ]
        )
    }) && parsed.windows(2).any(|window| {
        matches!(
            window,
            [(_, ParsedOp::PushI32(1_073_741_823)), (_, ParsedOp::BitAnd)]
        )
    })
}

fn plain_add_recurrence_loop_candidate(parsed: &[(usize, ParsedOp)]) -> bool {
    let has_backward_jump = parsed.iter().any(|(pc, op)| match op {
        ParsedOp::Jump(t) | ParsedOp::JumpIfTrue(t) | ParsedOp::JumpIfFalse(t) => *t <= *pc,
        _ => false,
    });
    if !has_backward_jump || scalar_osr_region_may_deopt(parsed) {
        return false;
    }
    let has_additive_self_update = parsed.windows(5).any(|window| {
        matches!(
            window,
            [
                (_, ParsedOp::LoadLocal(base)),
                (_, ParsedOp::PushI32(_)),
                (_, ParsedOp::Add | ParsedOp::Sub),
                (_, ParsedOp::Dup),
                (_, ParsedOp::StoreLocal(dst)),
            ] if base == dst
        )
    }) || parsed.windows(5).any(|window| {
        matches!(
            window,
            [
                (_, ParsedOp::PushI32(_)),
                (_, ParsedOp::LoadLocal(base)),
                (_, ParsedOp::Add),
                (_, ParsedOp::Dup),
                (_, ParsedOp::StoreLocal(dst)),
            ] if base == dst
        )
    });
    has_additive_self_update
        && parsed.windows(10).any(|window| {
            matches!(
                window,
                [
                    (_, ParsedOp::LoadLocal(base)),
                    (_, ParsedOp::ToNumeric),
                    (_, ParsedOp::Dup),
                    (_, ParsedOp::StoreLocal(_old)),
                    (_, ParsedOp::Inc | ParsedOp::IncI64),
                    (_, ParsedOp::StoreLocal(new)),
                    (_, ParsedOp::LoadLocal(load_new)),
                    (_, ParsedOp::StoreLocal(store_base)),
                    ..,
                ] if load_new == new && store_base == base
            )
        })
}

fn bitwise_int_control_loop_candidate(parsed: &[(usize, ParsedOp)]) -> bool {
    let has_backward_jump = parsed.iter().any(|(pc, op)| match op {
        ParsedOp::Jump(t) | ParsedOp::JumpIfTrue(t) | ParsedOp::JumpIfFalse(t) => *t <= *pc,
        _ => false,
    });
    if !has_backward_jump || scalar_osr_region_may_deopt(parsed) {
        return false;
    }
    let has_control_compare = parsed.windows(4).any(|window| {
        matches!(
            window,
            [
                (_, ParsedOp::LoadLocal(_)),
                (_, ParsedOp::LoadLocal(_)),
                (_, ParsedOp::Lt | ParsedOp::Le | ParsedOp::Gt | ParsedOp::Ge),
                (_, ParsedOp::JumpIfFalse(_)),
            ]
        )
    });
    has_control_compare
        && parsed
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::MathImul))
        && parsed.iter().any(|(_, op)| matches!(op, ParsedOp::UShr))
        && parsed.iter().any(|(_, op)| matches!(op, ParsedOp::BitXor))
}

fn postinc_update_temp_candidates(parsed: &[(usize, ParsedOp)]) -> Vec<(u16, u16, u16)> {
    let mut out = Vec::new();
    for window in parsed.windows(10) {
        let [(_, ParsedOp::LoadLocal(base_slot)), (_, ParsedOp::ToNumeric), (_, ParsedOp::Dup), (_, ParsedOp::StoreLocal(old_slot)), (_, ParsedOp::Inc | ParsedOp::IncI64), (_, ParsedOp::StoreLocal(new_slot)), (_, ParsedOp::LoadLocal(load_new_slot)), (_, ParsedOp::StoreLocal(store_base_slot)), (_, ParsedOp::LoadLocal(load_old_slot)), (_, ParsedOp::Pop)] =
            window
        else {
            continue;
        };
        if base_slot == store_base_slot && new_slot == load_new_slot && old_slot == load_old_slot {
            out.push((*base_slot, *old_slot, *new_slot));
        }
    }
    for window in parsed.windows(11) {
        let [(_, ParsedOp::LoadLocal(base_slot)), (_, ParsedOp::ToNumeric), (_, ParsedOp::Dup), (_, ParsedOp::StoreLocal(old_slot)), (_, ParsedOp::Inc | ParsedOp::IncI64), (_, ParsedOp::StoreLocal(new_slot)), (_, ParsedOp::LoadLocal(load_new_slot)), (_, ParsedOp::StoreLocal(store_base_slot)), (_, ParsedOp::ResetLocalCellNop), (_, ParsedOp::LoadLocal(load_old_slot)), (_, ParsedOp::Pop)] =
            window
        else {
            continue;
        };
        if base_slot == store_base_slot && new_slot == load_new_slot && old_slot == load_old_slot {
            out.push((*base_slot, *old_slot, *new_slot));
        }
    }
    out.sort_unstable();
    out.dedup();
    out
}

fn postinc_temp_storeback_exclusions(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut covered_temp_loads: std::collections::HashSet<usize> = std::collections::HashSet::new();
    let mut candidates: Vec<u16> = Vec::new();
    for (start, window) in parsed.windows(10).enumerate() {
        let [(_, ParsedOp::LoadLocal(base_slot)), (_, ParsedOp::ToNumeric), (_, ParsedOp::Dup), (_, ParsedOp::StoreLocal(old_slot)), (_, ParsedOp::Inc | ParsedOp::IncI64), (_, ParsedOp::StoreLocal(new_slot)), (_, ParsedOp::LoadLocal(load_new_slot)), (_, ParsedOp::StoreLocal(store_base_slot)), (_, ParsedOp::LoadLocal(load_old_slot)), (_, ParsedOp::Pop)] =
            window
        else {
            continue;
        };
        if base_slot == store_base_slot && new_slot == load_new_slot && old_slot == load_old_slot {
            push_unique_sorted(&mut candidates, *old_slot);
            push_unique_sorted(&mut candidates, *new_slot);
            covered_temp_loads.insert(start + 6);
            covered_temp_loads.insert(start + 8);
        }
    }
    for (start, window) in parsed.windows(11).enumerate() {
        let [(_, ParsedOp::LoadLocal(base_slot)), (_, ParsedOp::ToNumeric), (_, ParsedOp::Dup), (_, ParsedOp::StoreLocal(old_slot)), (_, ParsedOp::Inc | ParsedOp::IncI64), (_, ParsedOp::StoreLocal(new_slot)), (_, ParsedOp::LoadLocal(load_new_slot)), (_, ParsedOp::StoreLocal(store_base_slot)), (_, ParsedOp::ResetLocalCellNop), (_, ParsedOp::LoadLocal(load_old_slot)), (_, ParsedOp::Pop)] =
            window
        else {
            continue;
        };
        if base_slot == store_base_slot && new_slot == load_new_slot && old_slot == load_old_slot {
            push_unique_sorted(&mut candidates, *old_slot);
            push_unique_sorted(&mut candidates, *new_slot);
            covered_temp_loads.insert(start + 6);
            covered_temp_loads.insert(start + 9);
        }
    }

    candidates
        .into_iter()
        .filter(|slot| {
            parsed.iter().enumerate().all(|(idx, (_, op))| {
                !matches!(op, ParsedOp::LoadLocal(s) if s == slot)
                    || covered_temp_loads.contains(&idx)
            })
        })
        .collect()
}

fn scalar_i64_postinc_temp_slots(
    parsed: &[(usize, ParsedOp)],
    i64_payload_slots: &[usize],
) -> Vec<u16> {
    let mut out = Vec::new();
    for (base_slot, old_slot, new_slot) in postinc_update_temp_candidates(parsed) {
        if i64_payload_slots.contains(&usize::from(base_slot)) {
            push_unique_sorted(&mut out, old_slot);
            push_unique_sorted(&mut out, new_slot);
        }
    }
    out
}

fn push_unique_sorted(v: &mut Vec<u16>, slot: u16) {
    if !v.contains(&slot) {
        v.push(slot);
        v.sort_unstable();
    }
}

fn local_slot_name(locals: &[rusty_js_bytecode::compiler::LocalDescriptor], slot: u16) -> String {
    locals
        .get(usize::from(slot))
        .map(|local| local.name.clone())
        .unwrap_or_else(|| format!("<slot-{slot}>"))
}

fn describe_origin_with_local(
    origin: Origin,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> String {
    match origin {
        Origin::Local(slot) => format!("Local({slot}:{})", local_slot_name(locals, slot)),
        other => format!("{other:?}"),
    }
}

fn describe_expr_origin_with_locals(
    expr: &ExprOrigin,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> String {
    let origin = describe_origin_with_local(expr.origin, locals);
    let local_names = expr
        .locals
        .iter()
        .map(|slot| format!("{slot}:{}", local_slot_name(locals, *slot)))
        .collect::<Vec<_>>()
        .join(",");
    format!(
        "{origin} locals=[{local_names}] integer_rooted={} const_i32={:?} affine={:?} bitand={:?} string_len_slot={:?}",
        expr.integer_rooted,
        expr.const_i32,
        expr.affine_index,
        expr.bitand_mask,
        expr.string_length_receiver_slot
    )
}

fn describe_parsed_op_with_locals(
    pc: usize,
    op: &ParsedOp,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> String {
    match op {
        ParsedOp::LoadLocal(slot) => {
            format!("{pc}:LoadLocal({slot}:{})", local_slot_name(locals, *slot))
        }
        ParsedOp::StoreLocal(slot) => {
            format!("{pc}:StoreLocal({slot}:{})", local_slot_name(locals, *slot))
        }
        ParsedOp::InitLocal(slot) => {
            format!("{pc}:InitLocal({slot}:{})", local_slot_name(locals, *slot))
        }
        ParsedOp::TdzSeedLocal(slot) => {
            format!(
                "{pc}:TdzSeedLocal({slot}:{})",
                local_slot_name(locals, *slot)
            )
        }
        other => format!("{pc}:{other:?}"),
    }
}

fn recent_ops_with_locals(
    out: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> String {
    let start = out.len().saturating_sub(14);
    out[start..]
        .iter()
        .map(|(pc, op)| describe_parsed_op_with_locals(*pc, op, locals))
        .collect::<Vec<_>>()
        .join("; ")
}

fn primitive_string_index_bail_detail(
    out: &[(usize, ParsedOp)],
    bc: &[u8],
    pc_after_getindex: usize,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Option<String> {
    if !env_flag_truthy("CRUFT_OSR_TRACE") {
        return None;
    }
    let block_stack = simulate_block_stack(out);
    let expr_stack = simulate_expr_stack(out);
    let block_top = block_stack
        .as_ref()
        .map(|st| {
            let n = st.len();
            let receiver = n
                .checked_sub(2)
                .and_then(|idx| st.get(idx).copied())
                .map(|origin| describe_origin_with_local(origin, locals))
                .unwrap_or_else(|| "<missing>".to_string());
            let index = st
                .last()
                .copied()
                .map(|origin| describe_origin_with_local(origin, locals))
                .unwrap_or_else(|| "<missing>".to_string());
            format!("block_receiver={receiver} block_index={index} block_depth={n}")
        })
        .unwrap_or_else(|| "block_stack=<unavailable>".to_string());
    let expr_top = expr_stack
        .as_ref()
        .map(|st| {
            let n = st.len();
            let receiver = n
                .checked_sub(2)
                .and_then(|idx| st.get(idx))
                .map(|expr| describe_expr_origin_with_locals(expr, locals))
                .unwrap_or_else(|| "<missing>".to_string());
            let index = st
                .last()
                .map(|expr| describe_expr_origin_with_locals(expr, locals))
                .unwrap_or_else(|| "<missing>".to_string());
            format!("expr_receiver={receiver} expr_index={index} expr_depth={n}")
        })
        .unwrap_or_else(|| "expr_stack=<unavailable>".to_string());
    let next_op = bc
        .get(pc_after_getindex)
        .and_then(|byte| op_from_byte(*byte))
        .map(|op| format!("{op:?}"))
        .unwrap_or_else(|| "<eof-or-unknown>".to_string());
    let recent_ops = recent_ops_with_locals(out, locals);
    Some(format!(
        " primitive-string-index-candidate {{{block_top}; {expr_top}; next_op={next_op}; recent_ops=[{recent_ops}]; old_object_lane=not-used}}"
    ))
}

fn primitive_string_index_admission_probe_enabled() -> bool {
    env_flag_truthy("CRUFT_LEJIT_PRIMITIVE_STRING_INDEX_ADMISSION_PROBE")
}

#[cfg(test)]
fn parse_bytecode(
    bc: &[u8],
    constants: &ConstantsPool,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Result<Vec<(usize, ParsedOp)>, String> {
    parse_bytecode_with_stable_callee_preloads(
        bc,
        constants,
        locals,
        &std::collections::HashSet::new(),
        &std::collections::HashMap::new(),
        &std::collections::HashMap::new(),
        &std::collections::HashSet::new(),
        &std::collections::HashSet::new(),
        &std::collections::HashSet::new(),
    )
}

fn parse_bytecode_with_stable_callee_preloads(
    bc: &[u8],
    constants: &ConstantsPool,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
    stable_callee_preload_slots: &std::collections::HashSet<u16>,
    stable_host_global_preload_slots: &std::collections::HashMap<
        u16,
        crate::ic_table::HostGlobalObjectKind,
    >,
    stable_host_object_preload_slots: &std::collections::HashMap<
        u16,
        crate::ic_table::HostNativeObjectKind,
    >,
    stable_object_upvalue_preload_slots: &std::collections::HashSet<u16>,
    stable_numeric_upvalue_preload_slots: &std::collections::HashSet<u16>,
    stable_string_upvalue_preload_slots: &std::collections::HashSet<u16>,
) -> Result<Vec<(usize, ParsedOp)>, String> {
    let mut out = Vec::new();
    let mut pc = 0;
    while pc < bc.len() {
        let op_pc = pc;
        let opcode = op_from_byte(bc[pc])
            .ok_or_else(|| format!("unknown opcode byte 0x{:02x} at pc={}", bc[pc], pc))?;
        pc += 1;
        let parsed = match opcode {
            Op::LoadArg => {
                let s = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                ParsedOp::LoadArg(s)
            }
            Op::LoadLocal => {
                let s = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                ParsedOp::LoadLocal(s)
            }
            Op::LoadUpvalue => {
                let upvalue_slot = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                let Some(next_op) = bc.get(pc).and_then(|b| op_from_byte(*b)) else {
                    return Err(format!(
                        "LoadUpvalue at pc={op_pc}: missing following stable-callee preload store"
                    ));
                };
                if !matches!(next_op, Op::InitLocal | Op::StoreLocal) {
                    return Err(format!(
                        "LoadUpvalue at pc={op_pc}: upvalue_slot={upvalue_slot} followed by {next_op:?} is unsupported in JIT alphabet outside stable preload"
                    ));
                }
                let store_pc = pc;
                pc += 1;
                if pc + 1 >= bc.len() {
                    return Err(format!(
                        "LoadUpvalue at pc={op_pc}: truncated following {next_op:?}"
                    ));
                }
                let local_slot = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                if stable_callee_preload_slots.contains(&local_slot) {
                    ParsedOp::StableCalleePreload {
                        upvalue_slot,
                        local_slot,
                    }
                } else if let Some(object_kind) = stable_host_global_preload_slots.get(&local_slot)
                {
                    ParsedOp::StableHostGlobalObjectPreload {
                        upvalue_slot,
                        local_slot,
                        object_kind: *object_kind,
                    }
                } else if let Some(object_kind) = stable_host_object_preload_slots.get(&local_slot)
                {
                    ParsedOp::StableHostObjectPreload {
                        upvalue_slot,
                        local_slot,
                        object_kind: *object_kind,
                    }
                } else if stable_object_upvalue_preload_slots.contains(&local_slot) {
                    ParsedOp::StableObjectUpvaluePreload {
                        upvalue_slot,
                        local_slot,
                    }
                } else if stable_numeric_upvalue_preload_slots.contains(&local_slot) {
                    ParsedOp::StableNumericUpvaluePreload {
                        upvalue_slot,
                        local_slot,
                    }
                } else if stable_string_upvalue_preload_slots.contains(&local_slot) {
                    ParsedOp::LoadLocal(local_slot)
                } else {
                    return Err(format!(
                        "LoadUpvalue at pc={op_pc}: {next_op:?} local slot {local_slot} at pc={store_pc} has no stable direct-callee fact, stable host-object fact, stable object-upvalue fact, stable numeric-upvalue fact, or stable string-upvalue fact"
                    ));
                }
            }
            Op::LoadGlobal => {
                let idx = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                if is_script_var_global_bind_helper(constants, idx)
                    && consume_script_var_global_bind_mirror_nop(bc, &mut pc, constants, locals)
                {
                    ParsedOp::ResetLocalCellNop
                } else {
                    match script_global_var_slot(constants, locals, idx) {
                        Some(slot) => ParsedOp::LoadLocal(slot),
                        None => {
                            if matches!(constants.get(idx), Some(Constant::String(s)) if s == "globalThis")
                            {
                                ParsedOp::GlobalThis
                            } else if matches!(constants.get(idx), Some(Constant::String(s)) if s == "undefined")
                            {
                                ParsedOp::PushUndefined
                            } else if matches!(constants.get(idx), Some(Constant::String(s)) if s == "String")
                            {
                                ParsedOp::PendingStringGlobal
                            } else if matches!(constants.get(idx), Some(Constant::String(s)) if s == "Number")
                            {
                                ParsedOp::PendingNumberGlobal
                            } else if let Some(object_kind) =
                                constants.get(idx).and_then(|constant| match constant {
                                    Constant::String(s) => {
                                        crate::ic_table::lookup_host_global_object(s.as_str())
                                    }
                                    _ => None,
                                })
                            {
                                ParsedOp::HostGlobalObject {
                                    name_idx: idx,
                                    object_kind,
                                    consumes_receiver: false,
                                }
                            } else {
                                return Err(format!(
                                "LoadGlobal at pc={op_pc}: {} not a script-global var alias (aliases: {})",
                                describe_constant_name(constants, idx),
                                describe_script_global_var_aliases(locals)
                            ));
                            }
                        }
                    }
                }
            }
            Op::PushUndef => ParsedOp::PushUndefined,
            Op::StoreLocal => {
                let s = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                if matches!(
                    out.last(),
                    Some((_, ParsedOp::StringConcatOwnedResult { left_slot }
                        | ParsedOp::StringConcatLocalValue { left_slot }
                        | ParsedOp::StringConcatLocalValuePreserveRight { left_slot })) if *left_slot != s
                ) {
                    return Err(format!(
                        "StoreLocal at pc={op_pc}: string concat/writeback destination slot {s} does not match left string local"
                    ));
                }
                ParsedOp::StoreLocal(s)
            }
            Op::InitLocal => {
                let s = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                ParsedOp::InitLocal(s)
            }
            Op::StoreGlobal => {
                let idx = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                match script_global_var_slot(constants, locals, idx) {
                    Some(slot) => ParsedOp::StoreScriptGlobalVar {
                        slot,
                        name_idx: idx,
                    },
                    None => {
                        return Err(format!(
                        "StoreGlobal at pc={op_pc}: {} not a script-global var alias (aliases: {})",
                        describe_constant_name(constants, idx),
                        describe_script_global_var_aliases(locals)
                    ))
                    }
                }
            }
            Op::PushI32 => {
                let n = i32::from_le_bytes([bc[pc], bc[pc + 1], bc[pc + 2], bc[pc + 3]]);
                pc += 4;
                ParsedOp::PushI32(n)
            }

            Op::PushTrue => {
                if let Some(slot) = boolean_literal_local_store_slot(bc, pc) {
                    return Err(format!(
                        "PushTrue at pc={op_pc}: boolean literal stored to local slot {slot} '{}' (unsound in f64 OSR alphabet; route boolean-preserving local domain)",
                        local_name_for_diag(locals, slot)
                    ));
                }
                ParsedOp::PushI32(1)
            }
            Op::PushFalse => {
                if let Some(slot) = boolean_literal_local_store_slot(bc, pc) {
                    return Err(format!(
                        "PushFalse at pc={op_pc}: boolean literal stored to local slot {slot} '{}' (unsound in f64 OSR alphabet; route boolean-preserving local domain)",
                        local_name_for_diag(locals, slot)
                    ));
                }
                ParsedOp::PushI32(0)
            }
            Op::PushTDZ => {
                let store_pc = pc;
                let next = op_from_byte(*bc.get(pc).ok_or_else(|| {
                    format!("PushTDZ at pc={op_pc}: missing following StoreLocal/InitLocal")
                })?)
                .ok_or_else(|| {
                    format!(
                        "PushTDZ at pc={op_pc}: unknown following opcode byte 0x{:02x}",
                        bc[pc]
                    )
                })?;
                pc += 1;
                if !matches!(next, Op::StoreLocal | Op::InitLocal) {
                    return Err(format!(
                        "PushTDZ at pc={op_pc}: expected StoreLocal/InitLocal seed, found {next:?} at pc={store_pc}"
                    ));
                }
                let slot = u16::from_le_bytes([
                    *bc.get(pc).ok_or_else(|| {
                        format!("PushTDZ at pc={op_pc}: missing StoreLocal/InitLocal slot low byte")
                    })?,
                    *bc.get(pc + 1).ok_or_else(|| {
                        format!(
                            "PushTDZ at pc={op_pc}: missing StoreLocal/InitLocal slot high byte"
                        )
                    })?,
                ]);
                pc += 2;
                ParsedOp::TdzSeedLocal(slot)
            }

            Op::PushConst => {
                let idx = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                match constants.get(idx) {
                    Some(Constant::Number(n)) => ParsedOp::PushConst(*n),
                    Some(Constant::String(s)) if string_literal_probe_enabled() => {
                        ParsedOp::PushStringConst {
                            ptr: s.as_ptr() as i64,
                            len: s.len() as i64,
                        }
                    }
                    Some(other) => {
                        return Err(format!(
                            "PushConst at pc={op_pc}: non-Number constant unsupported in JIT alphabet ({})",
                            describe_constant_value(other)
                    ))
                    }
                    None => {
                        return Err(format!(
                            "PushConst at pc={op_pc}: constant idx {idx} out of bounds"
                        ))
                    }
                }
            }

            Op::PushLiteral => {
                let idx = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                match constants.get_literal(idx as u32) {
                    Some(Constant::Number(n)) => ParsedOp::PushConst(*n),
                    Some(Constant::String(s)) if string_literal_probe_enabled() => {
                        ParsedOp::PushStringConst {
                            ptr: s.as_ptr() as i64,
                            len: s.len() as i64,
                        }
                    }
                    Some(other) => {
                        return Err(format!(
                            "PushLiteral at pc={op_pc}: non-Number literal unsupported in JIT alphabet ({})",
                            describe_constant_value(other)
                        ))
                    }
                    None => {
                        return Err(format!(
                            "PushLiteral at pc={op_pc}: literal idx {idx} out of bounds"
                        ))
                    }
                }
            }

            Op::GetProp | Op::GetArrayLengthDirect => {
                let idx = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                let key = match constants.get(idx) {
                    Some(Constant::String(s)) => s.as_str(),
                    Some(_) => {
                        return Err(format!("GetProp at pc={op_pc}: non-String key unsupported"))
                    }
                    None => {
                        return Err(format!(
                            "GetProp at pc={op_pc}: constant idx {idx} out of bounds"
                        ))
                    }
                };
                let string_from_char_code_receiver =
                    if matches!(out.last(), Some((_, ParsedOp::PendingStringGlobal))) {
                        out.pop();
                        Some(false)
                    } else if out.len() >= 2
                        && matches!(out[out.len() - 2].1, ParsedOp::PendingStringGlobal)
                        && matches!(out[out.len() - 1].1, ParsedOp::Dup)
                    {
                        out.pop();
                        out.pop();
                        Some(true)
                    } else {
                        None
                    };
                if let Some(has_method_receiver) = string_from_char_code_receiver {
                    if key == "fromCharCode" {
                        if has_method_receiver {
                            out.push((op_pc, ParsedOp::StringFromCharCodeReceiver));
                        }
                        ParsedOp::StringFromCharCodeCallee
                    } else {
                        return Err(format!(
                            "GetProp at pc={op_pc}: only String.fromCharCode is admitted in LeJIT string-producing concat/writeback substrate"
                        ));
                    }
                } else {
                    if matches!(out.last(), Some((_, ParsedOp::GlobalThis))) {
                        if let Some(object_kind) = crate::ic_table::lookup_host_global_object(key) {
                            ParsedOp::HostGlobalObject {
                                name_idx: idx,
                                object_kind,
                                consumes_receiver: true,
                            }
                        } else {
                            return Err(format!(
                                "GetProp at pc={op_pc}: globalThis key '{key}' has no host-global object fact"
                            ));
                        }
                    } else {
                        let receiver_origin = simulate_block_stack(&out)
                            .and_then(|st| st.last().copied())
                            .or_else(|| match out.last() {
                                Some((_, ParsedOp::LoadLocal(slot))) => Some(Origin::Local(*slot)),
                                _ => None,
                            });
                        let receiver_origin = match receiver_origin {
                            Some(Origin::Local(slot)) => {
                                if let Some(object_kind) =
                                    stable_host_global_preload_slots.get(&slot)
                                {
                                    Some(Origin::HostGlobalObject(*object_kind))
                                } else {
                                    host_native_object_local_origin(&out, slot)
                                        .map(Origin::HostNativeObject)
                                        .or(Some(Origin::Local(slot)))
                                }
                            }
                            other => other,
                        };
                        if let Some(Origin::HostGlobalObject(global_kind)) = receiver_origin {
                            ParsedOp::HostGlobalObjectProp {
                                global_kind,
                                prop_idx: idx,
                            }
                        } else if let Some(Origin::HostNativeObject(object_kind)) = receiver_origin
                        {
                            ParsedOp::HostNativeObjectProp {
                                object_kind,
                                prop_idx: idx,
                            }
                        } else if key == "join" && !array_join_probe_enabled() {
                            return Err(format!(
                            "GetProp at pc={op_pc}: key '{key}' not in IC_TABLE (receiver not a direct local)"
                        ));
                        } else {
                            match crate::ic_table::lookup_by_key(key) {
                                Some(entry_idx) => {
                                    match crate::ic_table::IC_TABLE[entry_idx as usize].kind {
                                        crate::ic_table::IcEntryKind::PropertyGet => {
                                            ParsedOp::IcPropertyGet(entry_idx)
                                        }
                                        crate::ic_table::IcEntryKind::MethodCall { .. } => {
                                            ParsedOp::IcMethodResolve(entry_idx)
                                        }
                                    }
                                }

                                None => {
                                    if matches!(
                                        receiver_origin,
                                        Some(
                                            Origin::Local(_)
                                                | Origin::IndexedObjectCallee {
                                                    receiver_slot: Some(_),
                                                    ..
                                                }
                                        )
                                    ) {
                                        ParsedOp::GetPropOnObject(idx)
                                    } else {
                                        return Err(format!(
                                    "GetProp at pc={op_pc}: key '{key}' not in IC_TABLE (receiver not a direct local)"
                                ));
                                    }
                                }
                            }
                        }
                    }
                }
            }

            Op::CallMethod | Op::TailCallMethod => {
                let n = bc[pc];
                pc += 1;
                let method_origin = simulate_block_stack(&out).and_then(|st| {
                    let method_depth = st.len().checked_sub(usize::from(n) + 1)?;
                    Some(st[method_depth])
                });
                match method_origin {
                    Some(Origin::StringFromCharCodeCallee) if n == 1 => {
                        ParsedOp::CallStringFromCharCodeMethod
                    }
                    Some(Origin::StringFromCharCodeCallee) => {
                        return Err(format!(
                            "CallMethod at pc={op_pc}: String.fromCharCode arity {n} unsupported in LeJIT string-producing concat/writeback substrate"
                        ))
                    }
                    Some(Origin::HostNativeObjectProperty {
                        object_kind,
                        prop_idx,
                    }) if n == 0 => ParsedOp::HostNativeObjectMethod0 {
                        object_kind,
                        prop_idx,
                    },
                    Some(Origin::HostNativeObjectProperty {
                        object_kind,
                        prop_idx,
                    }) if object_kind == crate::ic_table::HostNativeObjectKind::Buffer && n == 2 =>
                    {
                        let key = match constants.get(prop_idx) {
                            Some(Constant::String(s)) => s.as_str(),
                            _ => "<non-string>",
                        };
                        match crate::ic_table::lookup_by_key(key) {
                            Some(entry_idx)
                                if matches!(
                                    crate::ic_table::IC_TABLE[entry_idx as usize].kind,
                                    crate::ic_table::IcEntryKind::MethodCall { arity: 2 }
                                ) =>
                            {
                                ParsedOp::IcMethodCall(entry_idx)
                            }
                            _ => {
                                return Err(format!(
                                    "CallMethod at pc={op_pc}: host-native object {object_kind:?} method '{key}' arity {n} reached unsupported object-result method gate"
                                ));
                            }
                        }
                    }
                    Some(Origin::HostNativeObjectProperty {
                        object_kind,
                        prop_idx,
                    }) if object_kind == crate::ic_table::HostNativeObjectKind::Buffer && n == 1 =>
                    {
                        let key = match constants.get(prop_idx) {
                            Some(Constant::String(s)) => s.as_str(),
                            _ => "<non-string>",
                        };
                        if key == "toString" {
                            ParsedOp::HostNativeObjectMethod1String {
                                object_kind,
                                prop_idx,
                            }
                        } else {
                            return Err(format!(
                                "CallMethod at pc={op_pc}: host-native object {object_kind:?} method '{key}' arity {n} reached unsupported object-result method gate"
                            ));
                        }
                    }
                    Some(Origin::HostNativeObjectProperty {
                        object_kind,
                        prop_idx,
                    }) => {
                        let key = match constants.get(prop_idx) {
                            Some(Constant::String(s)) => s.as_str(),
                            _ => "<non-string>",
                        };
                        return Err(format!(
                            "CallMethod at pc={op_pc}: host-native object {object_kind:?} method '{key}' arity {n} reached unsupported object-result method gate"
                        ));
                    }
                    Some(Origin::HostGlobalObjectProperty {
                        global_kind,
                        prop_idx,
                    }) => {
                        let key = match constants.get(prop_idx) {
                            Some(Constant::String(s)) => s.as_str(),
                            _ => "<non-string>",
                        };
                        let receiver =
                            crate::ic_table::host_global_object_candidate_name(global_kind);
                        if matches!(
                            global_kind,
                            crate::ic_table::HostGlobalObjectKind::Math
                        ) && key == "imul"
                            && n == 2
                        {
                            ParsedOp::MathImul
                        } else if matches!(
                            global_kind,
                            crate::ic_table::HostGlobalObjectKind::Array
                        ) && key == "isArray"
                            && n == 1
                        {
                            ParsedOp::ArrayIsArrayStatic
                        } else if let Some(candidate) =
                            crate::ic_table::lookup_host_native_method_candidate(receiver, key, n)
                        {
                            if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Object
                            ) && n == 1
                            {
                                ParsedOp::HostNativeMethod1ObjRet {
                                    receiver_slot: 0,
                                    prop_idx,
                                    object_kind: candidate.object_kind.ok_or_else(|| {
                                        format!(
                                            "CallMethod at pc={op_pc}: host-global native candidate '{receiver}.{key}' object result lacks object kind"
                                        )
                                    })?,
                                }
                            } else if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Object
                            ) && n == 2
                            {
                                ParsedOp::HostNativeMethod2ObjRet {
                                    receiver_slot: 0,
                                    prop_idx,
                                    object_kind: candidate.object_kind.ok_or_else(|| {
                                        format!(
                                            "CallMethod at pc={op_pc}: host-global native candidate '{receiver}.{key}' object result lacks object kind"
                                        )
                                    })?,
                                }
                            } else if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Number
                            ) && n == 0
                            {
                                ParsedOp::HostNativeMethod0NumRet { prop_idx }
                            } else if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Number
                                    | crate::ic_table::HostNativeResultKind::Boolean
                            ) && n == 1
                            {
                                ParsedOp::HostNativeMethod1NumRet { prop_idx }
                            } else if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::String
                            ) && n == 1
                            {
                                ParsedOp::HostNativeMethod1String { prop_idx }
                            } else if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::String
                            ) && n == 4
                            {
                                ParsedOp::HostNativeMethod4String { prop_idx }
                            } else {
                                return Err(format!(
                                    "CallMethod at pc={op_pc}: host-global native candidate '{receiver}.{key}' arity {n} result {:?} reached unsupported host-native method gate",
                                    candidate.result
                                ));
                            }
                        } else {
                            return Err(format!(
                                "CallMethod at pc={op_pc}: host-global object method '{receiver}.{key}' arity {n} reached method-call lowering gate"
                            ));
                        }
                    }
                    Some(Origin::ObjectProperty {
                        receiver_slot,
                        prop_idx,
                    }) => {
                        let key = match constants.get(prop_idx) {
                            Some(Constant::String(s)) => s.as_str(),
                            _ => "<non-string>",
                        };
                        let receiver = receiver_slot
                            .and_then(|slot| locals.get(usize::from(slot)))
                            .map(|local| local.name.as_str())
                            .unwrap_or("<unknown-receiver>");
                        if let Some(candidate) =
                            crate::ic_table::lookup_host_native_method_candidate(receiver, key, n)
                        {
                            if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Object
                            ) && n == 1
                            {
                                if let Some(receiver_slot) = receiver_slot {
                                    ParsedOp::HostNativeMethod1ObjRet {
                                        receiver_slot,
                                        prop_idx,
                                        object_kind: candidate.object_kind.ok_or_else(|| {
                                            format!(
                                                "CallMethod at pc={op_pc}: host-native candidate '{receiver}.{key}' object result lacks object kind"
                                            )
                                        })?,
                                    }
                                } else {
                                    return Err(format!(
                                        "CallMethod at pc={op_pc}: host-native candidate '{receiver}.{key}' arity {n} lacks receiver slot for object-return method lowering"
                                    ));
                                }
                            } else if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Object
                            ) && n == 2
                            {
                                if let Some(receiver_slot) = receiver_slot {
                                    ParsedOp::HostNativeMethod2ObjRet {
                                        receiver_slot,
                                        prop_idx,
                                        object_kind: candidate.object_kind.ok_or_else(|| {
                                            format!(
                                                "CallMethod at pc={op_pc}: host-native candidate '{receiver}.{key}' object result lacks object kind"
                                            )
                                        })?,
                                    }
                                } else {
                                    return Err(format!(
                                        "CallMethod at pc={op_pc}: host-native candidate '{receiver}.{key}' arity {n} lacks receiver slot for object-return method lowering"
                                    ));
                                }
                            } else if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Number
                                    | crate::ic_table::HostNativeResultKind::Boolean
                            ) && n == 1
                            {
                                ParsedOp::HostNativeMethod1NumRet { prop_idx }
                        } else if matches!(
                            candidate.result,
                            crate::ic_table::HostNativeResultKind::String
                        ) && n == 1
                        {
                            ParsedOp::HostNativeMethod1String { prop_idx }
                        } else if key == "slice"
                            && n == 2
                            && receiver_slot.is_some_and(|slot| {
                                stable_string_upvalue_preload_slots.contains(&slot)
                            })
                        {
                            ParsedOp::HostNativeMethod2String { prop_idx }
                        } else {
                            return Err(format!(
                                "CallMethod at pc={op_pc}: host-native candidate '{receiver}.{key}' arity {n} result {:?} reached unsupported host-native method gate",
                                candidate.result
                                ));
                            }
                        } else if key == "slice"
                            && n == 2
                            && receiver_slot.is_some_and(|slot| {
                                stable_string_upvalue_preload_slots.contains(&slot)
                            })
                        {
                            ParsedOp::HostNativeMethod2String { prop_idx }
                        } else {
                            return Err(format!(
                                "CallMethod at pc={op_pc}: generic object method '{receiver}.{key}' arity {n} reached method-call lowering gate"
                            ));
                        }
                    }
                    Some(Origin::IndexedObjectCallee { receiver_slot, .. }) if n == 1 => {
                        if receiver_slot.is_some() {
                            ParsedOp::CallIndexedDirect1
                        } else {
                            return Err(format!(
                                "CallMethod at pc={op_pc}: indexed callee lacks guarded receiver slot"
                            ));
                        }
                    }
                    _ => {

                let prev_idx = out.iter().rev().find_map(|(_, op)| {
                    if let ParsedOp::IcMethodResolve(i) = op {
                        if let crate::ic_table::IcEntryKind::MethodCall { arity } =
                            crate::ic_table::IC_TABLE[*i as usize].kind
                        {
                            if arity == n {
                                return Some(*i);
                            }
                        }
                    }
                    None
                });
                match prev_idx {
                    Some(i) => ParsedOp::IcMethodCall(i),
                    None => return Err(format!("CallMethod at pc={op_pc}: arity {n} has no preceding IcMethodResolve match in IC_TABLE")),
                }
                    }
                }
            }
            Op::GetPropSkipForMethod => {
                let idx = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                let key = match constants.get(idx) {
                    Some(Constant::String(s)) => s.as_str(),
                    Some(_) => {
                        return Err(format!(
                            "GetPropSkipForMethod at pc={op_pc}: non-String key unsupported"
                        ))
                    }
                    None => {
                        return Err(format!(
                            "GetPropSkipForMethod at pc={op_pc}: constant idx {idx} out of bounds"
                        ))
                    }
                };
                match crate::ic_table::lookup_by_key(key) {
                    Some(entry_idx)
                        if matches!(
                            crate::ic_table::IC_TABLE[entry_idx as usize].kind,
                            crate::ic_table::IcEntryKind::MethodCall { .. }
                        ) =>
                    {
                        ParsedOp::IcMethodResolve(entry_idx)
                    }
                    Some(_) => {
                        return Err(format!(
                            "GetPropSkipForMethod at pc={op_pc}: key '{key}' is not a method-call IC entry"
                        ))
                    }
                    None => {
                        return Err(format!(
                            "GetPropSkipForMethod at pc={op_pc}: key '{key}' not in IC_TABLE"
                        ))
                    }
                }
            }
            Op::CallMethodIcCached => {
                let ihi_entry_idx = bc[pc];
                pc += 1;
                match out.iter().rev().find_map(|(_, op)| {
                    if let ParsedOp::IcMethodResolve(i) = op {
                        if matches!(
                            crate::ic_table::IC_TABLE[*i as usize].kind,
                            crate::ic_table::IcEntryKind::MethodCall { .. }
                        ) {
                            return Some(*i);
                        }
                    }
                    None
                })
                .or_else(|| jit_ic_for_interpreter_cached_method(ihi_entry_idx))
                {
                    Some(i) => ParsedOp::IcMethodCall(i),
                    None => {
                        return Err(format!(
                            "CallMethodIcCached at pc={op_pc}: cached IHI idx {ihi_entry_idx} has no preceding IcMethodResolve match in IC_TABLE"
                        ))
                    }
                }
            }
            Op::Call | Op::TailCall => {
                let n = bc[pc];
                pc += 1;
                let callee_origin = simulate_block_stack(&out)
                    .or_else(|| simulate_current_block_stack_suffix(&out))
                    .and_then(|st| {
                        let callee_depth = st.len().checked_sub(usize::from(n) + 1)?;
                        Some(st[callee_depth])
                    });
                match callee_origin {
                    Some(Origin::StringFromCharCodeCallee) if n == 1 => {
                        ParsedOp::CallStringFromCharCode
                    }
                    Some(Origin::StringFromCharCodeCallee) => {
                        return Err(format!(
                            "Call at pc={op_pc}: String.fromCharCode arity {n} unsupported in LeJIT string-producing concat/writeback substrate"
                        ))
                    }
                    Some(Origin::PendingStringGlobal) if n == 1 && string_ctor_probe_enabled() => {
                        ParsedOp::CallStringCtor
                    }
                    Some(Origin::PendingStringGlobal) => {
                        return Err(format!(
                            "Call at pc={op_pc}: String constructor arity {n} unsupported in LeJIT string-producing concat/writeback substrate"
                        ))
                    }
                    Some(Origin::Local(callee_slot)) => ParsedOp::CallDirect {
                        arity: n,
                        callee_slot,
                    },
                    _ => {
                        return Err(format!(
                            "Call at pc={op_pc}: callee not a direct local callee_origin={callee_origin:?}"
                        ))
                    }
                }
            }
            Op::New => {
                let n = bc[pc];
                pc += 1;
                let callee_origin = simulate_block_stack(&out).and_then(|st| {
                    let callee_depth = st.len().checked_sub(usize::from(n) + 1)?;
                    Some(st[callee_depth])
                });
                match callee_origin {
                    Some(Origin::Local(slot)) => {
                        let ctor_name = locals
                            .get(usize::from(slot))
                            .map(|local| local.name.as_str())
                            .unwrap_or("<unknown-local>");
                        if let Some(candidate) =
                            crate::ic_table::lookup_host_native_constructor_candidate(ctor_name, n)
                        {
                            if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Object
                            ) && n == 1
                            {
                                ParsedOp::HostNativeConstructor1ObjRet {
                                    ctor_slot: slot,
                                    object_kind: candidate.object_kind,
                                }
                            } else {
                                return Err(format!(
                                    "New at pc={op_pc}: host-native constructor candidate '{ctor_name}' arity {n} result {:?} reached unsupported host-native constructor gate",
                                    candidate.result
                                ));
                            }
                        } else {
                            return Err(format!(
                                "New at pc={op_pc}: constructor local '{ctor_name}' arity {n} reached constructor lowering gate"
                            ));
                        }
                    }
                    Some(Origin::HostGlobalObject(object_kind)) => {
                        let ctor_name =
                            crate::ic_table::host_global_object_candidate_name(object_kind);
                        if let Some(candidate) =
                            crate::ic_table::lookup_host_native_constructor_candidate(ctor_name, n)
                        {
                            if matches!(
                                candidate.result,
                                crate::ic_table::HostNativeResultKind::Object
                            ) && n == 1
                            {
                                ParsedOp::HostNativeConstructor1ObjRet {
                                    ctor_slot: 0,
                                    object_kind: candidate.object_kind,
                                }
                            } else {
                                return Err(format!(
                                    "New at pc={op_pc}: host-global constructor candidate '{ctor_name}' arity {n} result {:?} reached unsupported host-native constructor gate",
                                    candidate.result
                                ));
                            }
                        } else {
                            return Err(format!(
                                "New at pc={op_pc}: host-global constructor '{ctor_name}' arity {n} reached constructor lowering gate"
                            ));
                        }
                    }
                    _ => return Err(format!("New at pc={op_pc}: constructor not a direct local")),
                }
            }
            Op::BitOr => ParsedOp::BitOr,
            Op::BitAnd => ParsedOp::BitAnd,
            Op::BitXor => ParsedOp::BitXor,
            Op::BitNot => ParsedOp::BitNot,
            Op::Shl => ParsedOp::Shl,
            Op::Shr => ParsedOp::Shr,
            Op::UShr => match out.last() {
                Some((_, ParsedOp::PushI32(count))) if (0..=31).contains(count) => ParsedOp::UShr,
                _ => {
                    return Err(format!(
                        "UShr at pc={op_pc}: only literal small shift count admitted"
                    ))
                }
            },
            Op::Mod => ParsedOp::Mod,

            Op::ResetLocalCell => {
                let _slot = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                ParsedOp::ResetLocalCellNop
            }
            Op::Add => ParsedOp::Add,
            Op::PushNull => ParsedOp::PushNull,
            Op::Sub => ParsedOp::Sub,
            Op::Neg => ParsedOp::Neg,
            Op::Mul => ParsedOp::Mul,
            Op::Div => ParsedOp::Div,
            Op::ToNumeric => ParsedOp::ToNumeric,
            Op::Inc => ParsedOp::Inc,
            Op::Dec => ParsedOp::Dec,
            Op::Lt => ParsedOp::Lt,
            Op::Le => ParsedOp::Le,
            Op::Gt => ParsedOp::Gt,
            Op::Ge => ParsedOp::Ge,
            Op::Eq => ParsedOp::Eq,
            Op::Ne => ParsedOp::Ne,
            Op::StrictEq => ParsedOp::StrictEq,
            Op::StrictNe => ParsedOp::StrictNe,
            Op::Dup => ParsedOp::Dup,
            Op::Pop => ParsedOp::Pop,
            Op::Jump => {
                let disp = i32::from_le_bytes([bc[pc], bc[pc + 1], bc[pc + 2], bc[pc + 3]]);
                pc += 4;
                let target = (pc as i32 + disp) as usize;
                ParsedOp::Jump(target)
            }
            Op::JumpIfTrue => {
                let disp = i32::from_le_bytes([bc[pc], bc[pc + 1], bc[pc + 2], bc[pc + 3]]);
                pc += 4;
                ParsedOp::JumpIfTrue((pc as i32 + disp) as usize)
            }
            Op::JumpIfFalse => {
                let disp = i32::from_le_bytes([bc[pc], bc[pc + 1], bc[pc + 2], bc[pc + 3]]);
                pc += 4;
                ParsedOp::JumpIfFalse((pc as i32 + disp) as usize)
            }
            Op::ToNumberIndexCall => {
                if env_flag_truthy("CRUFT_LEJIT_REGEXP_SCAN_FULL_ADMIT") {
                    ParsedOp::ToNumberIndexOnObject
                } else {
                    return Err(format!(
                        "ToNumberIndexCall at pc={op_pc}: regexp scan full-admission disabled"
                    ));
                }
            }
            Op::JumpIfFalseKeep => {
                let disp = i32::from_le_bytes([bc[pc], bc[pc + 1], bc[pc + 2], bc[pc + 3]]);
                pc += 4;
                ParsedOp::JumpIfFalseKeep((pc as i32 + disp) as usize)
            }
            Op::JumpIfTrueKeep => {
                let disp = i32::from_le_bytes([bc[pc], bc[pc + 1], bc[pc + 2], bc[pc + 3]]);
                pc += 4;
                ParsedOp::JumpIfTrueKeep((pc as i32 + disp) as usize)
            }
            Op::Return => ParsedOp::Return,
            Op::ReturnUndef => ParsedOp::ReturnUndef,

            Op::GetPropOnObject => {
                let s = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                ParsedOp::GetPropOnObject(s)
            }

            Op::GetIndex => {
                let recv_is_local = simulate_block_stack(&out)
                    .map(|st| {
                        let n = st.len();
                        n >= 2 && matches!(st[n - 2], Origin::Local(_))
                    })
                    .unwrap_or(false);
                if recv_is_local {
                    ParsedOp::GetIndexOnObject
                } else {
                    trace_primitive_string_index_mouth(op_pc, &out, locals);
                    if primitive_string_index_admission_probe_enabled() {
                        if let Some(candidate) = primitive_string_index_cross_block_candidate(&out)
                        {
                            ParsedOp::PrimitiveStringIndexRead {
                                predicate_pc: candidate.predicate_pc,
                                accumulator_slot: candidate.accumulator_slot,
                                receiver_slot: candidate.receiver_slot,
                                index_slot: candidate.index_slot,
                            }
                        } else {
                            let detail = primitive_string_index_bail_detail(&out, bc, pc, locals)
                                .unwrap_or_default();
                            return Err(format!(
                                "GetIndex at pc={op_pc}: receiver not a direct local{detail}"
                            ));
                        }
                    } else {
                        let detail = primitive_string_index_bail_detail(&out, bc, pc, locals)
                            .unwrap_or_default();
                        return Err(format!(
                            "GetIndex at pc={op_pc}: receiver not a direct local{detail}"
                        ));
                    }
                }
            }
            Op::NewObjectWithCapacity => {
                let raw = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                if raw == 1 {
                    ParsedOp::NewObjectLiteral { capacity: raw }
                } else {
                    return Err(format!(
                        "NewObjectWithCapacity at pc={op_pc}: only capacity-1 object literals admitted; raw={raw}"
                    ));
                }
            }
            Op::NewArray => {
                let raw = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;
                if raw == 0 {
                    ParsedOp::NewArrayEmpty
                } else if raw & 0x8000 == 0 && array_literal_probe_enabled() {
                    ParsedOp::NewArrayLiteral { len: raw }
                } else {
                    return Err(format!(
                        "NewArray at pc={op_pc}: only empty non-holey arrays admitted; raw={raw}"
                    ));
                }
            }
            Op::InitIndex => {
                let idx = u32::from_le_bytes([bc[pc], bc[pc + 1], bc[pc + 2], bc[pc + 3]]);
                pc += 4;
                ParsedOp::InitIndex { idx }
            }
            Op::InitPropStaticSlot => {
                let idx = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                let slot = u16::from_le_bytes([bc[pc + 2], bc[pc + 3]]);
                pc += 4;
                let stack = simulate_block_stack(&out).unwrap_or_default();
                let n = stack.len();
                if n >= 2
                    && matches!(stack[n - 2], Origin::FreshObjectLiteral)
                    && matches!(stack[n - 1], Origin::Local(_))
                {
                    ParsedOp::InitPropStaticObject {
                        prop_idx: idx,
                        slot,
                    }
                } else {
                    return Err(format!(
                        "InitPropStaticSlot at pc={op_pc}: only fresh-object object-valued static init admitted"
                    ));
                }
            }

            Op::SetProp => {
                let idx = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                pc += 2;

                let recv_is_local = simulate_block_stack(&out)
                    .map(|st| {
                        let n = st.len();
                        n >= 2 && matches!(st[n - 2], Origin::Local(_))
                    })
                    .unwrap_or(false);
                if recv_is_local {
                    ParsedOp::SetPropOnObject(idx)
                } else {
                    return Err(format!(
                        "SetProp at pc={op_pc}: receiver not a direct local (poisoned or computed receiver)"
                    ));
                }
            }

            Op::SetIndex | Op::SetIndexStrict => {
                let op_name = if matches!(opcode, Op::SetIndexStrict) {
                    "SetIndexStrict"
                } else {
                    "SetIndex"
                };

                let recv_is_local = simulate_block_stack(&out)
                    .map(|st| {
                        let n = st.len();
                        n >= 3 && matches!(st[n - 3], Origin::Local(_))
                    })
                    .unwrap_or(false);
                if recv_is_local {
                    ParsedOp::SetIndexOnObject
                } else {
                    return Err(format!(
                        "{op_name} at pc={op_pc}: receiver not a direct local (poisoned or computed receiver)"
                    ));
                }
            }
            Op::AddI64 => ParsedOp::AddI64,
            Op::SubI64 => ParsedOp::SubI64,
            Op::MulI64 => ParsedOp::MulI64,
            Op::IncI64 => ParsedOp::IncI64,
            Op::DecI64 => ParsedOp::DecI64,
            Op::LtI64 => ParsedOp::LtI64,
            Op::LeI64 => ParsedOp::LeI64,
            Op::GtI64 => ParsedOp::GtI64,
            Op::GeI64 => ParsedOp::GeI64,
            Op::EqI64 => ParsedOp::EqI64,
            Op::NeI64 => ParsedOp::NeI64,
            other => {
                if matches!(
                    other,
                    Op::StoreUpvalue | Op::StoreUpvalueRaw | Op::DeleteUpvalue
                ) {
                    let upvalue_slot = u16::from_le_bytes([bc[pc], bc[pc + 1]]);
                    if matches!(other, Op::StoreUpvalue | Op::StoreUpvalueRaw) {
                        if let Some((arity, callee_slot, callee_name)) =
                            stable_direct_call_return_upvalue_publication_source(&out, locals)
                        {
                            if matches!(other, Op::StoreUpvalue) {
                                let pop_pc = pc + 2;
                                if bc.get(pop_pc).copied() == Some(Op::Pop as u8) {
                                    pc = pop_pc + 1;
                                    match arity {
                                        0 => {
                                            out.push((
                                                op_pc,
                                                ParsedOp::CallDirect0ValueStoreDead {
                                                    callee_slot,
                                                    upvalue_slot,
                                                    resume_pc: pc as u32,
                                                },
                                            ));
                                            continue;
                                        }
                                        4 => {
                                            out.push((
                                                op_pc,
                                                ParsedOp::CallDirect4ValueStoreDead {
                                                    callee_slot,
                                                    upvalue_slot,
                                                    resume_pc: pc as u32,
                                                },
                                            ));
                                            continue;
                                        }
                                        _ => {
                                            return Err(format!(
                                                "StoreUpvalue at pc={op_pc}: stable Call {arity} helper '{callee_name}' local_slot={callee_slot} result publication to captured upvalue_slot={upvalue_slot} requires nonnumeric captured-value writeback ABI"
                                            ));
                                        }
                                    }
                                } else {
                                    return Err(format!(
                                        "StoreUpvalue at pc={op_pc}: stable Call {arity} helper '{callee_name}' local_slot={callee_slot} result publication to captured upvalue_slot={upvalue_slot} requires immediate dead Pop before bounded value-store lowering"
                                    ));
                                }
                            } else {
                                return Err(format!(
                                    "StoreUpvalueRaw at pc={op_pc}: stable Call {arity} helper '{callee_name}' local_slot={callee_slot} result publication to captured upvalue_slot={upvalue_slot} requires nonnumeric captured-value writeback ABI"
                                ));
                            }
                        } else {
                            return Err(format!(
                                "StoreUpvalue at pc={op_pc}: stable Call 0 result publication to captured upvalue_slot={upvalue_slot} requires nonnumeric captured-value writeback ABI"
                            ));
                        }
                    } else {
                        return Err(format!(
                            "first-cut JIT does not support op {:?} at pc={} upvalue_slot={}",
                            other, op_pc, upvalue_slot
                        ));
                    }
                }
                return Err(format!(
                    "first-cut JIT does not support op {:?} at pc={}",
                    other, op_pc
                ));
            }
        };
        out.push((op_pc, parsed));
    }
    if env_flag_enabled_by_default("CRUFT_LEJIT_STRING_COMMA_TERNARY_REWRITE") {
        rewrite_string_comma_ternary(&mut out);
    }
    if string_builder_index_reads_enabled() {
        rewrite_getindex_string_feeding_concat(&mut out);
    }
    rewrite_path_parse_name_fusion(&mut out, constants);
    if scanner_predicate_envelope_rewrite_enabled() {
        rewrite_scanner_ascii_word_predicate(&mut out);
        rewrite_scanner_ascii_ident_predicate_branch(&mut out, locals);
    }
    rewrite_css_identifier_mapped_ternary_store(&mut out);
    rewrite_stable_helper_parent_string_prop_stricteq(&mut out, constants);
    rewrite_stable_helper_parent_object_prop_direct_call_args(&mut out, constants);
    rewrite_stable_helper_parent_prop_predicate_calls(&mut out);
    rewrite_aria_parent_predicate_fusion(&mut out, constants);
    report_site874_token_literal_eq_rewrite_probe(&out, locals);
    report_site874_token_finalization_body_probe(&out, locals);
    report_site874_token_finalization_lowering_prereq_probe(&out, locals);
    report_site874_generated_aggregate_production_contract_probe(&out, locals);
    validate_site874_token_finalization_mouth_gate(&out, locals)?;
    rewrite_site874_generated_aggregate_production(&mut out);
    validate_site874_generated_aggregate_full_loop_gate(&out)?;
    report_aria_inline_consumption_classifier(&out, constants);
    report_aria_inline_emitter_feasibility(&out, constants);
    report_aria_heap_property_load_contract(&out, constants);
    report_aria_entry_table_consumption_contract(&out, constants);
    if let Some(reason) =
        stable_helper_predicate_parent_value_polymorphic_getprop_gap(&out, constants)
    {
        return Err(reason);
    }
    rewrite_stable_helper_predicate_keep_chain(&mut out);
    rewrite_and_chain_short_circuit(&mut out)?;
    rewrite_scanner_predicate_envelope_probe(&mut out);
    rewrite_string_concat_adds(&mut out)?;
    validate_string_concat_writebacks(&out)?;
    report_css_site813_mapped_string_eq_probe(&out, locals);
    report_css_site813_mapped_branch_body_coverage_probe(&out, locals);
    if env_flag_truthy("CRUFT_SBRT_TRACE") {
        for (pc, op) in &out {
            eprintln!("[sbrt-parsed] pc={pc} op={op:?}");
        }
    }
    Ok(out)
}

fn rewrite_path_parse_name_fusion(parsed: &mut Vec<(usize, ParsedOp)>, constants: &ConstantsPool) {
    let mut i = 0usize;
    while i + 1 < parsed.len() {
        let (
            ParsedOp::HostNativeMethod1ObjRet {
                object_kind: crate::ic_table::HostNativeObjectKind::PathParseResult,
                prop_idx: parse_idx,
                ..
            },
            ParsedOp::HostNativeObjectProp {
                object_kind: crate::ic_table::HostNativeObjectKind::PathParseResult,
                prop_idx: name_idx,
            },
        ) = (&parsed[i].1, &parsed[i + 1].1)
        else {
            i += 1;
            continue;
        };
        let parse_key = match constants.get(*parse_idx) {
            Some(Constant::String(s)) => s.as_str(),
            _ => "",
        };
        let name_key = match constants.get(*name_idx) {
            Some(Constant::String(s)) => s.as_str(),
            _ => "",
        };
        if parse_key == "parse" && name_key == "name" {
            parsed[i].1 = ParsedOp::HostNativeMethod1String {
                prop_idx: *parse_idx,
            };
            parsed.remove(i + 1);
        } else {
            i += 1;
        }
    }
}

fn rewrite_string_comma_ternary(parsed: &mut Vec<(usize, ParsedOp)>) {
    let mut i = 0usize;
    while i + 5 < parsed.len() {
        let (left_pc, left_op) = parsed[i];
        let (_, cond_op) = parsed[i + 1];
        let (_, branch_op) = parsed[i + 2];
        let (_, comma_op) = parsed[i + 3];
        let (_, jump_op) = parsed[i + 4];
        let (empty_pc, empty_op) = parsed[i + 5];
        let (
            ParsedOp::LoadLocal(left_slot),
            ParsedOp::LoadLocal(cond_slot),
            ParsedOp::JumpIfFalse(empty_target),
            ParsedOp::PushStringConst {
                ptr: comma_ptr,
                len: 1,
            },
            ParsedOp::Jump(join_target),
            ParsedOp::PushStringConst { len: 0, .. },
        ) = (left_op, cond_op, branch_op, comma_op, jump_op, empty_op)
        else {
            i += 1;
            continue;
        };
        if left_slot != cond_slot || empty_target != empty_pc {
            i += 1;
            continue;
        }
        let Some((join_pc, _)) = parsed.get(i + 6) else {
            break;
        };
        if join_target != *join_pc || !string_const_is(comma_ptr, 1, b",") {
            i += 1;
            continue;
        }
        parsed.splice(
            i..=i + 5,
            [
                (left_pc, ParsedOp::LoadLocal(left_slot)),
                (
                    left_pc + 1,
                    ParsedOp::StringCommaIfTruthy { slot: cond_slot },
                ),
            ],
        );
        i += 2;
    }
}

fn rewrite_css_identifier_mapped_ternary_store(parsed: &mut Vec<(usize, ParsedOp)>) {
    let mut i = 0usize;
    while i + 14 < parsed.len() {
        let [(ident_pc, ParsedOp::LoadLocal(ident_slot_a)), (
            _,
            ParsedOp::PushStringConst {
                ptr: color_ptr,
                len: color_len,
            },
        ), (_, ParsedOp::StrictEq | ParsedOp::Eq), (_, ParsedOp::JumpIfFalse(false_margin_pc)), (
            _,
            c_push @ ParsedOp::PushStringConst {
                ptr: c_ptr,
                len: c_len,
            },
        ), (_, ParsedOp::Jump(join_pc_a)), (margin_pc, ParsedOp::LoadLocal(ident_slot_b)), (
            _,
            ParsedOp::PushStringConst {
                ptr: margin_ptr,
                len: margin_len,
            },
        ), (_, ParsedOp::StrictEq | ParsedOp::Eq), (_, ParsedOp::JumpIfFalse(false_ident_pc)), (
            _,
            m_push @ ParsedOp::PushStringConst {
                ptr: m_ptr,
                len: m_len,
            },
        ), (_, ParsedOp::Jump(join_pc_b)), (ident_fallback_pc, ParsedOp::LoadLocal(ident_slot_c)), (join_pc, ParsedOp::InitLocal(mapped_slot) | ParsedOp::StoreLocal(mapped_slot)), (after_join_pc, _)] =
            parsed[i..i + 15]
        else {
            i += 1;
            continue;
        };

        if ident_slot_a != ident_slot_b
            || ident_slot_a != ident_slot_c
            || false_margin_pc != margin_pc
            || false_ident_pc != ident_fallback_pc
            || join_pc_a != join_pc
            || join_pc_b != join_pc
            || !string_const_is(color_ptr, color_len, b"color")
            || !string_const_is(c_ptr, c_len, b"c")
            || !string_const_is(margin_ptr, margin_len, b"margin")
            || !string_const_is(m_ptr, m_len, b"m")
        {
            i += 1;
            continue;
        }

        parsed.splice(
            i..i + 14,
            [
                (ident_pc, ParsedOp::LoadLocal(ident_slot_a)),
                (
                    ident_pc + 1,
                    ParsedOp::PushStringConst {
                        ptr: color_ptr,
                        len: color_len,
                    },
                ),
                (
                    ident_pc + 2,
                    ParsedOp::StringLocalConstStrictEq {
                        slot: ident_slot_a,
                        ptr: color_ptr,
                        len: color_len,
                    },
                ),
                (ident_pc + 3, ParsedOp::JumpIfFalse(margin_pc)),
                (ident_pc + 4, c_push),
                (ident_pc + 5, ParsedOp::InitLocal(mapped_slot)),
                (ident_pc + 6, ParsedOp::Jump(after_join_pc)),
                (margin_pc, ParsedOp::LoadLocal(ident_slot_a)),
                (
                    margin_pc + 1,
                    ParsedOp::PushStringConst {
                        ptr: margin_ptr,
                        len: margin_len,
                    },
                ),
                (
                    margin_pc + 2,
                    ParsedOp::StringLocalConstStrictEq {
                        slot: ident_slot_a,
                        ptr: margin_ptr,
                        len: margin_len,
                    },
                ),
                (margin_pc + 3, ParsedOp::JumpIfFalse(ident_fallback_pc)),
                (margin_pc + 4, m_push),
                (margin_pc + 5, ParsedOp::InitLocal(mapped_slot)),
                (margin_pc + 6, ParsedOp::Jump(after_join_pc)),
                (ident_fallback_pc, ParsedOp::LoadLocal(ident_slot_a)),
                (ident_fallback_pc + 1, ParsedOp::InitLocal(mapped_slot)),
            ],
        );
        i += 16;
    }
}

fn rewrite_getindex_string_feeding_concat(parsed: &mut [(usize, ParsedOp)]) {
    for i in 0..parsed.len().saturating_sub(2) {
        if matches!(parsed[i].1, ParsedOp::GetIndexOnObject)
            && matches!(parsed[i + 1].1, ParsedOp::PushStringConst { .. })
            && matches!(parsed[i + 2].1, ParsedOp::Add)
        {
            parsed[i].1 = ParsedOp::GetIndexStringOnObject;
        }
    }

    for i in 0..parsed.len().saturating_sub(1) {
        if matches!(parsed[i].1, ParsedOp::GetIndexOnObject)
            && matches!(parsed[i + 1].1, ParsedOp::IcMethodCall(idx)
                if crate::ic_table::IC_TABLE.get(idx as usize).is_some_and(|e| e.key == "exec"))
        {
            parsed[i].1 = ParsedOp::GetIndexStringOnObject;
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PrimitiveStringIndexCrossBlockCandidate {
    predicate_pc: usize,
    accumulator_slot: u16,
    receiver_slot: u16,
    index_slot: u16,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PrimitiveStringIndexAdmissionGap {
    MissingReceiverPrimitiveStringDomain { receiver_slot: u16, index_slot: u16 },
    MissingUtf16Materialization { receiver_slot: u16, index_slot: u16 },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ScannerPredicateKeepChain {
    first_keep_pc: usize,
    keep_count: usize,
    tested_slot: u16,
    materialized_slot: Option<u16>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ScannerPredicateMaterializationContract {
    first_keep_pc: usize,
    tested_slot: u16,
    materialized_slot: u16,
    true_keep_count: usize,
    false_keep_count: usize,
    requires_synthetic_boolean: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct StableHelperPredicateKeepChain {
    first_keep_pc: usize,
    keep_count: usize,
    direct_call_count: usize,
    tail_call_count: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StableHelperValueKeepChain {
    first_keep_pc: usize,
    keep_count: usize,
    direct_call_count: usize,
    return_pc: usize,
    candidate_materialization_slots: Vec<u16>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct JumpIfKeepKeptStackCandidate {
    keep_pc: usize,
    keep_kind: &'static str,
    keep_target_pc: usize,
    pop_pc: Option<usize>,
    target_op: Option<&'static str>,
    kept_origin: Origin,
    kept_locals: Vec<u16>,
    kept_integer_rooted: bool,
    incoming_to_keep_target: usize,
    incoming_to_pop: usize,
    materialized_slot: Option<u16>,
    next_plain_branch_pc: Option<usize>,
}

fn jumpifkeep_refusal_detail(parsed: &[(usize, ParsedOp)], start_idx: usize) -> String {
    let scanner_detail = scanner_predicate_keep_chain_detail(parsed, start_idx).unwrap_or_default();
    let Some(candidate) = jumpifkeep_kept_stack_candidate(parsed, start_idx) else {
        return scanner_detail;
    };
    format!("{scanner_detail} jumpifkeep-kept-stack {{ keep_pc={}, keep_kind={}, keep_target_pc={}, pop_pc={:?}, target_op={:?}, kept_origin={:?}, kept_locals={:?}, kept_integer_rooted={}, incoming_to_keep_target={}, incoming_to_pop={}, materialized_slot={:?}, next_plain_branch_pc={:?} }}",
        candidate.keep_pc,
        candidate.keep_kind,
        candidate.keep_target_pc,
        candidate.pop_pc,
        candidate.target_op,
        candidate.kept_origin,
        candidate.kept_locals,
        candidate.kept_integer_rooted,
        candidate.incoming_to_keep_target,
        candidate.incoming_to_pop,
        candidate.materialized_slot,
        candidate.next_plain_branch_pc
    )
}

fn jumpifx_nonempty_stack_detail(
    parsed: &[(usize, ParsedOp)],
    branch_idx: usize,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> String {
    let Some((branch_pc, branch_op)) = parsed.get(branch_idx) else {
        return String::new();
    };
    let expr_stack = simulate_expr_stack(&parsed[..branch_idx]).unwrap_or_default();
    let cond = expr_stack
        .last()
        .map(|expr| describe_expr_origin_with_locals(expr, locals))
        .unwrap_or_else(|| "<missing-cond>".to_string());
    let residual = expr_stack
        .iter()
        .take(expr_stack.len().saturating_sub(1))
        .map(|expr| describe_expr_origin_with_locals(expr, locals))
        .collect::<Vec<_>>()
        .join(" | ");
    let recent_start = branch_idx.saturating_sub(12);
    let recent_ops = parsed[recent_start..=branch_idx]
        .iter()
        .map(|(pc, op)| describe_parsed_op_with_locals(*pc, op, locals))
        .collect::<Vec<_>>()
        .join("; ");
    format!(
        " jumpifx-stack {{ branch_pc={}, branch_op={:?}, cond={}, residual_depth={}, residual=[{}], recent_ops=[{}] }}",
        branch_pc,
        branch_op,
        cond,
        expr_stack.len().saturating_sub(1),
        residual,
        recent_ops
    )
}

fn parsed_op_kind(op: ParsedOp) -> &'static str {
    match op {
        ParsedOp::Jump(_) => "Jump",
        ParsedOp::JumpIfTrue(_) => "JumpIfTrue",
        ParsedOp::JumpIfFalse(_) => "JumpIfFalse",
        ParsedOp::JumpIfTrueKeep(_) => "JumpIfTrueKeep",
        ParsedOp::JumpIfFalseKeep(_) => "JumpIfFalseKeep",
        ParsedOp::Pop => "Pop",
        ParsedOp::InitLocal(_) => "InitLocal",
        ParsedOp::StoreLocal(_) => "StoreLocal",
        ParsedOp::Return => "Return",
        ParsedOp::ReturnUndef => "ReturnUndef",
        _ => "Other",
    }
}

fn jumpifkeep_target(op: ParsedOp) -> Option<usize> {
    match op {
        ParsedOp::JumpIfFalseKeep(target) | ParsedOp::JumpIfTrueKeep(target) => Some(target),
        _ => None,
    }
}

fn jump_target(op: ParsedOp) -> Option<usize> {
    match op {
        ParsedOp::Jump(target)
        | ParsedOp::JumpIfTrue(target)
        | ParsedOp::JumpIfFalse(target)
        | ParsedOp::JumpIfFalseKeep(target)
        | ParsedOp::JumpIfTrueKeep(target) => Some(target),
        _ => None,
    }
}

fn jumpifkeep_kept_stack_candidate(
    parsed: &[(usize, ParsedOp)],
    start_idx: usize,
) -> Option<JumpIfKeepKeptStackCandidate> {
    let (keep_pc, keep_op) = parsed.get(start_idx).copied()?;
    let keep_target_pc = jumpifkeep_target(keep_op)?;
    let keep_kind = match keep_op {
        ParsedOp::JumpIfFalseKeep(_) => "JumpIfFalseKeep",
        ParsedOp::JumpIfTrueKeep(_) => "JumpIfTrueKeep",
        _ => return None,
    };
    let expr_stack = simulate_expr_stack(&parsed[..start_idx])?;
    let kept = expr_stack.last()?.clone();
    let pop_pc = parsed
        .get(start_idx + 1)
        .and_then(|(pc, op)| matches!(op, ParsedOp::Pop).then_some(*pc));
    let target_op = parsed
        .iter()
        .find(|(pc, _)| *pc == keep_target_pc)
        .map(|(_, op)| parsed_op_kind(*op));
    let incoming_to_keep_target = parsed
        .iter()
        .enumerate()
        .filter(|(idx, (_, op))| *idx != start_idx && jump_target(*op) == Some(keep_target_pc))
        .count();
    let incoming_to_pop = pop_pc
        .map(|pop_pc| {
            parsed
                .iter()
                .enumerate()
                .filter(|(idx, (_, op))| *idx != start_idx && jump_target(*op) == Some(pop_pc))
                .count()
        })
        .unwrap_or(0);
    let mut materialized_slot = None;
    let mut next_plain_branch_pc = None;
    for (pc, op) in parsed.iter().skip(start_idx + 1) {
        match *op {
            ParsedOp::InitLocal(slot) | ParsedOp::StoreLocal(slot) => {
                materialized_slot = Some(slot);
                break;
            }
            ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_) => {
                next_plain_branch_pc = Some(*pc);
                break;
            }
            ParsedOp::Return | ParsedOp::ReturnUndef | ParsedOp::Jump(_) => break,
            _ => {}
        }
    }
    Some(JumpIfKeepKeptStackCandidate {
        keep_pc,
        keep_kind,
        keep_target_pc,
        pop_pc,
        target_op,
        kept_origin: kept.origin,
        kept_locals: kept.locals,
        kept_integer_rooted: kept.integer_rooted,
        incoming_to_keep_target,
        incoming_to_pop,
        materialized_slot,
        next_plain_branch_pc,
    })
}

fn scanner_predicate_keep_chain(
    parsed: &[(usize, ParsedOp)],
    start_idx: usize,
) -> Option<ScannerPredicateKeepChain> {
    let (first_keep_pc, first_keep) = parsed.get(start_idx)?;
    if !matches!(
        first_keep,
        ParsedOp::JumpIfFalseKeep(_) | ParsedOp::JumpIfTrueKeep(_)
    ) {
        return None;
    }
    let tested_slot = (0..start_idx).rev().find_map(|idx| match parsed[idx].1 {
        ParsedOp::LoadLocal(slot) => Some(slot),
        ParsedOp::PushI32(_)
        | ParsedOp::StrictEq
        | ParsedOp::Ge
        | ParsedOp::Le
        | ParsedOp::Lt
        | ParsedOp::Gt
        | ParsedOp::Eq
        | ParsedOp::Ne
        | ParsedOp::StrictNe => None,
        _ => None,
    })?;

    let mut keep_count = 0usize;
    let mut materialized_slot = None;
    for (_, op) in parsed.iter().skip(start_idx) {
        match *op {
            ParsedOp::JumpIfFalseKeep(_) | ParsedOp::JumpIfTrueKeep(_) => {
                keep_count += 1;
            }
            ParsedOp::InitLocal(slot) | ParsedOp::StoreLocal(slot) => {
                materialized_slot = Some(slot);
                break;
            }
            ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_) | ParsedOp::GetIndexOnObject => {
                break;
            }
            _ => {}
        }
    }
    if keep_count < 2 {
        return None;
    }
    Some(ScannerPredicateKeepChain {
        first_keep_pc: *first_keep_pc,
        keep_count,
        tested_slot,
        materialized_slot,
    })
}

fn scanner_predicate_materialization_contract(
    parsed: &[(usize, ParsedOp)],
    start_idx: usize,
) -> Option<ScannerPredicateMaterializationContract> {
    let chain = scanner_predicate_keep_chain(parsed, start_idx)?;
    let materialized_slot = chain.materialized_slot?;
    let mut true_keep_count = 0usize;
    let mut false_keep_count = 0usize;
    for (_, op) in parsed.iter().skip(start_idx) {
        match *op {
            ParsedOp::JumpIfTrueKeep(_) => true_keep_count += 1,
            ParsedOp::JumpIfFalseKeep(_) => false_keep_count += 1,
            ParsedOp::InitLocal(slot) | ParsedOp::StoreLocal(slot) if slot == materialized_slot => {
                break;
            }
            ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_) | ParsedOp::GetIndexOnObject => {
                break;
            }
            _ => {}
        }
    }
    if true_keep_count == 0 || false_keep_count == 0 {
        return None;
    }
    Some(ScannerPredicateMaterializationContract {
        first_keep_pc: chain.first_keep_pc,
        tested_slot: chain.tested_slot,
        materialized_slot,
        true_keep_count,
        false_keep_count,
        requires_synthetic_boolean: true,
    })
}

fn scanner_predicate_materialization_contracts(
    parsed: &[(usize, ParsedOp)],
    start_idx: usize,
) -> Vec<ScannerPredicateMaterializationContract> {
    let Some(root) = scanner_predicate_materialization_contract(parsed, start_idx) else {
        return Vec::new();
    };
    let mut contracts = Vec::new();
    for idx in start_idx..parsed.len() {
        let Some(contract) = scanner_predicate_materialization_contract(parsed, idx) else {
            continue;
        };
        if contract.tested_slot != root.tested_slot
            || contract.materialized_slot != root.materialized_slot
        {
            continue;
        }
        contracts.push(contract);
    }
    contracts
}

fn scanner_predicate_keep_chain_detail(
    parsed: &[(usize, ParsedOp)],
    start_idx: usize,
) -> Option<String> {
    let chain = scanner_predicate_keep_chain(parsed, start_idx)?;
    let contract = scanner_predicate_materialization_contract(parsed, start_idx);
    let stable_helper_chain = stable_helper_predicate_keep_chain(parsed, start_idx);
    if env_flag_truthy("CRUFT_LEJIT_SCANNER_PREDICATE_TRACE") {
        eprintln!(
            "[scanner-predicate-keep-chain] first_keep_pc={} keep_count={} tested_slot={} materialized_slot={:?} materialization_contract={:?} stable_helper_chain={:?}",
            chain.first_keep_pc,
            chain.keep_count,
            chain.tested_slot,
            chain.materialized_slot,
            contract,
            stable_helper_chain
        );
    }
    if env_flag_truthy("CRUFT_LEJIT_SCANNER_PREDICATE_ENVELOPE_PROBE") {
        for contract in scanner_predicate_materialization_contracts(parsed, start_idx) {
            eprintln!(
                "[scanner-predicate-envelope-probe] first_keep_pc={} true_keep_count={} false_keep_count={} tested_slot={} materialized_slot={} requires_synthetic_boolean={}",
                contract.first_keep_pc,
                contract.true_keep_count,
                contract.false_keep_count,
                contract.tested_slot,
                contract.materialized_slot,
                contract.requires_synthetic_boolean
            );
        }
    }
    Some(format!(
        " scanner-predicate-keep-chain {{ first_keep_pc={}, keep_count={}, tested_slot={}, materialized_slot={:?}, materialization_contract={:?}, stable_helper_chain={:?}, stable_helper_value_chain={:?} }}",
        chain.first_keep_pc,
        chain.keep_count,
        chain.tested_slot,
        chain.materialized_slot,
        contract,
        stable_helper_chain,
        stable_helper_value_keep_chain(parsed, start_idx)
    ))
}

fn stable_helper_value_keep_chain(
    parsed: &[(usize, ParsedOp)],
    start_idx: usize,
) -> Option<StableHelperValueKeepChain> {
    let (first_keep_pc, first_keep) = parsed.get(start_idx)?;
    if !matches!(first_keep, ParsedOp::JumpIfTrueKeep(_)) {
        return None;
    }
    let mut keep_count = 0usize;
    let mut direct_call_count = 0usize;
    let mut candidate_materialization_slots = Vec::new();
    let mut return_pc = None;

    if let Some(callee_slot) = (0..start_idx)
        .rev()
        .find_map(|idx| direct_call_callee_slot(parsed[idx].1))
    {
        direct_call_count += 1;
        push_unique_sorted(&mut candidate_materialization_slots, callee_slot);
    }

    let mut i = start_idx;
    while i < parsed.len() {
        match parsed[i].1 {
            op if direct_call_callee_slot(op).is_some() => {
                let callee_slot = direct_call_callee_slot(op)?;
                direct_call_count += 1;
                push_unique_sorted(&mut candidate_materialization_slots, callee_slot);
            }
            ParsedOp::JumpIfTrueKeep(_) => {
                keep_count += 1;
            }
            ParsedOp::JumpIfFalseKeep(_) => return None,
            ParsedOp::Return => {
                if return_pc.is_none() {
                    return_pc = Some(parsed[i].0);
                }
                break;
            }
            ParsedOp::ReturnUndef => break,
            _ => {}
        }
        i += 1;
    }
    if keep_count < 2 || direct_call_count < keep_count {
        return None;
    }
    Some(StableHelperValueKeepChain {
        first_keep_pc: *first_keep_pc,
        keep_count,
        direct_call_count,
        return_pc: return_pc?,
        candidate_materialization_slots,
    })
}

fn rewrite_stable_helper_value_keep_chain(parsed: &mut Vec<(usize, ParsedOp)>) {
    let Some(first_keep_idx) =
        (0..parsed.len()).find(|idx| stable_helper_value_keep_chain(parsed, *idx).is_some())
    else {
        return;
    };
    let Some(first_call_idx) = (0..first_keep_idx)
        .rev()
        .find(|idx| direct_call_callee_slot(parsed[*idx].1).is_some())
    else {
        return;
    };
    let Some(return_idx) = parsed[first_keep_idx..]
        .iter()
        .position(|(_, op)| matches!(op, ParsedOp::Return))
        .map(|rel| first_keep_idx + rel)
    else {
        return;
    };
    let return_undef = parsed
        .get(return_idx + 1)
        .filter(|(_, op)| matches!(op, ParsedOp::ReturnUndef))
        .copied();
    let Some(first_expr_idx) = first_call_idx.checked_sub(2) else {
        return;
    };
    let chain = &parsed[first_expr_idx..=return_idx];
    let [load0, load0_arg0, (_, call0 @ ParsedOp::CallDirect { arity: 1, .. }), _, (_, ParsedOp::Pop), preload1, load1, load1_arg0, load1_arg1, (_, call1 @ ParsedOp::CallDirect { arity: 2, .. }), _, (_, ParsedOp::Pop), preload2, load2, load2_arg0, load2_arg1, (_, call2 @ ParsedOp::CallDirect { arity: 2, .. }), _, (_, ParsedOp::Pop), preload3, load3, (_, call3 @ ParsedOp::CallDirect { arity: 0, .. }), (_, ParsedOp::Return)] =
        chain
    else {
        return;
    };
    let (
        ParsedOp::CallDirect {
            callee_slot: slot0, ..
        },
        ParsedOp::CallDirect {
            callee_slot: slot1, ..
        },
        ParsedOp::CallDirect {
            callee_slot: slot2, ..
        },
        ParsedOp::CallDirect {
            callee_slot: slot3, ..
        },
    ) = (*call0, *call1, *call2, *call3)
    else {
        return;
    };
    let base_pc = parsed[first_expr_idx].0;
    let next1_pc = base_pc + 20;
    let next2_pc = base_pc + 40;
    let next3_pc = base_pc + 60;
    let mut rewritten = vec![
        (base_pc, load0.1),
        (base_pc + 1, load0_arg0.1),
        (base_pc + 2, *call0),
        (base_pc + 3, ParsedOp::StoreLocal(slot0)),
        (base_pc + 4, ParsedOp::LoadLocal(slot0)),
        (base_pc + 5, ParsedOp::JumpIfFalse(next1_pc)),
        (base_pc + 6, ParsedOp::LoadLocal(slot0)),
        (base_pc + 7, ParsedOp::Return),
        (next1_pc, preload1.1),
        (next1_pc + 1, load1.1),
        (next1_pc + 2, load1_arg0.1),
        (next1_pc + 3, load1_arg1.1),
        (next1_pc + 4, *call1),
        (next1_pc + 5, ParsedOp::StoreLocal(slot1)),
        (next1_pc + 6, ParsedOp::LoadLocal(slot1)),
        (next1_pc + 7, ParsedOp::JumpIfFalse(next2_pc)),
        (next1_pc + 8, ParsedOp::LoadLocal(slot1)),
        (next1_pc + 9, ParsedOp::Return),
        (next2_pc, preload2.1),
        (next2_pc + 1, load2.1),
        (next2_pc + 2, load2_arg0.1),
        (next2_pc + 3, load2_arg1.1),
        (next2_pc + 4, *call2),
        (next2_pc + 5, ParsedOp::StoreLocal(slot2)),
        (next2_pc + 6, ParsedOp::LoadLocal(slot2)),
        (next2_pc + 7, ParsedOp::JumpIfFalse(next3_pc)),
        (next2_pc + 8, ParsedOp::LoadLocal(slot2)),
        (next2_pc + 9, ParsedOp::Return),
        (next3_pc, preload3.1),
        (next3_pc + 1, load3.1),
        (next3_pc + 2, *call3),
        (next3_pc + 3, ParsedOp::StoreLocal(slot3)),
        (next3_pc + 4, ParsedOp::LoadLocal(slot3)),
        (next3_pc + 5, ParsedOp::Return),
    ];
    if let Some((_, op)) = return_undef {
        rewritten.push((next3_pc + 6, op));
    }
    parsed.splice(
        first_expr_idx..=return_idx + usize::from(return_undef.is_some()),
        rewritten,
    );
}

fn rewrite_value_jump_to_return(parsed: &mut Vec<(usize, ParsedOp)>) {
    let return_pcs: std::collections::HashSet<usize> = parsed
        .iter()
        .filter_map(|(pc, op)| matches!(op, ParsedOp::Return).then_some(*pc))
        .collect();
    for idx in 0..parsed.len() {
        let ParsedOp::Jump(target) = parsed[idx].1 else {
            continue;
        };
        if !return_pcs.contains(&target) {
            continue;
        }
        let Some(stack) = simulate_block_stack(&parsed[..idx]) else {
            continue;
        };
        if stack.len() == 1 {
            parsed[idx].1 = ParsedOp::Return;
        }
    }
}

fn rewrite_interop_require_default_keep_chain(parsed: &mut Vec<(usize, ParsedOp)>) {
    let mut idx = 0usize;
    while idx + 6 < parsed.len() {
        let (
            ParsedOp::LoadLocal(test_slot),
            ParsedOp::JumpIfFalseKeep(fallback_pc),
            ParsedOp::Pop,
            ParsedOp::LoadLocal(prop_slot),
            ParsedOp::GetPropOnObject(_) | ParsedOp::GetPropTruthyOnObject(_),
            ParsedOp::JumpIfFalse(prop_fallback_pc),
            ParsedOp::LoadLocal(return_slot),
        ) = (
            parsed[idx].1,
            parsed[idx + 1].1,
            parsed[idx + 2].1,
            parsed[idx + 3].1,
            parsed[idx + 4].1,
            parsed[idx + 5].1,
            parsed[idx + 6].1,
        )
        else {
            idx += 1;
            continue;
        };
        if test_slot == prop_slot && prop_slot == return_slot && fallback_pc == prop_fallback_pc {
            parsed[idx + 1].1 = ParsedOp::JumpIfFalse(fallback_pc);
            parsed.remove(idx + 2);
            continue;
        }
        idx += 1;
    }
}

fn rewrite_getprop_truthy_branch_domain(parsed: &mut Vec<(usize, ParsedOp)>) {
    for idx in 0..parsed.len().saturating_sub(1) {
        let ParsedOp::GetPropOnObject(prop_idx) = parsed[idx].1 else {
            continue;
        };
        if matches!(
            parsed[idx + 1].1,
            ParsedOp::JumpIfTrue(_) | ParsedOp::JumpIfFalse(_)
        ) {
            parsed[idx].1 = ParsedOp::GetPropTruthyOnObject(prop_idx);
        }
    }
}

fn direct_call_callee_slot(op: ParsedOp) -> Option<u16> {
    match op {
        ParsedOp::CallDirect {
            callee_slot,
            arity: 0 | 1 | 2,
        }
        | ParsedOp::CallDirectLeaf {
            callee_slot,
            leaf: _,
        }
        | ParsedOp::CallDirectLeafConstI32 { callee_slot, .. }
        | ParsedOp::CallDirectLeaf2 {
            callee_slot,
            leaf: _,
        }
        | ParsedOp::CallDirectLeaf2ConstI32 { callee_slot, .. } => Some(callee_slot),
        _ => None,
    }
}

fn stable_helper_predicate_keep_chain(
    parsed: &[(usize, ParsedOp)],
    start_idx: usize,
) -> Option<StableHelperPredicateKeepChain> {
    let chain = scanner_predicate_keep_chain(parsed, start_idx).or_else(|| {
        stable_helper_predicate_fused_keep_chain(parsed, start_idx).map(
            |(first_keep_pc, keep_count)| ScannerPredicateKeepChain {
                first_keep_pc,
                keep_count,
                tested_slot: 0,
                materialized_slot: None,
            },
        )
    })?;
    if chain.materialized_slot.is_some() {
        return None;
    }
    let mut direct_call_count = 0usize;
    let mut tail_call_count = 0usize;
    for (_, op) in parsed.iter().skip(start_idx) {
        match *op {
            ParsedOp::CallDirect { .. }
            | ParsedOp::CallDirect2PropPredicate { .. }
            | ParsedOp::AriaParentPredicateFusion { .. }
            | ParsedOp::CallDirectLeaf { .. }
            | ParsedOp::CallDirectLeafConstI32 { .. }
            | ParsedOp::CallDirectLeaf2 { .. }
            | ParsedOp::CallDirectLeaf2ConstI32 { .. }
            | ParsedOp::CallDirectLeaf3 { .. } => direct_call_count += 1,
            ParsedOp::Return | ParsedOp::ReturnUndef => break,
            _ => {}
        }
    }
    if direct_call_count == 0 {
        return None;
    }
    if matches!(
        parsed
            .iter()
            .skip(start_idx)
            .rev()
            .find(|(_, op)| !matches!(op, ParsedOp::Return | ParsedOp::ReturnUndef))
            .map(|(_, op)| op),
        Some(
            ParsedOp::CallDirect { .. }
                | ParsedOp::CallDirect2PropPredicate { .. }
                | ParsedOp::AriaParentPredicateFusion { .. }
                | ParsedOp::CallDirectLeaf { .. }
                | ParsedOp::CallDirectLeafConstI32 { .. }
                | ParsedOp::CallDirectLeaf2 { .. }
                | ParsedOp::CallDirectLeaf2ConstI32 { .. }
                | ParsedOp::CallDirectLeaf3 { .. }
        )
    ) {
        tail_call_count = 1;
    }
    Some(StableHelperPredicateKeepChain {
        first_keep_pc: chain.first_keep_pc,
        keep_count: chain.keep_count,
        direct_call_count,
        tail_call_count,
    })
}

fn stable_helper_predicate_fused_keep_chain(
    parsed: &[(usize, ParsedOp)],
    start_idx: usize,
) -> Option<(usize, usize)> {
    let (first_keep_pc, first_keep) = parsed.get(start_idx)?;
    if !matches!(
        first_keep,
        ParsedOp::JumpIfFalseKeep(_) | ParsedOp::JumpIfTrueKeep(_)
    ) {
        return None;
    }
    if !matches!(
        start_idx.checked_sub(1).and_then(|idx| parsed.get(idx)),
        Some((_, ParsedOp::StringPropStrictEq { .. }))
    ) {
        return None;
    }
    let mut keep_count = 0usize;
    for (_, op) in parsed.iter().skip(start_idx) {
        match *op {
            ParsedOp::JumpIfFalseKeep(_) | ParsedOp::JumpIfTrueKeep(_) => {
                keep_count += 1;
            }
            ParsedOp::InitLocal(_) | ParsedOp::StoreLocal(_) => return None,
            ParsedOp::Return | ParsedOp::ReturnUndef => break,
            _ => {}
        }
    }
    (keep_count >= 2).then_some((*first_keep_pc, keep_count))
}

fn stable_helper_predicate_parent_value_polymorphic_getprop_gap(
    parsed: &[(usize, ParsedOp)],
    constants: &ConstantsPool,
) -> Option<String> {
    let start_idx =
        (0..parsed.len()).find(|idx| stable_helper_predicate_keep_chain(parsed, *idx).is_some())?;
    let chain = stable_helper_predicate_keep_chain(parsed, start_idx)?;
    let mut first_gap: Option<(usize, String)> = None;
    let mut string_eq_props: Vec<String> = Vec::new();
    let mut helper_arg_props: Vec<String> = Vec::new();
    for (idx, (pc, op)) in parsed.iter().enumerate() {
        match *op {
            ParsedOp::GetPropOnObject(prop_idx) => {
                let prop = match constants.get(prop_idx) {
                    Some(Constant::String(s)) => s.clone(),
                    _ => "<non-string-prop>".to_string(),
                };
                if prop != "length" {
                    if first_gap.is_none() {
                        first_gap = Some((*pc, prop.clone()));
                    }
                    if stable_helper_getprop_feeds_immediate_equality(parsed, idx, prop_idx) {
                        push_unique_string(&mut string_eq_props, prop);
                    } else if stable_helper_getprop_feeds_direct_helper_arg(parsed, idx) {
                        push_unique_string(&mut helper_arg_props, prop);
                    }
                }
            }
            ParsedOp::Return | ParsedOp::ReturnUndef => break,
            _ => {}
        }
    }
    first_gap.map(|(pc, prop)| {
        let transport = stable_helper_value_transport_summary(&string_eq_props, &helper_arg_props);
        format!(
            "stable-helper predicate parent requires value-polymorphic GetProp at pc={pc} prop={prop:?} transport={transport} chain={chain:?}"
        )
    })
}

fn rewrite_stable_helper_parent_string_prop_stricteq(
    parsed: &mut Vec<(usize, ParsedOp)>,
    constants: &ConstantsPool,
) {
    if !(0..parsed.len()).any(|idx| stable_helper_predicate_keep_chain(parsed, idx).is_some()) {
        return;
    }
    let mut i = 0usize;
    while i + 4 < parsed.len() {
        let Some((pc, lhs_slot, rhs_slot, prop_idx)) = (match &parsed[i..i + 5] {
            [(pc, ParsedOp::LoadLocal(lhs_slot)), (_, ParsedOp::GetPropOnObject(lhs_prop_idx)), (_, ParsedOp::LoadLocal(rhs_slot)), (_, ParsedOp::GetPropOnObject(rhs_prop_idx)), (_, ParsedOp::StrictEq | ParsedOp::Eq)]
                if lhs_prop_idx == rhs_prop_idx
                    && !constant_string_is(constants, *lhs_prop_idx, "length") =>
            {
                Some((*pc, *lhs_slot, *rhs_slot, *lhs_prop_idx))
            }
            _ => None,
        }) else {
            i += 1;
            continue;
        };
        parsed.splice(
            i..i + 5,
            [(
                pc,
                ParsedOp::StringPropStrictEq {
                    lhs_slot,
                    rhs_slot,
                    prop_idx,
                },
            )],
        );
        i += 1;
    }
}

fn rewrite_stable_helper_parent_object_prop_direct_call_args(
    parsed: &mut [(usize, ParsedOp)],
    constants: &ConstantsPool,
) {
    if !(0..parsed.len()).any(|idx| stable_helper_predicate_keep_chain(parsed, idx).is_some()) {
        return;
    }
    for idx in 0..parsed.len() {
        let ParsedOp::GetPropOnObject(prop_idx) = parsed[idx].1 else {
            continue;
        };
        if constant_string_is(constants, prop_idx, "length") {
            continue;
        }
        if !matches!(
            idx.checked_sub(1).and_then(|prev| parsed.get(prev)),
            Some((_, ParsedOp::LoadLocal(_)))
        ) {
            continue;
        }
        if !stable_helper_getprop_feeds_direct_helper_arg(parsed, idx) {
            continue;
        }
        parsed[idx].1 = ParsedOp::StableHelperObjectPropArg { prop_idx };
    }
}

fn rewrite_stable_helper_parent_prop_predicate_calls(parsed: &mut Vec<(usize, ParsedOp)>) {
    if !(0..parsed.len()).any(|idx| stable_helper_predicate_keep_chain(parsed, idx).is_some()) {
        return;
    }
    let mut i = 0usize;
    while i + 5 < parsed.len() {
        let Some((pc, callee_slot, lhs_slot, rhs_slot, prop_idx)) = (match &parsed[i..i + 6] {
            [(pc, ParsedOp::LoadLocal(callee_slot)), (_, ParsedOp::LoadLocal(lhs_slot)), (
                _,
                ParsedOp::StableHelperObjectPropArg {
                    prop_idx: lhs_prop_idx,
                },
            ), (_, ParsedOp::LoadLocal(rhs_slot)), (
                _,
                ParsedOp::StableHelperObjectPropArg {
                    prop_idx: rhs_prop_idx,
                },
            ), (
                _,
                ParsedOp::CallDirectLeaf2 {
                    callee_slot: call_callee_slot,
                    leaf: DirectCallLeaf::PredicateObjObj,
                }
                | ParsedOp::CallDirect {
                    arity: 2,
                    callee_slot: call_callee_slot,
                },
            )] if lhs_prop_idx == rhs_prop_idx && callee_slot == call_callee_slot => {
                Some((*pc, *callee_slot, *lhs_slot, *rhs_slot, *lhs_prop_idx))
            }
            _ => None,
        }) else {
            i += 1;
            continue;
        };
        parsed.splice(
            i..i + 6,
            [(
                pc,
                ParsedOp::CallDirect2PropPredicate {
                    callee_slot,
                    lhs_slot,
                    rhs_slot,
                    prop_idx,
                },
            )],
        );
        i += 1;
    }
}

fn rewrite_aria_parent_predicate_fusion(
    parsed: &mut Vec<(usize, ParsedOp)>,
    _constants: &ConstantsPool,
) {
    let mut i = 0usize;
    while i + 7 < parsed.len() {
        enum AriaFusionShape {
            KeepPop {
                pc: usize,
                lhs_slot: u16,
                rhs_slot: u16,
                name_prop_idx: u16,
                constraints_callee_slot: u16,
                constraints_prop_idx: u16,
                attributes_callee_slot: u16,
                attributes_prop_idx: u16,
            },
            StablePreload {
                pc: usize,
                constraints_preload: (usize, ParsedOp),
                attributes_preload: (usize, ParsedOp),
                lhs_slot: u16,
                rhs_slot: u16,
                name_prop_idx: u16,
                constraints_callee_slot: u16,
                constraints_prop_idx: u16,
                attributes_callee_slot: u16,
                attributes_prop_idx: u16,
            },
            KeepPopStablePreload {
                pc: usize,
                constraints_preload: (usize, ParsedOp),
                attributes_preload: (usize, ParsedOp),
                lhs_slot: u16,
                rhs_slot: u16,
                name_prop_idx: u16,
                constraints_callee_slot: u16,
                constraints_prop_idx: u16,
                attributes_callee_slot: u16,
                attributes_prop_idx: u16,
            },
        }
        let Some(shape) = (if i + 9 < parsed.len() {
            match &parsed[i..i + 10] {
                [(
                    pc,
                    ParsedOp::StringPropStrictEq {
                        lhs_slot,
                        rhs_slot,
                        prop_idx: name_prop_idx,
                    },
                ), (_, ParsedOp::JumpIfFalseKeep(_)), (_, ParsedOp::Pop), constraints_preload @ (
                    _,
                    ParsedOp::StableCalleePreload {
                        local_slot: constraints_preload_slot,
                        ..
                    },
                ), (
                    _,
                    ParsedOp::CallDirect2PropPredicate {
                        callee_slot: constraints_callee_slot,
                        lhs_slot: constraints_lhs_slot,
                        rhs_slot: constraints_rhs_slot,
                        prop_idx: constraints_prop_idx,
                    },
                ), (_, ParsedOp::JumpIfFalseKeep(_)), (_, ParsedOp::Pop), attributes_preload @ (
                    _,
                    ParsedOp::StableCalleePreload {
                        local_slot: attributes_preload_slot,
                        ..
                    },
                ), (
                    _,
                    ParsedOp::CallDirect2PropPredicate {
                        callee_slot: attributes_callee_slot,
                        lhs_slot: attributes_lhs_slot,
                        rhs_slot: attributes_rhs_slot,
                        prop_idx: attributes_prop_idx,
                    },
                ), (_, ParsedOp::Return)]
                    if constraints_preload_slot == constraints_callee_slot
                        && attributes_preload_slot == attributes_callee_slot
                        && lhs_slot == constraints_lhs_slot
                        && lhs_slot == attributes_lhs_slot
                        && rhs_slot == constraints_rhs_slot
                        && rhs_slot == attributes_rhs_slot =>
                {
                    Some(AriaFusionShape::KeepPopStablePreload {
                        pc: *pc,
                        constraints_preload: (constraints_preload.0, constraints_preload.1.clone()),
                        attributes_preload: (attributes_preload.0, attributes_preload.1.clone()),
                        lhs_slot: *lhs_slot,
                        rhs_slot: *rhs_slot,
                        name_prop_idx: *name_prop_idx,
                        constraints_callee_slot: *constraints_callee_slot,
                        constraints_prop_idx: *constraints_prop_idx,
                        attributes_callee_slot: *attributes_callee_slot,
                        attributes_prop_idx: *attributes_prop_idx,
                    })
                }
                _ => None,
            }
        } else {
            None
        })
        .or_else(|| match &parsed[i..i + 8] {
            [(
                pc,
                ParsedOp::StringPropStrictEq {
                    lhs_slot,
                    rhs_slot,
                    prop_idx: name_prop_idx,
                },
            ), (_, ParsedOp::JumpIfFalseKeep(false_target_a)), (_, ParsedOp::Pop), (
                _,
                ParsedOp::CallDirect2PropPredicate {
                    callee_slot: constraints_callee_slot,
                    lhs_slot: constraints_lhs_slot,
                    rhs_slot: constraints_rhs_slot,
                    prop_idx: constraints_prop_idx,
                },
            ), (_, ParsedOp::JumpIfFalseKeep(false_target_b)), (_, ParsedOp::Pop), (
                _,
                ParsedOp::CallDirect2PropPredicate {
                    callee_slot: attributes_callee_slot,
                    lhs_slot: attributes_lhs_slot,
                    rhs_slot: attributes_rhs_slot,
                    prop_idx: attributes_prop_idx,
                },
            ), (_, ParsedOp::Return)]
                if false_target_a == false_target_b
                    && lhs_slot == constraints_lhs_slot
                    && lhs_slot == attributes_lhs_slot
                    && rhs_slot == constraints_rhs_slot
                    && rhs_slot == attributes_rhs_slot =>
            {
                Some(AriaFusionShape::KeepPop {
                    pc: *pc,
                    lhs_slot: *lhs_slot,
                    rhs_slot: *rhs_slot,
                    name_prop_idx: *name_prop_idx,
                    constraints_callee_slot: *constraints_callee_slot,
                    constraints_prop_idx: *constraints_prop_idx,
                    attributes_callee_slot: *attributes_callee_slot,
                    attributes_prop_idx: *attributes_prop_idx,
                })
            }
            [(
                pc,
                ParsedOp::StringPropStrictEq {
                    lhs_slot,
                    rhs_slot,
                    prop_idx: name_prop_idx,
                },
            ), (_, ParsedOp::JumpIfFalse(false_target_a)), constraints_preload @ (
                _,
                ParsedOp::StableCalleePreload {
                    local_slot: constraints_preload_slot,
                    ..
                },
            ), (
                _,
                ParsedOp::CallDirect2PropPredicate {
                    callee_slot: constraints_callee_slot,
                    lhs_slot: constraints_lhs_slot,
                    rhs_slot: constraints_rhs_slot,
                    prop_idx: constraints_prop_idx,
                },
            ), (_, ParsedOp::JumpIfFalse(false_target_b)), attributes_preload @ (
                _,
                ParsedOp::StableCalleePreload {
                    local_slot: attributes_preload_slot,
                    ..
                },
            ), (
                _,
                ParsedOp::CallDirect2PropPredicate {
                    callee_slot: attributes_callee_slot,
                    lhs_slot: attributes_lhs_slot,
                    rhs_slot: attributes_rhs_slot,
                    prop_idx: attributes_prop_idx,
                },
            ), (_, ParsedOp::Return)]
                if false_target_a == false_target_b
                    && constraints_preload_slot == constraints_callee_slot
                    && attributes_preload_slot == attributes_callee_slot
                    && lhs_slot == constraints_lhs_slot
                    && lhs_slot == attributes_lhs_slot
                    && rhs_slot == constraints_rhs_slot
                    && rhs_slot == attributes_rhs_slot =>
            {
                Some(AriaFusionShape::StablePreload {
                    pc: *pc,
                    constraints_preload: (constraints_preload.0, constraints_preload.1.clone()),
                    attributes_preload: (attributes_preload.0, attributes_preload.1.clone()),
                    lhs_slot: *lhs_slot,
                    rhs_slot: *rhs_slot,
                    name_prop_idx: *name_prop_idx,
                    constraints_callee_slot: *constraints_callee_slot,
                    constraints_prop_idx: *constraints_prop_idx,
                    attributes_callee_slot: *attributes_callee_slot,
                    attributes_prop_idx: *attributes_prop_idx,
                })
            }
            _ => None,
        }) else {
            i += 1;
            continue;
        };
        let replacement = match shape {
            AriaFusionShape::KeepPop {
                pc,
                lhs_slot,
                rhs_slot,
                name_prop_idx,
                constraints_callee_slot,
                constraints_prop_idx,
                attributes_callee_slot,
                attributes_prop_idx,
            } => vec![(
                pc,
                ParsedOp::AriaParentPredicateFusion {
                    constraints_callee_slot,
                    attributes_callee_slot,
                    lhs_slot,
                    rhs_slot,
                    name_prop_idx,
                    constraints_prop_idx,
                    attributes_prop_idx,
                },
            )],
            AriaFusionShape::StablePreload {
                pc,
                constraints_preload,
                attributes_preload,
                lhs_slot,
                rhs_slot,
                name_prop_idx,
                constraints_callee_slot,
                constraints_prop_idx,
                attributes_callee_slot,
                attributes_prop_idx,
            } => vec![
                constraints_preload,
                attributes_preload,
                (
                    pc,
                    ParsedOp::AriaParentPredicateFusion {
                        constraints_callee_slot,
                        attributes_callee_slot,
                        lhs_slot,
                        rhs_slot,
                        name_prop_idx,
                        constraints_prop_idx,
                        attributes_prop_idx,
                    },
                ),
                (pc, ParsedOp::Return),
            ],
            AriaFusionShape::KeepPopStablePreload {
                pc,
                constraints_preload,
                attributes_preload,
                lhs_slot,
                rhs_slot,
                name_prop_idx,
                constraints_callee_slot,
                constraints_prop_idx,
                attributes_callee_slot,
                attributes_prop_idx,
            } => vec![
                constraints_preload,
                attributes_preload,
                (
                    pc,
                    ParsedOp::AriaParentPredicateFusion {
                        constraints_callee_slot,
                        attributes_callee_slot,
                        lhs_slot,
                        rhs_slot,
                        name_prop_idx,
                        constraints_prop_idx,
                        attributes_prop_idx,
                    },
                ),
                (pc, ParsedOp::Return),
            ],
        };
        let replaced_len = match shape {
            AriaFusionShape::KeepPopStablePreload { .. } => 10,
            _ => 8,
        };
        parsed.splice(i..i + replaced_len, replacement);
        i += 1;
    }
}

fn aria_callsite_direct_entry_contracts(
    parsed: &[(usize, ParsedOp)],
) -> Vec<AriaCallsiteDirectEntryContract> {
    parsed
        .iter()
        .filter_map(|(_, op)| match op {
            ParsedOp::AriaParentPredicateFusion {
                constraints_callee_slot,
                attributes_callee_slot,
                lhs_slot,
                rhs_slot,
                name_prop_idx,
                constraints_prop_idx,
                attributes_prop_idx,
            } => Some(AriaCallsiteDirectEntryContract {
                constraints_callee_slot: *constraints_callee_slot,
                attributes_callee_slot: *attributes_callee_slot,
                lhs_slot: *lhs_slot,
                rhs_slot: *rhs_slot,
                name_prop_idx: *name_prop_idx,
                constraints_prop_idx: *constraints_prop_idx,
                attributes_prop_idx: *attributes_prop_idx,
            }),
            _ => None,
        })
        .collect()
}

fn constant_string<'a>(constants: &'a ConstantsPool, idx: u16) -> Option<&'a str> {
    match constants.get(idx) {
        Some(Constant::String(s)) => Some(s.as_str()),
        _ => None,
    }
}

fn report_aria_inline_consumption_classifier(
    parsed: &[(usize, ParsedOp)],
    constants: &ConstantsPool,
) {
    if !aria_inline_consumption_classifier_enabled() {
        return;
    }
    for (pc, op) in parsed {
        let ParsedOp::AriaParentPredicateFusion {
            constraints_callee_slot,
            attributes_callee_slot,
            lhs_slot,
            rhs_slot,
            name_prop_idx,
            constraints_prop_idx,
            attributes_prop_idx,
        } = op
        else {
            continue;
        };
        let name_prop = constant_string(constants, *name_prop_idx).unwrap_or("<non-string>");
        let constraints_prop =
            constant_string(constants, *constraints_prop_idx).unwrap_or("<non-string>");
        let attributes_prop =
            constant_string(constants, *attributes_prop_idx).unwrap_or("<non-string>");
        let expected_props = name_prop == "name"
            && constraints_prop == "constraints"
            && attributes_prop == "attributes";
        let stable_slots_distinct = constraints_callee_slot != attributes_callee_slot;
        let receiver_slots_distinct = lhs_slot != rhs_slot;
        let inline_fact_ready = expected_props && stable_slots_distinct && receiver_slots_distinct;
        let first_missing = if !expected_props {
            "expected-property-triple"
        } else if !stable_slots_distinct {
            "distinct-stable-callee-slots"
        } else if !receiver_slots_distinct {
            "distinct-receiver-slots"
        } else {
            "inline-emitter-consumes-fact"
        };
        eprintln!(
            "[aria-inline-consumption-classifier] pc={} lhs_slot={} rhs_slot={} constraints_callee_slot={} attributes_callee_slot={} name_prop={} constraints_prop={} attributes_prop={} expected_props={} stable_slots_distinct={} receiver_slots_distinct={} inline_fact_ready={} current_lowering=runtime-helper-callout first_missing={} receiver=P-LEJIT-ARIA-GENERATED-PARENT-PREDICATE-INLINE-CONSUMPTION",
            pc,
            lhs_slot,
            rhs_slot,
            constraints_callee_slot,
            attributes_callee_slot,
            name_prop,
            constraints_prop,
            attributes_prop,
            expected_props,
            stable_slots_distinct,
            receiver_slots_distinct,
            inline_fact_ready,
            first_missing
        );
    }
}

