fn push_unique_string(values: &mut Vec<String>, value: String) {
    if !values.iter().any(|existing| existing == &value) {
        values.push(value);
    }
}

fn stable_helper_value_transport_summary(
    string_eq_props: &[String],
    helper_arg_props: &[String],
) -> String {
    let mut parts = Vec::new();
    if !string_eq_props.is_empty() {
        parts.push(format!("string-eq props={string_eq_props:?}"));
    }
    if !helper_arg_props.is_empty() {
        parts.push(format!("helper-arg props={helper_arg_props:?}"));
    }
    if parts.is_empty() {
        "unknown".to_string()
    } else {
        parts.join("; ")
    }
}

fn stable_helper_getprop_feeds_immediate_equality(
    parsed: &[(usize, ParsedOp)],
    idx: usize,
    prop_idx: u16,
) -> bool {
    let Some((_, ParsedOp::GetPropOnObject(other_prop_idx))) = parsed.get(idx + 2) else {
        return false;
    };
    *other_prop_idx == prop_idx
        && matches!(
            parsed.get(idx + 3).map(|(_, op)| op),
            Some(ParsedOp::Eq | ParsedOp::StrictEq)
        )
}

fn stable_helper_getprop_feeds_direct_helper_arg(parsed: &[(usize, ParsedOp)], idx: usize) -> bool {
    for (_, op) in parsed.iter().skip(idx + 1).take(6) {
        match op {
            ParsedOp::CallDirect { .. }
            | ParsedOp::CallDirectLeaf { .. }
            | ParsedOp::CallDirectLeafConstI32 { .. }
            | ParsedOp::CallDirectLeaf2 { .. }
            | ParsedOp::CallDirectLeaf2ConstI32 { .. }
            | ParsedOp::CallDirectLeaf3 { .. } => return true,
            ParsedOp::JumpIfFalse(_)
            | ParsedOp::JumpIfTrue(_)
            | ParsedOp::JumpIfFalseKeep(_)
            | ParsedOp::JumpIfTrueKeep(_)
            | ParsedOp::Return
            | ParsedOp::ReturnUndef => return false,
            _ => {}
        }
    }
    false
}

fn scanner_predicate_envelope_probe_enabled() -> bool {
    env_flag_truthy("CRUFT_LEJIT_SCANNER_PREDICATE_ENVELOPE_PROBE")
}

fn rewrite_scanner_predicate_envelope_probe(parsed: &mut [(usize, ParsedOp)]) {
    if !scanner_predicate_envelope_probe_enabled() {
        return;
    }
    let mut i = 0usize;
    while i < parsed.len() {
        let Some(chain) = scanner_predicate_keep_chain(parsed, i) else {
            i += 1;
            continue;
        };
        if env_flag_truthy("CRUFT_LEJIT_SCANNER_PREDICATE_TRACE") {
            eprintln!(
                "[scanner-predicate-envelope-probe] first_keep_pc={} keep_count={} tested_slot={} materialized_slot={:?}",
                chain.first_keep_pc, chain.keep_count, chain.tested_slot, chain.materialized_slot
            );
        }
        parsed[i].1 = ParsedOp::ScannerPredicateEnvelope {
            first_keep_pc: chain.first_keep_pc,
            keep_count: chain.keep_count,
            tested_slot: chain.tested_slot,
            materialized_slot: chain.materialized_slot,
        };
        let mut next = i + 1;
        while next < parsed.len() {
            if matches!(
                parsed[next].1,
                ParsedOp::InitLocal(_) | ParsedOp::StoreLocal(_)
            ) {
                next += 1;
                break;
            }
            next += 1;
        }
        i = next;
    }
}

fn scanner_predicate_envelope_rewrite_enabled() -> bool {
    env_flag_enabled_by_default("CRUFT_LEJIT_SCANNER_PREDICATE_ENVELOPE_REWRITE")
}

fn rewrite_scanner_ascii_word_predicate(parsed: &mut Vec<(usize, ParsedOp)>) {
    let mut i = 0usize;
    while i < parsed.len() {
        let Some(contract) = scanner_predicate_materialization_contract(parsed, i) else {
            i += 1;
            continue;
        };
        let Some(start_idx) = i.checked_sub(3) else {
            i += 1;
            continue;
        };
        let Some(end_rel) = parsed[i..].iter().position(|(_, op)| {
            matches!(op, ParsedOp::InitLocal(slot) | ParsedOp::StoreLocal(slot) if *slot == contract.materialized_slot)
        }) else {
            i += 1;
            continue;
        };
        let end_idx = i + end_rel;
        if !scanner_ascii_word_predicate_terms_match(
            &parsed[start_idx..=end_idx],
            contract.tested_slot,
        ) {
            i += 1;
            continue;
        }
        let start_pc = parsed[start_idx].0;
        parsed.splice(
            start_idx..=end_idx,
            [(
                start_pc,
                ParsedOp::ScannerAsciiWordPredicate {
                    tested_slot: contract.tested_slot,
                    materialized_slot: contract.materialized_slot,
                },
            )],
        );
        i = start_idx + 1;
    }
}

fn scanner_ascii_word_predicate_terms_match(slice: &[(usize, ParsedOp)], tested_slot: u16) -> bool {
    let mut terms = Vec::new();
    let mut idx = 0usize;
    while idx + 2 < slice.len() {
        match (&slice[idx].1, &slice[idx + 1].1, &slice[idx + 2].1) {
            (
                ParsedOp::LoadLocal(slot),
                ParsedOp::PushI32(value),
                ParsedOp::StrictEq
                | ParsedOp::Eq
                | ParsedOp::Ge
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Lt,
            ) if *slot == tested_slot => {
                terms.push((*value, slice[idx + 2].1));
                idx += 3;
            }
            _ => idx += 1,
        }
    }
    matches!(
        terms.as_slice(),
        [
            (95, ParsedOp::StrictEq | ParsedOp::Eq),
            (48, ParsedOp::Ge),
            (57, ParsedOp::Le),
            (65, ParsedOp::Ge),
            (90, ParsedOp::Le),
            (97, ParsedOp::Ge),
            (122, ParsedOp::Le),
        ]
    )
}

fn scanner_ascii_ident_predicate_terms_match(
    slice: &[(usize, ParsedOp)],
    tested_slot: u16,
) -> bool {
    let mut terms = Vec::new();
    let mut idx = 0usize;
    while idx + 2 < slice.len() {
        match (&slice[idx].1, &slice[idx + 1].1, &slice[idx + 2].1) {
            (
                ParsedOp::LoadLocal(slot),
                ParsedOp::PushI32(value),
                ParsedOp::StrictEq
                | ParsedOp::Eq
                | ParsedOp::Ge
                | ParsedOp::Le
                | ParsedOp::Gt
                | ParsedOp::Lt,
            ) if *slot == tested_slot => {
                terms.push((*value, slice[idx + 2].1));
                idx += 3;
            }
            _ => idx += 1,
        }
    }
    matches!(
        terms.as_slice(),
        [
            (48, ParsedOp::Ge),
            (57, ParsedOp::Le),
            (65, ParsedOp::Ge),
            (90, ParsedOp::Le),
            (97, ParsedOp::Ge),
            (122, ParsedOp::Le),
            (45, ParsedOp::StrictEq | ParsedOp::Eq),
            (95, ParsedOp::StrictEq | ParsedOp::Eq),
        ]
    )
}

fn scanner_predicate_synthetic_boolean_slot(
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Option<u16> {
    locals
        .iter()
        .position(|local| local.name == "<update.old>")
        .and_then(|slot| u16::try_from(slot).ok())
}

fn rewrite_scanner_ascii_ident_predicate_branch(
    parsed: &mut Vec<(usize, ParsedOp)>,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) {
    let Some(materialized_slot) = scanner_predicate_synthetic_boolean_slot(locals) else {
        return;
    };
    let mut i = 0usize;
    while i < parsed.len() {
        let Some(chain) = scanner_predicate_keep_chain(parsed, i) else {
            i += 1;
            continue;
        };
        if chain.materialized_slot.is_some() {
            i += 1;
            continue;
        }
        let Some(branch_pc) = jumpifkeep_kept_stack_candidate(parsed, i)
            .and_then(|candidate| candidate.next_plain_branch_pc)
        else {
            i += 1;
            continue;
        };
        let Some(branch_idx) = parsed.iter().position(|(pc, _)| *pc == branch_pc) else {
            i += 1;
            continue;
        };
        if !matches!(
            parsed[branch_idx].1,
            ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_)
        ) {
            i += 1;
            continue;
        }
        let Some(start_idx) = i.checked_sub(3) else {
            i += 1;
            continue;
        };
        if start_idx >= branch_idx {
            i += 1;
            continue;
        }
        if !scanner_ascii_ident_predicate_terms_match(
            &parsed[start_idx..branch_idx],
            chain.tested_slot,
        ) {
            i += 1;
            continue;
        }
        let start_pc = parsed[start_idx].0;
        let branch = parsed[branch_idx];
        parsed.splice(
            start_idx..=branch_idx,
            [
                (
                    start_pc,
                    ParsedOp::ScannerAsciiIdentPredicate {
                        tested_slot: chain.tested_slot,
                        materialized_slot,
                    },
                ),
                (start_pc + 1, ParsedOp::LoadLocal(materialized_slot)),
                branch,
            ],
        );
        i = start_idx + 3;
    }
}

fn primitive_string_index_cross_block_candidate(
    parsed: &[(usize, ParsedOp)],
) -> Option<PrimitiveStringIndexCrossBlockCandidate> {
    let [(predicate_pc, predicate), (_, ParsedOp::LoadLocal(accumulator_slot)), (_, ParsedOp::LoadLocal(receiver_slot)), (_, ParsedOp::LoadLocal(index_slot))] =
        parsed.get(parsed.len().checked_sub(4)?..)?
    else {
        return None;
    };
    if !matches!(
        predicate,
        ParsedOp::JumpIfFalse(_) | ParsedOp::JumpIfTrue(_)
    ) {
        return None;
    }
    if accumulator_slot == receiver_slot
        || accumulator_slot == index_slot
        || receiver_slot == index_slot
    {
        return None;
    }
    Some(PrimitiveStringIndexCrossBlockCandidate {
        predicate_pc: *predicate_pc,
        accumulator_slot: *accumulator_slot,
        receiver_slot: *receiver_slot,
        index_slot: *index_slot,
    })
}

fn primitive_string_index_object_guard_domain_gaps(
    parsed: &[(usize, ParsedOp)],
) -> Vec<(usize, PrimitiveStringIndexCrossBlockCandidate)> {
    let mut gaps = Vec::new();
    for i in 0..parsed.len() {
        if !matches!(parsed[i].1, ParsedOp::GetIndexOnObject) {
            continue;
        }
        if let Some(candidate) = primitive_string_index_cross_block_candidate(&parsed[..i]) {
            gaps.push((i, candidate));
        }
    }
    gaps
}

fn rewrite_primitive_string_index_object_guards(parsed: &mut [(usize, ParsedOp)]) {
    for i in 0..parsed.len() {
        if !matches!(parsed[i].1, ParsedOp::GetIndexOnObject) {
            continue;
        }
        if let Some(candidate) = primitive_string_index_cross_block_candidate(&parsed[..i]) {

            if !string_slot_hint_contains(candidate.receiver_slot) {
                continue;
            }
            parsed[i].1 = ParsedOp::PrimitiveStringIndexRead {
                predicate_pc: candidate.predicate_pc,
                accumulator_slot: candidate.accumulator_slot,
                receiver_slot: candidate.receiver_slot,
                index_slot: candidate.index_slot,
            };
        }
    }
}

fn primitive_string_index_receiver_slots(parsed: &[(usize, ParsedOp)]) -> Vec<u16> {
    let mut slots = Vec::new();
    for (_, op) in parsed {
        if let ParsedOp::PrimitiveStringIndexRead { receiver_slot, .. } = op {
            push_unique_sorted(&mut slots, *receiver_slot);
        }
    }
    slots
}

fn primitive_string_index_admission_gap(
    parsed: &[(usize, ParsedOp)],
) -> Option<PrimitiveStringIndexAdmissionGap> {
    let candidate = primitive_string_index_cross_block_candidate(parsed)?;
    let string_slots = hoistable_string_charcode_receiver_slots(parsed);
    if !string_slots.contains(&candidate.receiver_slot) {
        return Some(
            PrimitiveStringIndexAdmissionGap::MissingReceiverPrimitiveStringDomain {
                receiver_slot: candidate.receiver_slot,
                index_slot: candidate.index_slot,
            },
        );
    }
    Some(
        PrimitiveStringIndexAdmissionGap::MissingUtf16Materialization {
            receiver_slot: candidate.receiver_slot,
            index_slot: candidate.index_slot,
        },
    )
}

fn trace_primitive_string_index_mouth(
    op_pc: usize,
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) {
    if !env_flag_truthy("CRUFT_LEJIT_PRIMITIVE_STRING_INDEX_TRACE") {
        return;
    }

    let block_stack = simulate_block_stack(parsed).unwrap_or_default();
    let expr_stack = simulate_expr_stack(parsed).unwrap_or_default();
    let origin_receiver = block_stack.get(block_stack.len().saturating_sub(2));
    let expr_receiver = expr_stack.get(expr_stack.len().saturating_sub(2));
    let expr_index = expr_stack.last();
    let receiver_slots = expr_receiver
        .map(|expr| expr.locals.clone())
        .unwrap_or_default();
    let index_slots = expr_index
        .map(|expr| expr.locals.clone())
        .unwrap_or_default();
    let receiver_names: Vec<String> = receiver_slots
        .iter()
        .map(|slot| {
            let name = locals
                .get(usize::from(*slot))
                .map(|local| local.name.as_str())
                .unwrap_or("<unknown-local>");
            format!("{slot}:{name}")
        })
        .collect();
    let index_names: Vec<String> = index_slots
        .iter()
        .map(|slot| {
            let name = locals
                .get(usize::from(*slot))
                .map(|local| local.name.as_str())
                .unwrap_or("<unknown-local>");
            format!("{slot}:{name}")
        })
        .collect();
    let consumer = parsed
        .last()
        .map(|(pc, op)| format!("prev_pc={pc} prev_op={op:?}"))
        .unwrap_or_else(|| "prev=<none>".to_string());
    let recent_ops: Vec<String> = parsed
        .iter()
        .rev()
        .take(8)
        .rev()
        .map(|(pc, op)| format!("{pc}:{op:?}"))
        .collect();
    let immediate_index_slot = match parsed.last().map(|(_, op)| *op) {
        Some(ParsedOp::LoadLocal(slot)) => Some(slot),
        _ => None,
    };
    let nearby_receiver_slot = immediate_index_slot.and_then(|index_slot| {
        parsed.iter().rev().skip(1).find_map(|(_, op)| match *op {
            ParsedOp::LoadLocal(slot) if slot != index_slot => Some(slot),
            _ => None,
        })
    });
    let nearby_receiver_name = nearby_receiver_slot
        .and_then(|slot| {
            locals
                .get(usize::from(slot))
                .map(|local| format!("{slot}:{}", local.name))
        })
        .unwrap_or_else(|| "<none>".to_string());
    let cross_block_candidate = primitive_string_index_cross_block_candidate(parsed);
    let admission_gap = primitive_string_index_admission_gap(parsed);

    eprintln!(
        "[primitive-string-index-mouth] pc={op_pc} origin_receiver={origin_receiver:?} receiver_locals={receiver_names:?} index_locals={index_names:?} immediate_index_slot={immediate_index_slot:?} nearby_receiver={nearby_receiver_name} cross_block_candidate={cross_block_candidate:?} admission_gap={admission_gap:?} index_integer_rooted={} index_string_mod_length={:?} consumer={} recent_ops={recent_ops:?} object_string_lane=false",
        expr_index
            .map(|expr| expr.integer_rooted)
            .unwrap_or(false),
        expr_index.and_then(|expr| expr.string_mod_length_index),
        consumer
    );
}

struct CssSite813MappedStringEqShape {
    ident_slot: u16,
    mapped_slot: u16,
    color_load_pc: usize,
    color_eq_pc: usize,
    color_false_pc: usize,
    color_true_store_pc: usize,
    margin_load_pc: usize,
    margin_eq_pc: usize,
    margin_false_pc: usize,
    margin_true_store_pc: usize,
    ident_fallback_store_pc: usize,
    generic_strict_eq: bool,
}

fn css_site813_mapped_string_eq_shape(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Option<CssSite813MappedStringEqShape> {
    let ident_slot = local_slot_by_name(locals, "ident")?;
    let mapped_slot = local_slot_by_name(locals, "mapped")?;
    for window in parsed.windows(16) {
        let [(color_load_pc, ParsedOp::LoadLocal(color_slot)), (_, ParsedOp::PushStringConst { len: color_len, .. }), (
            color_eq_pc,
            color_eq @ (ParsedOp::StrictEq
            | ParsedOp::Eq
            | ParsedOp::StringLocalConstStrictEq { .. }),
        ), (color_branch_pc, ParsedOp::JumpIfFalse(margin_load_pc_target)), (_, ParsedOp::PushStringConst { len: c_len, .. }), (
            color_store_pc,
            ParsedOp::InitLocal(color_mapped) | ParsedOp::StoreLocal(color_mapped),
        ), (_, ParsedOp::Jump(after_color_pc)), (margin_load_pc, ParsedOp::LoadLocal(margin_slot)), (
            _,
            ParsedOp::PushStringConst {
                len: margin_len, ..
            },
        ), (
            margin_eq_pc,
            margin_eq @ (ParsedOp::StrictEq
            | ParsedOp::Eq
            | ParsedOp::StringLocalConstStrictEq { .. }),
        ), (margin_branch_pc, ParsedOp::JumpIfFalse(ident_fallback_pc_target)), (_, ParsedOp::PushStringConst { len: m_len, .. }), (
            margin_store_pc,
            ParsedOp::InitLocal(margin_mapped) | ParsedOp::StoreLocal(margin_mapped),
        ), (_, ParsedOp::Jump(after_margin_pc)), (ident_fallback_pc, ParsedOp::LoadLocal(fallback_slot)), (
            ident_fallback_store_pc,
            ParsedOp::InitLocal(fallback_mapped) | ParsedOp::StoreLocal(fallback_mapped),
        )] = window
        else {
            continue;
        };
        if *color_slot != ident_slot
            || *margin_slot != ident_slot
            || *fallback_slot != ident_slot
            || *color_mapped != mapped_slot
            || *margin_mapped != mapped_slot
            || *fallback_mapped != mapped_slot
            || *margin_load_pc_target != *margin_load_pc
            || *ident_fallback_pc_target != *ident_fallback_pc
            || after_color_pc != after_margin_pc
            || *color_len != 5
            || *c_len != 1
            || *margin_len != 6
            || *m_len != 1
        {
            continue;
        }
        return Some(CssSite813MappedStringEqShape {
            ident_slot,
            mapped_slot,
            color_load_pc: *color_load_pc,
            color_eq_pc: *color_eq_pc,
            color_false_pc: *color_branch_pc,
            color_true_store_pc: *color_store_pc,
            margin_load_pc: *margin_load_pc,
            margin_eq_pc: *margin_eq_pc,
            margin_false_pc: *margin_branch_pc,
            margin_true_store_pc: *margin_store_pc,
            ident_fallback_store_pc: *ident_fallback_store_pc,
            generic_strict_eq: matches!(color_eq, ParsedOp::StrictEq)
                && matches!(margin_eq, ParsedOp::StrictEq),
        });
    }
    None
}

fn report_css_site813_mapped_string_eq_probe(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) {
    if !env_flag_truthy("CRUFT_LEJIT_CSS_SITE813_MAPPED_STRING_EQ_PROBE") {
        return;
    }
    let Some(shape) = css_site813_mapped_string_eq_shape(parsed, locals) else {
        eprintln!(
            "[css-site813-mapped-string-eq] shape_present=false execute=false next=derive-ternary-shape-or-route-away"
        );
        return;
    };
    eprintln!(
        "[css-site813-mapped-string-eq] ident_slot={} mapped_slot={} color_load_pc={} color_eq_pc={} color_false_pc={} color_true_store_pc={} margin_load_pc={} margin_eq_pc={} margin_false_pc={} margin_true_store_pc={} ident_fallback_store_pc={} generic_strict_eq={} execute=false next={}",
        shape.ident_slot,
        shape.mapped_slot,
        shape.color_load_pc,
        shape.color_eq_pc,
        shape.color_false_pc,
        shape.color_true_store_pc,
        shape.margin_load_pc,
        shape.margin_eq_pc,
        shape.margin_false_pc,
        shape.margin_true_store_pc,
        shape.ident_fallback_store_pc,
        shape.generic_strict_eq,
        if shape.generic_strict_eq {
            "derive-string-local-const-eq-consumer-or-prove-generic-eq-correct"
        } else {
            "derive-generated-hash-state-parity"
        }
    );
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Site874TokenLiteralEqCandidate {
    load_pc: usize,
    eq_pc: usize,
    token_slot: u16,
    literal_len: i64,
    branch_pc: Option<usize>,
    aggregate_store_pc: Option<usize>,
    aggregate_slot: Option<u16>,
}

fn site874_token_literal_eq_candidates(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Vec<Site874TokenLiteralEqCandidate> {
    let mut out = Vec::new();
    for idx in 0..parsed.len().saturating_sub(2) {
        let [(load_pc, ParsedOp::LoadLocal(token_slot)), (_, ParsedOp::PushStringConst { len, .. }), (eq_pc, ParsedOp::StrictEq | ParsedOp::Eq)] =
            &parsed[idx..idx + 3]
        else {
            continue;
        };
        if locals
            .get(usize::from(*token_slot))
            .map(|local| local.name.as_str())
            != Some("token")
        {
            continue;
        }
        let branch_pc = parsed
            .get(idx + 3)
            .and_then(|(pc, op)| matches!(op, ParsedOp::JumpIfFalse(_)).then_some(*pc));
        let mut aggregate_store_pc = None;
        let mut aggregate_slot = None;
        for (pc, op) in parsed.iter().skip(idx + 4).take(12) {
            if let ParsedOp::StoreLocal(slot) = op {
                if matches!(*slot, 1 | 2 | 3 | 4) {
                    aggregate_store_pc = Some(*pc);
                    aggregate_slot = Some(*slot);
                    break;
                }
            }
        }
        out.push(Site874TokenLiteralEqCandidate {
            load_pc: *load_pc,
            eq_pc: *eq_pc,
            token_slot: *token_slot,
            literal_len: *len,
            branch_pc,
            aggregate_store_pc,
            aggregate_slot,
        });
    }
    out
}

fn report_site874_token_literal_eq_rewrite_probe(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) {
    if !site874_token_literal_eq_rewrite_probe_enabled() {
        return;
    }
    let candidates = site874_token_literal_eq_candidates(parsed, locals);
    if candidates.is_empty() {
        return;
    }
    let aggregate_ready = candidates
        .iter()
        .filter(|candidate| {
            candidate.branch_pc.is_some()
                && candidate.aggregate_store_pc.is_some()
                && candidate.aggregate_slot.is_some()
        })
        .count();
    eprintln!(
        "[site874-token-literal-eq-rewrite-probe] candidates={candidates:?} aggregate_ready={aggregate_ready} execute=false next={}",
        if aggregate_ready >= 3 {
            "derive-token-literal-eq-helper-lowering-before-aggregate-value-production"
        } else {
            "derive-token-literal-eq-shape-before-aggregate-value-production"
        }
    );
}

