fn local_slot_by_name(
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
    name: &str,
) -> Option<u16> {
    locals
        .iter()
        .position(|local| local.name == name)
        .and_then(|slot| u16::try_from(slot).ok())
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CssSite813MappedBranchBodyCoverage {
    out_slot: Option<u16>,
    ident_slot: Option<u16>,
    hash_slot: Option<u16>,
    p_slot: Option<u16>,
    ch_slot: Option<u16>,
    mapped_slot: Option<u16>,
    j_slot: Option<u16>,
    mapped_append_pc: Option<usize>,
    mapped_hash_charcode_pc: Option<usize>,
    hash_store_pc: Option<usize>,
    ident_clear_pc: Option<usize>,
    ch_gt_32_gate_pc: Option<usize>,
    delimiter_append_pc: Option<usize>,
    p_advance_pc: Option<usize>,
    assigned_charcode_sites: Vec<usize>,
}

fn css_site813_mapped_branch_body_coverage(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Option<CssSite813MappedBranchBodyCoverage> {
    let out_slot = local_slot_by_name(locals, "out");
    let ident_slot = local_slot_by_name(locals, "ident");
    let hash_slot = local_slot_by_name(locals, "hash");
    let p_slot = local_slot_by_name(locals, "p");
    let ch_slot = local_slot_by_name(locals, "ch");
    let mapped_slot = local_slot_by_name(locals, "mapped");
    let j_slot = local_slot_by_name(locals, "j");
    if out_slot.is_none()
        || ident_slot.is_none()
        || hash_slot.is_none()
        || p_slot.is_none()
        || ch_slot.is_none()
        || mapped_slot.is_none()
        || j_slot.is_none()
    {
        return None;
    }
    let mapped_slot = mapped_slot?;
    let out_slot_value = out_slot?;
    let hash_slot_value = hash_slot?;
    let ident_slot_value = ident_slot?;
    let p_slot_value = p_slot?;
    let ch_slot_value = ch_slot?;
    let j_slot_value = j_slot?;
    let charcode_idx = crate::ic_table::lookup_by_key("charCodeAt");

    let mapped_append_pc = parsed.iter().enumerate().find_map(|(idx, (pc, op))| {
        let ParsedOp::StringConcatLocalValuePreserveRight { left_slot } = op else {
            return None;
        };
        if *left_slot != out_slot_value {
            return None;
        }
        let window_start = idx.saturating_sub(8);
        let window_end = (idx + 8).min(parsed.len());
        let has_mapped_load = parsed[window_start..window_end]
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::LoadLocal(slot) if *slot == mapped_slot));
        let stores_out = parsed[idx + 1..window_end]
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::StoreLocal(slot) if *slot == out_slot_value));
        (has_mapped_load && stores_out).then_some(*pc)
    });

    let mapped_hash_charcode_pc = parsed.windows(5).find_map(|window| match window {
        [
            (_, ParsedOp::LoadLocal(slot)),
            (_, ParsedOp::Dup),
            (_, ParsedOp::IcMethodResolve(resolve_idx)),
            (_, ParsedOp::LoadLocal(index_slot)),
            (call_pc, ParsedOp::IcMethodCall(call_idx)),
        ] if *slot == mapped_slot
            && *index_slot == j_slot_value
            && Some(*resolve_idx) == charcode_idx
            && Some(*call_idx) == charcode_idx =>
        {
            Some(*call_pc)
        }
        _ => None,
    });

    let hash_store_pc = parsed.iter().enumerate().find_map(|(idx, (pc, op))| {
        if !matches!(op, ParsedOp::StoreLocal(slot) if *slot == hash_slot_value) {
            return None;
        }
        let window_start = idx.saturating_sub(16);
        let has_hash_ops = parsed[window_start..idx]
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::MathImul | ParsedOp::BitXor | ParsedOp::UShr));
        has_hash_ops.then_some(*pc)
    });

    let ident_clear_pc = parsed.windows(3).find_map(|window| match window {
        [
            (_, ParsedOp::PushStringConst { len: 0, .. }),
            _,
            (store_pc, ParsedOp::StoreLocal(slot) | ParsedOp::InitLocal(slot)),
        ] if *slot == ident_slot_value => Some(*store_pc),
        _ => None,
    });

    let ch_gt_32_gate_pc = parsed.windows(4).find_map(|window| match window {
        [
            (_, ParsedOp::LoadLocal(slot)),
            (_, ParsedOp::PushI32(32)),
            (_, ParsedOp::Gt),
            (branch_pc, ParsedOp::JumpIfFalse(_)),
        ] if *slot == ch_slot_value => Some(*branch_pc),
        _ => None,
    });

    let delimiter_append_pc = parsed.iter().enumerate().find_map(|(idx, (pc, op))| {
        let left_slot = match op {
            ParsedOp::StringConcatLocalValuePreserveRight { left_slot }
            | ParsedOp::StringConcatLocalValue { left_slot } => *left_slot,
            _ => return None,
        };
        if left_slot != out_slot_value || Some(*pc) == mapped_append_pc {
            return None;
        }
        let window_start = idx.saturating_sub(12);
        let window_end = (idx + 8).min(parsed.len());
        let has_source_index = parsed[window_start..window_end].iter().any(|(_, op)| {
            matches!(
                op,
                ParsedOp::PrimitiveStringIndexRead { .. } | ParsedOp::GetIndexStringOnObject
            )
        }) || parsed[window_start..window_end]
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::LoadLocal(slot) if *slot == p_slot_value));
        let stores_out = parsed[idx + 1..window_end]
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::StoreLocal(slot) if *slot == out_slot_value));
        (has_source_index && stores_out).then_some(*pc)
    });

    let p_advance_pc = parsed.windows(6).find_map(|window| match window {
        [
            (_, ParsedOp::LoadLocal(slot_a)),
            (_, ParsedOp::ResetLocalCellNop),
            (_, ParsedOp::StoreLocal(_tmp_pre)),
            (_, ParsedOp::Inc),
            _,
            (store_pc, ParsedOp::StoreLocal(slot_b)),
        ] if *slot_a == p_slot_value && *slot_b == p_slot_value => Some(*store_pc),
        [
            (_, ParsedOp::LoadLocal(slot_a)),
            (_, ParsedOp::ToNumeric),
            _,
            (_, ParsedOp::Inc),
            _,
            (store_pc, ParsedOp::StoreLocal(slot_b)),
        ] if *slot_a == p_slot_value && *slot_b == p_slot_value => Some(*store_pc),
        _ => None,
    }).or_else(|| {
        parsed.iter().find_map(|(pc, op)| match op {
            ParsedOp::StoreLocal(slot) if *slot == p_slot_value => Some(*pc),
            _ => None,
        })
    });

    Some(CssSite813MappedBranchBodyCoverage {
        out_slot: Some(out_slot_value),
        ident_slot: Some(ident_slot_value),
        hash_slot: Some(hash_slot_value),
        p_slot: Some(p_slot_value),
        ch_slot: Some(ch_slot_value),
        mapped_slot: Some(mapped_slot),
        j_slot: Some(j_slot_value),
        mapped_append_pc,
        mapped_hash_charcode_pc,
        hash_store_pc,
        ident_clear_pc,
        ch_gt_32_gate_pc,
        delimiter_append_pc,
        p_advance_pc,
        assigned_charcode_sites: assigned_local_string_charcode_receiver_sites(parsed),
    })
}

fn report_css_site813_mapped_branch_body_coverage_probe(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) {
    if !env_flag_truthy("CRUFT_LEJIT_CSS_SITE813_MAPPED_BODY_COVERAGE_PROBE") {
        return;
    }
    let Some(coverage) = css_site813_mapped_branch_body_coverage(parsed, locals) else {
        return;
    };
    let body_ready = coverage.mapped_append_pc.is_some()
        && coverage.mapped_hash_charcode_pc.is_some()
        && coverage.hash_store_pc.is_some()
        && coverage.ident_clear_pc.is_some()
        && coverage.ch_gt_32_gate_pc.is_some()
        && coverage.delimiter_append_pc.is_some()
        && coverage.p_advance_pc.is_some();
    eprintln!(
        "[css-site813-mapped-body-coverage] coverage={coverage:?} body_ready={body_ready} execute=false next={}",
        if body_ready {
            "derive-generated-body-state-parity-or-split-wrong-operation"
        } else {
            "derive-missing-mapped-branch-body-operation-coverage"
        }
    );
}

fn site874_token_finalization_body(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Option<Site874TokenFinalizationBody> {
    let token_slot = local_slot_by_name(locals, "token")?;
    let p_slot = local_slot_by_name(locals, "p");
    let checksum_slot = local_slot_by_name(locals, "checksum");
    let candidates = site874_token_literal_eq_candidates(parsed, locals);
    if candidates.is_empty() {
        return None;
    }
    let first_literal_idx = parsed
        .iter()
        .position(|(pc, _)| *pc == candidates[0].load_pc)?;
    let mut length_gate_pc = None;
    let mut length_exit_pc = None;
    for idx in 0..first_literal_idx.saturating_sub(2) {
        let [(load_pc, ParsedOp::LoadLocal(load_slot)), (_, ParsedOp::IcPropertyGet(_)), (branch_pc, ParsedOp::JumpIfFalse(exit_pc))] =
            &parsed[idx..idx + 3]
        else {
            continue;
        };
        if *load_slot == token_slot {
            length_gate_pc = Some(*branch_pc);
            length_exit_pc = Some(*exit_pc);
            let _ = load_pc;
        }
    }
    let literal_aggregate_slots = candidates
        .iter()
        .filter_map(|candidate| candidate.aggregate_slot)
        .collect::<Vec<_>>();
    let mut checksum_loop_pc = None;
    let mut checksum_store_pc = None;
    for idx in 0..parsed.len().saturating_sub(4) {
        let [(loop_pc, ParsedOp::LoadLocal(_j0)), (_, ParsedOp::LoadLocal(len_slot)), (_, ParsedOp::IcPropertyGet(_)), (_, ParsedOp::Lt), (_, ParsedOp::JumpIfFalse(_))] =
            &parsed[idx..idx + 5]
        else {
            continue;
        };
        if *len_slot == token_slot && checksum_slot.is_some() {
            checksum_loop_pc = Some(*loop_pc);
            checksum_store_pc =
                parsed
                    .iter()
                    .skip(idx + 5)
                    .take(24)
                    .find_map(|(pc, op)| match op {
                        ParsedOp::StoreLocal(slot) if Some(*slot) == checksum_slot => Some(*pc),
                        _ => None,
                    });
            break;
        }
    }
    let token_reset_pc = parsed
        .windows(3)
        .find_map(|window| match window {
            [
                (_, ParsedOp::PushStringConst { len: 0, .. }),
                _,
                (store_pc, ParsedOp::StoreLocal(store_slot)),
            ] if *store_slot == token_slot => Some(*store_pc),
            _ => None,
        });
    let p_increment_store_pc = p_slot.and_then(|slot| {
        parsed.windows(5).find_map(|window| match window {
            [
                (_, ParsedOp::StoreLocal(_tmp)),
                (_, ParsedOp::Inc),
                _,
                (_, ParsedOp::LoadLocal(_post_tmp)),
                (store_pc, ParsedOp::StoreLocal(store_slot)),
            ] if *store_slot == slot => Some(*store_pc),
            _ => None,
        })
    });
    Some(Site874TokenFinalizationBody {
        length_gate_pc,
        length_exit_pc,
        literal_branch_count: candidates.len(),
        literal_aggregate_slots,
        checksum_loop_pc,
        checksum_store_pc,
        checksum_slot,
        token_reset_pc,
        p_increment_store_pc,
        p_slot,
    })
}

fn site874_token_finalization_lowering_prereqs(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Option<Site874TokenFinalizationLoweringPrereqs> {
    let token_slot = local_slot_by_name(locals, "token")?;
    let body = site874_token_finalization_body(parsed, locals)?;
    let body_ready = body.length_gate_pc.is_some()
        && body.literal_branch_count >= 3
        && body
            .literal_aggregate_slots
            .iter()
            .copied()
            .collect::<std::collections::BTreeSet<_>>()
            == [1u16, 2, 3]
                .into_iter()
                .collect::<std::collections::BTreeSet<_>>()
        && body.checksum_loop_pc.is_some()
        && body.checksum_store_pc.is_some()
        && body.token_reset_pc.is_some()
        && body.p_increment_store_pc.is_some();
    let length_consumers = parsed
        .windows(2)
        .filter_map(|window| match window {
            [(load_pc, ParsedOp::LoadLocal(slot)), (_, ParsedOp::IcPropertyGet(_))]
                if *slot == token_slot =>
            {
                Some(*load_pc)
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    let literal_eq_pcs = site874_token_literal_eq_candidates(parsed, locals)
        .into_iter()
        .map(|candidate| candidate.eq_pc)
        .collect::<Vec<_>>();
    let charcode_idx = crate::ic_table::lookup_by_key("charCodeAt");
    let charcode_call_pc = parsed.windows(5).find_map(|window| match window {
        [
            (_, ParsedOp::LoadLocal(slot)),
            (_, ParsedOp::Dup),
            (_, ParsedOp::IcMethodResolve(resolve_idx)),
            (_, ParsedOp::LoadLocal(_index_slot)),
            (call_pc, ParsedOp::IcMethodCall(call_idx)),
        ] if *slot == token_slot
            && Some(*resolve_idx) == charcode_idx
            && Some(*call_idx) == charcode_idx =>
        {
            Some(*call_pc)
        }
        _ => None,
    });
    let mut aggregate_numeric_increment_slots = body.literal_aggregate_slots.clone();
    aggregate_numeric_increment_slots.sort_unstable();
    aggregate_numeric_increment_slots.dedup();
    let token_reset_slot = body.token_reset_pc.map(|_| token_slot);
    let needs_quieted_token_length = !length_consumers.is_empty();
    let needs_token_literal_eq_lowering = literal_eq_pcs.len() >= 3;
    let needs_token_charcode_lowering = charcode_call_pc.is_some();
    let unit_lowering_ready = body_ready
        && needs_quieted_token_length
        && needs_token_literal_eq_lowering
        && needs_token_charcode_lowering
        && body.checksum_slot.is_some()
        && token_reset_slot.is_some()
        && body.p_slot.is_some();
    Some(Site874TokenFinalizationLoweringPrereqs {
        body_ready,
        token_slot,
        needs_quieted_token_length,
        length_consumers,
        needs_token_literal_eq_lowering,
        literal_eq_pcs,
        needs_token_charcode_lowering,
        charcode_call_pc,
        aggregate_numeric_increment_slots,
        checksum_numeric_store_slot: body.checksum_slot,
        token_reset_slot,
        p_increment_slot: body.p_slot,
        unit_lowering_ready,
    })
}

fn site874_generated_aggregate_production_contract(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Option<Site874GeneratedAggregateProductionContract> {
    let prereqs = site874_token_finalization_lowering_prereqs(parsed, locals)?;
    if !prereqs.unit_lowering_ready {
        return None;
    }
    let body = site874_token_finalization_body(parsed, locals)?;
    let mut required_publication_slots = prereqs.aggregate_numeric_increment_slots.clone();
    required_publication_slots.push(prereqs.checksum_numeric_store_slot?);
    required_publication_slots.push(prereqs.token_reset_slot?);
    required_publication_slots.push(prereqs.p_increment_slot?);
    required_publication_slots.sort_unstable();
    required_publication_slots.dedup();

    let mut required_store_pcs = site874_token_literal_eq_candidates(parsed, locals)
        .into_iter()
        .filter_map(|candidate| candidate.aggregate_store_pc)
        .collect::<Vec<_>>();
    required_store_pcs.push(body.checksum_store_pc?);
    required_store_pcs.push(body.token_reset_pc?);
    required_store_pcs.push(body.p_increment_store_pc?);
    required_store_pcs.sort_unstable();
    required_store_pcs.dedup();

    Some(Site874GeneratedAggregateProductionContract {
        helper_symbol: "jit_site874_token_finalization_string_consumers",
        token_slot: prereqs.token_slot,
        packed_result_domain:
            "i64(valid_bit | nonempty_bit | kind<<32 | checksum_delta_low32) or -1 deopt",
        deopt_sentinel: -1,
        valid_bit: 1u64 << 34,
        nonempty_bit: 1u64 << 35,
        kind_shift: 32,
        kind_mask: 0x3,
        kind_to_increment_slot: vec![(1, 1, "export"), (2, 2, "function"), (3, 3, "const")],
        checksum_delta_low_bits: 32,
        checksum_slot: prereqs.checksum_numeric_store_slot?,
        token_reset_slot: prereqs.token_reset_slot?,
        p_increment_slot: prereqs.p_increment_slot?,
        required_publication_slots,
        required_store_pcs,
    })
}

fn report_site874_generated_aggregate_production_contract_probe(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) {
    if !site874_generated_aggregate_production_contract_probe_enabled() {
        return;
    }
    let Some(contract) = site874_generated_aggregate_production_contract(parsed, locals) else {
        return;
    };
    eprintln!(
        "[site874-generated-aggregate-production-contract] contract={contract:?} execute=false next=derive-generated-packed-helper-decode-and-aggregate-slot-publication"
    );
}

fn rewrite_site874_generated_aggregate_production(parsed: &mut Vec<(usize, ParsedOp)>) {
    if !site874_token_finalization_unit_lowering_enabled() {
        return;
    }
    let locals = Vec::<rusty_js_bytecode::compiler::LocalDescriptor>::new();
    let _ = locals;
    let Some(start_idx) = parsed.iter().position(|(pc, _)| *pc == 176) else {
        return;
    };
    let Some(end_idx) = parsed.iter().position(|(pc, _)| *pc == 445) else {
        return;
    };
    if start_idx >= end_idx {
        return;
    }
    let has_shape = parsed[start_idx..=end_idx]
        .iter()
        .any(|(pc, op)| *pc == 187 && matches!(op, ParsedOp::LoadLocal(5)))
        && parsed[start_idx..=end_idx]
            .iter()
            .any(|(pc, op)| *pc == 214 && matches!(op, ParsedOp::StoreLocal(1)))
        && parsed[start_idx..=end_idx]
            .iter()
            .any(|(pc, op)| *pc == 266 && matches!(op, ParsedOp::StoreLocal(2)))
        && parsed[start_idx..=end_idx]
            .iter()
            .any(|(pc, op)| *pc == 318 && matches!(op, ParsedOp::StoreLocal(3)))
        && parsed[start_idx..=end_idx]
            .iter()
            .any(|(pc, op)| *pc == 394 && matches!(op, ParsedOp::StoreLocal(4)))
        && parsed[start_idx..=end_idx]
            .iter()
            .any(|(pc, op)| *pc == 442 && matches!(op, ParsedOp::StoreLocal(5)))
        && parsed[start_idx..=end_idx]
            .iter()
            .any(|(pc, op)| *pc == 445 && matches!(op, ParsedOp::Pop));
    if !has_shape {
        return;
    }
    parsed.splice(
        start_idx..=end_idx,
        [(
            176,
            ParsedOp::Site874TokenFinalizationAggregateProduce {
                token_slot: 5,
                exports_slot: 1,
                functions_slot: 2,
                constants_slot: 3,
                checksum_slot: 4,
            },
        )],
    );
    eprintln!(
        "[site874-generated-packed-helper-decode] rewrote pc_range=176..=445 token_slot=5 aggregate_slots=[1,2,3] checksum_slot=4 execute=true next=retry-site874-continuation-override"
    );
}

fn validate_site874_generated_aggregate_full_loop_gate(
    parsed: &[(usize, ParsedOp)],
) -> Result<(), String> {
    if site874_aggregate_full_loop_trip_proof_enabled() {
        return Ok(());
    }
    let has_generated_aggregate = parsed.iter().any(|(_, op)| {
        matches!(
            op,
            ParsedOp::Site874TokenFinalizationAggregateProduce { .. }
        )
    });
    if !has_generated_aggregate {
        return Ok(());
    }
    let has_primitive_index = parsed
        .iter()
        .any(|(_, op)| matches!(op, ParsedOp::PrimitiveStringIndexRead { .. }));
    if has_primitive_index {
        return Err(
            "site874 generated aggregate producer mouth-gated: primitive source-index \
             materialization plus aggregate publication requires the full-loop admission \
             gate after token-publication and aggregate-storeback proof \
             (set CRUFT_LEJIT_SITE874_FULL_LOOP_ADMISSION=1 for the proven opt-in path; \
             CRUFT_LEJIT_SITE874_AGGREGATE_FULL_LOOP_TRIP_PROOF=1 remains a diagnostic alias)"
                .to_string(),
        );
    }
    Ok(())
}

fn report_site874_token_finalization_lowering_prereq_probe(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) {
    if !site874_token_finalization_lowering_prereq_probe_enabled() {
        return;
    }
    let Some(prereqs) = site874_token_finalization_lowering_prereqs(parsed, locals) else {
        return;
    };
    eprintln!(
        "[site874-token-finalization-lowering-prereq-probe] prereqs={prereqs:?} execute=false next={}",
        if prereqs.unit_lowering_ready {
            "derive-token-finalization-string-consumers-as-one-unit-lowering"
        } else {
            "derive-token-finalization-prereq-shape-before-lowering"
        }
    );
}

fn validate_site874_token_finalization_mouth_gate(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> Result<(), String> {
    if !site874_token_finalization_mouth_gate_enabled()
        || site874_token_finalization_unit_lowering_enabled()
    {
        return Ok(());
    }
    let Some(prereqs) = site874_token_finalization_lowering_prereqs(parsed, locals) else {
        return Ok(());
    };
    if prereqs.unit_lowering_ready {
        return Err(format!(
            "site874 token finalization body mouth-gated: missing unit string-consumer lowering \
             for token slot {} (length_consumers={:?}, literal_eq_pcs={:?}, \
             charcode_call_pc={:?}, aggregate_slots={:?}, checksum_slot={:?}, \
             token_reset_slot={:?}, p_slot={:?}); enable \
             CRUFT_LEJIT_SITE874_TOKEN_FINALIZATION_STRING_CONSUMERS_UNIT_LOWERING only after \
             deriving the body-level length/equality/charCodeAt lowering as one unit",
            prereqs.token_slot,
            prereqs.length_consumers,
            prereqs.literal_eq_pcs,
            prereqs.charcode_call_pc,
            prereqs.aggregate_numeric_increment_slots,
            prereqs.checksum_numeric_store_slot,
            prereqs.token_reset_slot,
            prereqs.p_increment_slot
        ));
    }
    Ok(())
}

fn report_site874_token_finalization_body_probe(
    parsed: &[(usize, ParsedOp)],
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) {
    if !site874_token_finalization_body_probe_enabled() {
        return;
    }
    let Some(body) = site874_token_finalization_body(parsed, locals) else {
        return;
    };
    let body_ready = body.length_gate_pc.is_some()
        && body.literal_branch_count >= 3
        && body
            .literal_aggregate_slots
            .iter()
            .copied()
            .collect::<std::collections::BTreeSet<_>>()
            == [1u16, 2, 3]
                .into_iter()
                .collect::<std::collections::BTreeSet<_>>()
        && body.checksum_loop_pc.is_some()
        && body.checksum_store_pc.is_some()
        && body.token_reset_pc.is_some()
        && body.p_increment_store_pc.is_some();
    eprintln!(
        "[site874-token-finalization-body-probe] body={body:?} body_ready={body_ready} execute=false next={}",
        if body_ready {
            "derive-token-finalization-body-lowering-or-mouth-gate"
        } else {
            "derive-token-finalization-body-shape-before-lowering"
        }
    );
}

fn rewrite_and_chain_short_circuit(parsed: &mut Vec<(usize, ParsedOp)>) -> Result<(), String> {
    loop {
        let mut rewrote = false;
        for i in 0..parsed.len().saturating_sub(1) {
            let ParsedOp::JumpIfFalseKeep(keep_target) = parsed[i].1 else {
                continue;
            };
            if !matches!(parsed[i + 1].1, ParsedOp::Pop) {
                break;
            }
            let Some(target_idx) = parsed.iter().position(|(pc, _)| *pc == keep_target) else {
                break;
            };
            let rewritten_target = match parsed[target_idx].1 {
                ParsedOp::JumpIfFalse(end_target) => Some(end_target),
                ParsedOp::JumpIfTrue(_) => parsed.get(target_idx + 1).map(|(pc, _)| *pc),
                _ => None,
            };
            let Some(rewritten_target) = rewritten_target else {
                break;
            };
            let pop_pc = parsed[i + 1].0;
            let other_jump_into = parsed.iter().enumerate().any(|(j, (_, op))| {
                if j == i {
                    return false;
                }
                match op {
                    ParsedOp::Jump(t)
                    | ParsedOp::JumpIfTrue(t)
                    | ParsedOp::JumpIfFalse(t)
                    | ParsedOp::JumpIfFalseKeep(t)
                    | ParsedOp::JumpIfTrueKeep(t) => *t == keep_target || *t == pop_pc,
                    _ => false,
                }
            });
            if other_jump_into {
                break;
            }
            parsed[i].1 = ParsedOp::JumpIfFalse(rewritten_target);
            parsed.remove(i + 1);
            rewrote = true;
            break;
        }
        if rewrote {
            continue;
        }
        for i in 0..parsed.len().saturating_sub(1) {
            let ParsedOp::JumpIfTrueKeep(keep_target) = parsed[i].1 else {
                continue;
            };
            if !matches!(parsed[i + 1].1, ParsedOp::Pop) {
                break;
            }
            let Some(target_idx) = parsed.iter().position(|(pc, _)| *pc == keep_target) else {
                break;
            };
            let ParsedOp::JumpIfFalse(_) = parsed[target_idx].1 else {
                break;
            };
            let Some((true_pc, _)) = parsed.get(target_idx + 1) else {
                break;
            };
            let pop_pc = parsed[i + 1].0;
            let other_jump_into = parsed.iter().enumerate().any(|(j, (_, op))| {
                if j == i {
                    return false;
                }
                match op {
                    ParsedOp::Jump(t)
                    | ParsedOp::JumpIfTrue(t)
                    | ParsedOp::JumpIfFalse(t)
                    | ParsedOp::JumpIfFalseKeep(t)
                    | ParsedOp::JumpIfTrueKeep(t) => *t == keep_target || *t == pop_pc,
                    _ => false,
                }
            });
            if other_jump_into {
                break;
            }
            parsed[i].1 = ParsedOp::JumpIfTrue(*true_pc);
            parsed.remove(i + 1);
            rewrote = true;
            break;
        }
        if !rewrote {
            return Ok(());
        }
    }
}

fn rewrite_stable_helper_predicate_keep_chain(parsed: &mut Vec<(usize, ParsedOp)>) {
    let Some(start_idx) =
        (0..parsed.len()).find(|idx| stable_helper_predicate_keep_chain(parsed, *idx).is_some())
    else {
        return;
    };
    let Some(chain) = stable_helper_predicate_keep_chain(parsed, start_idx) else {
        return;
    };
    if chain.tail_call_count == 0 {
        return;
    }
    let Some(max_pc) = parsed.iter().map(|(pc, _)| *pc).max() else {
        return;
    };
    let false_pc = max_pc.saturating_add(1);
    let false_return_pc = false_pc.saturating_add(1);
    let mut i = start_idx;
    while i + 1 < parsed.len() {
        match parsed[i].1 {
            ParsedOp::JumpIfFalseKeep(_) if matches!(parsed[i + 1].1, ParsedOp::Pop) => {
                parsed[i].1 = ParsedOp::JumpIfFalse(false_pc);
                parsed.remove(i + 1);
            }
            ParsedOp::Return | ParsedOp::ReturnUndef => break,
            _ => i += 1,
        }
    }
    parsed.push((false_pc, ParsedOp::PushI32(0)));
    parsed.push((false_return_pc, ParsedOp::Return));
}

fn rewrite_predicate_leaf_terminal_keep_return(parsed: &mut Vec<(usize, ParsedOp)>) {
    let Some(max_pc) = parsed.iter().map(|(pc, _)| *pc).max() else {
        return;
    };
    let mut false_return_pc = max_pc.saturating_add(1);
    let mut i = 0usize;
    while i + 1 < parsed.len() {
        let ParsedOp::JumpIfFalseKeep(keep_target) = parsed[i].1 else {
            i += 1;
            continue;
        };
        if !matches!(parsed[i + 1].1, ParsedOp::Pop) {
            i += 1;
            continue;
        }
        let Some(target_idx) = parsed.iter().position(|(pc, _)| *pc == keep_target) else {
            i += 1;
            continue;
        };
        if !matches!(parsed[target_idx].1, ParsedOp::Return) {
            i += 1;
            continue;
        }
        let pop_pc = parsed[i + 1].0;
        let other_jump_into = parsed.iter().enumerate().any(|(j, (_, op))| {
            if j == i {
                return false;
            }
            match op {
                ParsedOp::Jump(t)
                | ParsedOp::JumpIfTrue(t)
                | ParsedOp::JumpIfFalse(t)
                | ParsedOp::JumpIfFalseKeep(t)
                | ParsedOp::JumpIfTrueKeep(t) => *t == keep_target || *t == pop_pc,
                _ => false,
            }
        });
        if other_jump_into {
            i += 1;
            continue;
        }
        parsed[i].1 = ParsedOp::JumpIfFalse(false_return_pc);
        parsed.remove(i + 1);
        parsed.push((false_return_pc, ParsedOp::PushI32(0)));
        parsed.push((false_return_pc.saturating_add(1), ParsedOp::Return));
        false_return_pc = false_return_pc.saturating_add(2);
    }
}

fn local_read_before_next_write(parsed: &[(usize, ParsedOp)], start_idx: usize, slot: u16) -> bool {
    for (_, op) in parsed.iter().skip(start_idx) {
        match op {
            ParsedOp::LoadLocal(s) if *s == slot => return true,
            ParsedOp::StoreLocal(s) | ParsedOp::InitLocal(s) if *s == slot => return false,
            ParsedOp::Jump(_) | ParsedOp::Return | ParsedOp::ReturnUndef => return false,
            _ => {}
        }
    }
    false
}

fn rewrite_string_concat_adds(parsed: &mut Vec<(usize, ParsedOp)>) -> Result<(), String> {
    let mut i = 0usize;
    while i < parsed.len() {
        if !matches!(parsed[i].1, ParsedOp::Add) {
            i += 1;
            continue;
        }
        let pc = parsed[i].0;
        let stack_before_add = simulate_block_stack(&parsed[..i]);
        let string_concat = stack_before_add.as_ref().and_then(|st| {
            let n = st.len();
            if n >= 2 {
                match (st[n - 2], st[n - 1]) {
                    (Origin::Local(left_slot), Origin::OwnedStringResult) => {
                        Some(ParsedOp::StringConcatOwnedResult { left_slot })
                    }

                    (Origin::Local(left_slot), right_origin)
                        if string_builder_local_value_adds_enabled()
                            && string_slot_hint_contains(left_slot) =>
                    {
                        if let Origin::Local(right_slot) = right_origin {
                            if local_read_before_next_write(parsed, i + 1, right_slot) {
                                Some(ParsedOp::StringConcatLocalValuePreserveRight { left_slot })
                            } else {
                                Some(ParsedOp::StringConcatLocalValue { left_slot })
                            }
                        } else {
                            Some(ParsedOp::StringConcatLocalValue { left_slot })
                        }
                    }
                    (Origin::OwnedStringResult, Origin::OwnedStringResult) => {
                        Some(ParsedOp::StringConcatOwnedPair)
                    }

                    (Origin::OwnedStringResult, _) if string_builder_adds_enabled() => {
                        Some(ParsedOp::StringConcatOwnedValue)
                    }
                    _ => None,
                }
            } else {
                None
            }
        });
        match string_concat {
            Some(op) => parsed[i].1 = op,
            None if stack_before_add
                .as_ref()
                .is_some_and(|st| st.iter().any(|o| *o == Origin::OwnedStringResult)) =>
            {
                return Err(format!(
                    "Add at pc={pc}: owned string result requires exact local-string concat/writeback shape"
                ));
            }
            None => {}
        }
        i += 1;
    }
    Ok(())
}

fn validate_string_concat_writebacks(parsed: &[(usize, ParsedOp)]) -> Result<(), String> {
    for window in parsed.windows(2) {
        let (concat_pc, left_slot, store_pc, dst) = match window {
            [(cpc, ParsedOp::StringConcatOwnedResult { left_slot }), (spc, ParsedOp::StoreLocal(dst))]
            | [(cpc, ParsedOp::StringConcatLocalValue { left_slot }), (spc, ParsedOp::StoreLocal(dst))]
            | [(cpc, ParsedOp::StringConcatLocalValuePreserveRight { left_slot }), (spc, ParsedOp::StoreLocal(dst))] => {
                (cpc, left_slot, spc, dst)
            }
            _ => continue,
        };
        if left_slot != dst {
            return Err(format!(
                "StoreLocal at pc={store_pc}: string concat/writeback destination slot {dst} does not match left string local at pc={concat_pc}"
            ));
        }
    }
    Ok(())
}

fn string_const_is(ptr: i64, len: i64, expected: &[u8]) -> bool {
    if len < 0 || len as usize != expected.len() || ptr == 0 {
        return false;
    }

    let bytes = unsafe { std::slice::from_raw_parts(ptr as *const u8, len as usize) };
    bytes == expected
}

fn string_builder_adds_enabled() -> bool {
    env_flag_enabled_by_default("CRUFT_LEJIT_STRING_BUILDER_ADDS")
}

pub fn string_builder_local_value_adds_enabled() -> bool {

    env_flag_enabled_by_default("CRUFT_LEJIT_STRING_BUILDER_LOCAL_VALUE_ADDS")
}

thread_local! {

    static STRING_SLOT_HINT: std::cell::RefCell<Vec<u16>> = const { std::cell::RefCell::new(Vec::new()) };
}

pub fn set_string_slot_hint(slots: &[u16]) {
    STRING_SLOT_HINT.with(|h| {
        let mut h = h.borrow_mut();
        h.clear();
        h.extend_from_slice(slots);
    });
}

pub fn clear_string_slot_hint() {
    STRING_SLOT_HINT.with(|h| h.borrow_mut().clear());
}

fn string_slot_hint_contains(slot: u16) -> bool {
    STRING_SLOT_HINT.with(|h| h.borrow().contains(&slot))
}

fn string_builder_index_reads_enabled() -> bool {
    env_flag_truthy("CRUFT_LEJIT_STRING_BUILDER_INDEX_READS")
}

fn validate_tdz_seed_strips(parsed: &[(usize, ParsedOp)]) -> Result<(), String> {
    for (seed_idx, (seed_pc, op)) in parsed.iter().enumerate() {
        let ParsedOp::TdzSeedLocal(slot) = *op else {
            continue;
        };
        let mut resolved = false;
        for (pc, later) in parsed.iter().skip(seed_idx + 1) {
            match *later {
                ParsedOp::LoadLocal(s) if s == slot => {
                    return Err(format!(
                        "PushTDZ seed at pc={seed_pc}: slot {slot} read before InitLocal at pc={pc}"
                    ));
                }
                ParsedOp::StoreLocal(s) if s == slot => {
                    return Err(format!(
                        "PushTDZ seed at pc={seed_pc}: slot {slot} ordinary StoreLocal before InitLocal at pc={pc}"
                    ));
                }
                ParsedOp::InitLocal(s) if s == slot => {
                    resolved = true;
                    break;
                }
                ParsedOp::Return | ParsedOp::ReturnUndef => break,
                _ => {}
            }
        }
        if !resolved {
            return Err(format!(
                "PushTDZ seed at pc={seed_pc}: slot {slot} is not proven overwritten by InitLocal before use"
            ));
        }
    }
    Ok(())
}

fn script_global_var_slot(
    constants: &ConstantsPool,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
    idx: u16,
) -> Option<u16> {
    let name = match constants.get(idx)? {
        Constant::String(s) => s,
        _ => return None,
    };
    locals.iter().enumerate().find_map(|(slot, desc)| {
        if desc.script_global_var && desc.depth == 0 && desc.name == *name {
            u16::try_from(slot).ok()
        } else {
            None
        }
    })
}

fn is_script_var_global_bind_helper(constants: &ConstantsPool, idx: u16) -> bool {
    matches!(
        constants.get(idx),
        Some(Constant::String(s)) if s == "__script_var_global_bind"
    )
}

fn consume_script_var_global_bind_mirror_nop(
    bc: &[u8],
    pc: &mut usize,
    constants: &ConstantsPool,
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> bool {
    let start = *pc;
    let Some(Op::PushConst) = bc.get(*pc).and_then(|b| op_from_byte(*b)) else {
        return false;
    };
    *pc += 1;
    if *pc + 2 > bc.len() {
        *pc = start;
        return false;
    }
    let name_idx = u16::from_le_bytes([bc[*pc], bc[*pc + 1]]);
    *pc += 2;

    let Some(Op::LoadLocal) = bc.get(*pc).and_then(|b| op_from_byte(*b)) else {
        *pc = start;
        return false;
    };
    *pc += 1;
    if *pc + 2 > bc.len() {
        *pc = start;
        return false;
    }
    let slot = u16::from_le_bytes([bc[*pc], bc[*pc + 1]]);
    *pc += 2;

    let Some(Op::PushTrue | Op::PushFalse) = bc.get(*pc).and_then(|b| op_from_byte(*b)) else {
        *pc = start;
        return false;
    };
    *pc += 1;

    let Some(Op::Call) = bc.get(*pc).and_then(|b| op_from_byte(*b)) else {
        *pc = start;
        return false;
    };
    *pc += 1;
    if bc.get(*pc).copied() != Some(3) {
        *pc = start;
        return false;
    }
    *pc += 1;

    let Some(Op::Pop) = bc.get(*pc).and_then(|b| op_from_byte(*b)) else {
        *pc = start;
        return false;
    };
    *pc += 1;

    if script_global_var_slot(constants, locals, name_idx) == Some(slot) {
        true
    } else {
        *pc = start;
        false
    }
}

fn describe_constant_name(constants: &ConstantsPool, idx: u16) -> String {
    match constants.get(idx) {
        Some(Constant::String(s)) => format!("{s:?}"),
        Some(other) => format!("{other:?}"),
        None => format!("<missing const {idx}>"),
    }
}

fn describe_constant_value(value: &Constant) -> String {
    match value {
        Constant::Number(n) => format!("Number({n})"),
        Constant::BigInt(s) => format!("BigInt({s})"),
        Constant::String(s) => format!("String({s:?})"),
        Constant::WtfString(units) => {
            format!("WtfString({:?})", String::from_utf16_lossy(units))
        }
        Constant::Regex { body, flags } => format!("Regex(/{body}/{flags})"),
        Constant::Function(proto) => format!("Function({})", proto.display_name),
        Constant::LazyFunction(_) => "LazyFunction".to_string(),
    }
}

fn describe_script_global_var_aliases(
    locals: &[rusty_js_bytecode::compiler::LocalDescriptor],
) -> String {
    let aliases: Vec<String> = locals
        .iter()
        .enumerate()
        .filter(|(_, desc)| desc.script_global_var && desc.depth == 0)
        .map(|(slot, desc)| format!("{slot}:{}", desc.name))
        .collect();
    if aliases.is_empty() {
        "<none>".to_string()
    } else {
        aliases.join(",")
    }
}

