    fn empty_proto(bytecode: Vec<u8>, params: u16) -> FunctionProto {
        let mut locals = Vec::<LocalDescriptor>::new();
        for i in 0..params {
            locals.push(LocalDescriptor {
                name: format!("arg{}", i),
                kind: rusty_js_ast::VariableKind::Let,
                depth: 0,
                top_level_lexical: false,
                script_global_var: false,
                pure_local_no_mirror: false,
            });
        }
        FunctionProto {
            bytecode,
            constants: ConstantsPool::new(),
            params,
            display_name: "test".to_string(),
            function_length: params,
            has_simple_parameters: true,
            locals,
            catch_param_names: Vec::new(),
            upvalues: Vec::<UpvalueDescriptor>::new(),
            rest_param_slot: None,
            arguments_slot: None,
            self_name_slot: None,
            self_name_is_immutable: false,
            param_prologue_end: 0,
            is_generator: false,
            line_starts: Vec::new().into(),
            source_map: Vec::new(),
            construct_tags: Vec::new(),
            source_url: String::new(),
            source_text: None,
            diagnostic_source_text: None,
            is_async: false,
            strict: false,
            is_method: false,
            arguments_forbidden: false,
            is_class_constructor: false,
        }
    }

    #[test]
    fn function_tier_refuses_named_property_write_without_value_descriptor_contract() {
        let mut constants = ConstantsPool::new();
        let symbol_idx = constants.intern(Constant::String("symbol".to_string()));
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 1);
        encode_op(&mut bc, Op::SetProp);
        encode_u16(&mut bc, symbol_idx);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::ReturnUndef);

        let mut proto = empty_proto(bc, 1);
        proto.constants = constants;

        assert!(function_tier_has_named_property_write(&proto));
        let err = compile_function(&proto).expect_err(
            "function-tier SetProp must stay interpreted until Value/descriptor lowering",
        );
        assert!(
            err.contains("function-tier SetPropOnObject disabled"),
            "unexpected compile error: {err}"
        );
    }

    fn osr_proto_with_locals(bytecode: Vec<u8>, locals_len: u16) -> FunctionProto {
        let mut proto = empty_proto(bytecode, 0);
        proto.locals = (0..locals_len)
            .map(|i| LocalDescriptor {
                name: format!("l{}", i),
                kind: rusty_js_ast::VariableKind::Var,
                depth: 0,
                top_level_lexical: false,
                script_global_var: false,
                pure_local_no_mirror: false,
            })
            .collect();
        proto
    }

    #[test]
    fn scanner_tokenvalue_store_routes_stable_call0_publication_boundary() {
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadUpvalue);
        encode_u16(&mut bc, 13);
        encode_op(&mut bc, Op::InitLocal);
        encode_u16(&mut bc, 95);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 95);
        encode_op(&mut bc, Op::Call);
        encode_u8(&mut bc, 0);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::StoreUpvalue);
        encode_u16(&mut bc, 14);
        encode_op(&mut bc, Op::ReturnUndef);

        let mut proto = osr_proto_with_locals(bc, 96);
        proto.locals[95].name = "scanString".to_string();

        let mut stable_callees = std::collections::HashSet::new();
        stable_callees.insert(95);
        let err = parse_bytecode_with_stable_callee_preloads(
            &proto.bytecode,
            &proto.constants,
            &proto.locals,
            &stable_callees,
            &std::collections::HashMap::new(),
            &std::collections::HashMap::new(),
            &std::collections::HashSet::new(),
            &std::collections::HashSet::new(),
            &std::collections::HashSet::new(),
        )
        .expect_err(
            "nonnumeric helper return publication to captured tokenValue must bail precisely",
        );

        assert!(
            err.contains("stable Call 0 helper 'scanString'")
                && err.contains("captured upvalue_slot=14")
                && err.contains("nonnumeric captured-value writeback ABI"),
            "unexpected error: {err}"
        );
    }

