    #[test]
    fn site874_generated_aggregate_mouth_gates_without_full_loop_trip_proof() {
        std::env::set_var("CRUFT_LEJIT_SITE874_FULL_LOOP_ADMISSION", "0");
        std::env::remove_var("CRUFT_LEJIT_SITE874_AGGREGATE_FULL_LOOP_TRIP_PROOF");
        let parsed = vec![
            (
                0,
                ParsedOp::PrimitiveStringIndexRead {
                    predicate_pc: 135,
                    accumulator_slot: 5,
                    receiver_slot: 0,
                    index_slot: 7,
                },
            ),
            (
                2,
                ParsedOp::Site874TokenFinalizationAggregateProduce {
                    token_slot: 5,
                    exports_slot: 1,
                    functions_slot: 2,
                    constants_slot: 3,
                    checksum_slot: 4,
                },
            ),
            (3, ParsedOp::ReturnUndef),
        ];

        let err = validate_site874_generated_aggregate_full_loop_gate(&parsed)
            .expect_err("site874 aggregate + primitive index must mouth-gate when opted out");
        assert!(err.contains("full-loop admission"));
        std::env::remove_var("CRUFT_LEJIT_SITE874_FULL_LOOP_ADMISSION");

        validate_site874_generated_aggregate_full_loop_gate(&parsed)
            .expect("default admission opens the proven site874 full-loop path");

        std::env::set_var("CRUFT_LEJIT_SITE874_FULL_LOOP_ADMISSION", "1");
        validate_site874_generated_aggregate_full_loop_gate(&parsed)
            .expect("explicit admission flag may open the proven site874 full-loop path");
        std::env::remove_var("CRUFT_LEJIT_SITE874_FULL_LOOP_ADMISSION");

        std::env::set_var("CRUFT_LEJIT_SITE874_AGGREGATE_FULL_LOOP_TRIP_PROOF", "1");
        validate_site874_generated_aggregate_full_loop_gate(&parsed)
            .expect("legacy diagnostic proof flag remains an alias");
        std::env::remove_var("CRUFT_LEJIT_SITE874_AGGREGATE_FULL_LOOP_TRIP_PROOF");
    }

