    #[test]
    fn string_charcode_mod_length_bound_matches_osr_slice_shape() {
        let char_idx = crate::ic_table::lookup_by_key("charCodeAt").expect("charCodeAt IC entry");
        let length_idx = crate::ic_table::lookup_by_key("length").expect("length IC entry");
        let parsed = vec![
            (0, ParsedOp::LoadLocal(4)),
            (3, ParsedOp::PushI32(3000000)),
            (8, ParsedOp::Lt),
            (9, ParsedOp::JumpIfFalse(61)),
            (14, ParsedOp::LoadLocal(3)),
            (17, ParsedOp::LoadLocal(2)),
            (20, ParsedOp::Dup),
            (21, ParsedOp::IcMethodResolve(char_idx)),
            (24, ParsedOp::LoadLocal(4)),
            (27, ParsedOp::LoadLocal(2)),
            (30, ParsedOp::IcPropertyGet(length_idx)),
            (33, ParsedOp::Mod),
            (34, ParsedOp::IcMethodCall(char_idx)),
            (36, ParsedOp::Add),
            (37, ParsedOp::Dup),
            (38, ParsedOp::StoreLocal(3)),
            (41, ParsedOp::Pop),
            (42, ParsedOp::LoadLocal(4)),
            (45, ParsedOp::PushI32(1)),
            (50, ParsedOp::Add),
            (51, ParsedOp::Dup),
            (52, ParsedOp::StoreLocal(4)),
            (55, ParsedOp::Pop),
            (56, ParsedOp::Jump(0)),
            (61, ParsedOp::ReturnUndef),
        ];

        assert_eq!(hoistable_string_charcode_receiver_slots(&parsed), vec![2]);
        let expr_stack = simulate_expr_stack(&parsed[..12]).expect("expr stack");
        assert_eq!(
            expr_stack
                .last()
                .and_then(|expr| expr.string_mod_length_index),
            Some((4, 2))
        );
        assert_eq!(string_charcode_mod_length_bound_sites(&parsed), vec![12]);
        assert_eq!(string_charcode_length_bound_index_slots(&parsed), vec![4]);
        assert_eq!(
            string_charcode_reduction_sites(&parsed),
            vec![StringCharCodeReductionSite {
                charcode_site: 12,
                add_site: 13,
                receiver_slot: 2,
                index_slot: 4,
                accumulator_slot: 3,
            }]
        );
        let slots = mixed_domain_slots(&parsed, &[]);
        assert!(slots.i64_slots.contains(&3));
        assert!(slots.i64_slots.contains(&4));
        assert!(!slots.f64_slots.contains(&3));
    }

    #[test]
    fn siper_admits_rewritten_string_method_ic_pair() {
        let char_idx = crate::ic_table::lookup_by_key("charCodeAt").expect("charCodeAt IC entry");
        let mut constants = ConstantsPool::new();
        let key_idx = constants.intern(Constant::String("charCodeAt".to_string()));
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::GetPropSkipForMethod);
        encode_u16(&mut bc, key_idx);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::CallMethodIcCached);
        encode_u8(&mut bc, 0);
        encode_op(&mut bc, Op::Return);

        let mut proto = osr_proto_with_locals(bc, 2);
        proto.constants = constants;
        let parsed = parse_bytecode(&proto.bytecode, &proto.constants, &proto.locals)
            .expect("rewritten string method IC pair should parse");
        assert!(
            parsed
                .iter()
                .any(|(_, op)| matches!(op, ParsedOp::IcMethodResolve(i) if *i == char_idx)),
            "expected IcMethodResolve({char_idx}), got {parsed:?}"
        );
        assert!(
            parsed
                .iter()
                .any(|(_, op)| matches!(op, ParsedOp::IcMethodCall(i) if *i == char_idx)),
            "expected IcMethodCall({char_idx}), got {parsed:?}"
        );
        compile_function(&proto).expect("rewritten string method IC pair should compile");
    }

