    #[test]
    fn ic_site_descriptors_track_parse_order_property_reads() {
        let mut constants = ConstantsPool::new();
        let x_idx = constants.intern(Constant::String("x".to_string()));
        let y_idx = constants.intern(Constant::String("y".to_string()));
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, x_idx);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, y_idx);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::ReturnUndef);

        let mut proto = osr_proto_with_locals(bc, 1);
        proto.constants = constants;
        let jit = compile_function_osr(&proto).expect("property-read body should compile");

        assert_eq!(jit.ic_site_ids.len(), 2);
        assert_eq!(jit.ic_site_descriptors.len(), 2);
        assert_eq!(jit.ic_site_descriptors[0].site_id, jit.ic_site_ids[0]);
        assert_eq!(jit.ic_site_descriptors[0].kind, IcSiteKind::GetPropOnObject);
        assert_eq!(jit.ic_site_descriptors[0].prop_idx, x_idx);
        assert_eq!(jit.ic_site_descriptors[1].site_id, jit.ic_site_ids[1]);
        assert_eq!(jit.ic_site_descriptors[1].kind, IcSiteKind::GetPropOnObject);
        assert_eq!(jit.ic_site_descriptors[1].prop_idx, y_idx);
    }

