    #[test]
    fn mwor_ext1_classifies_multi_write_shaped_object_candidate() {
        let mut constants = ConstantsPool::new();
        let x_idx = constants.intern(Constant::String("x".to_string()));
        let y_idx = constants.intern(Constant::String("y".to_string()));
        let mut bc = Vec::new();

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, x_idx);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::SetProp);
        encode_u16(&mut bc, x_idx);
        encode_op(&mut bc, Op::Pop);

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, y_idx);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 1);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::SetProp);
        encode_u16(&mut bc, y_idx);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::ReturnUndef);

        let parsed = parse_bytecode(&bc, &constants, &[]).expect("object update body should parse");
        let candidate = multi_write_osr_candidate(&parsed)
            .expect("two shaped SetProp sites on a direct-local receiver should classify");
        assert_eq!(candidate.receiver_slots, vec![0]);
        assert_eq!(candidate.prop_indices, vec![x_idx, y_idx]);
        assert_eq!(candidate.getprop_site_indices.len(), 2);
        assert_eq!(candidate.setprop_site_indices.len(), 2);

        let mut proto = osr_proto_with_locals(bc, 3);
        proto.constants = constants;
        std::env::remove_var("CRUFT_MWOR_GUARD_PROBE");
        let jit = compile_function_osr(&proto)
            .expect("MWOR-EXT 6 default-on path should carry MWOR metadata");
        assert_eq!(
            jit.multi_write_osr_candidate,
            Some(MultiWriteOsrCandidate {
                receiver_slots: vec![0],
                prop_indices: vec![x_idx, y_idx],
                getprop_site_indices: candidate.getprop_site_indices.clone(),
                setprop_site_indices: candidate.setprop_site_indices.clone(),
            })
        );

        std::env::set_var("CRUFT_MWOR_GUARD_PROBE", "0");
        let err = compile_function_osr(&proto)
            .expect_err("MWOR opt-out should keep the old multi-write RMW rejection");
        assert!(
            err.contains("OSR RMW not resume-eligible: write_count=2"),
            "unexpected compile error: {err}"
        );

        std::env::set_var("CRUFT_MWOR_GUARD_PROBE", "1");
        let jit = compile_function_osr(&proto)
            .expect("explicit guard-probe path should carry MWOR metadata");
        std::env::remove_var("CRUFT_MWOR_GUARD_PROBE");
        assert_eq!(
            jit.multi_write_osr_candidate,
            Some(MultiWriteOsrCandidate {
                receiver_slots: vec![0],
                prop_indices: vec![x_idx, y_idx],
                getprop_site_indices: candidate.getprop_site_indices,
                setprop_site_indices: candidate.setprop_site_indices,
            })
        );
    }

    #[test]
    fn mwor_ext_single_write_classifies_direct_local_setprop_candidate() {
        let mut constants = ConstantsPool::new();
        let x_idx = constants.intern(Constant::String("x".to_string()));
        let mut bc = Vec::new();

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 3);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::SetProp);
        encode_u16(&mut bc, x_idx);
        encode_op(&mut bc, Op::Pop);

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::ToNumeric);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::Inc);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 7);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 7);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::ReturnUndef);

        let parsed = parse_bytecode(&bc, &constants, &[]).expect("single-write body should parse");
        let candidate = multi_write_osr_candidate(&parsed)
            .expect("single direct-local SetProp should publish raw write metadata");
        assert_eq!(candidate.receiver_slots, vec![3]);
        assert_eq!(candidate.prop_indices, vec![x_idx]);
        assert!(candidate.getprop_site_indices.is_empty());
        assert_eq!(candidate.setprop_site_indices, vec![2]);

        let mut proto = osr_proto_with_locals(bc, 8);
        proto.constants = constants;
        let jit = compile_function_osr(&proto)
            .expect("single-write body should carry raw write metadata");
        assert_eq!(
            jit.multi_write_osr_candidate,
            Some(MultiWriteOsrCandidate {
                receiver_slots: vec![3],
                prop_indices: vec![x_idx],
                getprop_site_indices: Vec::new(),
                setprop_site_indices: vec![2],
            })
        );
    }

