    #[test]
    fn indexed_post_write_deopt_site_materializes_resume_table_entry() {
        let evidence = IndexedPostWriteResumeEvidence {
            setindex_site_index: 49,
            setindex_pc: 138,
            pop_site_index: 50,
            resume_pc_after_pop: 140,
            live_after_pop_slots: vec![4, 5],
            value_slot: 5,
            stack_value_discarded: true,
        };
        let candidate = indexed_post_write_deopt_site_candidate(&evidence);
        let site = indexed_post_write_deopt_site_from_candidate(&candidate);

        assert_eq!(site.resume_pc, 140);
        assert_eq!(site.stack_depth, 0);
        assert!(site.stack_slots.is_empty());
        assert!(matches!(
            site.reason,
            crate::deopt::DeoptReason::ICShapeMismatch { ic_id: 0 }
        ));
        assert_eq!(
            site.live_locals,
            vec![
                crate::deopt::DeoptLiveLocal {
                    interp_slot: 4,
                    jit_location: crate::deopt::JitLocation::Register(0),
                },
                crate::deopt::DeoptLiveLocal {
                    interp_slot: 5,
                    jit_location: crate::deopt::JitLocation::Register(1),
                }
            ]
        );
    }

    #[test]
    fn indexed_post_write_deopt_site_candidate_marks_overflow_payloads() {
        let evidence = IndexedPostWriteResumeEvidence {
            setindex_site_index: 9,
            setindex_pc: 30,
            pop_site_index: 10,
            resume_pc_after_pop: 33,
            live_after_pop_slots: vec![0, 1, 2, 3, 4, 5, 6, 7, 8],
            value_slot: 8,
            stack_value_discarded: true,
        };
        let candidate = indexed_post_write_deopt_site_candidate(&evidence);

        assert_eq!(candidate.resume_pc, 33);
        assert!(candidate.requires_spill_payload);
        assert_eq!(candidate.overflow_local_slots, vec![4, 5, 6, 7, 8]);
        assert!(candidate.requires_memory_payload);
        assert_eq!(candidate.memory_payload_local_slots, vec![8]);
        assert_eq!(
            candidate.deopt_live_local_table.last(),
            Some(&crate::deopt::DeoptLiveLocal {
                interp_slot: 8,
                jit_location: crate::deopt::JitLocation::StackSlot(0),
            })
        );
    }

