    #[test]
    fn committed_write_continuation_suffix_candidate_translates_sites_to_full_body() {
        let row = 8;
        let e_idx = 12;
        let c_idx = 13;
        let parsed = vec![
            (0, ParsedOp::LoadLocal(1)),
            (3, ParsedOp::PushI32(1)),
            (6, ParsedOp::Add),
            (7, ParsedOp::StoreLocal(1)),
            (10, ParsedOp::LoadLocal(row)),
            (13, ParsedOp::PushI32(1)),
            (16, ParsedOp::SetPropOnObject(e_idx)),
            (19, ParsedOp::Pop),
            (20, ParsedOp::LoadLocal(row)),
            (23, ParsedOp::GetPropOnObject(e_idx)),
            (26, ParsedOp::LoadLocal(row)),
            (29, ParsedOp::GetPropOnObject(c_idx)),
            (32, ParsedOp::Add),
        ];

        let Some(contract) = committed_write_continuation_suffix_candidate(&parsed) else {
            panic!("expected suffix CWC candidate");
        };
        assert_eq!(contract.start, 4);
        assert_eq!(contract.suffix_entry_pc, 10);
        assert_eq!(contract.candidate.receiver_slot, row);
        assert_eq!(contract.candidate.prop_idx, e_idx);
        assert_eq!(contract.candidate.setprop_site_index, 6);
        assert_eq!(contract.live_ins, vec![row]);
        assert!(contract.storebacks.is_empty());
        assert_eq!(contract.deopt_live_slots, vec![row]);
        assert_eq!(contract.deopt_site_candidate.resume_pc, 0);
        assert_eq!(contract.deopt_site_candidate.live_local_slots, vec![row]);
        assert_eq!(
            contract.deopt_site_candidate.argument_register_slots,
            vec![row]
        );
        assert_eq!(
            contract.deopt_site_candidate.fixed_register_arg_capacity,
            crate::deopt::DEOPT_TRIP_FIXED_REGISTER_ARG_CAPACITY as u8
        );
        assert!(contract
            .deopt_site_candidate
            .overflow_local_slots
            .is_empty());
        assert!(!contract.deopt_site_candidate.requires_spill_payload);
        assert_eq!(contract.frame_base_deopt_plan, None);
        assert_eq!(contract.deopt_site_candidate.stack_depth, 0);
        assert_eq!(contract.candidate.post_write_getprop_site_indices, vec![9]);
        assert_eq!(
            contract.candidate.other_post_write_getprop_site_indices,
            vec![11]
        );
        assert_eq!(
            contract.candidate.other_post_write_prop_indices,
            vec![c_idx]
        );
    }

