    #[test]
    fn mdoa_getprop_receiver_uses_object_domain_and_restores_number_domain() {
        let mut constants = ConstantsPool::new();
        let e_idx = constants.intern(Constant::String("e".to_string()));
        let mut bc = Vec::new();

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::GetIndex);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 3);

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 3);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, e_idx);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::ReturnUndef);

        let mut proto = osr_proto_with_locals(bc, 4);
        proto.constants = constants;
        let jit = compile_function_osr(&proto)
            .expect("mixed-domain GetProp receiver/result domains should compile");
        assert!(jit.mixed_domain_osr);
        assert!(
            jit.mixed_domain_slots.object_slots.contains(&0),
            "array receiver should be object-domain: {:?}",
            jit.mixed_domain_slots
        );
        assert!(
            jit.mixed_domain_slots.object_slots.contains(&3),
            "row loaded from arr[i] should remain object-domain: {:?}",
            jit.mixed_domain_slots
        );
        assert!(
            jit.mixed_domain_slots.i64_slots.contains(&1),
            "index slot should be SafeI64: {:?}",
            jit.mixed_domain_slots
        );
        assert!(
            jit.mixed_domain_slots.f64_slots.contains(&2),
            "accumulator should stay numeric: {:?}",
            jit.mixed_domain_slots
        );
    }

    #[test]
    fn mwor_mdoa_classifies_single_write_receiver_and_postinc_slots() {
        let mut constants = ConstantsPool::new();
        let x_idx = constants.intern(Constant::String("x".to_string()));
        let mut bc = Vec::new();

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::Lt);
        encode_op(&mut bc, Op::JumpIfFalse);
        encode_i32(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 3);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::SetProp);
        encode_u16(&mut bc, x_idx);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::ToNumeric);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::Inc);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 7);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 7);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::ReturnUndef);

        let parsed = parse_bytecode(&bc, &constants, &[]).expect("single-write loop should parse");
        let slots = mixed_domain_slots(&parsed, &[]);
        assert_eq!(slots.object_slots, vec![3]);
        assert!(
            slots.i64_slots.contains(&0)
                && slots.i64_slots.contains(&4)
                && slots.i64_slots.contains(&6)
                && slots.i64_slots.contains(&7),
            "expected loop bound, induction, and postinc temps to be SafeI64, got {slots:?}"
        );
        assert!(
            !slots.f64_slots.contains(&4)
                && !slots.f64_slots.contains(&6)
                && !slots.f64_slots.contains(&7),
            "SafeI64 loop slots must not also be f64 slots: {slots:?}"
        );

        let mut proto = osr_proto_with_locals(bc, 8);
        proto.constants = constants;
        let jit = compile_function_osr(&proto)
            .expect("single-write loop should compile with MWOR-backed MDOA");
        assert_eq!(jit.mixed_domain_slots.object_slots, vec![3]);
        assert!(jit.mixed_domain_slots.i64_slots.contains(&0));
        assert!(jit.mixed_domain_slots.i64_slots.contains(&4));
    }

