    #[test]
    fn mdoa_ext11_packed_read_admits_tonumeric_only_with_numeric_domain_proof() {
        let parsed = vec![
            (0, ParsedOp::LoadLocal(0)),
            (3, ParsedOp::LoadLocal(1)),
            (6, ParsedOp::ToNumeric),
            (7, ParsedOp::GetIndexOnObject),
            (8, ParsedOp::StoreLocal(2)),
            (11, ParsedOp::ReturnUndef),
        ];
        let numeric_domains = vec![
            LocalDomain::ObjectBits,
            LocalDomain::SafeI64,
            LocalDomain::NumberF64,
        ];
        let object_index_domains = vec![
            LocalDomain::ObjectBits,
            LocalDomain::ObjectBits,
            LocalDomain::NumberF64,
        ];

        assert_eq!(
            packed_read_elision_slots(&parsed, Some(&numeric_domains)),
            vec![0]
        );
        assert!(
            packed_read_elision_slots(&parsed, None).is_empty(),
            "no domain proof must preserve the old syntactic rejection"
        );
        assert!(
            packed_read_elision_slots(&parsed, Some(&object_index_domains)).is_empty(),
            "object-domain ToNumeric may observe object-to-primitive coercion"
        );
    }

