    #[test]
    fn indexed_result_property_read_parses_as_object_getprop() {
        let mut constants = ConstantsPool::new();
        let value_idx = constants.intern(Constant::String("value".to_string()));
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 3);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 7);
        encode_op(&mut bc, Op::GetIndex);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, value_idx);
        encode_op(&mut bc, Op::Return);

        let parsed = parse_bytecode(&bc, &constants, &[])
            .expect("indexed object result should admit a guarded property read");
        assert_eq!(parsed.len(), 5, "unexpected parse: {parsed:?}");
        assert!(matches!(parsed[0], (0, ParsedOp::LoadLocal(3))));
        assert!(matches!(parsed[1], (3, ParsedOp::LoadLocal(7))));
        assert!(matches!(parsed[2], (6, ParsedOp::GetIndexOnObject)));
        assert!(matches!(
            parsed[3],
            (7, ParsedOp::GetPropOnObject(idx)) if idx == value_idx
        ));
        assert!(matches!(parsed[4], (10, ParsedOp::Return)));
    }

