    #[test]
    fn object_index_result_uses_object_helper_when_next_store_is_object_domain() {
        let parsed = vec![
            (0, ParsedOp::LoadLocal(3)),
            (1, ParsedOp::LoadLocal(7)),
            (2, ParsedOp::GetIndexOnObject),
            (3, ParsedOp::InitLocal(8)),
            (4, ParsedOp::ReturnUndef),
        ];
        let mut domains = vec![LocalDomain::RawF64; 9];
        domains[3] = LocalDomain::ObjectBits;
        domains[7] = LocalDomain::SafeI64;
        domains[8] = LocalDomain::ObjectBits;

        assert!(getindex_result_flows_to_object_local(
            &parsed,
            2,
            Some(&domains)
        ));

        domains[8] = LocalDomain::NumberF64;
        assert!(!getindex_result_flows_to_object_local(
            &parsed,
            2,
            Some(&domains)
        ));
    }

    #[test]
    fn indexed_object_callee_callmethod_parses_as_indexed_direct1() {
        let constants = ConstantsPool::new();
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 0);
        encode_op(&mut bc, Op::GetIndex);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 255);
        encode_op(&mut bc, Op::BitAnd);
        encode_op(&mut bc, Op::CallMethod);
        encode_u8(&mut bc, 1);
        encode_op(&mut bc, Op::Return);

        let parsed =
            parse_bytecode(&bc, &constants, &[]).expect("indexed closure call should parse");
        assert!(
            parsed
                .iter()
                .any(|(_, op)| matches!(op, ParsedOp::CallIndexedDirect1)),
            "expected indexed CallMethod to become CallIndexedDirect1, got {parsed:?}"
        );
        let getindex_idx = parsed
            .iter()
            .position(|(_, op)| matches!(op, ParsedOp::GetIndexOnObject))
            .expect("GetIndex should parse");
        assert!(getindex_result_flows_to_indexed_direct_call(
            &parsed,
            getindex_idx
        ));
    }

