    #[test]
    fn indexed_additive_closure_loop_descriptor_accepts_closure_factory_shape() {
        let mut leaves = [DirectCallLeaf::Arg0AddConst(0.0); 16];
        leaves[..4].copy_from_slice(&[
            DirectCallLeaf::Arg0AddConst(1.0),
            DirectCallLeaf::Arg0AddConst(3.0),
            DirectCallLeaf::Arg0AddConst(7.0),
            DirectCallLeaf::Arg0AddConst(11.0),
        ]);
        let parsed = vec![
            (0, ParsedOp::LoadLocal(4)),
            (3, ParsedOp::PushI32(3_000_000)),
            (8, ParsedOp::Lt),
            (9, ParsedOp::JumpIfFalse(67)),
            (14, ParsedOp::LoadLocal(3)),
            (17, ParsedOp::LoadLocal(2)),
            (20, ParsedOp::Dup),
            (21, ParsedOp::LoadLocal(4)),
            (24, ParsedOp::PushI32(3)),
            (29, ParsedOp::BitAnd),
            (30, ParsedOp::GetIndexOnObject),
            (31, ParsedOp::LoadLocal(4)),
            (34, ParsedOp::PushI32(255)),
            (39, ParsedOp::BitAnd),
            (
                40,
                ParsedOp::CallIndexedDirectLeafSwitch1 {
                    receiver_slot: 2,
                    index_mask: Some(PackedReadIndexMask::I32(3)),
                    index_slot: Some(4),
                    leaf_count: 4,
                    leaves,
                },
            ),
            (42, ParsedOp::Add),
            (43, ParsedOp::Dup),
            (44, ParsedOp::StoreLocal(3)),
            (47, ParsedOp::Pop),
            (48, ParsedOp::LoadLocal(4)),
            (51, ParsedOp::PushI32(1)),
            (56, ParsedOp::Add),
            (57, ParsedOp::Dup),
            (58, ParsedOp::StoreLocal(4)),
            (61, ParsedOp::Pop),
            (62, ParsedOp::Jump(0)),
            (67, ParsedOp::ReturnUndef),
        ];

        assert_eq!(
            indexed_additive_closure_loop_descriptors(&parsed),
            vec![IndexedAdditiveClosureLoopDescriptor {
                accumulator_slot: 3,
                induction_slot: 4,
                bound_const: 3_000_000,
                induction_step_const: 1,
                arg_mask_const: 255,
                leaf_mask_const: 3,
                leaf_constants: vec![1, 3, 7, 11],
            }]
        );
    }

