    #[test]
    fn indexed_object_callee_callmethod_only_admits_arity_one() {
        let constants = ConstantsPool::new();
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 0);
        encode_op(&mut bc, Op::GetIndex);
        encode_op(&mut bc, Op::CallMethod);
        encode_u8(&mut bc, 0);

        let err = parse_bytecode(&bc, &constants, &[])
            .expect_err("arity-0 indexed method call should stay outside the rung");
        assert!(
            err.contains("no preceding IcMethodResolve"),
            "unexpected parse error: {err}"
        );
    }

