    #[test]
    fn mdoa_ext40_classifies_postinc_update_temporaries_by_default_with_opt_out() {
        let mut bc = Vec::new();

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::GetIndex);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::Pop);

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::ToNumeric);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 7);
        encode_op(&mut bc, Op::Inc);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 8);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 8);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 7);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::ReturnUndef);

        std::env::set_var("CRUFT_LEJIT_MDOA", "1");

        let proto = osr_proto_with_locals(bc.clone(), 11);
        let default_jit = compile_function_osr(&proto)
            .expect("MDOA should accept typed-array postinc temporary classifier shape");

        assert!(default_jit.mixed_domain_osr);
        assert_eq!(
            default_jit.mixed_domain_slots,
            MixedDomainSlots {
                object_slots: vec![0],
                object_or_null_slots: Vec::new(),
                i64_slots: vec![6, 7, 8],
                f64_slots: vec![4],
                string_slots: vec![],
            }
        );

        std::env::set_var("CRUFT_LEJIT_MDOA_POSTINC_TEMPS", "0");
        let opt_out_proto = osr_proto_with_locals(bc, 11);
        let opt_out_jit = compile_function_osr(&opt_out_proto)
            .expect("MDOA should still compile without postinc temporary classification");

        std::env::remove_var("CRUFT_LEJIT_MDOA");
        std::env::remove_var("CRUFT_LEJIT_MDOA_POSTINC_TEMPS");

        assert!(opt_out_jit.mixed_domain_osr);
        assert_eq!(
            opt_out_jit.mixed_domain_slots,
            MixedDomainSlots {
                object_slots: vec![0],
                object_or_null_slots: Vec::new(),
                i64_slots: vec![6],
                f64_slots: vec![4, 7, 8],
                string_slots: vec![],
            }
        );
    }

