    #[test]
    fn mdoa_storeback_defaults_to_written_slots_with_opt_out() {
        let written_slots = [4_u16, 3_u16, 99_u16]
            .into_iter()
            .collect::<std::collections::HashSet<_>>();

        std::env::remove_var("CRUFT_LEJIT_MDOA_STORE_WRITTEN");
        assert_eq!(
            osr_storeback_slots_for(true, 5, &written_slots, false),
            vec![3, 4]
        );

        std::env::set_var("CRUFT_LEJIT_MDOA_STORE_WRITTEN", "0");
        assert_eq!(
            osr_storeback_slots_for(true, 5, &written_slots, false),
            vec![0, 1, 2, 3, 4]
        );

        assert_eq!(
            osr_storeback_slots_for(true, 5, &written_slots, true),
            vec![3, 4]
        );
        assert_eq!(
            osr_storeback_slots_for(false, 5, &written_slots, true),
            vec![0, 1, 2, 3, 4]
        );

        std::env::remove_var("CRUFT_LEJIT_MDOA_STORE_WRITTEN");
    }

