    #[test]
    fn fannkuch_packed_length_metadata_consumption_is_default_on_and_disable_gated() {
        let _guard = ENV_TEST_LOCK.lock().unwrap();
        std::env::remove_var("CRUFT_LEJIT_FANNKUCH_PACKED_LENGTH_METADATA_CONSUME");
        std::env::remove_var("CRUFT_LEJIT_FANNKUCH_PACKED_LENGTH_METADATA_CONSUME_PROBE");
        assert!(
            fannkuch_packed_length_admission_metadata_consumes_indexed_site(
                8,
                24,
                "getindex",
                Some(3),
                Some(16),
                Some(16),
                Some(0)
            )
        );

        std::env::set_var("CRUFT_LEJIT_FANNKUCH_PACKED_LENGTH_METADATA_CONSUME", "0");
        assert!(
            !fannkuch_packed_length_admission_metadata_consumes_indexed_site(
                8,
                24,
                "getindex",
                Some(3),
                Some(16),
                Some(16),
                Some(0)
            )
        );

        std::env::set_var(
            "CRUFT_LEJIT_FANNKUCH_PACKED_LENGTH_METADATA_CONSUME_PROBE",
            "1",
        );
        assert!(
            fannkuch_packed_length_admission_metadata_consumes_indexed_site(
                8,
                24,
                "getindex",
                Some(3),
                Some(16),
                Some(16),
                Some(0)
            )
        );
        assert!(
            fannkuch_packed_length_admission_metadata_consumes_indexed_site(
                9,
                25,
                "setindex",
                Some(2),
                Some(16),
                None,
                None
            )
        );
        assert!(
            fannkuch_packed_length_admission_metadata_consumes_indexed_site(
                10,
                30,
                "getindex",
                Some(3),
                None,
                Some(29),
                Some(1)
            )
        );
        assert!(
            fannkuch_packed_length_admission_metadata_consumes_indexed_site(
                11,
                31,
                "setindex",
                Some(3),
                Some(29),
                None,
                None
            )
        );
        assert!(
            !fannkuch_packed_length_admission_metadata_consumes_indexed_site(
                10,
                30,
                "getindex",
                Some(3),
                None,
                Some(29),
                Some(0)
            )
        );
        std::env::remove_var("CRUFT_LEJIT_FANNKUCH_PACKED_LENGTH_METADATA_CONSUME");
        std::env::remove_var("CRUFT_LEJIT_FANNKUCH_PACKED_LENGTH_METADATA_CONSUME_PROBE");
    }

