    #[test]
    fn direct_call_leaf_const_i32_result_folds_mulmod_fixture() {
        assert_eq!(
            direct_call_leaf_const_i32_result(
                DirectCallLeaf::Arg0LoopSumMulMod {
                    mul: 17,
                    modulus: 97,
                    step: 1,
                },
                800,
            ),
            Some(38351.0)
        );
        assert_eq!(
            direct_call_leaf_const_i32_result(
                DirectCallLeaf::Arg0LoopSumMulMod {
                    mul: 17,
                    modulus: 97,
                    step: 2,
                },
                800,
            ),
            None
        );
        assert_eq!(
            direct_call_leaf_const_i32_result(DirectCallLeaf::Arg0AddConst(1.0), 800),
            None
        );
        assert_eq!(
            direct_call_leaf_const_i32_result(DirectCallLeaf::Arg0ArrayPushPop64, -1),
            Some(0.0)
        );
        assert_eq!(
            direct_call_leaf_const_i32_result(DirectCallLeaf::Arg0ArrayPushPop64, 64),
            Some(64.0)
        );
        assert_eq!(
            direct_call_leaf_const_i32_result(DirectCallLeaf::Arg0ArrayPushPop64, 65),
            Some(128.0)
        );
        assert_eq!(
            direct_call_leaf_const_i32_result(DirectCallLeaf::Arg0ArrayPushPop64, 20_000),
            Some(199_988_048.0)
        );
    }

