    #[test]
    fn mdoa_postinc_temp_storeback_excludes_only_self_contained_temps() {
        let parsed = vec![
            (0, ParsedOp::LoadLocal(4)),
            (3, ParsedOp::ToNumeric),
            (4, ParsedOp::Dup),
            (5, ParsedOp::StoreLocal(6)),
            (8, ParsedOp::Inc),
            (9, ParsedOp::StoreLocal(7)),
            (12, ParsedOp::LoadLocal(7)),
            (15, ParsedOp::StoreLocal(4)),
            (18, ParsedOp::LoadLocal(6)),
            (21, ParsedOp::Pop),
        ];
        assert_eq!(postinc_temp_storeback_exclusions(&parsed), vec![6, 7]);

        let with_reset = vec![
            (0, ParsedOp::LoadLocal(4)),
            (3, ParsedOp::ToNumeric),
            (4, ParsedOp::Dup),
            (5, ParsedOp::StoreLocal(6)),
            (8, ParsedOp::Inc),
            (9, ParsedOp::StoreLocal(7)),
            (12, ParsedOp::LoadLocal(7)),
            (15, ParsedOp::StoreLocal(4)),
            (18, ParsedOp::ResetLocalCellNop),
            (19, ParsedOp::LoadLocal(6)),
            (22, ParsedOp::Pop),
        ];
        assert_eq!(postinc_temp_storeback_exclusions(&with_reset), vec![6, 7]);

        let externally_read = vec![
            (0, ParsedOp::LoadLocal(4)),
            (3, ParsedOp::ToNumeric),
            (4, ParsedOp::Dup),
            (5, ParsedOp::StoreLocal(6)),
            (8, ParsedOp::Inc),
            (9, ParsedOp::StoreLocal(7)),
            (12, ParsedOp::LoadLocal(7)),
            (15, ParsedOp::StoreLocal(4)),
            (18, ParsedOp::LoadLocal(6)),
            (21, ParsedOp::Pop),
            (22, ParsedOp::LoadLocal(6)),
            (25, ParsedOp::Pop),
        ];
        assert_eq!(postinc_temp_storeback_exclusions(&externally_read), vec![7]);
    }

