    #[test]
    fn mdoa_ext23_groups_affine_index_sites_by_receiver_and_index_slot() {
        let mut bc = Vec::new();
        for offset in [0, 1, 2] {
            encode_op(&mut bc, Op::LoadLocal);
            encode_u16(&mut bc, 0);
            encode_op(&mut bc, Op::LoadLocal);
            encode_u16(&mut bc, 1);
            if offset > 0 {
                encode_op(&mut bc, Op::PushI32);
                encode_i32(&mut bc, offset);
                encode_op(&mut bc, Op::Add);
            }
            encode_op(&mut bc, Op::GetIndex);
            encode_op(&mut bc, Op::StoreLocal);
            encode_u16(&mut bc, 2);
        }
        encode_op(&mut bc, Op::ReturnUndef);

        let proto = osr_proto_with_locals(bc, 3);
        let jit = compile_function_osr(&proto).expect("affine packed reads should compile");

        assert_eq!(jit.packed_read_affine_index_sites.len(), 3);
        assert_eq!(jit.packed_read_affine_index_groups.len(), 1);
        assert_eq!(
            jit.packed_read_affine_index_groups[0],
            PackedReadAffineIndexGroup {
                receiver_slot: 0,
                index_slot: 1,
                max_non_negative_offset: 2,
                site_indices: jit
                    .packed_read_affine_index_sites
                    .iter()
                    .map(|site| site.site_index)
                    .collect(),
            }
        );
    }

