    #[test]
    fn r252_splits_strict_inbounds_from_oob_absence_bounded_sites() {
        let strict_parsed = vec![
            (0, ParsedOp::LoadLocal(1)),
            (1, ParsedOp::PushI32(5)),
            (2, ParsedOp::Add),
            (3, ParsedOp::PushI32(15)),
            (4, ParsedOp::BitAnd),
            (5, ParsedOp::StoreLocal(2)),
            (6, ParsedOp::LoadLocal(0)),
            (7, ParsedOp::LoadLocal(2)),
            (8, ParsedOp::GetIndexOnObject),
        ];
        let oob_absence_parsed = vec![
            (0, ParsedOp::LoadLocal(1)),
            (1, ParsedOp::PushI32(5)),
            (2, ParsedOp::Add),
            (3, ParsedOp::LoadLocal(3)),
            (4, ParsedOp::BitAnd),
            (5, ParsedOp::StoreLocal(2)),
            (6, ParsedOp::LoadLocal(0)),
            (7, ParsedOp::LoadLocal(2)),
            (8, ParsedOp::GetIndexOnObject),
        ];
        let domains = [
            LocalDomain::ObjectBits,
            LocalDomain::SafeI64,
            LocalDomain::SafeI64,
            LocalDomain::SafeI64,
        ];
        let strict_sites = packed_read_bounded_index_sites(&strict_parsed, Some(&domains));
        let oob_absence_sites =
            packed_read_bounded_index_sites(&oob_absence_parsed, Some(&domains));

        assert_eq!(strict_sites.len(), 1);
        assert_eq!(strict_sites[0].mask, PackedReadIndexMask::I32(15));
        assert_eq!(
            packed_read_strict_inbounds_site_indices(&strict_sites),
            [8usize].into_iter().collect()
        );

        assert_eq!(oob_absence_sites.len(), 1);
        assert_eq!(oob_absence_sites[0].mask, PackedReadIndexMask::Local(3));
        assert!(packed_read_strict_inbounds_site_indices(&oob_absence_sites).is_empty());
    }

