    #[test]
    fn mdoa_ext25_classifies_constant_loop_bound_for_affine_group() {
        let mut bc = Vec::new();
        let loop_top = bc.len();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 1022);
        encode_op(&mut bc, Op::Lt);
        encode_op(&mut bc, Op::JumpIfFalse);
        let jif_disp_at = bc.len();
        encode_i32(&mut bc, 0);
        for offset in [0, 1, 2] {
            encode_op(&mut bc, Op::LoadLocal);
            encode_u16(&mut bc, 0);
            encode_op(&mut bc, Op::LoadLocal);
            encode_u16(&mut bc, 1);
            if offset > 0 {
                encode_op(&mut bc, Op::PushI32);
                encode_i32(&mut bc, offset);
                encode_op(&mut bc, Op::Add);
            }
            encode_op(&mut bc, Op::GetIndex);
            encode_op(&mut bc, Op::StoreLocal);
            encode_u16(&mut bc, 2);
        }
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::Inc);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::Jump);
        let jump_disp_at = bc.len();
        let jump_next_pc = bc.len() + 4;
        encode_i32(&mut bc, loop_top as i32 - jump_next_pc as i32);
        let exit_pc = bc.len();
        let jif_disp = exit_pc as i32 - (jif_disp_at + 4) as i32;
        bc[jif_disp_at..jif_disp_at + 4].copy_from_slice(&jif_disp.to_le_bytes());
        encode_op(&mut bc, Op::ReturnUndef);
        let _ = jump_disp_at;

        let proto = osr_proto_with_locals(bc, 3);
        let jit = compile_function_osr(&proto).expect("affine loop-bound proof should compile");

        assert_eq!(jit.packed_read_affine_index_groups.len(), 1);
        assert_eq!(jit.packed_read_affine_loop_bound_proofs.len(), 1);
        assert_eq!(
            jit.packed_read_affine_loop_bound_proofs[0],
            PackedReadAffineLoopBoundProof {
                receiver_slot: 0,
                index_slot: 1,
                max_non_negative_offset: 2,
                exclusive_upper_bound: PackedReadAffineUpperBound::Constant(1022),
            }
        );
    }

