    #[test]
    fn mixed_domain_slots_admits_int_typed_array_reduction_accumulator_by_default() {
        let parsed = vec![
            (0, ParsedOp::LoadLocal(1)),
            (1, ParsedOp::LoadLocal(0)),
            (2, ParsedOp::IcPropertyGet(0)),
            (3, ParsedOp::Lt),
            (4, ParsedOp::JumpIfFalse(0)),
            (5, ParsedOp::LoadLocal(4)),
            (6, ParsedOp::LoadLocal(0)),
            (7, ParsedOp::LoadLocal(1)),
            (8, ParsedOp::GetIndexOnObject),
            (9, ParsedOp::Add),
            (10, ParsedOp::Dup),
            (11, ParsedOp::StoreLocal(4)),
            (12, ParsedOp::Pop),
            (13, ParsedOp::LoadLocal(1)),
            (14, ParsedOp::Inc),
            (15, ParsedOp::StoreLocal(1)),
            (16, ParsedOp::ReturnUndef),
        ];
        let specs = vec![TypedArrayKindSpec {
            receiver_slot: 0,
            kind: 1,
        }];

        std::env::remove_var("CRUFT_LEJIT_MDOA_INT_REDUCTION");
        assert!(mixed_domain_slots(&parsed, &specs).i64_slots.contains(&4));

        std::env::set_var("CRUFT_LEJIT_MDOA_INT_REDUCTION", "0");
        assert!(!mixed_domain_slots(&parsed, &specs).i64_slots.contains(&4));

        std::env::set_var("CRUFT_LEJIT_MDOA_INT_REDUCTION", "true");
        assert!(mixed_domain_slots(&parsed, &specs).i64_slots.contains(&4));
        std::env::remove_var("CRUFT_LEJIT_MDOA_INT_REDUCTION");
    }

