    #[test]
    fn mdoa_ext27_affine_fast_compiles_under_loop_bound_proof() {
        crate::deopt::set_inline_ic_layout(crate::deopt::InlineIcLayout {
            slot_stride: 64,
            slot_payload_off: 8,
            object_shape_off: 0,
            object_shape_values_off: 0,
            vec_ptr_off: 0,
            value_size: 16,
            value_number_payload_off: 8,
            value_payload_off: 8,
            value_tag_number: 1,
            value_tag_string: 4,
            value_tag_object: 7,
            verified: true,
            object_array_dense_off: 16,
            object_dense_elements_off: 24,
            vec_len_off: 8,
            vec_cap_off: 16,
            array_verified: true,
            object_array_packed_all_safe_i64_off: 31,
            object_array_packed_off: 32,
            object_dense_doubles_off: 40,
            object_dense_i64_sidecar_valid_off: 33,
        });
        std::env::set_var("CRUFT_AGE_PACKED_READ", "1");
        std::env::remove_var("CRUFT_LEJIT_PACKED_READ_AFFINE_FAST");
        assert!(env_flag_enabled_by_default(
            "CRUFT_LEJIT_PACKED_READ_AFFINE_FAST"
        ));
        std::env::set_var("CRUFT_LEJIT_PACKED_READ_AFFINE_FAST", "0");
        assert!(!env_flag_enabled_by_default(
            "CRUFT_LEJIT_PACKED_READ_AFFINE_FAST"
        ));
        std::env::remove_var("CRUFT_LEJIT_PACKED_READ_AFFINE_FAST");

        let mut bc = Vec::new();
        let loop_top = bc.len();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 3);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 2);
        encode_op(&mut bc, Op::Sub);
        encode_op(&mut bc, Op::Lt);
        encode_op(&mut bc, Op::JumpIfFalse);
        let jif_disp_at = bc.len();
        encode_i32(&mut bc, 0);
        for offset in [0, 1, 2] {
            encode_op(&mut bc, Op::LoadLocal);
            encode_u16(&mut bc, 0);
            encode_op(&mut bc, Op::LoadLocal);
            encode_u16(&mut bc, 1);
            if offset > 0 {
                encode_op(&mut bc, Op::PushI32);
                encode_i32(&mut bc, offset);
                encode_op(&mut bc, Op::Add);
            }
            encode_op(&mut bc, Op::GetIndex);
            encode_op(&mut bc, Op::StoreLocal);
            encode_u16(&mut bc, 2);
        }
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::Inc);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::Jump);
        let jump_disp_at = bc.len();
        let jump_next_pc = bc.len() + 4;
        encode_i32(&mut bc, loop_top as i32 - jump_next_pc as i32);
        let exit_pc = bc.len();
        let jif_disp = exit_pc as i32 - (jif_disp_at + 4) as i32;
        bc[jif_disp_at..jif_disp_at + 4].copy_from_slice(&jif_disp.to_le_bytes());
        encode_op(&mut bc, Op::ReturnUndef);
        let _ = jump_disp_at;

        let proto = osr_proto_with_locals(bc, 4);
        let jit = compile_function_inner(&proto, true, false, true)
            .expect("affine fast should compile under loop-bound proof");
        std::env::set_var("CRUFT_LEJIT_PACKED_READ_I64_REDUCTION_PROBE", "1");
        let i64_jit = compile_function_inner(&proto, true, false, true)
            .expect("affine i64 metadata should compile under loop-bound proof");
        let f64_fallback_jit = compile_function_osr_mdoa_f64(&proto)
            .expect("affine f64 fallback should compile under loop-bound proof");

        std::env::remove_var("CRUFT_AGE_PACKED_READ");
        std::env::remove_var("CRUFT_LEJIT_PACKED_READ_AFFINE_FAST");
        std::env::remove_var("CRUFT_LEJIT_PACKED_READ_I64_REDUCTION_PROBE");
        crate::deopt::set_inline_ic_layout(crate::deopt::InlineIcLayout::default());

        assert_eq!(jit.packed_read_affine_loop_bound_proofs.len(), 1);
        assert_eq!(i64_jit.packed_read_all_safe_i64_slots, vec![0]);
        assert!(f64_fallback_jit.packed_read_all_safe_i64_slots.is_empty());
    }

