    fn compile_raw_packed_read_import(observe: bool) {
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::GetIndex);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::ReturnUndef);

        crate::deopt::set_inline_ic_layout(crate::deopt::InlineIcLayout {
            slot_stride: 64,
            slot_payload_off: 8,
            object_shape_off: 0,
            object_shape_values_off: 0,
            vec_ptr_off: 0,
            value_size: 16,
            value_number_payload_off: 8,
            value_payload_off: 8,
            value_tag_number: 1,
            value_tag_string: 4,
            value_tag_object: 7,
            verified: true,
            object_array_dense_off: 16,
            object_dense_elements_off: 24,
            vec_len_off: 8,
            vec_cap_off: 16,
            array_verified: true,
            object_array_packed_all_safe_i64_off: 31,
            object_array_packed_off: 32,
            object_dense_doubles_off: 40,
            object_dense_i64_sidecar_valid_off: 33,
        });
        std::env::set_var("CRUFT_LEJIT_PACKED_READ_RAW", "1");
        if observe {
            std::env::set_var("CRUFT_LEJIT_PACKED_READ_RAW_PROBE", "1");
        } else {
            std::env::remove_var("CRUFT_LEJIT_PACKED_READ_RAW_PROBE");
        }

        let proto = osr_proto_with_locals(bc, 3);
        let jit = compile_function_inner(&proto, true, false, true)
            .expect("raw packed-read thunk import should compile under opt-in");

        std::env::remove_var("CRUFT_LEJIT_PACKED_READ_RAW");
        std::env::remove_var("CRUFT_LEJIT_PACKED_READ_RAW_PROBE");
        crate::deopt::set_inline_ic_layout(crate::deopt::InlineIcLayout::default());

        assert!(jit.mixed_domain_osr);
        assert_eq!(jit.packed_read_elision_slots, vec![0]);
    }

