    #[test]
    fn loadglobal_undefined_parses_to_stack_only_compare_domain() {
        let mut constants = ConstantsPool::new();
        let prop_idx = constants.intern(Constant::String("constraints".to_string()));
        let undef_idx = constants.intern(Constant::String("undefined".to_string()));
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, prop_idx);
        encode_op(&mut bc, Op::LoadGlobal);
        encode_u16(&mut bc, undef_idx);
        encode_op(&mut bc, Op::StrictEq);
        encode_op(&mut bc, Op::Return);

        let mut proto = osr_proto_with_locals(bc, 1);
        proto.constants = constants;
        let parsed = parse_bytecode(&proto.bytecode, &proto.constants, &proto.locals)
            .expect("LoadGlobal undefined should parse as admitted compare literal");
        assert!(
            parsed
                .iter()
                .any(|(_, op)| matches!(op, ParsedOp::PushUndefined)),
            "expected PushUndefined in parsed ops, got {parsed:?}"
        );
        let jit = compile_function_inner(&proto, true, false, true)
            .expect("object property compared to undefined should compile in mixed domain");
        assert!(jit.mixed_domain_osr);
        assert_eq!(jit.mixed_domain_slots.object_slots, vec![0]);
    }

    #[test]
