        encode_op(&mut bc, Op::BitAnd);
        encode_op(&mut bc, Op::Call);
        bc.push(1);
        encode_op(&mut bc, Op::InitLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::PushNull);
        encode_op(&mut bc, Op::StrictEq);
        encode_op(&mut bc, Op::Return);

