    #[test]
    fn regexp_exec_object_or_null_global_ic_lowers_only_proved_exec_pc() {
        let exec_idx = crate::ic_table::IC_TABLE
            .iter()
            .position(|entry| entry.key == "exec")
            .expect("regexp exec IC entry") as u8;
        let parsed = vec![
            (0, ParsedOp::LoadLocal(0)),
            (3, ParsedOp::IcMethodResolve(exec_idx)),
            (6, ParsedOp::LoadLocal(1)),
            (9, ParsedOp::IcMethodCall(exec_idx)),
            (11, ParsedOp::InitLocal(2)),
            (14, ParsedOp::LoadLocal(2)),
            (17, ParsedOp::PushNull),
            (18, ParsedOp::StrictNe),
            (19, ParsedOp::JumpIfFalse(42)),
            (24, ParsedOp::LoadLocal(2)),
            (27, ParsedOp::PushI32(0)),
            (32, ParsedOp::GetIndexOnObject),
            (33, ParsedOp::GetPropOnObject(7)),
            (36, ParsedOp::Pop),
            (37, ParsedOp::Jump(0)),
            (42, ParsedOp::ReturnUndef),
            (45, ParsedOp::LoadLocal(0)),
            (48, ParsedOp::IcMethodResolve(exec_idx)),
            (51, ParsedOp::LoadLocal(1)),
            (54, ParsedOp::IcMethodCall(exec_idx)),
            (56, ParsedOp::Pop),
        ];
        let call_pcs: std::collections::HashSet<usize> =
            regexp_exec_object_or_null_nonnull_region_sites(&parsed)
                .into_iter()
                .map(|(exec_pc, _, _)| exec_pc)
                .collect();

        assert!(
            call_pcs.contains(&9),
            "guarded exec call should lower to /g object-or-null IC"
        );
        assert!(
            !call_pcs.contains(&54),
            "unconsumed exec call must keep the legacy object-id/deopt lowering"
        );
    }

