    #[test]
    fn regexp_exec_object_or_null_length_consumer_witnesses_live_continuation_shape() {
        let exec_idx = crate::ic_table::IC_TABLE
            .iter()
            .position(|entry| entry.key == "exec")
            .expect("regexp exec IC entry") as u8;
        let parsed = vec![
            (0, ParsedOp::PushConst(0.0)),
            (3, ParsedOp::InitLocal(5)),
            (6, ParsedOp::LoadLocal(5)),
            (9, ParsedOp::Dup),
            (10, ParsedOp::IcMethodResolve(exec_idx)),
            (13, ParsedOp::PushConst(1.0)),
            (16, ParsedOp::InitLocal(6)),
            (19, ParsedOp::LoadLocal(6)),
            (22, ParsedOp::IcMethodCall(exec_idx)),
            (24, ParsedOp::Dup),
            (25, ParsedOp::StoreLocal(4)),
            (28, ParsedOp::PushNull),
            (29, ParsedOp::StrictNe),
            (30, ParsedOp::JumpIfFalse(61)),
            (35, ParsedOp::LoadLocal(2)),
            (38, ParsedOp::LoadLocal(4)),
            (41, ParsedOp::PushI32(0)),
            (46, ParsedOp::GetIndexOnObject),
            (47, ParsedOp::GetPropOnObject(0)),
            (50, ParsedOp::Add),
            (51, ParsedOp::Dup),
            (52, ParsedOp::StoreLocal(2)),
            (55, ParsedOp::Pop),
            (56, ParsedOp::Jump(0)),
            (61, ParsedOp::ReturnUndef),
        ];

        assert_eq!(
            regexp_exec_object_or_null_nonnull_region_sites(&parsed),
            vec![(22, 4, 28)]
        );
        assert_eq!(
            regexp_exec_object_or_null_length_consumers(&parsed),
            vec![RegexpObjectOrNullLengthConsumer {
                exec_pc: 22,
                match_slot: 4,
                getindex_pc: 46,
                getindex_op_index: 17,
                getprop_pc: 47,
                prop_idx: 0,
            }]
        );
        assert_eq!(
            regexp_exec_object_or_null_indexed_length_sites(&parsed),
            vec![17],
            "only the proved m[0].length indexed read may lower as owned string"
        );

        let mut relative_jump_dump = parsed.clone();
        relative_jump_dump[13] = (30, ParsedOp::JumpIfFalse(26));
        relative_jump_dump[18] = (47, ParsedOp::IcPropertyGet(0));
        assert_eq!(
            regexp_exec_object_or_null_length_consumers(&relative_jump_dump),
            vec![RegexpObjectOrNullLengthConsumer {
                exec_pc: 22,
                match_slot: 4,
                getindex_pc: 46,
                getindex_op_index: 17,
                getprop_pc: 47,
                prop_idx: 0,
            }]
        );
        assert_eq!(
            regexp_exec_object_or_null_indexed_length_sites(&relative_jump_dump),
            vec![17],
            "live IcPropertyGet(length) dump should preserve the same owned-string index site"
        );
    }

