    #[test]
    fn regexp_exec_with_stable_upvalue_facts_does_not_fallback_to_factless_lowering() {
        let exec_idx = crate::ic_table::IC_TABLE
            .iter()
            .position(|entry| entry.key == "exec")
            .expect("regexp exec IC entry") as u8;
        let mut constants = ConstantsPool::new();
        let exec_key_idx = constants.intern(Constant::String("exec".to_string()));
        let length_key_idx = constants.intern(Constant::String("length".to_string()));
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadUpvalue);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::InitLocal);
        encode_u16(&mut bc, 5);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 5);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::GetPropSkipForMethod);
        encode_u16(&mut bc, exec_key_idx);
        encode_op(&mut bc, Op::LoadUpvalue);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::InitLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 6);
        encode_op(&mut bc, Op::CallMethodIcCached);
        bc.push(exec_idx);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::PushNull);
        encode_op(&mut bc, Op::StrictNe);
        encode_op(&mut bc, Op::JumpIfFalse);
        let exit_disp_at = bc.len();
        encode_i32(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 4);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 0);
        encode_op(&mut bc, Op::GetIndex);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, length_key_idx);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::ReturnUndef);
        let exit_pc = bc.len();
        let exit_disp = exit_pc as i32 - (exit_disp_at + 4) as i32;
        bc[exit_disp_at..exit_disp_at + 4].copy_from_slice(&exit_disp.to_le_bytes());
        encode_op(&mut bc, Op::ReturnUndef);

        let mut proto = osr_proto_with_locals(bc, 7);
        proto.constants = constants;
        proto.upvalues.push(UpvalueDescriptor {
            source: rusty_js_bytecode::UpvalueSource::Local(0),
            name: "re".to_string(),
            is_fn_self_name: false,
        });
        proto.upvalues.push(UpvalueDescriptor {
            source: rusty_js_bytecode::UpvalueSource::Local(1),
            name: "source".to_string(),
            is_fn_self_name: false,
        });

        std::env::set_var("CRUFT_LEJIT_REGEXP_EXEC_OBJECT_OR_NULL_DOMAIN", "1");
        let compiled = compile_function_osr_with_facts_and_stable_preloads_and_string(
            &proto,
            &[],
            &[],
            &[],
            &[],
            &[],
            &[StableObjectUpvaluePreloadSpec {
                local_slot: 5,
                object_return_nonnull_guard_factory: false,
                object_arg_param_mask: 0,
                object_mutation_arg_param_mask: 0,
            }],
            &[],
            &[StableStringUpvaluePreloadSpec { local_slot: 6 }],
        )
        .expect("regexp continuation now admits through the published object-or-null indexed-length proof");
        std::env::remove_var("CRUFT_LEJIT_REGEXP_EXEC_OBJECT_OR_NULL_DOMAIN");
        assert!(compiled.mixed_domain_osr);
    }

    #[test]
    fn jit_rejects_null_outside_immediate_equality_guard() {
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 15);
        encode_op(&mut bc, Op::BitAnd);
        encode_op(&mut bc, Op::Call);
        bc.push(1);
        encode_op(&mut bc, Op::InitLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::PushNull);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::Return);

        let mut proto = empty_proto(bc, 1);
        proto.locals[0].name = "makeAdder".to_string();
        proto.locals.push(LocalDescriptor {
            name: "i".to_string(),
            kind: rusty_js_ast::VariableKind::Var,
            depth: 0,
            top_level_lexical: false,
            script_global_var: false,
            pure_local_no_mirror: false,
        });
        proto.locals.push(LocalDescriptor {
            name: "f".to_string(),
            kind: rusty_js_ast::VariableKind::Var,
            depth: 0,
            top_level_lexical: false,
            script_global_var: false,
            pure_local_no_mirror: false,
        });

        let err = compile_function_inner(&proto, true, false, true)
            .expect_err("null admission must remain equality-guard-only");
        assert!(
            err.contains("immediate equality comparison"),
            "unexpected error: {err}"
        );
    }

    #[ignore = "Φ-EXT 3: i64-specific behavior; revisit at Move 2 typed-i64 fast path"]
    #[test]
    fn jit_typed_i64_sum() {

        use rusty_js_bytecode::op::{encode_i32, encode_u16};
        let mut bc = Vec::new();

        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 0);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 1);

        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 0);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 2);
        let loop_top = bc.len();

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::LoadArg);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::LtI64);

        encode_op(&mut bc, Op::JumpIfFalse);
        let jif_disp_at = bc.len();
        encode_i32(&mut bc, 0);

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::AddI64);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 1);

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::IncI64);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 2);

        encode_op(&mut bc, Op::Jump);
        let jump_disp_at = bc.len();
        let jump_next_pc = bc.len() + 4;
        encode_i32(&mut bc, loop_top as i32 - jump_next_pc as i32);

        let exit_pc = bc.len();

        let jif_disp = exit_pc as i32 - (jif_disp_at + 4) as i32;
        bc[jif_disp_at..jif_disp_at + 4].copy_from_slice(&jif_disp.to_le_bytes());

        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::Return);

        encode_op(&mut bc, Op::ReturnUndef);
        let _ = jump_disp_at;

        let mut proto = empty_proto(bc, 1);
        proto.locals.push(LocalDescriptor {
            name: "s".to_string(),
            kind: rusty_js_ast::VariableKind::Var,
            depth: 0,
            top_level_lexical: false,
            script_global_var: false,
            pure_local_no_mirror: false,
        });
        proto.locals.push(LocalDescriptor {
            name: "i".to_string(),
            kind: rusty_js_ast::VariableKind::Var,
            depth: 0,
            top_level_lexical: false,
            script_global_var: false,
            pure_local_no_mirror: false,
        });

        let jit = compile_function(&proto).expect("typed-i64 JIT compile failed");
        assert_eq!(jit.func.call1(0.0_f64), 0.0_f64);
        assert_eq!(jit.func.call1(5.0_f64), 10.0_f64);
        assert_eq!(jit.func.call1(100.0_f64), 4950.0_f64);
        assert_eq!(jit.func.call1(1_000_000 as f64), 499_999_500_000_i64 as f64);
    }

    #[ignore = "Φ-EXT 3: i64-specific behavior; revisit at Move 2 typed-i64 fast path"]
    #[test]
    fn guarded_sub_trips_on_overflow() {
        use crate::deopt::{
            clear_current_deopt_sites, set_current_deopt_sites, take_last_deopt, DeoptReason,
        };

        std::env::set_var("CRUFT_JIT_GUARD_OVERFLOW", "1");
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadArg);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::LoadArg);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::Sub);
        encode_op(&mut bc, Op::Return);
        let proto = empty_proto(bc, 2);
        let jit = compile_function(&proto).expect("guarded compile failed");
        std::env::remove_var("CRUFT_JIT_GUARD_OVERFLOW");

        assert_eq!(jit.deopt_sites.len(), 1);
        set_current_deopt_sites(&jit.deopt_sites);

        assert_eq!(jit.func.call2(10.0_f64, 3.0_f64), 7.0_f64);
        assert!(take_last_deopt().is_none());

        let r = jit.func.call2(i64::MIN as f64, 1 as f64);
        assert_eq!(r, 0 as f64, "guarded sub trips on i64::MIN - 1");
        let state = take_last_deopt().expect("sub overflow should trip");
        assert!(matches!(state.reason, DeoptReason::IntegerOverflow { .. }));
        assert_eq!(state.local_values, vec![(0, i64::MIN), (1, 1)]);

        clear_current_deopt_sites();
    }

