    #[test]
    fn predicate_leaf_result_abi_rewrites_terminal_keep_return() {
        let mut parsed = vec![
            (0, ParsedOp::LoadLocal(0)),
            (3, ParsedOp::PushUndefined),
            (6, ParsedOp::StrictEq),
            (7, ParsedOp::JumpIfFalseKeep(14)),
            (12, ParsedOp::Pop),
            (13, ParsedOp::PushI32(0)),
            (14, ParsedOp::Return),
        ];

        rewrite_predicate_leaf_terminal_keep_return(&mut parsed);

        assert!(matches!(parsed[3], (7, ParsedOp::JumpIfFalse(15))));
        assert!(!parsed
            .iter()
            .any(|entry| matches!(entry, (12, ParsedOp::Pop))));
        assert!(matches!(
            parsed.as_slice(),
            [.., (15, ParsedOp::PushI32(0)), (16, ParsedOp::Return)]
        ));
    }

