    #[test]
    fn mdoa_f64_fallback_strips_osr_entry_range_guards() {
        let mut bc = Vec::new();
        let loop_top = bc.len();
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 100_000);
        encode_op(&mut bc, Op::Lt);
        encode_op(&mut bc, Op::JumpIfFalse);
        let jif_disp_at = bc.len();
        encode_i32(&mut bc, 0);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 3);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::ToNumeric);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 2);
        encode_op(&mut bc, Op::Inc);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 3);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 3);
        encode_op(&mut bc, Op::StoreLocal);
        encode_u16(&mut bc, 1);
        encode_op(&mut bc, Op::Jump);
        let jump_next_pc = bc.len() + 4;
        encode_i32(&mut bc, loop_top as i32 - jump_next_pc as i32);
        let exit_pc = bc.len();
        let jif_disp = exit_pc as i32 - (jif_disp_at + 4) as i32;
        bc[jif_disp_at..jif_disp_at + 4].copy_from_slice(&jif_disp.to_le_bytes());
        encode_op(&mut bc, Op::ReturnUndef);

        let proto = osr_proto_with_locals(bc, 4);
        let default_jit =
            compile_function_osr(&proto).expect("default MDOA numeric loop should compile");
        assert!(
            !default_jit.osr_entry_range_guards.is_empty(),
            "default MDOA keeps SafeI64 entry range guards"
        );

        let fallback_jit = compile_function_osr_mdoa_f64(&proto)
            .expect("MDOA f64 fallback should compile without range guards");
        assert!(
            fallback_jit.osr_entry_range_guards.is_empty(),
            "f64 fallback must not retain the SafeI64 entry range guard it is escaping"
        );
    }

