    #[test]
    fn node_api_script_alias_getprop_preserves_method_receiver_fact() {
        let mut constants = ConstantsPool::new();
        let buffer_idx = constants.intern(Constant::String("__nodeApiProbeBuffer".to_string()));
        let alloc_idx = constants.intern(Constant::String("alloc".to_string()));
        let locals = vec![LocalDescriptor {
            name: "__nodeApiProbeBuffer".to_string(),
            kind: rusty_js_ast::VariableKind::Var,
            depth: 0,
            top_level_lexical: false,
            script_global_var: true,
            pure_local_no_mirror: false,
        }];
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadGlobal);
        encode_u16(&mut bc, buffer_idx);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, alloc_idx);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 8);
        encode_op(&mut bc, Op::CallMethod);
        encode_u8(&mut bc, 1);
        encode_op(&mut bc, Op::Return);

        let parsed = parse_bytecode(&bc, &constants, &locals)
            .expect("host-native method candidate should be admitted to the parsed alphabet");
        assert!(
            parsed.iter().any(|(_, op)| matches!(
                op,
                ParsedOp::HostNativeMethod1ObjRet {
                    receiver_slot: 0,
                    prop_idx,
                    ..
                } if *prop_idx == alloc_idx
            )),
            "expected HostNativeMethod1ObjRet for Buffer.alloc, got {parsed:?}"
        );

        let mut prefix = Vec::new();
        encode_op(&mut prefix, Op::LoadGlobal);
        encode_u16(&mut prefix, buffer_idx);
        encode_op(&mut prefix, Op::Dup);
        encode_op(&mut prefix, Op::GetProp);
        encode_u16(&mut prefix, alloc_idx);
        let parsed = parse_bytecode(&prefix, &constants, &locals)
            .expect("script-global alias method receiver should reach GetPropOnObject");
        assert!(
            parsed
                .iter()
                .any(|(_, op)| matches!(op, ParsedOp::GetPropOnObject(idx) if *idx == alloc_idx)),
            "expected GetPropOnObject for method-shaped script-global alias, got {parsed:?}"
        );

        let mut proto = osr_proto_with_locals(bc, 1);
        proto.constants = constants;
        proto.locals[0] = locals[0].clone();
        let err = compile_function_osr(&proto)
            .expect_err("host-native object-return method bridge must stay mouth-gated until value-return transport is proven for OSR");
        assert!(
            err.contains("object-domain return requires value-return transport"),
            "unexpected compile error: {err}"
        );
    }

