        encode_u16(&mut bc, other_idx);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, alloc_idx);
        encode_op(&mut bc, Op::PushI32);
