    #[test]
    fn interop_require_default_shape_admits_object_only_return_transport() {
        let default_idx = 65;
        let es_module_idx = 64;
        let mut parsed = vec![
            (0, ParsedOp::LoadLocal(0)),
            (3, ParsedOp::JumpIfFalseKeep(28)),
            (8, ParsedOp::Pop),
            (9, ParsedOp::LoadLocal(0)),
            (12, ParsedOp::GetPropOnObject(es_module_idx)),
            (15, ParsedOp::JumpIfFalse(28)),
            (20, ParsedOp::LoadLocal(0)),
            (23, ParsedOp::Jump(43)),
            (28, ParsedOp::NewObjectLiteral { capacity: 1 }),
            (31, ParsedOp::Dup),
            (32, ParsedOp::StoreLocal(2)),
            (35, ParsedOp::LoadLocal(0)),
            (
                38,
                ParsedOp::InitPropStaticObject {
                    prop_idx: default_idx,
                    slot: 0,
                },
            ),
            (43, ParsedOp::Return),
        ];

        rewrite_value_jump_to_return(&mut parsed);
        rewrite_getprop_truthy_branch_domain(&mut parsed);
        assert!(
            matches!(parsed[7].1, ParsedOp::Return),
            "_interopRequireDefault true arm should no longer need a cross-block value Jump"
        );
        assert!(
            matches!(parsed[4].1, ParsedOp::GetPropTruthyOnObject(idx) if idx == es_module_idx),
            "_interopRequireDefault __esModule branch read should use the truthiness GetProp lane: {parsed:?}"
        );

        let mut slots = mixed_domain_slots(&parsed, &[]);
        for slot in interop_require_default_value_return_object_slots(&parsed) {
            push_unique_sorted(&mut slots.object_slots, slot);
        }
        assert!(
            slots.object_slots.contains(&0),
            "_interopRequireDefault value arm should classify argument slot object-domain: {slots:?}"
        );
        assert!(
            object_entry_return_candidate(&parsed, &slots),
            "_interopRequireDefault should be an object-only entry-return candidate"
        );
    }

