    #[test]
    fn stable_object_upvalue_indexed_property_number_tag_elision_rejects_effect_boundaries() {
        let base = vec![
            (
                0,
                ParsedOp::StableObjectUpvaluePreload {
                    upvalue_slot: 0,
                    local_slot: 4,
                },
            ),
            (1, ParsedOp::LoadLocal(2)),
            (2, ParsedOp::LoadLocal(4)),
            (3, ParsedOp::LoadLocal(3)),
            (4, ParsedOp::GetIndexOnObject),
            (5, ParsedOp::GetPropOnObject(7)),
            (6, ParsedOp::Add),
            (7, ParsedOp::StoreLocal(2)),
        ];

        let mut with_write = base.clone();
        with_write.push((8, ParsedOp::SetPropOnObject(7)));
        assert!(!stable_object_upvalue_indexed_property_number_tag_elision_safe(&with_write));

        let mut with_call = base.clone();
        with_call.push((
            8,
            ParsedOp::CallDirect {
                arity: 0,
                callee_slot: 1,
            },
        ));
        assert!(!stable_object_upvalue_indexed_property_number_tag_elision_safe(&with_call));

        let mut with_allocation = base;
        with_allocation.push((8, ParsedOp::NewArrayEmpty));
        assert!(!stable_object_upvalue_indexed_property_number_tag_elision_safe(&with_allocation));
    }

    #[test]
    fn siper_normalizes_owned_pair_then_local_string_concat() {
        let suffix = "joined";
        let mut parsed = vec![
            (0, ParsedOp::LoadLocal(0)),
            (3, ParsedOp::StringCommaIfTruthy { slot: 0 }),
            (
                6,
                ParsedOp::PushStringConst {
                    ptr: suffix.as_ptr() as i64,
                    len: suffix.len() as i64,
                },
            ),
            (9, ParsedOp::Add),
            (10, ParsedOp::Add),
            (11, ParsedOp::StoreLocal(0)),
        ];

        rewrite_string_concat_adds(&mut parsed).expect("exact owned string concat chain");
        validate_string_concat_writebacks(&parsed).expect("writeback destination should match");

        assert!(matches!(parsed[3].1, ParsedOp::StringConcatOwnedPair));
        assert!(matches!(
            parsed[4].1,
            ParsedOp::StringConcatOwnedResult { left_slot: 0 }
        ));

        parsed[5].1 = ParsedOp::StoreLocal(1);
        let err = validate_string_concat_writebacks(&parsed)
            .expect_err("destination mismatch should stay rejected");
        assert!(
            err.contains("does not match left string local"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn siper_treats_array_join_as_owned_string_concat_source() {
        let sep = ":";
        let join_idx = crate::ic_table::lookup_by_key("join").expect("join IC entry");
        let mut parsed = vec![
            (0, ParsedOp::LoadLocal(6)),
            (3, ParsedOp::StringCommaIfTruthy { slot: 6 }),
            (6, ParsedOp::NewArrayLiteral { len: 1 }),
            (9, ParsedOp::PushI32(7)),
            (12, ParsedOp::InitIndex { idx: 0 }),
            (15, ParsedOp::Dup),
            (16, ParsedOp::IcMethodResolve(join_idx)),
            (
                18,
                ParsedOp::PushStringConst {
                    ptr: sep.as_ptr() as i64,
                    len: sep.len() as i64,
                },
            ),
            (21, ParsedOp::IcMethodCall(join_idx)),
            (24, ParsedOp::Add),
            (25, ParsedOp::Add),
            (26, ParsedOp::StoreLocal(6)),
            (27, ParsedOp::PushI32(0)),
            (30, ParsedOp::StoreLocal(7)),
            (
                33,
                ParsedOp::CallDirectLeaf {
                    callee_slot: 0,
                    leaf: DirectCallLeaf::Arg0AddConst(1.0),
                },
            ),
        ];

        rewrite_string_concat_adds(&mut parsed).expect("array.join should be owned-string source");
        validate_string_concat_writebacks(&parsed).expect("writeback destination should match");

        assert!(matches!(parsed[9].1, ParsedOp::StringConcatOwnedPair));
        assert!(matches!(
            parsed[10].1,
            ParsedOp::StringConcatOwnedResult { left_slot: 6 }
        ));

        let slots = mixed_domain_slots(&parsed, &[]);
        assert_eq!(
            slots.string_slots,
            vec![6],
            "array.join concat writeback should classify the persisted detail local as string"
        );
        assert!(
            !slots.f64_slots.contains(&6),
            "string local must not stay in the f64 guard set"
        );
    }

