    #[test]
    fn siper_admits_owned_string_result_value_concat_by_default() {
        let mut constants = ConstantsPool::new();
        let string_idx = constants.intern(Constant::String("String".to_string()));
        let from_char_code_idx = constants.intern(Constant::String("fromCharCode".to_string()));
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadGlobal);
        encode_u16(&mut bc, string_idx);
        encode_op(&mut bc, Op::Dup);
        encode_op(&mut bc, Op::GetProp);
        encode_u16(&mut bc, from_char_code_idx);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 65);
        encode_op(&mut bc, Op::CallMethod);
        encode_u8(&mut bc, 1);
        encode_op(&mut bc, Op::PushI32);
        encode_i32(&mut bc, 1);
        encode_op(&mut bc, Op::Add);
        encode_op(&mut bc, Op::ReturnUndef);

        std::env::remove_var("CRUFT_LEJIT_STRING_BUILDER_ADDS");
        let parsed = parse_bytecode(&bc, &constants, &[])
            .expect("owned string result + plain value should lower by default");
        assert!(
            parsed
                .iter()
                .any(|(_, op)| matches!(op, ParsedOp::StringConcatOwnedValue)),
            "owned string value concat should be present: {parsed:?}"
        );

        std::env::set_var("CRUFT_LEJIT_STRING_BUILDER_ADDS", "0");
        let err = parse_bytecode(&bc, &constants, &[])
            .expect_err("owned string result must not enter numeric Add");
        assert!(
            err.contains("owned string result requires exact local-string concat/writeback shape"),
            "unexpected error: {err}"
        );
        std::env::remove_var("CRUFT_LEJIT_STRING_BUILDER_ADDS");
    }

    #[test]
    fn siper3_erases_script_global_bind_helper_for_matching_alias() {
        let mut constants = ConstantsPool::new();
        let helper_idx = constants.intern(Constant::String("__script_var_global_bind".to_string()));
        let x_idx = constants.intern(Constant::String("x".to_string()));
        let locals = vec![LocalDescriptor {
            name: "x".to_string(),
            kind: rusty_js_ast::VariableKind::Var,
            depth: 0,
            top_level_lexical: false,
            script_global_var: true,
            pure_local_no_mirror: false,
        }];
        let mut bc = Vec::new();
        encode_op(&mut bc, Op::LoadGlobal);
        encode_u16(&mut bc, helper_idx);
        encode_op(&mut bc, Op::PushConst);
        encode_u16(&mut bc, x_idx);
        encode_op(&mut bc, Op::LoadLocal);
        encode_u16(&mut bc, 0);
        encode_op(&mut bc, Op::PushFalse);
        encode_op(&mut bc, Op::Call);
        encode_u8(&mut bc, 3);
        encode_op(&mut bc, Op::Pop);
        encode_op(&mut bc, Op::ReturnUndef);

        let parsed = parse_bytecode(&bc, &constants, &locals)
            .expect("compiler-generated script-var mirror helper should erase");
        assert!(matches!(parsed[0].1, ParsedOp::ResetLocalCellNop));
        assert!(matches!(parsed[1].1, ParsedOp::ReturnUndef));
    }

