    #[test]
    fn primitive_string_index_rewrite_moves_direct_local_scanner_receiver_to_string_guard() {
        let mut parsed = vec![
            (123, ParsedOp::PushI32(122)),
            (128, ParsedOp::Le),
            (129, ParsedOp::InitLocal(9)),
            (132, ParsedOp::LoadLocal(9)),
            (135, ParsedOp::JumpIfFalse(176)),
            (140, ParsedOp::LoadLocal(5)),
            (143, ParsedOp::LoadLocal(0)),
            (146, ParsedOp::LoadLocal(7)),
            (149, ParsedOp::GetIndexOnObject),
        ];

        clear_string_slot_hint();
        let mut array_parsed = parsed.clone();
        rewrite_primitive_string_index_object_guards(&mut array_parsed);
        assert!(
            matches!(array_parsed[8].1, ParsedOp::GetIndexOnObject),
            "no string-slot hint ⇒ scanner receiver stays an array GetIndexOnObject"
        );

        set_string_slot_hint(&[0]);
        rewrite_primitive_string_index_object_guards(&mut parsed);
        clear_string_slot_hint();

        match parsed[8].1 {
            ParsedOp::PrimitiveStringIndexRead {
                predicate_pc: 135,
                accumulator_slot: 5,
                receiver_slot: 0,
                index_slot: 7,
            } => {}
            ref other => panic!("unexpected op after rewrite: {other:?}"),
        }
        assert_eq!(primitive_string_index_receiver_slots(&parsed), vec![0]);
        assert!(primitive_string_index_object_guard_domain_gaps(&parsed).is_empty());
    }

