    #[test]
    fn css_identifier_mapped_ternary_sinks_store_into_arms() {
        static COLOR: &[u8] = b"color";
        static C: &[u8] = b"c";
        static MARGIN: &[u8] = b"margin";
        static M: &[u8] = b"m";
        let mut parsed = vec![
            (196, ParsedOp::LoadLocal(2)),
            (
                199,
                ParsedOp::PushStringConst {
                    ptr: COLOR.as_ptr() as i64,
                    len: COLOR.len() as i64,
                },
            ),
            (202, ParsedOp::StrictEq),
            (203, ParsedOp::JumpIfFalse(216)),
            (
                208,
                ParsedOp::PushStringConst {
                    ptr: C.as_ptr() as i64,
                    len: C.len() as i64,
                },
            ),
            (211, ParsedOp::Jump(239)),
            (216, ParsedOp::LoadLocal(2)),
            (
                219,
                ParsedOp::PushStringConst {
                    ptr: MARGIN.as_ptr() as i64,
                    len: MARGIN.len() as i64,
                },
            ),
            (222, ParsedOp::StrictEq),
            (223, ParsedOp::JumpIfFalse(236)),
            (
                228,
                ParsedOp::PushStringConst {
                    ptr: M.as_ptr() as i64,
                    len: M.len() as i64,
                },
            ),
            (231, ParsedOp::Jump(239)),
            (236, ParsedOp::LoadLocal(2)),
            (239, ParsedOp::InitLocal(7)),
            (242, ParsedOp::LoadLocal(1)),
        ];

        rewrite_css_identifier_mapped_ternary_store(&mut parsed);

        assert!(matches!(
            parsed.as_slice(),
            [
                (196, ParsedOp::LoadLocal(2)),
                (197, ParsedOp::PushStringConst { .. }),
                (198, ParsedOp::StringLocalConstStrictEq { .. }),
                (199, ParsedOp::JumpIfFalse(216)),
                (200, ParsedOp::PushStringConst { .. }),
                (201, ParsedOp::InitLocal(7)),
                (202, ParsedOp::Jump(242)),
                (216, ParsedOp::LoadLocal(2)),
                (217, ParsedOp::PushStringConst { .. }),
                (218, ParsedOp::StringLocalConstStrictEq { .. }),
                (219, ParsedOp::JumpIfFalse(236)),
                (220, ParsedOp::PushStringConst { .. }),
                (221, ParsedOp::InitLocal(7)),
                (222, ParsedOp::Jump(242)),
                (236, ParsedOp::LoadLocal(2)),
                (237, ParsedOp::InitLocal(7)),
                (242, ParsedOp::LoadLocal(1)),
            ]
        ));
    }

