    #[test]
    fn stable_helper_value_keep_chain_rewrites_to_materialized_object_returns() {
        let mut parsed = sliced_to_array_value_keep_chain_parsed();
        rewrite_stable_helper_value_keep_chain(&mut parsed);

        assert!(!parsed
            .iter()
            .any(|(_, op)| matches!(op, ParsedOp::JumpIfTrueKeep(_))));
        assert_eq!(direct_call1_object_return_sites(&parsed), vec![(8, 3, 3)]);
        assert_eq!(
            direct_call2_object_return_sites(&parsed),
            vec![(30, 4, 4), (50, 5, 5)]
        );
        assert_eq!(
            direct_call0_object_return_store_sites(&parsed),
            vec![(68, 6, 6)]
        );
        assert_eq!(
            materialized_helper_object_return_arg_sites(&parsed),
            vec![(8, 3, 0), (30, 4, 0), (50, 5, 0)]
        );

        let mut slots = mixed_domain_slots(&parsed, &[]);
        for (_, _, arg_slot) in materialized_helper_object_return_arg_sites(&parsed) {
            push_unique_sorted(&mut slots.object_slots, arg_slot);
        }
        assert!(slots.object_slots.contains(&0));
        assert!(slots.object_slots.contains(&3));
        assert!(slots.object_slots.contains(&4));
        assert!(slots.object_slots.contains(&5));
        assert!(slots.object_slots.contains(&6));
        assert!(materialized_object_or_undefined_entry_return_candidate(
            &parsed, &slots
        ));

        parsed.push((79, ParsedOp::PushI32(0)));
        parsed.push((80, ParsedOp::Return));
        assert!(materialized_object_or_undefined_entry_return_candidate(
            &parsed, &slots
        ));
    }

