    #[test]
    fn stable_helper_predicate_keep_chain_rewrites_to_false_return() {
        let mut parsed = vec![
            (0, ParsedOp::LoadLocal(0)),
            (3, ParsedOp::GetPropOnObject(64)),
            (6, ParsedOp::LoadLocal(1)),
            (9, ParsedOp::GetPropOnObject(64)),
            (12, ParsedOp::StrictEq),
            (13, ParsedOp::JumpIfFalseKeep(18)),
            (18, ParsedOp::Pop),
            (
                19,
                ParsedOp::StableCalleePreload {
                    upvalue_slot: 0,
                    local_slot: 3,
                },
            ),
            (25, ParsedOp::LoadLocal(3)),
            (28, ParsedOp::LoadLocal(0)),
            (31, ParsedOp::GetPropOnObject(65)),
            (34, ParsedOp::LoadLocal(1)),
            (37, ParsedOp::GetPropOnObject(65)),
            (
                40,
                ParsedOp::CallDirect {
                    arity: 2,
                    callee_slot: 3,
                },
            ),
            (42, ParsedOp::JumpIfFalseKeep(18)),
            (47, ParsedOp::Pop),
            (
                48,
                ParsedOp::StableCalleePreload {
                    upvalue_slot: 1,
                    local_slot: 4,
                },
            ),
            (54, ParsedOp::LoadLocal(4)),
            (57, ParsedOp::LoadLocal(0)),
            (60, ParsedOp::GetPropOnObject(66)),
            (63, ParsedOp::LoadLocal(1)),
            (66, ParsedOp::GetPropOnObject(66)),
            (
                69,
                ParsedOp::CallDirect {
                    arity: 2,
                    callee_slot: 4,
                },
            ),
            (71, ParsedOp::Return),
            (72, ParsedOp::ReturnUndef),
        ];

        rewrite_stable_helper_predicate_keep_chain(&mut parsed);

        assert!(matches!(parsed[5], (13, ParsedOp::JumpIfFalse(73))));
        assert!(!parsed
            .iter()
            .any(|(pc, op)| { matches!((*pc, op), (18, ParsedOp::Pop) | (47, ParsedOp::Pop)) }));
        assert!(parsed
            .iter()
            .any(|entry| matches!(entry, (42, ParsedOp::JumpIfFalse(73)))));
        assert!(matches!(
            parsed.as_slice(),
            [.., (73, ParsedOp::PushI32(0)), (74, ParsedOp::Return)]
        ));
    }

    #[test]
    fn stable_helper_predicate_parent_rejects_value_polymorphic_getprop() {
        let mut constants = ConstantsPool::new();
        let name_idx = constants.intern(Constant::String("name".to_string()));
        let constraints_idx = constants.intern(Constant::String("constraints".to_string()));
        let attributes_idx = constants.intern(Constant::String("attributes".to_string()));
        let parsed = vec![
            (0, ParsedOp::LoadLocal(0)),
            (3, ParsedOp::GetPropOnObject(name_idx)),
            (6, ParsedOp::LoadLocal(1)),
            (9, ParsedOp::GetPropOnObject(name_idx)),
            (12, ParsedOp::StrictEq),
            (13, ParsedOp::JumpIfFalseKeep(18)),
            (18, ParsedOp::Pop),
            (
                19,
                ParsedOp::StableCalleePreload {
                    upvalue_slot: 0,
                    local_slot: 3,
                },
            ),
            (25, ParsedOp::LoadLocal(3)),
            (28, ParsedOp::LoadLocal(0)),
            (31, ParsedOp::GetPropOnObject(constraints_idx)),
            (34, ParsedOp::LoadLocal(1)),
            (37, ParsedOp::GetPropOnObject(constraints_idx)),
            (
                40,
                ParsedOp::CallDirect {
                    arity: 2,
                    callee_slot: 3,
                },
            ),
            (42, ParsedOp::JumpIfFalseKeep(18)),
            (47, ParsedOp::Pop),
            (
                48,
                ParsedOp::StableCalleePreload {
                    upvalue_slot: 1,
                    local_slot: 4,
                },
            ),
            (54, ParsedOp::LoadLocal(4)),
            (57, ParsedOp::LoadLocal(0)),
            (60, ParsedOp::GetPropOnObject(attributes_idx)),
            (63, ParsedOp::LoadLocal(1)),
            (66, ParsedOp::GetPropOnObject(attributes_idx)),
            (
                69,
                ParsedOp::CallDirect {
                    arity: 2,
                    callee_slot: 4,
                },
            ),
            (71, ParsedOp::Return),
        ];

        let err = stable_helper_predicate_parent_value_polymorphic_getprop_gap(&parsed, &constants)
            .expect("ARIA-shaped stable-helper parent should reject non-length getprop");
        assert!(
            err.contains("value-polymorphic GetProp") && err.contains("prop=\"name\""),
            "unexpected gate reason: {err}"
        );
        assert!(
            err.contains("string-eq props=[\"name\"]"),
            "expected string equality transport split: {err}"
        );
        assert!(
            err.contains("helper-arg props=[\"constraints\", \"attributes\"]"),
            "expected helper argument transport split: {err}"
        );
    }

    #[test]
    fn stable_helper_parent_rewrites_string_prop_stricteq_before_value_gate() {
        let mut constants = ConstantsPool::new();
        let name_idx = constants.intern(Constant::String("name".to_string()));
        let constraints_idx = constants.intern(Constant::String("constraints".to_string()));
        let attributes_idx = constants.intern(Constant::String("attributes".to_string()));
        let mut parsed = vec![
            (0, ParsedOp::LoadLocal(0)),
            (3, ParsedOp::GetPropOnObject(name_idx)),
            (6, ParsedOp::LoadLocal(1)),
            (9, ParsedOp::GetPropOnObject(name_idx)),
            (12, ParsedOp::StrictEq),
            (13, ParsedOp::JumpIfFalseKeep(18)),
            (18, ParsedOp::Pop),
            (
                19,
                ParsedOp::StableCalleePreload {
                    upvalue_slot: 0,
                    local_slot: 3,
                },
            ),
            (25, ParsedOp::LoadLocal(3)),
            (28, ParsedOp::LoadLocal(0)),
            (31, ParsedOp::GetPropOnObject(constraints_idx)),
            (34, ParsedOp::LoadLocal(1)),
            (37, ParsedOp::GetPropOnObject(constraints_idx)),
            (
                40,
                ParsedOp::CallDirect {
                    arity: 2,
                    callee_slot: 3,
                },
            ),
            (42, ParsedOp::JumpIfFalseKeep(18)),
            (47, ParsedOp::Pop),
            (
                48,
                ParsedOp::StableCalleePreload {
                    upvalue_slot: 1,
                    local_slot: 4,
                },
            ),
            (54, ParsedOp::LoadLocal(4)),
            (57, ParsedOp::LoadLocal(0)),
            (60, ParsedOp::GetPropOnObject(attributes_idx)),
            (63, ParsedOp::LoadLocal(1)),
            (66, ParsedOp::GetPropOnObject(attributes_idx)),
            (
                69,
                ParsedOp::CallDirect {
                    arity: 2,
                    callee_slot: 4,
                },
            ),
            (71, ParsedOp::Return),
            (72, ParsedOp::ReturnUndef),
        ];

        rewrite_stable_helper_parent_string_prop_stricteq(&mut parsed, &constants);
        assert!(matches!(
            parsed[0],
            (
                0,
                ParsedOp::StringPropStrictEq {
                    lhs_slot: 0,
                    rhs_slot: 1,
                    prop_idx
                }
            ) if prop_idx == name_idx
        ));
        let err = stable_helper_predicate_parent_value_polymorphic_getprop_gap(&parsed, &constants)
            .expect("object helper argument props should remain gated");
        assert!(
            !err.contains("string-eq"),
            "string equality transport should be consumed before the residual gate: {err}"
        );
        assert!(
            err.contains("helper-arg props=[\"constraints\", \"attributes\"]"),
            "expected helper argument residual: {err}"
        );
    }

